ClinicalChunks.register("data/templates-085.js",[{"id":"templates-499532c08cf7dc5c2899","key":"v1-c9ccc21dfe2a3058|templates-499532c08cf7dc5c2899","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"屈指肌腱鞘炎","category":"门诊病历模板","raw":{"name":"屈指肌腱鞘炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左中指近节疼痛伴弹响2月，加重1周","现病史":"患者2个月前长期使用键盘打字(每日8小时)后出现左中指近节隐痛，VAS2分，屈伸时稍感费力，未重视。1个月前出现屈伸手指时 “弹响”，外院查手指 X 线无异常，予热敷治疗，效果差。1周前症状加重，VAS4分，屈伸时 “卡顿” 感明显，需用另一只手辅助才能伸直手指，影响日常活动。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认手指外伤、手术史，否认关节炎病史，否认药物过敏史，长期从事办公室工作。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：左中指近节掌侧压痛 +++，触及黄豆大小硬结(约0.3cm×0.5cm)，按压时疼痛加剧；\n活动度：左中指屈伸时可见 “弹响”，掌指关节屈曲90°(正常100°)、伸直5°(正常0°)，屈伸过程中 “卡顿” 明显；\n特殊试验：屈指肌腱紧张试验阳性(被动屈伸左中指时，近节掌侧疼痛加剧，伴 “弹响”)；\n神经系统：左中指感觉、肌力正常，病理反射未引出。","辅助检查":"手指 X 线片：左中指骨质未见异常，关节间隙正常；\n手指超声：左中指近节屈指肌腱鞘增厚，回声不均匀，肌腱局部增粗，提示腱鞘炎；\n血常规、ESR：均正常，排除感染；\n肌电图：左中指屈指肌运动单位动作电位正常，排除神经损伤。","初步诊断":"左中指近节屈指肌腱鞘炎(弹响指，慢性劳损性)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用氟比洛芬凝胶贴膏 每日1贴(贴于疼痛处)；\n局部阻滞：超声引导下左中指屈指肌腱鞘阻滞(0.5% 利多卡因2ml+倍他米松0.5ml)，每周1次，共2次；\n物理治疗：手指超声治疗(每次10分钟，每日1次)+ 热疗(每次15分钟，每日2次)，疗程2周；\n康复训练：疼痛缓解后行手指被动屈伸训练(每次5分钟，每日3组)，避免长时间打字、抓握硬物；\n生活指导：调整打字姿势，使用人体工学键盘，每工作30分钟活动手指5分钟，避免手指过度用力；\n随访：1周后复诊，评估疼痛及 “弹响” 改善情况，若保守治疗无效，评估腱鞘切开术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2197,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7b0970f2277d979496806ec9e57b04e49d3cf848eaf8b3e21e00b57e5ba27f46","pinyin":"quzhijijianqiaoyan","initials":"qzjjqy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d7e79e4e94bbd1e5bf30","key":"v1-c9ccc21dfe2a3058|templates-d7e79e4e94bbd1e5bf30","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腕背侧腱鞘囊肿","category":"门诊病历模板","raw":{"name":"腕背侧腱鞘囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧腕背侧肿块1月，增大伴隐痛2周","现病史":"患者1个月前偶然发现右侧腕背侧有黄豆大小肿块，无疼痛、活动受限，未重视。近2周肿块逐渐增大至乒乓球大小(约2cm×1.5cm)，出现轻微隐痛(VAS2分)，按压时疼痛稍明显，无麻木、腕关节活动受限，外院查腕关节 X 线无异常，建议观察，患者担心恶变，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认腕关节外伤、手术史，否认囊肿病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧腕背侧(桡腕关节间隙处)可触及直径约2cm 囊性肿块，质地柔软，边界清，活动度可，压痛 +，无粘连；\n活动度：腕关节屈伸、旋转基本正常，按压肿块时无活动受限；\n特殊试验：肿块透光试验阳性(手电筒照射可见透光)，提示囊性病变；\n神经系统：右手感觉、肌力正常，病理反射未引出。","辅助检查":"腕关节 X 线片：腕关节骨质未见异常，肿块处无钙化；\n腕关节超声：右侧腕背侧可见囊性无回声区(大小约2.1cm×1.6cm)，边界清，内透声好，提示腱鞘囊肿；\n腕关节 MRI：囊性肿块位于腕背侧腱鞘旁，信号均匀，无明显强化，排除肿瘤；\n血常规、ESR：均正常，排除感染性病变。","初步诊断":"右侧腕背侧腱鞘囊肿","处理方案":"保守治疗：若患者无明显不适，可选择观察，避免按压、挤压肿块；外用双氯芬酸二乙胺乳胶剂 每日2次(若疼痛加重时使用)；\n穿刺治疗：若患者要求处理，超声引导下囊肿穿刺抽液(抽出透明胶冻样液体)，注入0.5% 利多卡因2ml+倍他米松0.5ml，加压包扎3天；\n物理治疗：穿刺后1周行腕关节超声治疗(每次15分钟，每日1次)，预防复发；\n手术评估：若穿刺后复发或肿块持续增大，评估囊肿切除术指征，告知手术风险(复发、神经损伤)；\n生活指导：避免腕关节过度用力、重复性动作，佩戴腕关节护具(日常活动时)，减少囊肿刺激；\n随访：1个月后复诊，观察肿块变化，若出现肿块红肿、疼痛加剧，立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2198,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1ca316bad28c434d3bf7910440ffb4e004fb900e3aed0e3798b24713c5a87349","pinyin":"wanbeicejianqiaonangzhong","initials":"wbcjqnz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-34bcf39876a915bde791","key":"v1-c9ccc21dfe2a3058|templates-34bcf39876a915bde791","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"掌腱膜挛缩症","category":"门诊病历模板","raw":{"name":"掌腱膜挛缩症","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"双侧手掌皮肤增厚伴手指屈曲畸形2年","现病史":"患者2年前无明显诱因发现双侧手掌皮肤增厚，无疼痛、活动受限，未重视。1年前出现右手无名指轻微屈曲，无法完全伸直，外院诊断 “掌腱膜挛缩症”，予按摩治疗，效果差。6个月前症状加重，右手小指也出现屈曲畸形，双侧手掌可触及条索状硬结，VAS3分，影响抓握动作(如握笔、持碗)，今日来院就诊。自发病以来，精神稍焦虑，食欲正常，体重无变化，二便正常。既往体健，否认手掌外伤、手术史，否认风湿免疫病史，否认药物过敏史，家族中无类似疾病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：双侧手掌掌腱膜区皮肤增厚，可触及条索状硬结(右手无名指、小指掌侧明显，直径约0.3-0.5cm)，压痛 +；\n活动度：右手无名指掌指关节屈曲90°(正常100°)、近节指间关节屈曲60°(正常100°)，无法完全伸直；右手小指掌指关节屈曲80°、近节指间关节屈曲50°，伸直受限；左手症状较轻，手指屈伸基本正常；\n功能评估：右手抓握力下降(约为左手的60%)，无法完成握拳动作；\n神经系统：双手感觉、肌力(除屈曲畸形外)正常，病理反射未引出。","辅助检查":"手掌 X 线片：双侧手掌骨质未见异常，手指关节间隙正常；\n手掌超声：双侧掌腱膜增厚(右手明显，厚度约3mm)，回声不均匀，可见条索状高回声；\n手掌 MRI：双侧掌腱膜信号增高(T2WI)，增厚的掌腱膜牵拉手指屈肌腱，无骨质破坏；\n血常规、风湿三项：白细胞6.2×10⁹/L，类风湿因子、抗 O 均正常，排除风湿性疾病。","初步诊断":"掌腱膜挛缩症(双侧，右手 Ⅳ 期，左手 Ⅰ 期)","处理方案":"保守治疗(左手+右手轻度症状)：手掌热敷(每次20分钟，每日2次)+ 手法拉伸训练(每次10分钟，每日2组)，延缓挛缩进展；外用复方辣椒碱乳膏 每日2次涂抹，缓解不适；\n手术治疗(右手)：完善术前检查，评估掌腱膜部分切除术+皮肤 Z 字成形术指征，改善手指伸直功能，告知手术风险(瘢痕、神经损伤、复发)；\n术后康复：术后佩戴手指伸直支具(持续3个月)，2周后开始手指被动屈伸训练，逐渐恢复抓握功能；\n生活指导：避免手掌过度用力、摩擦，每日进行手指拉伸训练，定期复查；\n随访：手术患者术后1周、1个月、3个月复诊，评估伤口愈合及手指功能恢复；保守治疗患者每3个月复诊，监测挛缩进展。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2199,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dd3f161a8b32d29eefaf4b5d341113ac00e7378ae047ed050b8667963fe0bd46","pinyin":"zhangjianmoluansuozheng","initials":"zjmlsz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-aabe7bf38007d4aef263","key":"v1-c9ccc21dfe2a3058|templates-aabe7bf38007d4aef263","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腕手部开放性手术后遗症","category":"门诊病历模板","raw":{"name":"腕手部开放性手术后遗症","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧腕部隐痛伴活动受限1年，加重1月","现病史":"患者1年前因 “右侧桡骨远端骨折” 在外院行 “切开复位内固定术”，术后3个月骨折愈合，拆除内固定。此后出现右侧腕部持续性隐痛，VAS2-3分，腕关节屈伸受限，遇冷、劳累后疼痛加重，外院查腕关节 X 线示 “骨折愈合良好”，予物理治疗，效果差。近1个月因频繁用腕部工作，疼痛加重至 VAS4分，活动度进一步下降，影响日常活动。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往右侧桡骨远端骨折手术史(1年前)，否认其他外伤、慢性病。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧腕部手术瘢痕处(约5cm)无红肿，瘢痕周围压痛 ++，皮下可触及轻度粘连，无明显硬结；\n活动度：腕关节屈曲50°(正常80°)、背伸40°(正常70°)，屈伸过程中瘢痕处牵拉痛，前臂旋转轻度受限；\n特殊试验：腕关节研磨试验阴性(排除关节内损伤)，桡侧应力试验阴性；\n神经系统：右手感觉、肌力正常，病理反射未引出。","辅助检查":"腕关节 X 线片：右侧桡骨远端骨折愈合良好，无骨质增生、关节间隙狭窄；\n腕关节 MRI：右侧腕部皮下软组织轻度粘连，腕关节滑膜轻度增生，无明显神经压迫；\n肌电图：右侧腕部周围神经传导速度正常，排除神经损伤；\n血常规、ESR：均正常，排除感染、炎症。","初步诊断":"右侧腕手部开放性手术后遗症(术后软组织粘连，慢性疼痛)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用氟比洛芬凝胶贴膏 每日1贴(贴于瘢痕处)；\n物理治疗：腕部超声治疗(每次15分钟，每日1次)+ 蜡疗(每次20分钟，每日1次)，松解软组织粘连；\n康复训练：手法松解瘢痕粘连(每周2次)，指导腕关节主动屈伸训练(每次10分钟，每日3组)，逐渐增加活动度；\n生活指导：避免腕部过度劳累、受凉，佩戴腕关节保暖护具(遇冷时)，工作时注意腕部休息；\n神经阻滞：若疼痛持续，超声引导下腕部软组织粘连区域阻滞(0.5% 利多卡因5ml+倍他米松0.5ml)，每月1次，共2次；\n随访：2周后复诊，评估疼痛及活动度，调整康复方案，每3个月复查腕关节 MRI(必要时)。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2200,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"05e47197a64ed6318a9b3734a256636742b226ae09a48f6d40a7bddd462327b8","pinyin":"wanshoubukaifangxingshoushuhouyizheng","initials":"wsbkfxsshyz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-24d849443bf3603f1858","key":"v1-c9ccc21dfe2a3058|templates-24d849443bf3603f1858","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腕尺管综合征","category":"门诊病历模板","raw":{"name":"腕尺管综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧腕部尺侧痛伴右手尺侧麻木3月","现病史":"患者3个月前长期使用鼠标(腕部尺侧持续受压)后出现右侧腕部尺侧隐痛，VAS2分，未重视。2个月前出现右手尺侧(小指、环指尺侧半)麻木，夜间麻木加重，外院查腕关节 X 线无异常，予甲钴胺口服，麻木无缓解。1周前因抓握重物，症状加重，VAS5分，右手骨间肌无力，无法夹纸，今日来院就诊。自发病以来，精神焦虑，睡眠差，食欲正常，体重无变化，二便正常。既往体健，否认腕部外伤、手术史，否认糖尿病。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧腕尺管处(豌豆骨与钩骨之间)压痛 +++，Tinel 征阳性(轻叩腕尺管时，右手尺侧麻木加剧)；\n感觉检查：右手小指、环指尺侧半痛觉减退，触觉迟钝；\n肌力检查：右手骨间肌、小鱼际肌肌力4级(左侧5级)，夹纸试验阳性(双手夹纸时右侧力量弱)；\n活动度：腕关节屈伸基本正常，尺偏时疼痛、麻木加剧。","辅助检查":"腕关节 X 线片：腕关节无骨质增生、畸形，腕尺管区域无骨性狭窄；\n腕关节 MRI：右侧腕尺管处尺神经信号增高(T2WI)，神经轻度增粗，提示神经水肿；\n肌电图：右侧尺神经腕尺管段传导速度减慢(较左侧慢30%)，右手骨间肌可见失神经电位；\n血常规、血糖：均正常，排除糖尿病性神经病变。","初步诊断":"右侧腕尺管综合征(尺神经卡压，伴神经水肿)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；甲钴胺0.5mg 口服 每日3次(4周)；\n支具固定：佩戴右侧腕关节中立位支具(每日佩戴8小时，夜间可取下)，持续3周，减轻神经卡压；\n神经阻滞：超声引导下右侧腕尺管尺神经阻滞(0.5% 利多卡因3ml+倍他米松0.5ml)，每周1次，共2次；\n物理治疗：腕关节尺侧超声波治疗(每次15分钟，每日1次)，促进神经水肿吸收；\n手术评估：若保守治疗3个月无效(麻木无改善、肌力下降)，评估腕尺管松解术指征；\n生活指导：避免腕部尺侧受压(如调整鼠标位置，使用腕托)，减少抓握重物，工作时保持腕关节中立位；\n随访：1周后复诊，评估疼痛及麻木，2周后复查肌电图，监测神经传导改善情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2201,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"88a9093365dd5447f0362efdbaa9904b133f2e5c0693232ea9f5979687c485c8","pinyin":"wanchiguanzonghezheng","initials":"wcgzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4fa9c389c83b7accd2c6","key":"v1-c9ccc21dfe2a3058|templates-4fa9c389c83b7accd2c6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"正中神经返支卡压综合征","category":"门诊病历模板","raw":{"name":"正中神经返支卡压综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧腕部掌侧痛伴右手拇指对掌无力3月","现病史":"患者3个月前长期使用手机(频繁点击屏幕)后出现右侧腕部掌侧隐痛，VAS2分，未重视。2个月前出现右手拇指对掌无力，无法完成 “OK” 手势，外院查腕关节 X 线无异常，予按摩治疗，效果差。1周前因频繁抓握物品，症状加重，VAS4分，右手拇指无法主动对掌，影响握笔、持物，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认腕部外伤、手术史，否认糖尿病，否认药物过敏史，长期使用手机及电脑。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧腕部掌侧(正中神经返支走行区，拇短屈肌起点处)压痛 +++，Tinel 征阳性(轻叩时，拇指对掌无力加重)；\n感觉检查：右手拇指、食指、中指感觉正常(正中神经主干未受累)；\n肌力检查：右手拇对掌肌肌力3级(左侧5级)，拇指外展、屈曲肌力正常；\n特殊试验：拇对掌试验阳性(无法完成拇指与小指对捏动作)，正中神经主干功能试验阴性(排除腕管综合征)。","辅助检查":"腕关节 X 线片：右侧腕关节无骨质异常，正中神经返支区域无骨性压迫；\n腕关节 MRI：右侧腕部掌侧正中神经返支局部信号增高(T2WI)，神经轻度增粗；\n肌电图：右侧正中神经返支传导速度减慢(较左侧慢30%)，右手拇对掌肌可见失神经电位；\n血常规、血糖：均正常，排除糖尿病性神经病变。","初步诊断":"右侧正中神经返支卡压综合征(拇对掌肌功能障碍)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；甲钴胺0.5mg 口服 每日3次(4周)；\n物理治疗：右侧腕部掌侧超声治疗(每次15分钟，每日1次)+ 热疗(每次20分钟，每日2次)，促进神经恢复；\n神经阻滞：超声引导下右侧正中神经返支阻滞(0.5% 利多卡因3ml+倍他米松0.5ml)，每周1次，共2次；\n康复训练：佩戴拇指对掌支具(日常活动时)，疼痛缓解后行拇对掌肌肌力训练(弹力带对抗训练，每次10分钟，每日2组)；\n生活指导：减少手机点击、抓握物品等重复性动作，使用辅助工具(如笔握器)，避免腕部掌侧受压；\n随访：1周后复诊，评估疼痛及拇指功能，2周后复查肌电图，若保守治疗无效，评估神经松解术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2202,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b408780fa6cc453d9e731c82516e1095d12ff424ac50dbfbf69260ff01cae7fb","pinyin":"zhengzhongshenjingfanzhikayazonghezheng","initials":"zzsjfzkyzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7f76a4ee9e30bf7e9d6e","key":"v1-c9ccc21dfe2a3058|templates-7f76a4ee9e30bf7e9d6e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"雷诺综合征","category":"门诊病历模板","raw":{"name":"雷诺综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"双侧手指遇冷变色、疼痛2年，加重3月","现病史":"患者2年前冬季首次出现双侧手指遇冷后苍白、疼痛，VAS2分，保暖后10分钟缓解，未重视。此后每遇冷(如接触冷水、吹冷风)即发作，手指先苍白，数分钟后发紫，伴麻木、疼痛，最后潮红，保暖后逐渐恢复，外院查手指 X 线无异常，予保暖建议，效果差。3个月前症状加重，发作频率增加(每周3-4次)，疼痛加剧至 VAS4分，发作时间延长至30分钟，影响冬季外出活动，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常，无脱发、口腔溃疡等不适。既往体健，否认结缔组织病史，否认外伤、手术史，否认药物过敏史，家族中无类似疾病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：双侧手指皮肤无破溃、畸形，遇冷试验阳性(双手放入4℃冷水中1分钟，手指苍白、发紫，伴疼痛)；\n感觉检查：双侧手指痛觉、触觉正常(非发作期)，发作时感觉迟钝；\n血管检查：双侧桡动脉、尺动脉搏动正常，手指毛细血管充盈时间正常(非发作期)；\n神经系统：双手肌力正常，病理反射未引出。","辅助检查":"手指 X 线片：双侧手指骨质未见异常，关节间隙正常；\n上肢血管超声：双侧手指动脉血流正常(非发作期)，遇冷后血流速度减慢，血管管径缩小；\n血液检查：血常规、血沉、C 反应蛋白、抗核抗体谱均正常，排除结缔组织病；\n冷水试验+握拳试验：均阳性(诱发手指变色、疼痛)，确诊雷诺现象。","初步诊断":"雷诺综合征(双侧，原发性)","处理方案":"药物治疗：硝苯地平缓释片20mg 口服 每日2次(扩张血管)，疗程3个月；复方丹参滴丸10丸 口服 每日3次(改善微循环)；\n物理治疗：上肢温水浴(每次20分钟，每日2次，水温37-40℃)+ 红外线照射(每次15分钟，每日1次)，改善血液循环；\n生活指导：严格保暖(冬季戴手套、穿厚袜，避免接触冷水、吹冷风)，戒烟(避免血管收缩)，避免情绪紧张、劳累；\n避免诱因：禁用血管收缩药物(如麻黄碱)，避免长时间暴露于寒冷环境；\n随访：1个月后复诊，评估发作频率、疼痛程度，调整药物剂量；3个月后复查上肢血管超声、血液检查，排除继发性因素；\n警惕进展：告知患者若出现手指溃疡、麻木加重，立即就诊，排查结缔组织病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2203,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dd934f39510dd26dac670c33b88e6c8c6829ae066eba0bebc51b63ba45470304","pinyin":"leinuozonghezheng","initials":"lnzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3c9cad1920f23b1906e2","key":"v1-c9ccc21dfe2a3058|templates-3c9cad1920f23b1906e2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝关节外侧副韧带损伤","category":"门诊病历模板","raw":{"name":"膝关节外侧副韧带损伤","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧膝关节外侧疼痛伴活动受限4天","现病史":"患者4天前打篮球时被他人撞击膝关节内侧，当即出现右侧膝关节外侧剧痛，VAS5分，膝关节无法完全伸直，休息后疼痛稍缓解，未重视。次日疼痛加重，VAS6分，膝关节外侧肿胀，行走时膝关节内翻(如踩空时)疼痛剧烈，自行外用 “云南白药气雾剂”，效果差。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧膝关节外侧轻度肿胀，腓骨头尖至股骨外髁外侧副韧带走行区压痛 +++，未触及韧带断裂间隙；\n活动度：膝关节屈曲110°(正常135°)、伸直5°(正常0°)，屈伸过程中外侧疼痛加剧；\n特殊试验：膝关节内翻应力试验阳性(屈膝30° 时内翻力作用下外侧疼痛加剧，关节无明显不稳，提示 Ⅱ 度损伤)，Lachman 试验阴性(排除交叉韧带损伤)；\n神经系统：右下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片：膝关节骨质未见骨折、脱位，外侧关节间隙无增宽，排除骨性损伤；\n膝关节 MRI：右侧膝关节外侧副韧带连续性完整，韧带内信号增高(T2WI)，提示部分纤维撕裂(Ⅱ 度损伤)，周围软组织水肿；\n血常规、ESR：白细胞6.1×10⁹/L，ESR5mm/h，均正常，排除感染。","初步诊断":"右侧膝关节外侧副韧带损伤(Ⅱ 度，急性部分纤维撕裂)","处理方案":"药物治疗：塞来昔布胶囊0.2g 口服 每日2次(餐后)，疗程2周；外用双氯芬酸二乙胺乳胶剂 每日3次涂抹患处；\n固定与保护：佩戴膝关节支具(限制内翻动作，允许0-90° 屈伸)，每日佩戴8-10小时，持续3周；\n物理治疗：急性期(1周内)右侧膝关节外侧冷敷(每次15分钟，每日2次)，1周后改热敷(每次20分钟，每日2次)+ 超声波治疗(每次15分钟，每日1次)；\n康复训练：疼痛缓解后(VAS＜3分)开始，指导膝关节被动屈伸训练(每次10分钟，每日2组)，避免内翻动作，3周后逐渐进行肌力训练(直腿抬高)；\n生活指导：避免膝关节负重、剧烈运动(如打篮球、爬楼梯)，行走时注意防滑，避免膝关节内翻受力；\n随访：1周后复诊，评估疼痛及活动度，3周后复查膝关节 MRI，评估韧带修复情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2204,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bd60e37f0b836a788ea578f30b6ccb333c85280aed23cc84a056736dc022797a","pinyin":"xiguanjiewaicefurendaisunshang","initials":"xgjwcfrdss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-567ecf06ee5f92b7556a","key":"v1-c9ccc21dfe2a3058|templates-567ecf06ee5f92b7556a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝关节内侧副韧带损伤","category":"门诊病历模板","raw":{"name":"膝关节内侧副韧带损伤","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左膝关节内侧疼痛伴行走时加重3天。","现病史":"患者3天前下楼梯时不慎踩空，膝关节外翻受力后出现左侧膝关节内侧隐痛，VAS2分，行走时稍加重，休息后缓解，未重视。次日疼痛加重至 VAS4分，膝关节外翻(如侧身行走)时疼痛明显，无肿胀、关节不稳，自行热敷后疼痛无改善。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：左侧膝关节内侧无肿胀，股骨内髁至胫骨内侧髁内侧副韧带走行区压痛 ++，未触及韧带松弛；\n活动度：膝关节屈曲130°(正常135°)、伸直0°(正常0°)，屈伸基本正常，外翻时内侧疼痛加剧；\n特殊试验：膝关节外翻应力试验阳性(屈膝30° 时外翻力作用下内侧疼痛，关节无不稳，提示 Ⅰ 度损伤)，抽屉试验阴性(排除交叉韧带损伤)；\n神经系统：左下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片：膝关节骨质未见异常，内侧关节间隙无增宽；\n膝关节超声：左侧膝关节内侧副韧带回声均匀，周围软组织轻度水肿，无韧带撕裂；\n血常规、ESR：均正常，排除感染。","初步诊断":"左侧膝关节内侧副韧带损伤(Ⅰ 度，急性软组织水肿)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用氟比洛芬凝胶贴膏 每日1贴(贴于内侧疼痛区)；\n物理治疗：急性期(1周内)冷敷(每次15分钟，每日2次)，1周后热敷+超声波治疗(每次15分钟，每日1次)；\n康复训练：避免膝关节外翻动作，疼痛缓解后行直腿抬高训练(每次10分钟，每日3组)，逐渐恢复日常活动；\n生活指导：避免踩空、侧身受力，上下楼梯时扶扶手，减少膝关节外翻负荷；\n随访：1周后复诊，评估疼痛改善情况，若症状加重，复查膝关节 MRI。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2205,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7278ca23c70398a32cb36692c5ce38a53bf6275a675bfe67e000ded583f5314c","pinyin":"xiguanjieneicefurendaisunshang","initials":"xgjncfrdss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0de1ebbeaa49070ea0cd","key":"v1-c9ccc21dfe2a3058|templates-0de1ebbeaa49070ea0cd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝关节创伤性滑膜炎","category":"门诊病历模板","raw":{"name":"膝关节创伤性滑膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧膝关节肿胀、疼痛伴活动受限1周","现病史":"患者1周前跑步时膝关节扭伤后出现右侧膝关节隐痛，VAS2分，未重视。3天后膝关节逐渐肿胀，疼痛加重至 VAS5分，蹲起、上下楼梯时疼痛剧烈，关节活动时可闻及 “沙沙” 声，自行穿刺抽液(抽出淡黄色液体约10ml)后肿胀稍缓解，但2天后再次肿胀。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧膝关节明显肿胀(以髌上囊为主)，皮温正常，膝关节周围压痛 +，浮髌试验阳性(按压髌骨有浮动感)；\n活动度：膝关节屈曲90°(正常135°)、伸直10°(正常0°)，屈伸时因肿胀、疼痛受限；\n特殊试验：研磨试验阴性(排除半月板损伤)，侧方应力试验阴性；\n神经系统：右下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片：膝关节骨质未见异常，关节间隙增宽(提示积液)；\n膝关节超声：右侧膝关节髌上囊、关节腔内可见液性暗区(深度约15mm)，滑膜轻度增厚(厚度约3mm)，无明显钙化；\n关节液检查：穿刺抽出淡黄色清亮液体(约15ml)，白细胞计数1.2×10⁹/L，无细菌、尿酸盐结晶，排除感染、痛风；\n血常规、ESR、CRP：均正常，排除感染、炎症性疾病。","初步诊断":"右侧膝关节创伤性滑膜炎(急性，伴关节积液)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；口服迈之灵片0.3g 每日2次(2周，促进积液吸收)；\n穿刺治疗：超声引导下右侧膝关节穿刺抽液(抽出积液后)，注入0.5% 利多卡因5ml+复方倍他米松0.5ml，弹力绷带加压包扎2天；\n物理治疗：包扎拆除后行膝关节冷敷(急性期1周内)，1周后热敷+低频脉冲电疗(每次20分钟，每日1次)；\n康复训练：佩戴膝关节护膝(减少积液生成)，疼痛缓解后行直腿抬高训练(每次10分钟，每日3组)，避免蹲起、爬楼梯；\n生活指导：避免膝关节负重、剧烈运动，休息时抬高患肢(高于心脏水平)，促进积液回流；\n随访：1周后复诊，评估肿胀、疼痛改善情况，若积液复发，再次穿刺治疗并排查其他病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2206,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"673d09c7290f5e8de53e38c2fd0b06ef79440f79ce7d8e36eb037ba83da33f23","pinyin":"xiguanjiechuangshangxinghuamoyan","initials":"xgjcsxhmy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d85d5e69c5c66ac09fec","key":"v1-c9ccc21dfe2a3058|templates-d85d5e69c5c66ac09fec","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"髌下脂肪垫损伤","category":"门诊病历模板","raw":{"name":"髌下脂肪垫损伤","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"双侧膝关节髌下疼痛2月，加重1周","现病史":"患者2个月前长期蹲跪工作(每日4小时)后出现双侧膝关节髌下隐痛，VAS2分，蹲起时稍加重，休息后缓解，未重视。1周前因频繁爬楼梯(每日6层)，疼痛加重至 VAS5分，右侧明显，膝关节伸直时髌下有 “卡住” 感，行走时偶有 “弹响”，外院查膝关节 X 线无异常，予布洛芬口服，效果差。今日来院就诊。自发病以来，精神稍焦虑，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：双侧膝关节无肿胀，髌下脂肪垫区(髌骨下方、髌韧带两侧)压痛 +++(右侧明显)，按压时可触及硬结；\n活动度：膝关节屈曲120°(正常135°)、伸直0°(正常0°)，屈伸时髌下疼痛，伸直时 “卡住” 感明显；\n特殊试验：髌下脂肪垫挤压试验阳性(膝关节伸直，按压髌骨向下，疼痛加剧)，研磨试验阴性；\n神经系统：双下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片：双侧膝关节骨质未见异常，髌下脂肪垫区无钙化；\n膝关节 MRI：双侧髌下脂肪垫 T2WI 信号增高，右侧明显，提示脂肪垫水肿、损伤，无半月板、韧带异常；\n膝关节超声：双侧髌下脂肪垫增厚，回声不均匀，右侧可见条索状高回声，提示慢性损伤；\n血常规、ESR：均正常，排除感染。","初步诊断":"双侧髌下脂肪垫损伤(慢性劳损，右侧为重)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用双氯芬酸二乙胺乳胶剂 每日3次涂抹髌下区；\n局部阻滞：超声引导下双侧髌下脂肪垫阻滞(右侧0.5% 利多卡因3ml+倍他米松0.5ml，左侧0.5% 利多卡因3ml)，每周1次，共2次；\n物理治疗：双侧膝关节髌下区超声波治疗(每次15分钟，每日1次)+ 热疗(每次20分钟，每日2次)，疗程2周；\n康复训练：疼痛缓解后行膝关节伸直训练(避免脂肪垫挤压)，每次10分钟，每日3组，避免蹲跪、爬楼梯；\n生活指导：调整工作姿势(避免蹲跪)，爬楼梯时借助扶手，佩戴膝关节护具(减少髌下压力)；\n随访：1周后复诊，评估疼痛改善情况，2周后复查膝关节超声，监测脂肪垫水肿吸收。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2207,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"12bac11e05dc99941a49515e5fd9b71e962e1c20d6c530eea1a075adfbd0d70b","pinyin":"binxiazhifangdiansunshang","initials":"bxzfdss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6efdb4a9e9637a5763b0","key":"v1-c9ccc21dfe2a3058|templates-6efdb4a9e9637a5763b0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"髌韧带损伤","category":"门诊病历模板","raw":{"name":"髌韧带损伤","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左膝关节髌韧带处疼痛伴伸膝无力3天。","现病史":"患者3天前打篮球时跳跃落地后，左侧膝关节髌韧带处突发疼痛，VAS4分，伸膝无力，无法完成跳跃动作，休息后稍缓解，未重视。次日疼痛加重至 VAS6分，髌韧带处肿胀，按压时疼痛剧烈，伸膝时需用手辅助，外院查膝关节 X 线无异常，予冷敷处理，效果差。今日来院就诊。自发病以来，精神差，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史，否认药物过敏史，有篮球运动习惯。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：左侧膝关节髌韧带(髌骨下极至胫骨粗隆)止点处(胫骨粗隆)肿胀、压痛 +++，触及韧带紧张度降低；\n活动度：膝关节屈曲110°(正常135°)、伸直5°(正常0°)，伸膝时无力、疼痛加剧；\n特殊试验：伸膝抗阻试验阳性(膝关节伸直位，对抗阻力伸膝时，髌韧带处疼痛剧烈)，抽屉试验阴性；\n肌力检查：左侧伸膝肌力4级(右侧5级)，直腿抬高时髌韧带处疼痛。","辅助检查":"膝关节 X 线片：左侧胫骨粗隆无撕脱骨折，膝关节骨质未见异常；\n膝关节 MRI：左侧髌韧带止点处信号增高(T2WI)，韧带纤维部分撕裂，周围软组织水肿；\n膝关节超声：左侧髌韧带止点处增厚，回声不均匀，局部血流信号增多；\n血常规、ESR：均正常，排除感染。","初步诊断":"左侧髌韧带损伤(止点处部分撕裂，急性损伤)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用氟比洛芬凝胶贴膏 每日1贴(贴于止点处)；\n固定与保护：佩戴膝关节伸直位支具(限制屈膝＞90°)，每日佩戴10-12小时，持续3周，避免伸膝受力；\n物理治疗：急性期(1周内)冷敷(每次15分钟，每日2次)，1周后热敷+超声波治疗(每次15分钟，每日1次)；\n康复训练：3周内避免伸膝抗阻动作，疼痛缓解后行直腿抬高训练(无负重，每次10分钟，每日3组)，6周后逐渐恢复肌力训练；\n生活指导：暂停篮球运动，避免跳跃、爬楼梯，行走时注意保护膝关节，避免再次受力；\n随访：1周后复诊，评估疼痛及伸膝肌力，3周后复查膝关节 MRI，评估韧带修复情况，若撕裂加重，评估手术缝合指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2208,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"04a4e0fa9e4ecc3d40eb283915b4b0b764347c24de92960a9b81eeb0491e3492","pinyin":"binrendaisunshang","initials":"brdss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-544f9f46f3b837807538","key":"v1-c9ccc21dfe2a3058|templates-544f9f46f3b837807538","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鹅足滑囊炎","category":"门诊病历模板","raw":{"name":"鹅足滑囊炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧膝关节内侧下方疼痛2周","现病史":"患者2周前长期骑自行车(每日1小时)后出现右侧膝关节内侧下方隐痛，VAS2分，屈膝时稍加重，休息后缓解，未重视。1周前因频繁蹲起做家务，疼痛加重至 VAS5分，按压膝关节内侧下方时疼痛剧烈，无肿胀，外院查膝关节 X 线无异常，予热敷治疗，效果差。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧膝关节内侧下方(鹅足部位，胫骨内侧髁下方2cm)压痛 +++，无肿胀，触及约1cm×1cm 硬结，按压时疼痛无放射；\n活动度：膝关节屈曲125°(正常135°)、伸直0°(正常0°)，屈膝＞90° 时疼痛加剧；\n特殊试验：鹅足滑囊挤压试验阳性(膝关节屈曲90°，按压鹅足部位，疼痛加剧)，抗阻屈膝试验阳性(对抗阻力屈膝时，鹅足处疼痛)；\n神经系统：右下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片：右侧膝关节骨质未见异常，鹅足部位无钙化；\n膝关节超声：右侧鹅足滑囊增厚，内可见少量液性暗区(深度约3mm)，提示滑囊炎；\n膝关节 MRI：右侧鹅足滑囊 T2WI 高信号，提示滑囊积液、炎症；\n血常规、ESR：均正常，排除感染性滑囊炎。","初步诊断":"右侧鹅足滑囊炎(慢性劳损性，伴少量积液)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用双氯芬酸二乙胺乳胶剂 每日3次涂抹鹅足区；\n局部阻滞：超声引导下右侧鹅足滑囊阻滞(0.5% 利多卡因3ml+倍他米松0.5ml)，每周1次，共2次；\n物理治疗：急性期(1周内)冷敷(每次15分钟，每日2次)，1周后热敷+超声波治疗(每次15分钟，每日1次)；\n康复训练：避免屈膝＞90° 动作，疼痛缓解后行直腿抬高训练(每次10分钟，每日3组)，逐渐恢复日常活动；\n生活指导：调整骑自行车姿势(避免鹅足受压)，减少蹲起、屈膝动作，佩戴膝关节护膝(减少滑囊刺激)；\n随访：1周后复诊，评估疼痛改善情况，2周后复查膝关节超声，监测滑囊积液吸收。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2209,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"87dbfe1cf582d4586ec91861c3f61b1cdf9c41a1e85d9de99f645e9d6fdbe630","pinyin":"ezuhuanangyan","initials":"ezhny","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4b605d39708177ce73eb","key":"v1-c9ccc21dfe2a3058|templates-4b605d39708177ce73eb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"髌下滑囊炎","category":"门诊病历模板","raw":{"name":"髌下滑囊炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左侧膝关节髌骨下方疼痛1周","现病史":"患者1周前长期跪坐(每日2小时)后出现左侧膝关节髌骨下方隐痛，VAS2分，屈伸膝时稍加重，未重视。3天后疼痛加重至 VAS4分，屈伸膝时疼痛明显，行走时偶有 “弹响”，无肿胀，自行外用止痛贴膏，效果差。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：左侧膝关节髌骨下方(髌韧带与胫骨之间)压痛 +++，无肿胀，触及条索状硬结；\n活动度：膝关节屈曲130°(正常135°)、伸直0°(正常0°)，屈伸膝时髌骨下方疼痛，伸直时 “弹响” 明显；\n特殊试验：髌下滑囊挤压试验阳性(膝关节伸直，按压髌骨下方，屈伸膝时疼痛加剧)；\n神经系统：左下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片：左侧膝关节骨质未见异常，髌骨下方无钙化；\n膝关节超声：左侧髌下滑囊增厚，回声不均匀，内可见少量液性暗区(深度约2mm)，提示滑囊炎；\n膝关节 MRI：左侧髌下滑囊 T2WI 高信号，提示滑囊炎症、少量积液；\n血常规、ESR：均正常，排除感染。","初步诊断":"左侧髌下滑囊炎(急性劳损性)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用氟比洛芬凝胶贴膏 每日1贴(贴于髌骨下方)；\n物理治疗：急性期(1周内)冷敷(每次15分钟，每日2次)，1周后热敷+超声波治疗(每次15分钟，每日1次)；\n康复训练：避免跪坐、屈膝受压动作，疼痛缓解后行膝关节伸直训练(每次10分钟，每日3组)，减少 “弹响” 诱发；\n生活指导：避免膝关节长时间屈曲，坐立时在膝关节下方垫软枕，减少髌下滑囊受压；\n随访：1周后复诊，评估疼痛及 “弹响” 改善情况，若症状无缓解，复查膝关节 MRI。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2210,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"01091b706613d1725503d8cf4fe5ca4903c643359b9619fe4fd0b70057283fb6","pinyin":"binxiahuanangyan","initials":"bxhny","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d395f6e5f6cef4f5642d","key":"v1-c9ccc21dfe2a3058|templates-d395f6e5f6cef4f5642d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腘窝囊肿","category":"门诊病历模板","raw":{"name":"腘窝囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧腘窝肿块2月，增大伴隐痛2周","现病史":"患者2个月前偶然发现右侧腘窝处有鸡蛋大小肿块，无疼痛、活动受限，未重视。近2周肿块逐渐增大至拳头大小(约5cm×4cm)，出现轻微隐痛(VAS2分)，屈膝时肿块突出明显，无麻木、下肢肿胀，外院查膝关节 X 线无异常，建议观察，患者担心恶变，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧腘窝处可触及5cm×4cm 囊性肿块，质地柔软，边界清，活动度可，压痛 +，屈膝时肿块增大，伸膝时稍缩小；\n活动度：膝关节屈曲120°(正常135°)、伸直0°(正常0°)，屈伸基本正常，屈膝时肿块压迫感明显；\n特殊试验：肿块透光试验阳性(手电筒照射可见透光)，提示囊性病变；\n血管神经检查：右侧足背动脉搏动正常，小腿后侧感觉、肌力正常，排除血管神经压迫。","辅助检查":"膝关节 X 线片：右侧膝关节骨质未见异常，腘窝处无钙化；\n膝关节超声：右侧腘窝处可见5.2cm×4.1cm 囊性无回声区，内透声好，与关节腔相通，提示腘窝囊肿；\n膝关节 MRI：右侧腘窝囊性肿块，信号均匀，与膝关节腔相连，无明显强化，排除肿瘤；\n血常规、ESR：均正常，排除感染性病变。","初步诊断":"右侧腘窝囊肿(贝克囊肿)","处理方案":"保守治疗：若患者无明显不适，可选择观察，避免按压、挤压肿块；外用双氯芬酸二乙胺乳胶剂 每日2次(若疼痛加重时使用)；\n穿刺治疗：若患者要求处理，超声引导下囊肿穿刺抽液(抽出透明或淡黄色液体)，注入0.5% 利多卡因5ml+倍他米松0.5ml，加压包扎3天；\n物理治疗：穿刺后1周行腘窝区超声波治疗(每次15分钟，每日1次)，预防复发；\n手术评估：若穿刺后复发或肿块持续增大(＞6cm)，评估囊肿切除术指征，告知手术风险(复发、神经血管损伤)；\n生活指导：避免膝关节过度屈曲、剧烈运动，减少囊肿刺激，定期观察肿块大小变化；\n随访：1个月后复诊，超声复查囊肿大小，若出现肿块红肿、疼痛加剧或下肢肿胀，立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2211,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ad4c56ccb21ef5a5624637062333977bfde31e73afbd6b16cd2a16bb5761c483","pinyin":"guowonangzhong","initials":"gwnz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-74d1ff23779f8587972e","key":"v1-c9ccc21dfe2a3058|templates-74d1ff23779f8587972e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胫骨粗隆骨骺炎","category":"门诊病历模板","raw":{"name":"胫骨粗隆骨骺炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左侧胫骨粗隆处疼痛1月，加重2周","现病史":"患者(15岁，男性)1个月前打篮球(每日1小时)后出现左侧胫骨粗隆处隐痛，VAS2分，运动后加重，休息后缓解，未重视。近2周因训练量增加，疼痛加重至 VAS4分，胫骨粗隆处肿胀，按压时疼痛剧烈，无法完成跳跃动作，外院查膝关节 X 线示 “胫骨粗隆骨骺分离”，予休息建议，效果差。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认慢性病，否认药物过敏史，长期参加篮球训练。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：左侧胫骨粗隆处肿胀，压痛 +++，触及骨骺隆起，无畸形；\n活动度：膝关节屈曲125°(正常135°)、伸直0°(正常0°)，屈伸基本正常，伸膝抗阻时胫骨粗隆处疼痛加剧；\n特殊试验：伸膝抗阻试验阳性(膝关节伸直位，对抗阻力伸膝时，胫骨粗隆处疼痛剧烈)；\n神经系统：左下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片(正侧位)：左侧胫骨粗隆骨骺增大、不规则，可见骨碎片，骨骺线增宽，提示胫骨粗隆骨骺炎；\n膝关节超声：左侧胫骨粗隆骨骺周围软组织水肿，骨骺表面不平整，无明显积液；\n血常规、ESR：均正常，排除感染。","初步诊断":"左侧胫骨粗隆骨骺炎(奥 — 施病，青少年型)","处理方案":"休息与保护：暂停篮球训练，避免跑跳、蹲起动作，减少胫骨粗隆受力，持续4-6周；\n药物治疗：塞来昔布胶囊(儿童剂型，按体重计算剂量)口服 每日2次(2周)；外用双氯芬酸二乙胺乳胶剂 每日3次涂抹患处；\n物理治疗：急性期(1周内)冷敷(每次15分钟，每日2次)，1周后热敷+超声波治疗(每次15分钟，每日1次)；\n支具固定：佩戴胫骨粗隆护具(分散受力)，日常活动时佩戴，夜间取下；\n康复训练：疼痛缓解后(VAS＜2分)开始，行直腿抬高训练(无负重，每次10分钟，每日3组)，逐渐恢复肌力，避免过早运动；\n随访：2周后复诊，评估疼痛及肿胀改善情况，4周后复查膝关节 X 线，监测骨骺愈合情况，6周后根据恢复情况决定是否恢复训练。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2212,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9469eb0fabe524a775131ba7b00d7ac363763603432c52cb500944f528c2796e","pinyin":"jingguculongguhouyan","initials":"jgclghy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-29e5c3af5c4a08536330","key":"v1-c9ccc21dfe2a3058|templates-29e5c3af5c4a08536330","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝关节骨性关节炎","category":"门诊病历模板","raw":{"name":"膝关节骨性关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"双侧膝关节疼痛5年，加重1月","现病史":"患者5年前无明显诱因出现双侧膝关节隐痛，VAS2分，上下楼梯时加重，休息后缓解，未系统治疗。此后症状反复发作，每遇劳累、受凉后加重，逐渐出现膝关节畸形(内翻)。1个月前因受凉后疼痛加重至 VAS5分，右侧明显，行走时膝关节有 “骨摩擦音”，夜间翻身时疼痛明显，外院查膝关节 X 线示 “双侧膝关节骨质增生，右侧关节间隙狭窄”，予热敷治疗，效果差。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认风湿免疫病史，否认药物过敏史，年龄62岁。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：双侧膝关节轻度肿胀，右侧明显，内翻畸形(膝内翻约5°)，膝关节周围压痛 +++(内侧关节间隙为主)，触及骨摩擦感；\n活动度：膝关节屈曲100°(正常135°)、伸直5°(正常0°)，屈伸时疼痛加剧，伴 “骨摩擦音”；\n特殊试验：研磨试验阳性(膝关节屈曲，按压胫骨内外旋，疼痛加剧)，侧方应力试验阴性；\n神经系统：双下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片(正侧位)：双侧膝关节间隙变窄(右侧明显)，胫骨平台、股骨髁骨质增生，髁间棘变尖，右侧膝内翻畸形；\n膝关节 MRI：双侧膝关节软骨磨损(右侧 Ⅱ-Ⅲ 度)，半月板轻度退变，关节腔少量积液，滑膜轻度增生；\n骨密度检查：腰椎、髋部骨密度 T 值 -1.5，提示骨量减少；\n血常规、风湿三项：均正常，排除风湿性疾病。","初步诊断":"双侧膝关节骨性关节炎(右侧 Ⅲ 期，左侧 Ⅱ 期，伴膝内翻畸形、骨量减少)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)，疼痛缓解后改为0.2g 每日1次维持；氨基葡萄糖胶囊0.75g 口服 每日2次(3个月，改善软骨代谢)；碳酸钙 D3片600mg 口服 每日1次(补钙，改善骨量)；\n物理治疗：双侧膝关节热敷(每次20分钟，每日2次)+ 红外线照射(每次15分钟，每日1次)，疗程2周；\n康复训练：指导膝关节伸直训练、直腿抬高训练(每次10分钟，每日3组)，增强股四头肌肌力，改善关节稳定性；\n支具与辅助：右侧佩戴膝内翻矫正支具(每日佩戴8小时)，行走时使用手杖(减少膝关节负重)；\n手术评估：若保守治疗3个月无效，右侧疼痛加重影响生活，评估膝关节单髁置换术指征；\n生活指导：控制体重(避免肥胖加重关节负荷)，避免上下楼梯、蹲起，选择游泳、骑自行车等低负重运动；\n随访：1个月后复诊，评估疼痛及畸形改善情况，3个月后复查膝关节 X 线，监测病变进展。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2213,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8239bc7e5df2ca08d920222f967742717c1dbb2437ec365ac0ef8ede0f681b8c","pinyin":"xiguanjieguxingguanjieyan","initials":"xgjgxgjy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-22d926070965963b7bd1","key":"v1-c9ccc21dfe2a3058|templates-22d926070965963b7bd1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"髌骨软化症","category":"门诊病历模板","raw":{"name":"髌骨软化症","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧膝关节髌骨处疼痛3月，加重1月","现病史":"患者3个月前长期屈膝办公(每日8小时)后出现右侧膝关节髌骨处隐痛，VAS2分，上下楼梯时稍加重，休息后缓解，未重视。1个月前疼痛加重至 VAS4分，屈膝久坐(如乘车)后起身时疼痛剧烈，膝关节有 “打软腿” 感，外院查膝关节 X 线无异常，予甲钴胺口服，效果差。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认膝关节外伤、手术史，否认关节炎病史，否认药物过敏史，长期久坐办公。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧膝关节无肿胀，髌骨边缘压痛 +++，按压髌骨上下活动时疼痛加剧；\n活动度：膝关节屈曲125°(正常135°)、伸直0°(正常0°)，屈伸基本正常，屈膝30°-60° 时疼痛明显；\n特殊试验：髌骨研磨试验阳性(膝关节屈曲，按压髌骨并内外旋转，疼痛加剧)，挺髌试验阳性(伸直膝关节，按压髌骨向上，疼痛缓解)；\n肌力检查：右侧股四头肌肌力4级(左侧5级)，直腿抬高时膝关节 “无力感” 明显。","辅助检查":"膝关节 X 线片：右侧膝关节骨质未见异常，髌骨无明显畸形，关节间隙正常；\n膝关节 MRI：右侧髌骨软骨表面不平整，软骨信号降低(T2WI)，提示软骨软化(Ⅱ 度)，无半月板、韧带异常；\n膝关节超声：右侧髌骨软骨厚度变薄，表面粗糙，回声不均匀；\n血常规、ESR：均正常，排除感染、炎症性疾病。","初步诊断":"右侧髌骨软化症(髌骨软骨 Ⅱ 度软化，伴股四头肌肌力下降)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；氨基葡萄糖胶囊0.75g 口服 每日2次(3个月，修复软骨)；\n物理治疗：右侧膝关节超声波治疗(每次15分钟，每日1次)+ 低频脉冲电疗(每次20分钟，每日1次)，促进软骨修复；\n康复训练：重点进行股四头肌肌力训练(直腿抬高、靠墙静蹲，每次10分钟，每日3组)，避免屈膝30°-60° 负重动作；\n支具保护：佩戴髌骨护具(减少髌骨压力)，日常活动时使用，避免屈膝久坐；\n生活指导：调整办公姿势(避免屈膝＞90°)，每工作1小时起身活动5分钟，上下楼梯时扶扶手，减少髌骨受力；\n随访：1个月后复诊，评估疼痛及肌力改善情况，3个月后复查膝关节 MRI，监测软骨修复情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2214,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"10c7d226ad538cb38ca7356b0679d6d5492935358ee915d1b875caf850dac3f9","pinyin":"binguruanhuazheng","initials":"bgrhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-78b910fe835229917c14","key":"v1-c9ccc21dfe2a3058|templates-78b910fe835229917c14","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝关节开放性手术后关节功能障碍","category":"门诊病历模板","raw":{"name":"膝关节开放性手术后关节功能障碍","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧膝关节疼痛伴活动受限6月，加重2月","现病史":"患者6个月前因 “右侧膝关节半月板撕裂” 在外院行 “关节镜下半月板部分切除术”，术后1个月疼痛缓解，但膝关节活动度未恢复，屈膝仅能达90°，无法完全下蹲。近2个月因未规律康复，疼痛加重至 VAS4分，屈膝时关节有 “粘连感”，行走时偶有 “弹响”，外院查膝关节 X 线示 “术后改变，无明显异常”，予物理治疗，效果差。今日来院就诊。自发病以来，精神稍焦虑，食欲正常，体重无变化，二便正常。既往右侧膝关节半月板手术史(6个月前)，否认其他外伤、慢性病。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧膝关节手术瘢痕处(约3cm)无红肿，关节周围压痛 ++，皮下可触及轻度粘连，无明显积液；\n活动度：膝关节屈曲90°(正常135°)、伸直0°(正常0°)，屈膝时粘连感明显，疼痛加剧，无法完全下蹲；\n特殊试验：研磨试验阴性(排除半月板再损伤)，侧方应力试验阴性；\n肌力检查：右侧股四头肌肌力4级(左侧5级)，直腿抬高时力量减弱。","辅助检查":"膝关节 X 线片：右侧膝关节术后改变，骨质未见异常，关节间隙正常；\n膝关节 MRI：右侧膝关节内滑膜轻度增生，关节腔少量积液，半月板术后残端无明显撕裂，关节周围软组织轻度粘连；\n膝关节超声：右侧膝关节内少量积液，滑膜增厚，软组织粘连；\n血常规、ESR：均正常，排除术后感染。","初步诊断":"右侧膝关节开放性手术后关节功能障碍(术后软组织粘连，伴股四头肌肌力下降)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用氟比洛芬凝胶贴膏 每日1贴(贴于瘢痕处)；\n物理治疗：膝关节超声治疗(每次15分钟，每日1次)+ 蜡疗(每次20分钟，每日1次)，松解软组织粘连；\n康复训练：专业康复师手法松解粘连(每周2次)，指导膝关节被动屈伸训练(逐渐增加屈膝角度，每次10分钟，每日3组)，同步进行股四头肌肌力训练(直腿抬高、弹力带抗阻)；\n生活指导：避免膝关节过度负重，每日坚持康复训练，避免久坐，逐渐增加关节活动度；\n神经阻滞：若疼痛持续，超声引导下膝关节周围粘连区域阻滞(0.5% 利多卡因5ml+倍他米松0.5ml)，每月1次，共2次；\n随访：2周后复诊，评估疼痛及活动度改善情况，调整康复方案，2个月后复查膝关节 MRI，监测粘连松解情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2215,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"13fa42f36fb9ff960ea608b97e7915f6109cf69f3eb359b198339b6d5a5e9de5","pinyin":"xiguanjiekaifangxingshoushuhouguanjiegongnengzhangai","initials":"xgjkfxsshgjgnza","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2d2aebc9771c16d3bd6f","key":"v1-c9ccc21dfe2a3058|templates-2d2aebc9771c16d3bd6f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝关节强直","category":"门诊病历模板","raw":{"name":"膝关节强直","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右侧膝关节活动受限1年，加重3月","现病史":"患者1年前因 “右侧膝关节骨折” 在外院行 “切开复位内固定术”，术后未及时康复训练，膝关节活动度逐渐下降，3个月前膝关节完全无法屈伸，呈伸直位僵硬(约5° 屈曲)，伴轻微疼痛(VAS3分)，无法行走，需借助轮椅，外院查膝关节 X 线示 “骨折愈合良好，关节间隙狭窄”，予保守治疗，效果差。今日来院就诊。自发病以来，精神差，食欲下降，体重无变化，二便正常。既往右侧膝关节骨折手术史(1年前)，否认其他外伤、慢性病。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧膝关节无肿胀，关节周围肌肉萎缩(股四头肌明显)，关节间隙压痛 +，膝关节固定于5° 屈曲位，无法活动；\n活动度：膝关节屈曲5°(正常135°)、伸直5°(正常0°)，完全强直，无活动度；\n特殊试验：所有膝关节活动相关试验均无法完成；\n神经系统：右下肢感觉正常，股四头肌肌力3级(废用性下降)，踝、足肌力正常。","辅助检查":"膝关节 X 线片：右侧膝关节骨折愈合良好，关节间隙明显狭窄，关节面骨质增生，关节周围软组织钙化；\n膝关节 CT：右侧膝关节内滑膜增生、钙化，关节间隙消失，关节面融合趋势；\n膝关节 MRI：右侧膝关节软骨完全磨损，半月板退变，关节内粘连严重，软组织萎缩；\n血常规、ESR：均正常，排除感染、炎症性疾病。","初步诊断":"右侧膝关节强直(外伤术后，继发性骨性强直)","处理方案":"术前评估：完善膝关节正侧位 X 线、CT、MRI，评估强直程度，排查手术禁忌证(如感染、严重骨质疏松)；\n手术治疗：多学科会诊(骨科、麻醉科)，评估膝关节置换术或关节松解术指征，告知手术风险(感染、神经损伤、术后活动度不佳)；\n术前康复：术前2周进行股四头肌肌力训练(被动直腿抬高)，改善肌肉条件；\n术后康复：术后佩戴膝关节支具，2周后开始被动屈伸训练，逐渐增加活动度，配合物理治疗(超声、电疗)；\n药物治疗：术前予塞来昔布0.2g 口服 每日2次(2周)，缓解疼痛；术后予抗生素预防感染，镇痛药物控制疼痛；\n生活指导：术前避免膝关节受压，术后遵医嘱进行康复训练，定期复查；\n随访：术前每周复诊，评估手术准备情况；术后1周、1个月、3个月复诊，监测伤口愈合及关节功能恢复。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2216,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"11234dd14fbcf0ecf23cee316f56a343c0cd9f4cf05b7716f6f71a96302799da","pinyin":"xiguanjieqiangzhi","initials":"xgjqz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8e693f04a5391c351fc4","key":"v1-c9ccc21dfe2a3058|templates-8e693f04a5391c351fc4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝关节类风湿关节炎","category":"门诊病历模板","raw":{"name":"膝关节类风湿关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"双侧膝关节疼痛、肿胀伴晨僵3月，加重1周","现病史":"患者3个月前无明显诱因出现双侧膝关节隐痛、肿胀，伴晨僵(持续30分钟)，未重视。1个月前症状加重，晨僵延长至1小时以上，双侧手指掌指关节也出现疼痛、肿胀，外院查类风湿因子阳性，予布洛芬口服，效果差。1周前因受凉，膝关节疼痛加重至 VAS5分，行走困难，夜间痛醒。今日来院就诊。自发病以来，精神差，食欲下降，体重无变化，二便正常，无脱发、口腔溃疡。既往体健，否认膝关节外伤、手术史，否认其他慢性病，否认药物过敏史，家族中无类风湿关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：双侧膝关节明显肿胀(以髌上囊为主)，皮温稍高，膝关节周围压痛 +++，双侧手指掌指关节(2-4指)肿胀、压痛 +；\n活动度：膝关节屈曲90°(正常135°)、伸直10°(正常0°)，屈伸时疼痛加剧，晨僵明显；\n特殊试验：浮髌试验阳性(双侧)，提示关节积液；\n神经系统：双下肢感觉、肌力正常，病理反射未引出。","辅助检查":"膝关节 X 线片：双侧膝关节间隙变窄，关节面骨质疏松，软组织肿胀，无明显骨质增生；\n膝关节 MRI：双侧膝关节滑膜增厚，关节腔大量积液，软骨轻度磨损，骨髓水肿；\n血液检查：类风湿因子(RF)120IU/ml(正常＜20IU/ml)，抗环瓜氨酸肽抗体(抗 CCP)阳性，血沉(ESR)35mm/h，C 反应蛋白(CRP)28mg/L，均升高；\n关节液检查：穿刺抽出淡黄色浑浊液体，白细胞计数8×10⁹/L，以淋巴细胞为主，排除感染。","初步诊断":"双侧膝关节类风湿关节炎(活动期，伴手指关节受累)","处理方案":"药物治疗：\n非甾体抗炎药：塞来昔布0.2g 口服 每日2次(2周)，缓解疼痛、肿胀；\n改善病情抗风湿药：甲氨蝶呤10mg 口服 每周1次(需监测血常规、肝肾功能)，柳氮磺吡啶1.0g 口服 每日2次；\n糖皮质激素：泼尼松10mg 口服 每日1次(短期使用，控制急性炎症，2周后逐渐减量)；\n物理治疗：急性期(1周内)冷敷(每次15分钟，每日2次)，1周后热敷+低频脉冲电疗(每次20分钟，每日1次)，改善关节症状；\n关节穿刺：若关节积液多，超声引导下穿刺抽液，注入复方倍他米松0.5ml，快速缓解肿胀；\n康复训练：疼痛缓解后行直腿抬高训练(每次10分钟，每日3组)，避免关节畸形，保持关节活动度；\n生活指导：注意保暖，避免受凉、劳累，均衡饮食，补充蛋白质、钙，定期监测炎症指标；\n随访：2周后复诊，复查血常规、肝肾功能、ESR、CRP，调整药物剂量；1个月后复查膝关节超声，评估滑膜、积液情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2217,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b6217b3a382edcc60682aed1dccb4160fbe08a6933d6f9209e3258c88eb10ee0","pinyin":"xiguanjieleifengshiguanjieyan","initials":"xgjlfsgjy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a294613fd2c41347a27f","key":"v1-c9ccc21dfe2a3058|templates-a294613fd2c41347a27f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"踝关节陈旧性损伤","category":"门诊病历模板","raw":{"name":"踝关节陈旧性损伤","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右踝疼痛1年，加重1周","现病史":"患者1年前打篮球时右侧踝关节扭伤，当时诊断 “踝关节韧带损伤”，予保守治疗后症状缓解。此后每遇劳累(如行走＞5000步)、受凉后，右侧踝关节即出现隐痛，VAS2-3分，休息后可缓解，未系统治疗。1周前因连续3天长时间行走，疼痛加重至 VAS4分，踝关节酸胀无力，上下楼梯时不稳感明显，外院查踝关节 X 线无异常，予热敷治疗效果差。今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往右侧踝关节扭伤史(1年前)，否认其他外伤、手术史，否认关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧踝关节无明显肿胀，外踝前下方压痛 ++，未触及骨擦感，踝关节稳定性可(距骨倾斜试验阴性)；\n活动度：踝关节背伸10°(正常20°)、跖屈30°(正常40°)，活动时外踝处隐痛，久行后酸胀加重；\n特殊试验：前抽屉试验弱阳性(较左侧松弛度稍增加)，内翻应力试验阴性；\n神经系统：右足感觉、肌力正常，病理反射未引出。","辅助检查":"踝关节 X 线片：右侧踝关节骨质未见骨折、脱位，关节间隙正常，排除骨性损伤；\n踝关节 MRI：右侧踝关节外侧副韧带局部信号增高(T2WI)，韧带连续性完整，提示慢性损伤，关节腔少量积液；\n踝关节超声：右侧外踝前下方软组织回声不均匀，局部血流信号轻度增多；\n血常规、ESR：均正常，排除感染、炎症性疾病。","初步诊断":"右侧踝关节陈旧性损伤(外侧副韧带慢性损伤，伴关节腔少量积液)","处理方案":"药物治疗：塞来昔布胶囊0.2g 口服 每日2次(餐后)，疗程2周；外用双氯芬酸二乙胺乳胶剂 每日3次涂抹外踝处；\n物理治疗：右侧踝关节热敷(每次20分钟，每日2次)+ 超声波治疗(每次15分钟，每日1次)+ 低频脉冲电疗(每次20分钟，每日1次)，疗程2周；\n康复训练：指导踝关节稳定性训练(单腿站立平衡训练，每次20秒，每日3组)，疼痛缓解后行踝关节肌力训练(弹力带抗阻背伸、跖屈，每次10分钟，每日2组)；\n生活指导：避免长时间行走、剧烈运动(如篮球)，选择高帮鞋保护踝关节，受凉时佩戴护踝；\n随访：2周后复诊，评估疼痛及稳定性改善情况，若症状反复，复查踝关节 MRI。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2218,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"148a9f6ac27bdee8ab70041683efd81be851abd3f12b2b1f1fa5a58e5ea4e04b","pinyin":"huaiguanjiechenjiuxingsunshang","initials":"hgjcjxss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-95b86fce788a01ceb4d6","key":"v1-c9ccc21dfe2a3058|templates-95b86fce788a01ceb4d6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性跟腱炎","category":"门诊病历模板","raw":{"name":"慢性跟腱炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"双侧跟腱疼痛6个月，加重1周","现病史":"患者6个月前长期跑步(每日5公里)后出现双侧跟腱处隐痛，VAS2分，晨起时僵硬明显，活动后稍缓解，未重视。此后症状反复发作，每遇跑步、爬楼梯后加重，右侧症状更明显。1周前因参加马拉松训练，疼痛加重至 VAS5分，跟腱处触及硬结，行走时 “僵硬感” 显著，外院查跟腱超声示 “跟腱退变”，予布洛芬口服效果差。今日来院就诊。自发病以来，精神稍焦虑，食欲正常，体重无变化，二便正常。既往体健，否认跟腱外伤、手术史，否认痛风病史，否认药物过敏史，有长期跑步习惯。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：双侧跟腱无肿胀，右侧跟腱中下段(距跟骨止点2cm 处)压痛 +++，触及条索状硬结(约1cm×0.5cm)，左侧压痛 +，无硬结；\n活动度：踝关节跖屈35°(正常40°)，背伸15°(正常20°)，跖屈时跟腱处疼痛加剧；\n特殊试验：跟腱挤压试验阳性(挤压跟腱时疼痛加剧)，Thompson 试验阴性(排除跟腱断裂)；\n神经系统：双足感觉、肌力正常，病理反射未引出。","辅助检查":"跟骨 X 线片：双侧跟骨无骨质增生、骨折，排除骨性病变；\n跟腱超声：右侧跟腱中下段增厚(厚度约6mm，正常＜4mm)，回声不均匀，可见条索状高回声，提示慢性炎症；左侧跟腱轻度增厚，回声尚均匀；\n跟腱 MRI：右侧跟腱中下段 T2WI 信号增高，纤维结构紊乱，无断裂，左侧跟腱信号轻度异常；\n血常规、血尿酸：均正常，排除感染、痛风。","初步诊断":"慢性跟腱炎(双侧，右侧中度，左侧轻度)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用氟比洛芬凝胶贴膏 每日1贴(贴于右侧跟腱痛点)；\n局部阻滞：超声引导下右侧跟腱周围阻滞(0.5% 利多卡因3ml+复方倍他米松0.5ml)，每周1次，共2次；\n物理治疗：双侧跟腱区超声波治疗(每次15分钟，每日1次)+ 冲击波治疗(每周1次，共3次)，促进炎症吸收；\n康复训练：暂停跑步等剧烈运动，疼痛缓解后行跟腱拉伸训练(靠墙弓步拉伸，每次保持30秒，每日3组)，逐渐进行低强度肌力训练(踮脚尖训练，每次10分钟，每日2组)；\n生活指导：选择软底鞋，避免穿高跟鞋，运动前充分热身，避免跟腱过度受力；\n随访：1周后复诊，评估疼痛及硬结改善情况，2周后复查跟腱超声。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2219,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"40a3daa7381495519446e8e7d908e5ff2711d058a8ee9c728c10ce5aac844956","pinyin":"manxinggenjianyan","initials":"mxgjy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2f0c3ed8697a4b137b1f","key":"v1-c9ccc21dfe2a3058|templates-2f0c3ed8697a4b137b1f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"跟痛症","category":"门诊病历模板","raw":{"name":"跟痛症","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左足跟疼痛3个月，加重1周","现病史":"患者3个月前无明显诱因出现左侧足跟隐痛，VAS2分，晨起下床第一步时疼痛明显，行走数步后稍缓解，未重视。此后疼痛逐渐加重，VAS4分，行走＞1000步后疼痛加剧，休息后可缓解，外院查跟骨 X 线示 “跟骨骨刺”，予按摩治疗效果差。1周前因穿硬底鞋行走，疼痛加重，无法长时间站立，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认足跟外伤、手术史，否认痛风、关节炎病史，否认药物过敏史，年龄58岁。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：左侧足跟无肿胀，跟骨结节内侧(足底筋膜起点)压痛 +++，跟骨外侧压痛 +，未触及波动感；\n活动度：踝关节活动基本正常(背伸18°，跖屈38°)，踮脚尖时足跟疼痛加剧；\n特殊试验：足底筋膜牵拉试验阳性(被动背伸脚趾，牵拉足底筋膜时足跟疼痛加剧)；\n神经系统：左足感觉、肌力正常，病理反射未引出。","辅助检查":"跟骨 X 线片：左侧跟骨结节处可见骨刺形成(长度约3mm)，跟骨骨质未见其他异常；\n足底超声：左侧足底筋膜起点增厚(厚度约5mm，正常＜4mm)，回声不均匀，局部血流信号增多，提示足底筋膜炎；\n跟骨 MRI：左侧足底筋膜起点 T2WI 信号增高，跟骨骨髓轻度水肿，无其他异常；\n血常规、血尿酸：均正常，排除感染、痛风。","初步诊断":"左侧跟痛症(足底筋膜炎伴跟骨骨刺形成)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；外用双氯芬酸二乙胺乳胶剂 每日3次涂抹足跟痛点；\n局部阻滞：超声引导下左侧足底筋膜起点阻滞(0.5% 利多卡因3ml+倍他米松0.5ml)，每周1次，共2次；\n物理治疗：左侧足跟区冲击波治疗(每周1次，共3次)+ 热敷(每次20分钟，每日2次)，促进炎症消退；\n康复训练：疼痛缓解后行足底筋膜拉伸训练(毛巾牵拉足底，每次保持30秒，每日3组)，避免踮脚尖、长时间行走；\n生活指导：更换软底、厚底鞋，使用足跟垫减轻压力，避免穿硬底鞋，控制体重(若超重)；\n随访：1周后复诊，评估疼痛改善情况，2周后复查足底超声，监测筋膜炎症吸收。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2220,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fa43544ca8c97ac85067c39dbb697634cd39efe4f148fcaf97a7ae3516488831","pinyin":"gentongzheng","initials":"gtz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-25bf986892b84d2ac8fb","key":"v1-c9ccc21dfe2a3058|templates-25bf986892b84d2ac8fb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"足背腱鞘囊肿","category":"门诊病历模板","raw":{"name":"足背腱鞘囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右足背肿块3个月，增大伴压痛2周","现病史":"患者3个月前偶然发现右侧足背有黄豆大小肿块，无疼痛、活动受限，未重视。近2周肿块逐渐增大至乒乓球大小(约2cm×1.5cm)，按压时出现轻微隐痛(VAS2分)，无足背麻木、踝关节活动受限，穿鞋时偶有挤压感，外院查足背 X 线无异常，建议观察，患者担心恶变，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认足背外伤、手术史，否认囊肿病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧足背(第2-3跖骨间)可触及2cm×1.5cm 囊性肿块，质地柔软，边界清，活动度可，压痛 +，按压时无放射痛；\n活动度：踝关节、足趾活动基本正常，按压肿块时无活动受限；\n特殊试验：肿块透光试验阳性(手电筒照射可见透光)，提示囊性病变；\n神经系统：右足感觉、肌力正常，病理反射未引出。","辅助检查":"足背 X 线片：右侧足背骨质未见异常，肿块处无钙化；\n足背超声：右侧足背可见2.1cm×1.6cm 囊性无回声区，边界清，内透声好，与腱鞘相通，提示腱鞘囊肿；\n足部 MRI：右侧足背囊性肿块，信号均匀，无明显强化，与周围组织无粘连，排除肿瘤；\n血常规、ESR：均正常，排除感染性病变。","初步诊断":"右侧足背腱鞘囊肿","处理方案":"保守治疗：若患者无明显不适，可选择观察，避免按压、挤压肿块；外用双氯芬酸二乙胺乳胶剂 每日2次(若疼痛加重时使用)；\n穿刺治疗：若患者要求处理，超声引导下囊肿穿刺抽液(抽出透明胶冻样液体)，注入0.5% 利多卡因2ml+倍他米松0.5ml，加压包扎3天；\n物理治疗：穿刺后1周行足背区超声波治疗(每次15分钟，每日1次)，预防复发；\n手术评估：若穿刺后复发或肿块持续增大(＞3cm)，评估囊肿切除术指征，告知手术风险(复发、神经损伤)；\n生活指导：选择宽松鞋子，避免足背受压、摩擦，定期观察肿块大小变化；\n随访：1个月后复诊，超声复查囊肿大小，若出现肿块红肿、疼痛加剧，立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2221,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f55ec373aefe984ddad5cf9c0417162491e2eccdb7ff6515167543b55db6c57c","pinyin":"zubeijianqiaonangzhong","initials":"zbjqnz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-526d8b168c79ea5aee9b","key":"v1-c9ccc21dfe2a3058|templates-526d8b168c79ea5aee9b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"踝足部神经卡压综合征","category":"门诊病历模板","raw":{"name":"踝足部神经卡压综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右足背内侧麻木、疼痛2个月，加重1周","现病史":"患者2个月前穿紧身鞋后出现右侧足背内侧隐痛、麻木，VAS2分，脱鞋休息后缓解，未重视。1个月前麻木范围扩大至第1-2趾间，按压足背内侧时疼痛明显，外院查足部 X 线无异常，予甲钴胺口服效果差。1周前因长时间穿高跟鞋，症状加重至 VAS4分，行走时足背内侧刺痛，夜间麻木影响睡眠，今日来院就诊。自发病以来，精神焦虑，睡眠差，食欲正常，体重无变化，二便正常。既往体健，否认踝足部外伤、手术史，否认糖尿病。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧足背内侧(腓深神经走行区，第1-2跖骨间)压痛 +++，Tinel 征阳性(轻叩时足背内侧、第1-2趾间麻木加剧)；\n感觉检查：右侧足背内侧、第1-2趾间痛觉减退，触觉迟钝；\n肌力检查：右侧足背伸肌力正常(腓深神经运动支未受累)，无足下垂；\n活动度：踝关节、足趾活动正常，穿鞋挤压时疼痛加剧。","辅助检查":"足部 X 线片：右侧足部骨质未见异常，第1-2跖骨间无骨性狭窄；\n足部超声：右侧足背第1-2跖骨间腓深神经局部增厚，回声不均匀，周围软组织轻度水肿；\n肌电图：右侧腓深神经感觉支传导速度减慢(较左侧慢28%)，运动支传导正常；\n血常规、血糖：均正常，排除糖尿病性神经病变。","初步诊断":"右侧踝足部神经卡压综合征(腓深神经感觉支卡压，第1-2跖骨间)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；甲钴胺0.5mg 口服 每日3次(4周)；\n物理治疗：右侧足背超声治疗(每次15分钟，每日1次)+ 低频脉冲电疗(每次20分钟，每日1次)，促进神经恢复；\n神经阻滞：超声引导下右侧腓深神经感觉支阻滞(0.5% 利多卡因3ml+倍他米松0.5ml)，每周1次，共2次；\n生活指导：更换宽松、平底鞋，避免足背挤压，减少长时间行走，休息时抬高患肢；\n康复训练：疼痛缓解后行足背感觉训练(轻柔触摸不同质地物品，每次10分钟，每日2组)；\n随访：1周后复诊，评估疼痛及麻木改善情况，2周后复查肌电图，若症状无改善，评估神经松解术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2222,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"71e38594fb3c2a758532f0ae9fba9a33c7ff6208f2ad0f5fcb326a845355e9d1","pinyin":"huaizubushenjingkayazonghezheng","initials":"hzbsjkyzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a8c940ea7a7d22de9c98","key":"v1-c9ccc21dfe2a3058|templates-a8c940ea7a7d22de9c98","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"跖管综合征","category":"门诊病历模板","raw":{"name":"跖管综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右足底麻木、疼痛2个月，加重1周","现病史":"患者2个月前长期站立工作(每日8小时)后出现右侧足底隐痛、麻木，VAS2分，夜间休息后缓解，未重视。1个月前麻木加重，累及足跟，夜间偶有痛醒，外院查足部 X 线无异常，予甲钴胺口服效果差。1周前因连续站立工作，症状加重至 VAS5分，足底 “烧灼感” 明显，行走时需踮脚减轻疼痛，今日来院就诊。自发病以来，精神差，睡眠差，食欲正常，体重无变化，二便正常。既往体健，否认足部外伤、手术史，否认糖尿病，否认药物过敏史，长期从事站立式工作。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧内踝下方跖管处压痛 +++，Tinel 征阳性(轻叩跖管时，足底麻木、烧灼感加剧)；\n感觉检查：右侧足底、足跟痛觉减退，触觉迟钝，痛觉过敏(触碰时 “烧灼感”)；\n肌力检查：右侧足跖屈肌力4级(左侧5级)，足内翻肌力4级，无明显肌肉萎缩；\n特殊试验：跖屈试验阳性(踝关节极度跖屈1分钟，足底麻木、疼痛加剧)。","辅助检查":"足部 X 线片：右侧足部骨质未见异常，跖管区域无骨性狭窄；\n足部 MRI：右侧跖管内胫神经信号增高(T2WI)，神经轻度增粗，周围软组织轻度水肿；\n肌电图：右侧胫神经跖管段传导速度减慢(较左侧慢35%)，足底肌肉可见失神经电位；\n血常规、血糖：均正常，排除糖尿病性神经病变。","初步诊断":"右侧跖管综合征(胫神经卡压，伴足底感觉异常)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；甲钴胺0.5mg 口服 每日3次(4周)；\n物理治疗：右侧跖管区超声治疗(每次15分钟，每日1次)+ 低频脉冲电疗(每次20分钟，每日1次)，促进神经水肿吸收；\n神经阻滞：超声引导下右侧跖管胫神经阻滞(0.5% 利多卡因3ml+倍他米松0.5ml)，每周1次，共2-3次；\n支具固定：佩戴右侧踝关节中立位支具(夜间佩戴，避免跖屈加重卡压)，持续3周；\n生活指导：调整工作姿势，减少站立时间(每1小时休息10分钟)，选择宽松、软底鞋，避免穿高跟鞋；\n手术评估：若保守治疗3个月无效(麻木无改善、肌力下降)，评估跖管松解术指征；\n随访：1周后复诊，评估疼痛及麻木，2周后复查肌电图，监测神经传导改善情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2223,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4d00f878ef01c7d9d618c2e44974dc4977dfe8dc770d1d6377de1a9ed9e23ea4","pinyin":"zhiguanzonghezheng","initials":"zgzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4826d6dc49dd3532e6f6","key":"v1-c9ccc21dfe2a3058|templates-4826d6dc49dd3532e6f6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"Morton 跖骨痛","category":"门诊病历模板","raw":{"name":"Morton 跖骨痛","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右足第3、4趾间疼痛1个月，加重1周","现病史":"患者1个月前穿高跟鞋后出现右侧足第3-4趾间隐痛，VAS2分，脱鞋休息后缓解，未重视。2周前疼痛加重，VAS4分，行走时疼痛明显，偶有 “放射痛” 至第3-4趾端，外院查足部 X 线无异常，予布洛芬口服效果差。1周前因穿窄头鞋，症状加重至 VAS5分，行走时需跛行，按压第3-4跖间时疼痛剧烈，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认足部外伤、手术史，否认痛风病史，否认药物过敏史，有穿高跟鞋习惯。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧足第3-4跖间压痛 +++，可触及黄豆大小硬结(约0.5cm×0.3cm)，按压时疼痛放射至第3-4趾端；\n活动度：足趾活动正常，行走时第3-4跖间疼痛加剧；\n特殊试验：跖间挤压试验阳性(挤压第3-4跖骨，疼痛加剧并放射至趾端)；\n神经系统：右侧第3-4趾感觉减退，其他足趾感觉、肌力正常。","辅助检查":"足部 X 线片：右侧足部跖骨无骨折、骨质增生，第3-4跖间无骨性狭窄；\n足部超声：右侧第3-4跖间可见0.6cm×0.4cm 低回声结节，边界清，提示跖间神经瘤；\n足部 MRI：右侧第3-4跖间 T2WI 高信号结节，与神经走行一致，提示神经瘤；\n血常规、血尿酸：均正常，排除感染、痛风。","初步诊断":"右侧 Morton 跖骨痛(第3-4跖间神经瘤)","处理方案":"药物治疗：塞来昔布0.2g 口服 每日2次(2周)；甲钴胺0.5mg 口服 每日3次(4周)；\n局部阻滞：超声引导下右侧第3-4跖间神经瘤阻滞(0.5% 利多卡因2ml+倍他米松0.5ml)，每周1次，共2次；\n物理治疗：右侧足跖间区超声治疗(每次15分钟，每日1次)+ 低频脉冲电疗(每次20分钟，每日1次)，疗程2周；\n生活指导：更换宽松、宽头、软底鞋，避免穿高跟鞋、窄头鞋，减少行走，避免跖间挤压；\n康复训练：疼痛缓解后行足趾拉伸训练(每次10分钟，每日2组)，避免跖间过度受力；\n手术评估：若保守治疗3个月无效，疼痛影响生活，评估跖间神经瘤切除术指征；\n随访：1周后复诊，评估疼痛及感觉改善情况，2周后复查足部超声，监测神经瘤大小。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2224,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0569d0eb6f16544bcfea2bf3465b7c42979e4956199d7cf628004cee24b2f82e","pinyin":"Morton zhigutong","initials":"Mzgt","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2005641692f4393ab682","key":"v1-c9ccc21dfe2a3058|templates-2005641692f4393ab682","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"足和踝部类风湿关节炎","category":"门诊病历模板","raw":{"name":"足和踝部类风湿关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"双足踝疼痛、肿胀伴晨僵3个月，加重1周","现病史":"患者3个月前无明显诱因出现双侧足和踝关节隐痛、肿胀，伴晨僵(持续30分钟)，未重视。1个月前症状加重，晨僵延长至1小时以上，双侧第2-4跖趾关节也出现肿胀、疼痛，外院查类风湿因子阳性，予布洛芬口服效果差。1周前因受凉，症状加重至 VAS5分，晨僵持续2小时，行走困难，夜间痛醒，今日来院就诊。自发病以来，精神差，食欲下降，体重无变化，二便正常，无脱发、口腔溃疡。既往体健，否认足踝外伤、手术史，否认其他慢性病，否认药物过敏史，家族中无类风湿关节炎病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：双侧足和踝关节明显肿胀，皮温稍高，踝关节周围、双侧第2-4跖趾关节压痛 +++，可见关节畸形(轻度跖屈畸形)；\n活动度：踝关节背伸5°(正常20°)、跖屈25°(正常40°)，足趾屈伸受限，活动时疼痛加剧，晨僵明显；\n特殊试验：浮髌试验阳性(双侧踝关节)，提示关节积液；\n神经系统：双足感觉、肌力正常，病理反射未引出。","辅助检查":"足踝 X 线片：双侧踝关节、跖趾关节间隙变窄，关节面骨质疏松，软组织肿胀，无明显骨质增生；\n足踝 MRI：双侧踝关节、跖趾关节滑膜增厚，关节腔大量积液，软骨轻度磨损，骨髓水肿；\n血液检查：类风湿因子(RF)150IU/ml(正常＜20IU/ml)，抗环瓜氨酸肽抗体(抗 CCP)阳性，血沉(ESR)40mm/h，C 反应蛋白(CRP)35mg/L，均升高；\n关节液检查：穿刺抽出淡黄色浑浊液体，白细胞计数10×10⁹/L，以淋巴细胞为主，排除感染。","初步诊断":"足和踝部类风湿关节炎(双侧，活动期，伴多关节受累)","处理方案":"药物治疗：\n非甾体抗炎药：塞来昔布0.2g 口服 每日2次(2周)，缓解疼痛、肿胀；\n改善病情抗风湿药：甲氨蝶呤10mg 口服 每周1次(需监测血常规、肝肾功能)，来氟米特10mg 口服 每日1次；\n糖皮质激素：泼尼松10mg 口服 每日1次(短期使用，控制急性炎症，2周后逐渐减量)；\n物理治疗：急性期(1周内)冷敷(每次15分钟，每日2次)，1周后热敷+低频脉冲电疗(每次20分钟，每日1次)，改善关节症状；\n关节穿刺：若关节积液多，超声引导下穿刺抽液，注入复方倍他米松0.5ml，快速缓解肿胀；\n康复训练：疼痛缓解后行足踝关节被动活动训练(每次10分钟，每日3组)，避免关节畸形，保持关节活动度；\n生活指导：注意保暖，避免受凉、劳累，均衡饮食，补充蛋白质、钙，定期监测炎症指标及肝肾功能；\n随访：2周后复诊，复查血常规、肝肾功能、ESR、CRP，调整药物剂量；1个月后复查足踝超声，评估滑膜、积液情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2225,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f3c97690861e2d514f93a5e03d5df20b91d492391160d934cf86c7d8e8845bf7","pinyin":"zuhehuaibuleifengshiguanjieyan","initials":"zhhblfsgjy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9bf492c110726f9647cb","key":"v1-c9ccc21dfe2a3058|templates-9bf492c110726f9647cb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"踝关节强直","category":"门诊病历模板","raw":{"name":"踝关节强直","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右踝外伤后活动受限2年，加重1年","现病史":"患者2年前因 “右侧踝关节粉碎性骨折” 在外院行 “切开复位内固定术”，术后未及时康复训练，踝关节活动度逐渐下降，1年前踝关节基本无法屈伸，呈跖屈10° 固定位，伴轻微疼痛(VAS3分)，行走时需借助手杖，呈跛行步态，外院查踝关节 X 线示 “骨折愈合良好，关节间隙消失”，予保守治疗效果差。今日来院就诊，要求改善关节功能。自发病以来，精神差，食欲下降，体重无变化，二便正常。既往右侧踝关节骨折手术史(2年前)，否认其他外伤、慢性病。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧踝关节无肿胀，手术瘢痕处(约8cm)无红肿，关节间隙压痛 +，踝关节固定于跖屈10° 位，无活动度；\n活动度：踝关节背伸0°(正常20°)、跖屈10°(正常40°)，完全强直，无任何活动；\n特殊试验：所有踝关节活动相关试验均无法完成；\n神经系统：右足感觉正常，足跖屈、背伸肌力3级(废用性下降)。","辅助检查":"踝关节 X 线片：右侧踝关节骨折愈合良好，关节间隙完全消失，关节面融合，周围软组织钙化；\n踝关节 CT：右侧踝关节骨性融合，关节面骨质增生，内固定物位置良好，无松动；\n踝关节 MRI：右侧踝关节软骨完全磨损，关节内粘连严重，软组织萎缩；\n血常规、ESR：均正常，排除感染、炎症性疾病。","初步诊断":"右侧踝关节强直(外伤术后继发性骨性强直)","处理方案":"术前评估：完善踝关节正侧位 X 线、CT、MRI，评估强直范围及骨质条件，排查手术禁忌证(如感染、严重骨质疏松)；\n手术治疗：多学科会诊(骨科、麻醉科)，评估踝关节置换术或关节融合松解术指征，告知手术风险(感染、神经血管损伤、术后活动度不佳)；\n术前康复：术前2周进行足踝部肌肉被动训练(按摩、被动活动足趾)，改善肌肉条件，为术后康复做准备；\n术后康复：术后佩戴踝关节支具(根据手术方式确定固定角度)，2周后开始被动屈伸训练，逐渐增加活动度，配合物理治疗(超声、电疗)；\n药物治疗：术前予塞来昔布0.2g 口服 每日2次(2周)，缓解疼痛；术后予抗生素预防感染，镇痛药物控制疼痛；\n生活指导：术前避免踝关节受压，术后严格遵医嘱进行康复训练，定期复查；\n随访：术前每周复诊，评估手术准备情况；术后1周、1个月、3个月复诊，监测伤口愈合及关节功能恢复，调整康复方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2226,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a17bdd674fa74dd1e832af02890425394cd21b88cf92f191cd4dfc54339fddfb","pinyin":"huaiguanjieqiangzhi","initials":"hgjqz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a164cf0dddce9e41659b","key":"v1-c9ccc21dfe2a3058|templates-a164cf0dddce9e41659b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"足拇指外翻","category":"门诊病历模板","raw":{"name":"足拇指外翻","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"双足拇指内侧疼痛5年，畸形加重1周","现病史":"患者5年前无明显诱因出现双侧足拇指轻度外翻，无疼痛，未重视。此后畸形逐渐加重，3年前开始出现行走时足拇指内侧疼痛，VAS2-3分，外院建议穿矫形鞋，效果差。1周前因穿窄头鞋，疼痛加重至 VAS5分，足拇指内侧红肿，无法长时间行走，穿鞋时挤压痛明显，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认足部外伤、手术史，否认关节炎病史，否认药物过敏史，母亲有足拇指外翻病史。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：双侧足拇指外翻畸形，右侧明显，足拇指外翻角约30°(正常＜15°)，第1-2跖骨间角约15°(正常＜10°)，右侧足拇指内侧滑囊处红肿、压痛 +++，可触及骨赘；\n活动度：双侧足拇指屈伸基本正常，外翻时疼痛加剧；\n特殊试验：足拇指挤压试验阳性(挤压足拇指内侧，疼痛加剧)；\n神经系统：双足感觉、肌力正常，病理反射未引出。","辅助检查":"足部 X 线片(负重位)：双侧足拇指外翻畸形，右侧足拇指外翻角30°，第1-2跖骨间角15°，右侧足拇指内侧骨赘形成，第1跖趾关节间隙稍窄；\n足部超声：右侧足拇指内侧滑囊增厚，内可见少量液性暗区，提示滑囊炎；\n血常规、ESR：均正常，排除感染、炎症性疾病。","初步诊断":"足拇指外翻(双侧，右侧中度，左侧轻度，右侧伴内侧滑囊炎)","处理方案":"保守治疗(左侧+右侧急性期)：\n药物：塞来昔布0.2g 口服 每日2次(2周)；外用双氯芬酸二乙胺乳胶剂 每日3次涂抹右侧足拇指内侧；\n矫形：左侧佩戴足拇指外翻矫形器(夜间佩戴)，右侧急性期佩戴拇囊保护垫，减少挤压；\n物理治疗：右侧足拇指内侧超声治疗(每次15分钟，每日1次)，缓解滑囊炎；\n手术评估(右侧)：若保守治疗3个月无效，疼痛影响生活，评估足拇指外翻矫正术指征(如 Chevron 截骨术)，告知手术风险(复发、神经损伤)；\n生活指导：更换宽松、宽头、软底鞋，避免穿高跟鞋、窄头鞋，控制体重(若超重)，减少足部负重；\n康复训练：疼痛缓解后行足拇指拉伸训练(每次10分钟，每日2组)，改善关节活动度；\n随访：2周后复诊，评估疼痛及畸形改善情况，3个月后复查足部 X 线，监测外翻角度变化，决定是否手术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2227,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"72d81298cff13aa9e8d0f2a1c9a09d867f797ffabdb4562cfdbba64cab421c1b","pinyin":"zumuzhiwaifan","initials":"zmzwf","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1d777932c21aef3c8005","key":"v1-c9ccc21dfe2a3058|templates-1d777932c21aef3c8005","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"无菌性足舟骨坏死","category":"门诊病历模板","raw":{"name":"无菌性足舟骨坏死","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右足背疼痛6个月，加重1周","现病史":"患者(12岁，男性)6个月前踢足球时出现右侧足背隐痛，VAS2分，运动后加重，休息后缓解，未重视。3个月前疼痛加重至 VAS3分，足背出现轻微肿胀，按压足舟骨处疼痛明显，外院查足部 X 线示 “足舟骨密度增高”，予休息建议，效果差。1周前因再次踢足球，症状加重至 VAS4分，行走时足背疼痛剧烈，无法运动，今日来院就诊。自发病以来，精神尚可，食欲正常，体重无变化，二便正常。既往体健，否认足部外伤、手术史，否认慢性病，否认药物过敏史，长期参加足球训练。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧足背轻度肿胀(足舟骨区)，足舟骨处压痛 +++，无皮温升高，未触及波动感；\n活动度：踝关节背伸10°(正常20°)、跖屈30°(正常40°)，足趾活动正常，运动时足舟骨处疼痛加剧；\n特殊试验：足舟骨挤压试验阳性(挤压足舟骨，疼痛加剧)；\n神经系统：右足感觉、肌力正常，病理反射未引出。","辅助检查":"足部 X 线片：右侧足舟骨密度增高，骨小梁模糊，形态变扁，周围骨质无明显异常；\n足部 CT：右侧足舟骨骨质密度不均匀，可见囊性变，无骨皮质断裂；\n足部 MRI：右侧足舟骨 T1WI 低信号、T2WI 高信号，提示骨坏死，周围软组织轻度水肿；\n血常规、ESR、碱性磷酸酶：均正常，排除感染、代谢性疾病。","初步诊断":"右侧无菌性足舟骨坏死(Kohler 病，青少年型)","处理方案":"制动与保护：暂停足球等剧烈运动，避免足部负重，佩戴足弓支撑矫形鞋垫，必要时佩戴行走支具(减少足舟骨受力)，持续3-6个月；\n药物治疗：塞来昔布胶囊(儿童剂型，按体重计算剂量)口服 每日2次(2周)；外用双氯芬酸二乙胺乳胶剂 每日3次涂抹足舟骨区；\n物理治疗：右侧足舟骨区超声波治疗(每次15分钟，每日1次)+ 红外线照射(每次20分钟，每日2次)，促进骨修复；\n康复训练：疼痛缓解后行足部肌肉训练(踮脚尖、抓毛巾训练，每次10分钟，每日2组)，避免肌肉萎缩；\n生活指导：选择软底、高帮鞋，避免长时间行走、站立，定期复查影像学，监测骨坏死修复情况；\n随访：1个月后复诊，复查足部 X 线，评估骨密度变化；3个月后复查足部 MRI，监测骨坏死修复进展，根据恢复情况调整治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2228,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ea6c96f306934144e45142f61b01f8eb7f9d95fd307e8f430b78f700d89f0bfd","pinyin":"wujunxingzuzhouguhuaisi","initials":"wjxzzghs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-311997469397e64197b6","key":"v1-c9ccc21dfe2a3058|templates-311997469397e64197b6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"踝足部骨折","category":"门诊病历模板","raw":{"name":"踝足部骨折","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右外踝外伤后疼痛、肿胀、畸形2小时","现病史":"患者2小时前下楼梯时不慎摔倒，右侧外踝着地，当即出现右侧外踝剧痛，VAS9分，伴肿胀、畸形，无法行走，被家人送至我院急诊。急诊查右侧外踝 X 线示 “右侧外踝骨折”，为进一步诊疗收入门诊。自受伤以来，精神差，无昏迷、呕吐，无其他部位疼痛，食欲未进食，二便正常。既往体健，否认踝足部外伤、手术史，否认慢性病。","既往史":"既往体健，否认高血压糖尿病病史。否认肝炎结核等传染病史。否认手术外伤史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视触诊：右侧外踝明显肿胀、畸形(外踝向外侧突出)，皮下瘀青，压痛 ++++，可触及骨擦感，踝关节活动受限；\n活动度：踝关节因疼痛无法活动，被动活动时剧烈疼痛；\n特殊试验：内翻应力试验因疼痛无法完成，足背动脉搏动正常(排除血管损伤)；\n神经系统：右足感觉正常，肌力因疼痛无法准确评估，病理反射未引出。","辅助检查":"踝关节 X 线片(正侧位+斜位)：右侧外踝骨折，骨折线累及踝关节面，骨折远端向外移位约2mm，踝关节间隙正常；\n踝关节 CT：右侧外踝粉碎性骨折，骨折块移位，关节面不平整；\n血常规、凝血功能：均正常，排除出血倾向；\n踝关节超声：右侧外踝周围软组织肿胀，无明显血管损伤。","初步诊断":"右侧踝足部骨折(外踝粉碎性骨折，累及关节面)","处理方案":"紧急处理：予右侧踝关节夹板固定(中立位)，抬高患肢(高于心脏水平)，冷敷(每次15分钟，每2小时1次)，减轻肿胀、疼痛；\n镇痛治疗：盐酸曲马多缓释片100mg 口服 每12小时1次(短期使用，控制剧烈疼痛)；\n手术评估：完善术前检查(心电图、胸片、肝肾功能)，排除手术禁忌证，评估右侧外踝骨折切开复位内固定术指征，告知手术风险(感染、神经血管损伤、骨折不愈合)；\n术后康复：术后佩戴踝关节支具，2周后拆线，开始被动活动训练，6-8周后根据骨折愈合情况逐渐负重；\n生活指导：术前避免足部负重，术后遵医嘱进行康复训练，定期复查 X 线，监测骨折愈合；\n随访：术前每日复诊，评估肿胀、疼痛情况；术后1周、2周、1个月复诊，复查 X 线，调整康复方案，指导负重时间。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2229,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9bfc0b57c1f8cc648901ad9672ff09ab3857c90fbb8a32bfd72203468124e04e","pinyin":"huaizubuguzhe","initials":"hzbgz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8b3fd76dba604bc013c7","key":"v1-c9ccc21dfe2a3058|templates-8b3fd76dba604bc013c7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹壁前皮神经卡压综合征","category":"门诊病历模板","raw":{"name":"腹壁前皮神经卡压综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右下腹壁针刺样疼痛2周","现病史":"患者2周前无明显诱因出现右下腹前壁局部刺痛，呈针刺样，与进食、排便无关，久坐或躯干前屈时疼痛明显，站立伸展后稍缓解，外院按'慢性阑尾炎'予抗感染治疗1周无效，遂来诊。否认发热、恶心呕吐、腹泻便秘。自发病以来精神可，睡眠因夜间翻身牵拉疼痛受影响，食欲二便正常，体重无变化。既往无腹部手术史。从事长期久坐的文员工作，近期常穿高腰紧身裤。","既往史":"既往体健，否认高血压、糖尿病史。否认腹部外伤、手术史（尤其无剖腹产、胆囊切除等）。否认肝炎结核等传染病史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地，无疫区接触史。不吸烟，不饮酒。生活规律，工作以久坐为主。否认食物药物过敏史。","体格检查":"视触诊：右下腹前壁局部无红肿、无包块，腹直肌外缘压痛(+)，疼痛为浅表性，捏起该处皮肤及皮下组织时疼痛加剧（提捏试验阳性），按压深部无固定深压痛；反跳痛（-）；咳嗽、Valsalva动作时疼痛不加重；背部检查脊柱无叩击痛；髂腰肌试验（-）。","辅助检查":"腹部超声：肝、胆、胰、脾、肾及盆腔未见异常，排除腹腔脏器疾病所致腹痛；\n腹壁高频超声：腹壁前皮神经穿出点局部筋膜增厚、神经增粗，无占位性病变；\n肌电图：腹壁前皮神经感觉支传导速度较对侧减慢，无肌源性损害；\n胸部X线片：双肺、胸膜未见异常；\n血常规、血沉、C反应蛋白、尿常规及尿淀粉酶等常规检验，排除感染、炎症及泌尿系统疾病。","初步诊断":"右下腹壁前皮神经卡压综合征","处理方案":"药物治疗：塞来昔布0.2g口服每日1次（7天，餐后服）；甲钴胺0.5mg口服每日3次（2周）；卡马西平0.1g口服每日2次起始（2天，无效可渐加量，用于神经病理性疼痛，监测头晕、皮疹）\n物理治疗：局部超声波治疗（每次10分钟，每日1次，共5次）+ 经皮神经电刺激（TENS，每日1次，每次20分钟，2周）\n注射治疗：1%利多卡因2ml+复方倍他米松0.5ml局部痛点注射1次，1周后无效可重复1次\n生活指导：避免久坐及穿紧身裤，衣裤腰带勿过紧，避免反复弯腰负重\n随诊：1周后复诊评估疗效，2周后疼痛无明显缓解复查腹部CT排除腹内病变"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2230,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0fd907010be604a48056673c6e296e68481e8c175aeb6be61426336767cad257","pinyin":"fubiqianpishenjingkayazonghezheng","initials":"fbqpsjkyzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b23c5bba2d51f15187d6","key":"v1-c9ccc21dfe2a3058|templates-b23c5bba2d51f15187d6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"生殖股神经卡压综合征","category":"门诊病历模板","raw":{"name":"生殖股神经卡压综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左腹股沟及阴囊区烧灼样疼痛1个月","现病史":"患者1个月前于剧烈运动（仰卧起坐及深蹲训练）后出现左侧腹股沟区及阴囊上部烧灼样、针刺样疼痛，久站、跑跳时加重，平卧屈髋后减轻，外院按'腹股沟疝''附睾炎'分别予抗炎治疗均无效。1周前症状向大腿内侧上段放射，阴囊皮肤出现触痛过敏，夜间偶痛醒。自发病以来精神焦虑，睡眠差，食欲二便正常，体重无变化。否认外伤、腹股沟手术史。平素健身训练频繁，近期增加负重训练量。","既往史":"既往体健，否认慢性病史。否认腹股沟疝手术、疝修补术、腹股沟区创伤史。否认肝炎结核病史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地。不吸烟，偶饮酒。无特殊毒物接触史。否认食物药物过敏史。","体格检查":"视触诊：左侧腹股沟区无红肿，无可见包块，腹股沟韧带中点内侧（生殖股神经穿出区）压痛(+)，按压时可诱发阴囊及大腿内侧放射痛；左侧阴囊触痛过敏，捏觉轻度减退；提睾反射两侧对称；咳嗽冲击试验腹股沟管外环口无膨胀冲击感（排除疝）；直腿抬高试验（-）；髋关节屈伸旋转活动正常；股四头肌肌力5级，膝腱反射正常。","辅助检查":"检查计划：患者左腹股沟及阴囊区烧灼样疼痛1个月，发病前有剧烈运动（仰卧起坐及深蹲）史，久站跑跳时加重、平卧屈髋后减轻，外院按腹股沟疝及附睾炎治疗均无效，需完善腹股沟区超声检查，了解有无疝囊、有无肿物及精索结构是否正常，排除腹股沟疝、精索静脉曲张及附睾睾丸病变所致疼痛；患者疼痛向左大腿内侧上段放射，完善腰椎MRI检查，明确L1-L2节段有无椎间盘突出、有无椎管狭窄及神经根受压，排除腰椎源性神经根性疼痛；患者阴囊皮肤触痛过敏、夜间痛醒，完善肌电图及神经传导速度检查，评估左侧生殖股神经感觉传导波幅降低程度与运动传导功能，明确神经卡压诊断并定位卡压节段；患者平素健身训练频繁、近期增加负重训练量，完善骨盆正位X线检查，了解髂前上棘、腹股沟区骨性结构有无异常，排除骨性压迫及应力性损伤；本次拟行神经松解或局部封闭治疗，术前完善血常规、肝肾功能及凝血功能检查，排除感染、贫血、肝肾功能不全及凝血障碍，明确用药与操作禁忌；完善泌尿系超声检查，排除泌尿系结石、附睾炎等所致腹股沟区放射痛；完善疼痛评分及感觉功能评定，动态了解神经功能恢复情况以评估疗效。\n\n（检查清单）\n腹股沟区超声：未见疝囊、未见肿物，精索结构正常；腰椎MRI：L1-2节段无间盘突出、无椎管狭窄；肌电图：左侧生殖股神经感觉传导异常（波幅降低约30%），运动传导正常。","初步诊断":"左侧生殖股神经卡压综合征","处理方案":"药物治疗：普瑞巴林75mg口服每日1次睡前（3天，可渐增至75mg每日2次，用于神经病理性疼痛，监测头晕嗜睡）；甲钴胺0.5mg口服每日3次（4周）；疼痛急性期布洛芬缓释胶囊0.3g口服每日2次（5天，餐后）\n物理治疗：腹股沟区超声波治疗（每日1次，每次10分钟，2周）+ 低频脉冲电疗（每日1次，20分钟，2周）\n注射治疗：超声引导下左侧生殖股神经卡压点阻滞（0.5%利多卡因3ml+复方倍他米松0.5ml），每周1次，共2次\n康复指导：暂停负重深蹲、仰卧起坐等诱发动作2周，避免久站，可佩戴腹股沟护具\n随诊：2周后复诊评估疼痛麻木改善；4周无效且药物难控者考虑外科神经松解术评估，并复查腹盆腔CT排除腹膜后占位"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2231,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9ea38715178c8c07b769c7901c7c8c984a454a96b97c50c4162cacc4a8463ac8","pinyin":"shengzhigushenjingkayazonghezheng","initials":"szgsjkyzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cabdf57a43be5bc59d4f","key":"v1-c9ccc21dfe2a3058|templates-cabdf57a43be5bc59d4f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"股神经返支卡压综合征","category":"门诊病历模板","raw":{"name":"股神经返支卡压综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左膝内侧麻木伴疼痛3周","现病史":"患者3周前长时间跪姿作业（每日约4小时，木工）后出现左膝前内侧至胫骨前内侧条带状麻木感，伴膝周钝痛，屈膝久坐（坐姿超过20分钟）时麻木明显，伸直膝关节或站立行走后缓解，无膝部肿胀。外院按'膝骨关节炎'予塞来昔布口服1周症状无改善，麻木反而加重，遂来诊。自发病以来精神可，睡眠因麻木感易醒，食欲二便正常，体重无变化。否认膝部外伤、手术史，否认腰椎疾病史。","既往史":"既往体健，否认糖尿病（排除周围神经病）、甲状腺功能异常史。否认膝部手术、外伤史。否认肝炎结核病史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地。不吸烟，不饮酒。职业为木工，常有跪姿作业。否认食物药物过敏史。","体格检查":"视触诊：左膝无红肿、无积液，浮髌试验（-）；膝前内侧（缝匠肌与股薄肌间隐神经穿出区）Tinel征阳性（轻叩诱发小腿内侧麻木放射）；感觉检查：左小腿内侧及膝前内侧痛觉减退（较对侧约30%），触觉迟钝；股四头肌肌力5级，膝腱反射正常（排除股神经主干损伤）；腰椎检查无棘突压痛、直腿抬高试验（-）。","辅助检查":"双膝X线：未见骨质增生、关节间隙狭窄等骨关节炎表现；腰椎MRI：无间盘突出；肌电图：左侧隐神经感觉传导速度减慢（35m/s，正常>45m/s），股四头肌肌电图正常（排除股神经主干病变）。","初步诊断":"左膝隐神经髌下支卡压综合征（股神经皮支返支卡压）","处理方案":"药物治疗：塞来昔布0.2g口服每日1次（7天）；甲钴胺0.5mg口服每日3次（4周）；维生素B1 10mg口服每日3次（4周）\n物理治疗：膝内侧超声波治疗（每日1次，每次10分钟，2周）\n注射治疗：超声引导下隐神经卡压点阻滞（0.5%利多卡因2ml+复方倍他米松0.5ml），每周1次，共1-2次\n生活指导：避免跪姿及长时间屈膝作业，工作使用护膝垫，久坐时每30分钟伸膝活动\n随诊：2周后复诊，症状无缓解复查膝关节MRI排除占位，4周无效考虑神经松解评估"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2232,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dc7904ac300c2ea826c43b0bbd644f433ccccae0a3a7b185b351091669d53cb9","pinyin":"gushenjingfanzhikayazonghezheng","initials":"gsjfzkyzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e5319a44f49a17f5060b","key":"v1-c9ccc21dfe2a3058|templates-e5319a44f49a17f5060b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腓肠神经卡压综合征","category":"门诊病历模板","raw":{"name":"腓肠神经卡压综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"右外踝及足外侧麻木伴针刺样痛2周","现病史":"患者2周前因打球时右踝扭伤（轻度内翻）后出现右外踝后方至足外侧缘第4-5趾区麻木，伴间断针刺样疼痛，穿高帮靴、久站或踝关节反复活动后麻木加重，休息抬高患肢后减轻，外院查右踝X线示'未见骨折'，予活血止痛膏外用无效。1周前麻木范围固定，夜间偶感足外侧烧灼。自发病以来精神可，睡眠受影响，食欲二便正常，体重无变化。否认踝部手术史，否认糖尿病、腰椎病史。","既往史":"既往体健，否认糖尿病、下肢血管病史。否认踝关节骨折、手术史。否认肝炎结核病史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地。不吸烟，偶饮酒。平素喜爱球类运动。否认食物药物过敏史。","体格检查":"视触诊：右踝无肿胀畸形，踝关节活动度正常，前抽屉试验（-）、内翻应力试验（-）（排除韧带撕裂）；外踝后方跟腱外侧缘（腓肠神经走行区）Tinel征阳性（轻叩足外侧放射麻木）；感觉检查：右足外侧缘及第4-5趾背侧痛觉减退（约30%），触觉迟钝，两点辨别觉增宽；足内在肌肌力正常，趾屈伸正常（排除腓总/胫神经主干损伤）；踝背伸跖屈肌力5级。","辅助检查":"右踝X线：未见骨折及关节脱位；右踝MRI：未见肌腱断裂、未见占位，腓肠神经走行区轻度水肿；肌电图：右侧腓肠神经感觉传导速度减慢（32m/s），运动神经传导正常。\n\n血常规、血沉、C反应蛋白、空腹血糖及肝肾功能等常规检验，以排除感染、代谢性疾病及全身性疾病所致周围神经病变。","初步诊断":"右腓肠神经卡压综合征（外伤后）","处理方案":"药物治疗：塞来昔布0.2g口服每日1次（7天）；甲钴胺0.5mg口服每日3次（4周）\n物理治疗：外踝后方超声波治疗（每日1次，每次10分钟，2周）+ 蜡疗（每日1次，2周）\n注射治疗：超声引导下腓肠神经卡压点阻滞（0.5%利多卡因2ml+复方倍他米松0.5ml）1次\n康复指导：避免穿高帮紧口靴、久站，踝部保护性支具2周（允许正常行走），肿胀消退后行踝关节功能锻炼（弹力带抗阻背伸跖屈，每日3组×10次）\n随诊：2周后复诊复查肌电图，4周无效考虑神经松解并排查下肢静脉曲张压迫等继发因素"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2233,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f9a121fe22b3a0bf1c1f7f08a2388af545e73f1f89c1e73bf7b6593f081391cd","pinyin":"feichangshenjingkayazonghezheng","initials":"fcsjkyzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cd7fe44f22e7010c7d28","key":"v1-c9ccc21dfe2a3058|templates-cd7fe44f22e7010c7d28","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"足底趾神经卡压综合征","category":"门诊病历模板","raw":{"name":"足底趾神经卡压综合征","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"左足底第2、3趾间疼痛3个月","现病史":"患者3个月前无明显诱因出现左足底第2、3趾蹼间烧灼样疼痛，穿窄头皮鞋行走超过500米即出现，脱鞋休息5-10分钟缓解，为间歇性放电样剧痛，夜间不痛。外院按'跖筋膜炎'予足底按摩、冲击波治疗2次无效。1个月前疼痛加重，发作频繁，需穿宽松运动鞋。自发病以来精神焦虑，睡眠正常，食欲二便正常，体重无变化。否认足部外伤、手术史，否认糖尿病、痛风病史。平素常穿高跟鞋及窄头鞋。","既往史":"既往体健，否认糖尿病、周围神经病史。否认足部手术、骨折史。否认肝炎结核病史。否认食物药物过敏史。","个人史及过敏史":"生于原籍，久居本地。不吸烟，不饮酒。否认食物药物过敏史。","体格检查":"视触诊：左足外观正常，无肿胀畸形；第2、3跖骨头间蹼间隙掌侧压痛(+)，横向挤压第2、3跖骨头时疼痛向足趾放射（Morton挤压试验阳性）；局部Tinel征（-）；跖趾关节活动正常，足背动脉搏动正常，足趾血运良好；感觉检查：第2、3趾蹼间及相邻趾感觉轻度减退；踝背伸试验（-）（排除胫神经卡压）；小腿周径两侧对称。","辅助检查":"检查计划：患者左足底第2、3趾蹼间烧灼样疼痛3个月，穿窄头皮鞋行走超过500米即诱发、脱鞋休息5-10分钟缓解，属典型跖骨头间神经受压表现，首诊即完善左足X线（正斜位）检查，了解有无跖骨骨折、脱位及骨性突起，排除骨性结构异常所致的机械性疼痛；因外院按跖筋膜炎予按摩、冲击波治疗2次无效，且疼痛呈间歇性放电样剧痛、需与跖筋膜炎及跖骨应力性骨折鉴别，完善足部MRI检查明确第2、3跖骨间有无趾神经瘤样低信号结节、跖筋膜有无增厚，以明确卡压部位与范围；为客观评估神经受损程度，查肌电图及神经传导速度测定，了解左足底内侧神经感觉传导速度有无减慢，排除糖尿病周围神经病、腰椎间盘突出所致神经根性疼痛等其他病因；患者平素常穿高跟鞋及窄头鞋，完善足部负重位X线及足弓测量，评估有无拇外翻、跖骨排列异常等足部力学失衡因素，指导鞋具矫正方案；本病多为门诊诊疗，完善血常规、凝血功能及肝肾功能检查，排除感染、贫血及凝血异常，为后续局部封闭或神经松解手术做准备；查空腹血糖及糖化血红蛋白，排除糖尿病所致周围神经病变；若保守治疗3个月无效、疼痛影响行走而拟行趾神经瘤切除术，则术前完善心电图、胸部X线及感染筛查；术后定期复查足部X线及肌电图，评估神经功能恢复情况。\n\n（检查清单）\n左足X线：未见骨折、脱位，跖骨排列正常，无骨性突起；足部MRI：第2、3跖骨间可见低信号结节样影（直径约6mm，符合趾神经瘤改变），跖筋膜无增厚；肌电图：左足底内侧神经感觉传导轻度减慢。","初步诊断":"左足底趾间神经卡压综合征（第2、3趾蹼，Morton神经瘤）","处理方案":"药物治疗：塞来昔布0.2g口服每日1次（7天）；甲钴胺0.5mg口服每日3次（4周）；疼痛剧烈夜间加用普瑞巴林75mg口服睡前（3天起，渐加量）\n物理治疗：足底局部超声波治疗（每日1次，10分钟，2周）\n注射治疗：超声引导下跖骨间注射（0.5%利多卡因1.5ml+复方倍他米松0.5ml）1次，2周后可重复1次\n矫形处理：改用宽头鞋、加跖骨垫（第2、3跖骨头后方）抬高减压，避免穿高跟鞋及窄头鞋2个月\n随诊：2周后复诊评估；注射2次仍无效、症状持续>6个月者，评估手术切除趾间神经瘤；症状控制后建议步态及鞋具调整随访"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2234,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ca3c7117d5291ba67dc402c4276418d36b48fca47831cc09e492ae368fb55494","pinyin":"zudizhishenjingkayazonghezheng","initials":"zdzsjkyzhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-08baafd818fa490061c4","key":"v1-c9ccc21dfe2a3058|templates-08baafd818fa490061c4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑梗塞后遗症","category":"住院病历模板","raw":{"name":"脑梗塞后遗症","category":"住院病历模板","case":{"case_name":"病例1：患者，男，68岁","templates":{"入院记录":"主诉：左侧肢体活动不利2年，加重伴言语不清1周。\n\n现病史：患者2年前无明显诱因突发左侧肢体活动不利，表现为左上肢抬举无力、左下肢行走拖曳，伴言语含糊，无头痛呕吐，无意识障碍，无抽搐。当时至外院就诊，头颅CT示\"右侧基底节区脑梗塞\"，予抗血小板、改善循环、营养神经等治疗（具体不详），病情稳定后出院，遗留左侧肢体活动不利，左上肢肌力3级，左下肢肌力4级，可行走但跛行，言语稍含糊，日常生活部分自理。长期口服阿司匹林肠溶片100mg qd、阿托伐他汀钙片20mg qn。近1周患者自觉左侧肢体活动不利加重，左上肢不能抬举，左下肢行走困难，需家人搀扶，伴言语不清加重，饮水偶有呛咳，无头痛头晕，无恶心呕吐，无胸闷胸痛，无呼吸困难，无发热咳嗽，无抽搐。发病以来，患者精神欠佳，食欲尚可，睡眠一般，大小便正常，体重近1月下降约2kg。\n\n既往史：高血压病史10年，最高血压180/100mmHg，长期口服硝苯地平缓释片20mg bid，血压控制在140-150/80-90mmHg。2型糖尿病病史8年，长期口服二甲双胍0.5g tid，血糖控制欠佳，空腹血糖8-10mmol/L。否认冠心病、房颤病史。否认肝炎、结核等传染病史。否认手术、外伤、输血史。否认食物、药物过敏史。\n\n个人史及过敏史：生于本地，久居本地，无疫区旅居史。吸烟40年，每日20支，未戒烟。饮酒30年，每日白酒2两，已戒1年。否认工业毒物、粉尘、放射性物质接触史。否认药物过敏史。\n\n体格检查：T 36.5℃，P 78次/分，R 18次/分，BP 150/95mmHg。发育正常，营养中等，神志清楚，精神欠佳，构音障碍，查体合作。全身皮肤黏膜无黄染、皮疹及出血点，浅表淋巴结未触及肿大。头颅无畸形，眼睑无水肿，结膜无充血，巩膜无黄染，双瞳孔等大等圆，直径约3mm，对光反射灵敏。耳鼻未见异常，口唇无紫绀，伸舌左偏，咽无充血，扁桃体无肿大。颈软，无抵抗，颈静脉无怒张，气管居中，甲状腺未触及肿大。胸廓对称无畸形，双肺呼吸音清，未闻及干湿性啰音。心前区无隆起，心尖搏动位于第五肋间左锁骨中线内0.5cm，未触及震颤，心界不大，心率78次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，未见胃肠型及蠕动波，未触及包块，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常，4次/分。肛门直肠及外生殖器未查。脊柱生理弯曲存在，无畸形，活动自如。\n\n专科检查：神志清楚，构音障碍，记忆力、计算力、定向力粗测正常。双侧额纹对称，左侧鼻唇沟变浅，伸舌左偏。左上肢肌力2级，左下肢肌力3级，右侧肢体肌力5级。左侧肢体肌张力增高（Ashworth 2级），右侧正常。左侧肱二头肌、肱三头肌、膝反射、跟腱反射亢进（+++），右侧正常。左侧Babinski征阳性，右侧阴性。左侧偏身痛觉减退，右侧正常。指鼻试验、跟膝胫试验左侧不合作，右侧稳准。Romberg征不合作。\n\n辅助检查：头颅CT（外院，2年前）：右侧基底节区低密度灶，考虑脑梗塞。\n头颅MRI（本院，2026-09-01）：右侧基底节区陈旧性脑梗塞，右侧脑室旁新发腔隙性脑梗塞。\n血糖：8.5mmol/L（空腹）。\n血脂：总胆固醇5.8mmol/L，甘油三酯2.1mmol/L，低密度脂蛋白3.6mmol/L。\n肝肾功能、电解质、凝血功能正常。\n\n初步诊断：\n1. 脑梗塞后遗症\n2. 新发腔隙性脑梗塞（右侧脑室旁）\n3. 高血压病3级（很高危）\n4. 2型糖尿病\n\n处理方案：\n1. 神经内科护理常规，一级护理，低盐低脂糖尿病饮食，留陪护，防跌倒、防误吸。\n2. 抗血小板：阿司匹林肠溶片100mg qd 口服。\n3. 调脂稳定斑块：阿托伐他汀钙片20mg qn 口服。\n4. 改善循环：丁苯酞软胶囊0.2g tid 口服；银杏叶提取物片40mg tid 口服。\n5. 营养神经：甲钴胺片0.5mg tid 口服；依达拉奉注射液30mg + NS 100ml 静滴 bid。\n6. 控制血压：硝苯地平缓释片20mg bid 口服，目标血压<140/90mmHg。\n7. 控制血糖：二甲双胍0.5g tid 口服，监测血糖，目标空腹<7mmol/L，餐后2h<10mmol/L。\n8. 康复治疗：病情稳定后尽早行肢体功能锻炼、言语训练、吞咽功能训练。\n9. 完善检查：头颅MRI+DWI（目的：明确责任病灶部位、范围及有无新发梗死，为病因分型与二级预防方案提供依据）、颈动脉超声（目的：评估颅内外动脉粥样硬化斑块与狭窄程度，明确TOAST病因分型）、心脏超声（目的：筛查心房颤动、心腔内血栓及瓣膜病变等心源性栓塞病因）、同型半胱氨酸（目的：评估高同型半胱氨酸血症这一独立危险因素，为补充叶酸、维生素B12治疗提供依据）、糖化血红蛋白（目的：评估血糖长期控制水平，明确糖尿病这一脑血管病危险因素并指导降糖方案）。\n10. 健康教育：戒烟，控制血压血糖血脂，定期复查。","首次病程记录":"2026-09-01 10:30 首次病程记录\n\n患者，男，68岁，因\"左侧肢体活动不利2年，加重伴言语不清1周\"入院。\n\n一、病例特点：\n1. 老年男性，68岁，慢性病程急性加重。\n2. 临床表现：左侧肢体活动不利2年，加重伴言语不清1周。2年前脑梗塞病史，遗留左侧肢体活动不利。近1周症状加重，左上肢不能抬举，左下肢需搀扶行走，伴言语不清加重，饮水偶呛。\n3. 既往史：高血压10年、2型糖尿病8年，长期服药，控制欠佳。吸烟40年。\n4. 体格检查：BP 150/95mmHg，神志清楚，构音障碍，左侧鼻唇沟变浅，伸舌左偏。左上肢肌力2级，左下肢肌力3级，左侧肌张力增高，左侧腱反射亢进，左侧Babinski征阳性，左侧偏身痛觉减退。\n5. 辅助检查：头颅MRI示右侧基底节区陈旧性脑梗塞，右侧脑室旁新发腔隙性脑梗塞。空腹血糖8.5mmol/L，血脂升高。\n\n二、拟诊讨论：\n（一）初步诊断：\n1. 脑梗塞后遗症\n2. 新发腔隙性脑梗塞（右侧脑室旁）\n3. 高血压病3级（很高危）\n4. 2型糖尿病\n\n（二）诊断依据：\n1. 脑梗塞后遗症/新发腔隙性脑梗塞：老年男性，有高血压、糖尿病、吸烟等危险因素；2年前脑梗塞病史，遗留左侧肢体活动不利；近1周症状加重；查体见左侧中枢性面舌瘫、偏瘫、偏身感觉障碍、病理征阳性；头颅MRI证实右侧基底节区陈旧梗塞+右侧脑室旁新发腔梗。\n2. 高血压病3级（很高危）：高血压病史10年，最高180/100mmHg，合并糖尿病、脑梗塞，分层为很高危。\n3. 2型糖尿病：糖尿病病史8年，长期口服降糖药，空腹血糖8.5mmol/L。\n\n（三）鉴别诊断：\n1. 脑出血：多在活动或情绪激动时发病，头痛、呕吐、意识障碍多见，头颅CT可见高密度出血灶。本患者慢性病程急性加重，无头痛呕吐，头颅MRI未见出血，可排除。\n2. 脑栓塞：起病急骤，数秒至数分钟达高峰，常有房颤等栓子来源。本患者症状逐渐加重，无房颤病史，不支持，但需完善心脏超声排除。\n3. 颅内占位性病变：慢性起病，进行性加重，可有头痛、视乳头水肿等颅内压增高表现，头颅MRI可见占位效应。本患者急性加重，MRI未见占位，可排除。\n4. 低血糖反应：糖尿病患者可出现肢体无力、言语不清，但多伴心慌、出汗、饥饿感，血糖低于2.8mmol/L，补糖后迅速缓解。本患者血糖8.5mmol/L，可排除。\n\n三、诊疗计划：\n1. 神经内科护理常规，一级护理，低盐低脂糖尿病饮食，留陪护。\n2. 抗血小板、调脂、改善循环、营养神经治疗。\n3. 控制血压、血糖。\n4. 完善检查：头颅MRI+DWI（目的：明确责任病灶部位、范围及有无新发梗死，为病因分型与二级预防方案提供依据）、颈动脉超声（目的：评估颅内外动脉粥样硬化斑块与狭窄程度，明确TOAST病因分型）、心脏超声（目的：筛查心房颤动、心腔内血栓及瓣膜病变等心源性栓塞病因）、同型半胱氨酸（目的：评估高同型半胱氨酸血症这一独立危险因素，为补充叶酸、维生素B12治疗提供依据）、糖化血红蛋白（目的：评估血糖长期控制水平，明确糖尿病这一脑血管病危险因素并指导降糖方案）。\n5. 病情稳定后康复治疗。\n6. 健康教育，戒烟。\n\n医师签名：X","主治查房记录":"2026-09-02 09:00 主治医师查房记录\n\n今日主治医师X查房，患者诉左侧肢体活动不利较前稍好转，左上肢可轻微抬举，言语不清改善不明显，饮水呛咳减轻。无头痛头晕，无恶心呕吐，无胸闷胸痛，无发热。\n\n查体：T 36.4℃，P 76次/分，R 18次/分，BP 145/90mmHg。神志清楚，构音障碍。左侧鼻唇沟变浅，伸舌左偏。左上肢肌力2+级，左下肢肌力3+级，左侧肌张力增高，左侧腱反射亢进，左侧Babinski征阳性。双肺呼吸音清，心率76次/分，律齐。腹软，无压痛。\n\n辅助检查回报：\n糖化血红蛋白：7.8%。\n同型半胱氨酸：18μmol/L（升高）。\n颈动脉超声：双侧颈动脉内膜增厚，左侧颈动脉斑块形成（软斑）。\n心脏超声：左室舒张功能减退，未见附壁血栓，EF 58%。\n\n主治医师意见：\n1. 患者脑梗塞后遗症合并新发腔隙性脑梗塞诊断明确，目前治疗有效，继续当前方案。\n2. 患者同型半胱氨酸升高，为脑卒中独立危险因素，加用叶酸片0.8mg qd、维生素B6 10mg tid、维生素B12 0.5mg tid口服。\n3. 颈动脉超声示软斑，需强化调脂，阿托伐他汀加量至40mg qn，注意监测肝功能、肌酶。\n4. 血压控制尚可，继续当前降压方案，目标血压<140/90mmHg。\n5. 血糖控制欠佳，糖化血红蛋白7.8%，建议加用格列美脲2mg qd，监测血糖。\n6. 患者饮水呛咳，注意防误吸，必要时行吞咽功能评估，给予吞咽训练。\n7. 病情稳定，可开始康复治疗，包括肢体功能锻炼、言语训练、吞咽训练。\n8. 向患者及家属交代病情，脑卒中二级预防重要性，戒烟，控制危险因素。\n\n医师签名：X","主任查房记录":"2026-09-04 10:00 主任医师查房记录\n\n今日主任医师X查房，详细询问病史并查体。患者诉左侧肢体活动不利继续好转，左上肢可抬至胸前，左下肢可独立站立，言语较前清晰，饮水无呛咳。无不适主诉。\n\n查体：T 36.3℃，P 74次/分，R 17次/分，BP 140/85mmHg。神志清楚，言语较前清晰。左侧鼻唇沟稍浅，伸舌稍左偏。左上肢肌力3级，左下肢肌力4级，左侧肌张力较前降低，左侧腱反射亢进，左侧Babinski征阳性。双肺呼吸音清，心率74次/分，律齐。\n\n复查：肝功能正常，肌酸激酶正常。空腹血糖6.8mmol/L。\n\n主任医师意见：\n1. 患者诊断明确：脑梗塞后遗症、新发腔隙性脑梗塞、高血压病3级、2型糖尿病。经治疗后症状改善，治疗有效。\n2. 脑卒中二级预防是关键：\n - 抗血小板：阿司匹林100mg qd长期服用，注意有无出血倾向。\n - 调脂：阿托伐他汀40mg qn，目标LDL-C<1.8mmol/L，定期监测肝功能、肌酶。\n - 降压：目标<140/90mmHg，可耐受可降至<130/80mmHg。\n - 降糖：目标糖化血红蛋白<7%，避免低血糖。\n - 降同型半胱氨酸：叶酸+B族维生素。\n3. 康复治疗应尽早、持续、规范：\n - 肢体功能训练：被动活动→主动辅助→主动活动，循序渐进。\n - 言语训练：发音训练、复述训练、命名训练。\n - 吞咽训练：冰刺激、空吞咽、摄食训练。\n - 日常生活活动能力训练：穿衣、进食、洗漱、转移。\n4. 患者吸烟40年，必须戒烟，吸烟是脑卒中重要危险因素，家属监督。\n5. 预防并发症：防跌倒、防误吸、防压疮、防深静脉血栓、防肺部感染。\n6. 患者及家属需掌握脑卒中识别（FAST），如有新发症状立即就诊。\n7. 预计住院10-14天，出院后继续康复，定期门诊随访。\n\n医师签名：X","病程记录":"2026-09-03 09:00 病程记录\n\n患者诉左侧肢体活动不利较前好转，左上肢可轻微抬举，左下肢可在搀扶下短距离行走，言语不清稍改善，饮水偶有呛咳。无头痛头晕，无恶心呕吐，无胸闷胸痛，无发热咳嗽。饮食睡眠可，大小便正常。\n\n查体：T 36.5℃，P 76次/分，R 18次/分，BP 142/88mmHg。神志清楚，构音障碍。左侧鼻唇沟变浅，伸舌左偏。左上肢肌力2+级，左下肢肌力3+级，左侧肌张力增高，左侧腱反射亢进，左侧Babinski征阳性。双肺呼吸音清，心率76次/分，律齐。腹软，无压痛。\n\n治疗同前，继续抗血小板、调脂、改善循环、营养神经、控制血压血糖。加用叶酸、维生素B6、B12降同型半胱氨酸。阿托伐他汀加量至40mg qn。开始康复治疗。\n\n患者病情稳定，继续观察。\n\n医师签名：X\n\n2026-09-05 09:00 病程记录\n\n患者诉左侧肢体活动不利继续好转，左上肢可抬至胸前，左下肢可独立站立，言语较前清晰，饮水无呛咳。无不适主诉。饮食睡眠可，大小便正常。\n\n查体：T 36.4℃，P 74次/分，R 17次/分，BP 138/85mmHg。神志清楚，言语较前清晰。左侧鼻唇沟稍浅，伸舌稍左偏。左上肢肌力3级，左下肢肌力4级，左侧肌张力较前降低，左侧腱反射亢进，左侧Babinski征阳性。双肺呼吸音清，心率74次/分，律齐。\n\n复查肝功能、肌酶正常。空腹血糖6.8mmol/L。治疗同前，继续康复训练。患者病情稳定，继续观察。\n\n医师签名：X","出院记录":"入院日期：2026-09-01\n出院日期：2026-09-12\n住院天数：11天\n\n入院诊断：\n1. 脑梗塞后遗症\n2. 新发腔隙性脑梗塞（右侧脑室旁）\n3. 高血压病3级（很高危）\n4. 2型糖尿病\n\n入院情况：患者，男，68岁，因\"左侧肢体活动不利2年，加重伴言语不清1周\"入院。查体：BP 150/95mmHg，神志清楚，构音障碍，左侧鼻唇沟变浅，伸舌左偏。左上肢肌力2级，左下肢肌力3级，左侧肌张力增高，左侧腱反射亢进，左侧Babinski征阳性，左侧偏身痛觉减退。头颅MRI示右侧基底节区陈旧性脑梗塞，右侧脑室旁新发腔隙性脑梗塞。\n\n诊疗经过：入院后完善相关检查，予抗血小板（阿司匹林100mg qd）、调脂稳定斑块（阿托伐他汀40mg qn）、改善循环（丁苯酞、银杏叶提取物）、营养神经（甲钴胺、依达拉奉）、控制血压（硝苯地平缓释片20mg bid）、控制血糖（二甲双胍+格列美脲）、降同型半胱氨酸（叶酸+B6+B12）等治疗。病情稳定后行肢体功能锻炼、言语训练、吞咽训练等康复治疗。\n\n出院情况：患者左侧肢体活动不利明显好转，左上肢肌力3级，左下肢肌力4级，言语清晰，饮水无呛咳，可独立行走。BP 135/82mmHg，空腹血糖6.5mmol/L。\n\n出院诊断：\n1. 脑梗塞后遗症\n2. 腔隙性脑梗塞（右侧脑室旁，恢复期）\n3. 高血压病3级（很高危）\n4. 2型糖尿病\n5. 高同型半胱氨酸血症\n6. 颈动脉斑块\n\n出院医嘱：1. 用药指导：\n - 阿司匹林肠溶片100mg qd（长期，注意有无出血）\n - 阿托伐他汀钙片40mg qn（长期，3月后复查肝功能、肌酶、血脂）\n - 硝苯地平缓释片20mg bid（监测血压）\n - 二甲双胍0.5g tid + 格列美脲2mg qd（监测血糖）\n - 叶酸0.8mg qd + 维生素B6 10mg tid + 甲钴胺0.5mg tid\n - 丁苯酞软胶囊0.2g tid（服用3个月）\n2. 康复训练：继续肢体功能锻炼、言语训练、日常生活活动能力训练，建议康复科门诊随访。\n3. 生活方式：戒烟限酒，低盐低脂糖尿病饮食，适当运动，控制体重。\n4. 复诊：2周后门诊复查血压、血糖、血脂；1月后复查肝肾功能；3月后复查颈动脉超声。\n5. 注意事项：如出现新发肢体无力、言语不清、头痛、意识障碍等，立即就诊。\n6. 家庭护理：防跌倒、防误吸，家属协助康复训练。\n\n医师签名：X\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n","医患沟通记录":"时间：2026-09-01 15:00\n地点：神经内科医生办公室\n参加人员：患者、患者家属（妻子）、主管医师X\n\n沟通内容：\n1. 病情告知：患者目前诊断为脑梗塞后遗症合并新发腔隙性脑梗塞，同时有高血压、糖尿病。目前左侧肢体活动不利、言语不清，病情可能进一步进展，也可能出现出血转化、脑水肿、肺部感染、深静脉血栓、压疮等并发症。\n2. 治疗方案：予抗血小板、调脂、改善循环、营养神经、控制血压血糖等治疗，病情稳定后康复治疗。治疗过程中可能出现药物不良反应（如胃肠道反应、肝功能异常、肌肉酸痛、出血等）。\n3. 检查目的：完善头颅MRI、颈动脉超声、心脏超声等检查，明确病因和血管情况，指导治疗和二级预防。\n4. 预后说明：脑梗塞后遗症恢复需要较长时间，左侧肢体功能可能无法完全恢复正常，需长期康复训练。脑卒中复发风险高，需严格控制血压、血糖、血脂，戒烟，长期服药。\n5. 费用说明：住院及康复治疗费用较高，部分药物和康复项目可能不在医保报销范围。\n6. 患者及家属表示理解，同意治疗方案，积极配合治疗和康复。\n\n患者/家属签字：X\n医师签字：X"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2235,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fcae496dfb2faf5d280d8348153030d57e09a58594754fa8fdb80f3a3c80d281","pinyin":"naogengsehouyizheng","initials":"ngshyz","setting":"in","caseName":"病例1：患者，男，68岁","templateNames":["入院记录","首次病程记录","主治查房记录","主任查房记录","病程记录","出院记录","医患沟通记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，68岁",60],["模板名称","入院记录 首次病程记录 主治查房记录 主任查房记录 病程记录 出院记录 医患沟通记录",30],["主要诊断编码","",30]]},{"id":"templates-282470c1aadbc82f8e7d","key":"v1-c9ccc21dfe2a3058|templates-282470c1aadbc82f8e7d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑出血后遗症","category":"住院病历模板","raw":{"name":"脑出血后遗症","category":"住院病历模板","case":{"case_name":"病例1：患者，女，65岁","templates":{"入院记录":"主诉：右侧肢体活动不利1年半，加重伴头痛头晕3天。\n\n现病史：患者1年半前因情绪激动突发头痛、呕吐，随即出现右侧肢体活动不利、意识不清，急送至外院，头颅CT示\"左侧基底节区脑出血，量约30ml\"，予脱水降颅压、控制血压、营养神经等保守治疗，住院1月后病情稳定出院，遗留右侧肢体活动不利，右上肢肌力2级，右下肢肌力3级，可行走但需拐杖，言语流利，日常生活需家人协助。长期口服硝苯地平控释片30mg qd控制血压。近3天患者无明显诱因出现头痛头晕，呈持续性胀痛，以右侧颞部为主，伴右侧肢体活动不利加重，右下肢行走无力，无恶心呕吐，无意识障碍，无抽搐，无胸闷胸痛，无发热咳嗽。发病以来，患者精神欠佳，食欲尚可，睡眠差，大小便正常，体重无明显变化。\n\n既往史：高血压病史15年，最高血压200/110mmHg，长期口服硝苯地平控释片30mg qd，血压控制在150-160/90-100mmHg。否认糖尿病、冠心病病史。否认肝炎、结核等传染病史。1年半前脑出血病史，保守治疗。否认手术、外伤、输血史。否认食物、药物过敏史。\n\n个人史及过敏史：生于本地，久居本地，无疫区旅居史。无吸烟饮酒史。否认工业毒物、粉尘、放射性物质接触史。否认药物过敏史。\n\n体格检查：T 36.4℃，P 72次/分，R 18次/分，BP 165/100mmHg。发育正常，营养中等，神志清楚，精神欠佳，言语流利，查体合作。全身皮肤黏膜无黄染、皮疹及出血点，浅表淋巴结未触及肿大。头颅无畸形，眼睑无水肿，结膜无充血，巩膜无黄染，双瞳孔等大等圆，直径约3mm，对光反射灵敏。耳鼻未见异常，口唇无紫绀，伸舌右偏，咽无充血，扁桃体无肿大。颈软，无抵抗，颈静脉无怒张，气管居中，甲状腺未触及肿大。胸廓对称无畸形，双肺呼吸音清，未闻及干湿性啰音。心前区无隆起，心尖搏动位于第五肋间左锁骨中线内0.5cm，未触及震颤，心界向左下扩大，心率72次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，未见胃肠型及蠕动波，未触及包块，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常，4次/分。肛门直肠及外生殖器未查。脊柱生理弯曲存在，无畸形，活动自如。\n\n专科检查：神志清楚，言语流利，记忆力、计算力、定向力粗测正常。双侧额纹对称，右侧鼻唇沟变浅，伸舌右偏。右上肢肌力2级，右下肢肌力3级，左侧肢体肌力5级。右侧肢体肌张力增高（Ashworth 2级），左侧正常。右侧肱二头肌、肱三头肌、膝反射、跟腱反射亢进（+++），左侧正常。右侧Babinski征阳性，左侧阴性。右侧偏身痛觉减退，左侧正常。指鼻试验、跟膝胫试验右侧不合作，左侧稳准。Romberg征不合作。\n\n辅助检查：头颅CT（外院，1年半前）：左侧基底节区脑出血，量约30ml。\n头颅CT（本院，2026-09-02）：左侧基底节区脑出血后软化灶形成，脑室系统稍扩大，脑沟增宽。\n血压：165/100mmHg。\n血糖：5.6mmol/L。\n血脂：总胆固醇5.2mmol/L，甘油三酯1.8mmol/L，低密度脂蛋白3.2mmol/L。\n肝肾功能、电解质、凝血功能正常。\n\n初步诊断：\n1. 脑出血后遗症\n2. 高血压病3级（很高危）\n3. 脑出血后软化灶形成\n4. 脑萎缩\n\n处理方案：\n1. 神经内科护理常规，一级护理，低盐低脂饮食，留陪护，防跌倒。\n2. 控制血压：硝苯地平控释片30mg qd 口服，加用缬沙坦胶囊80mg qd，目标血压<140/90mmHg。\n3. 脱水降颅压：头痛明显时予甘露醇125ml 静滴 q12h（注意肾功能、电解质）。\n4. 营养神经：甲钴胺片0.5mg tid 口服；胞磷胆碱钠片0.2g tid 口服。\n5. 改善脑循环：银杏叶提取物片40mg tid 口服。\n6. 调脂稳定斑块：阿托伐他汀钙片20mg qn 口服。\n7. 对症治疗：头痛明显时予布洛芬缓释胶囊0.3g bid 口服。\n8. 康复治疗：病情稳定后行肢体功能锻炼、日常生活活动能力训练。\n9. 完善检查：头颅MRI+MRA（目的：明确既往出血病灶部位与范围、评估颅内动脉瘤或血管畸形等出血病因，为再出血风险评估提供依据）、颈动脉超声（目的：评估颅内外动脉粥样硬化及狭窄程度，为脑血管病二级预防提供依据）、心脏超声（目的：排除心腔内血栓、瓣膜病变及心房颤动等心源性栓塞病因）、同型半胱氨酸（目的：评估血管性危险因素水平，为脑卒中复发风险分层与叶酸干预提供依据）、凝血功能+血小板计数（目的：评估凝血与止血功能，为抗栓治疗时机与安全性提供依据）。\n10. 健康教育：控制血压，避免情绪激动，保持大便通畅，定期复查。","首次病程记录":"2026-09-02 11:00 首次病程记录\n\n患者，女，65岁，因\"右侧肢体活动不利1年半，加重伴头痛头晕3天\"入院。\n\n一、病例特点：\n1. 老年女性，65岁，慢性病程急性加重。\n2. 临床表现：右侧肢体活动不利1年半，加重伴头痛头晕3天。1年半前脑出血病史，遗留右侧肢体活动不利。近3天头痛头晕，右侧肢体无力加重。\n3. 既往史：高血压15年，最高200/110mmHg，控制欠佳。1年半前脑出血保守治疗。\n4. 体格检查：BP 165/100mmHg，神志清楚，言语流利，右侧鼻唇沟变浅，伸舌右偏。右上肢肌力2级，右下肢肌力3级，右侧肌张力增高，右侧腱反射亢进，右侧Babinski征阳性，右侧偏身痛觉减退。\n5. 辅助检查：头颅CT示左侧基底节区脑出血后软化灶形成，脑萎缩。血压165/100mmHg，血脂升高。\n\n二、拟诊讨论：\n（一）初步诊断：\n1. 脑出血后遗症\n2. 高血压病3级（很高危）\n3. 脑出血后软化灶形成\n4. 脑萎缩\n\n（二）诊断依据：\n1. 脑出血后遗症：老年女性，高血压病史；1年半前脑出血病史，遗留右侧肢体活动不利；查体见右侧中枢性面舌瘫、偏瘫、偏身感觉障碍、病理征阳性；头颅CT证实左侧基底节区软化灶。\n2. 高血压病3级（很高危）：高血压病史15年，最高200/110mmHg，合并脑出血、靶器官损害，分层为很高危。\n3. 脑出血后软化灶形成、脑萎缩：头颅CT证实。\n\n（三）鉴别诊断：\n1. 脑梗塞：多在安静状态下起病，头痛呕吐不明显，头颅CT可见低密度灶。本患者有脑出血病史，CT见软化灶，本次加重无新发低密度灶，不支持新发脑梗塞，但需完善头颅MRI+DWI排除。\n2. 脑出血复发：多在活动或情绪激动时发病，头痛呕吐、意识障碍多见，头颅CT可见新发高密度出血灶。本患者头痛但无呕吐、意识障碍，CT未见新发出血，可排除，但需密切观察，必要时复查CT。\n3. 颅内占位性病变：慢性起病，进行性加重，可有颅内压增高表现，头颅MRI可见占位效应。本患者急性加重，CT未见占位，可排除。\n4. 高血压脑病：血压急剧升高（舒张压>120mmHg），伴头痛、呕吐、意识障碍、抽搐，降压后症状迅速缓解。本患者血压165/100mmHg，无意识障碍、抽搐，不支持。\n\n三、诊疗计划：\n1. 神经内科护理常规，一级护理，低盐低脂饮食，留陪护。\n2. 控制血压，必要时脱水降颅压。\n3. 营养神经、改善循环、调脂治疗。\n4. 完善检查：头颅MRI+MRA（目的：明确既往出血病灶部位与范围、评估颅内动脉瘤或血管畸形等出血病因，为再出血风险评估提供依据）、颈动脉超声（目的：评估颅内外动脉粥样硬化及狭窄程度，为脑血管病二级预防提供依据）、心脏超声（目的：排除心腔内血栓、瓣膜病变及心房颤动等心源性栓塞病因）、同型半胱氨酸（目的：评估血管性危险因素水平，为脑卒中复发风险分层与叶酸干预提供依据）、凝血功能+血小板计数（目的：评估凝血与止血功能，为抗栓治疗时机与安全性提供依据）。\n5. 病情稳定后康复治疗。\n6. 健康教育，避免情绪激动，控制血压。\n\n医师签名：X","病程记录":"2026-09-03 09:00 病程记录\n\n患者诉头痛头晕较前减轻，右侧肢体活动不利无明显变化，无恶心呕吐，无意识障碍，无抽搐。饮食睡眠可，大小便正常。\n\n查体：T 36.4℃，P 70次/分，R 18次/分，BP 150/95mmHg。神志清楚，言语流利。右侧鼻唇沟变浅，伸舌右偏。右上肢肌力2级，右下肢肌力3级，右侧肌张力增高，右侧腱反射亢进，右侧Babinski征阳性。双肺呼吸音清，心率70次/分，律齐。腹软，无压痛。\n\n治疗同前，继续控制血压、营养神经、改善循环。患者头痛减轻，甘露醇减量为125ml qd。患者病情稳定，继续观察。\n\n医师签名：X\n\n2026-09-05 09:00 病程记录\n\n患者诉头痛头晕基本缓解，右侧肢体活动不利较前稍好转，右下肢行走较前有力。无不适主诉。饮食睡眠可，大小便正常。\n\n查体：T 36.3℃，P 68次/分，R 17次/分，BP 145/90mmHg。神志清楚，言语流利。右侧鼻唇沟稍浅，伸舌稍右偏。右上肢肌力2+级，右下肢肌力3+级，右侧肌张力增高，右侧腱反射亢进，右侧Babinski征阳性。双肺呼吸音清，心率68次/分，律齐。\n\n停用甘露醇。继续控制血压、营养神经、改善循环、调脂治疗。开始康复治疗。患者病情稳定，继续观察。\n\n医师签名：X","出院记录":"入院日期：2026-09-02\n出院日期：2026-09-11\n住院天数：9天\n\n入院诊断：\n1. 脑出血后遗症\n2. 高血压病3级（很高危）\n3. 脑出血后软化灶形成\n4. 脑萎缩\n\n入院情况：患者，女，65岁，因\"右侧肢体活动不利1年半，加重伴头痛头晕3天\"入院。查体：BP 165/100mmHg，神志清楚，言语流利，右侧鼻唇沟变浅，伸舌右偏。右上肢肌力2级，右下肢肌力3级，右侧肌张力增高，右侧腱反射亢进，右侧Babinski征阳性，右侧偏身痛觉减退。头颅CT示左侧基底节区脑出血后软化灶形成，脑萎缩。\n\n诊疗经过：入院后完善相关检查，予控制血压（硝苯地平控释片+缬沙坦）、脱水降颅压（甘露醇，短期使用）、营养神经（甲钴胺、胞磷胆碱钠）、改善循环（银杏叶提取物）、调脂（阿托伐他汀）等治疗。病情稳定后行肢体功能锻炼等康复治疗。\n\n出院情况：患者头痛头晕缓解，右侧肢体活动不利较前好转，右上肢肌力2+级，右下肢肌力4级，可独立行走。BP 140/88mmHg。\n\n出院诊断：\n1. 脑出血后遗症\n2. 高血压病3级（很高危）\n3. 脑出血后软化灶形成\n4. 脑萎缩\n5. 高脂血症\n\n出院医嘱：1. 用药指导：\n - 硝苯地平控释片30mg qd + 缬沙坦胶囊80mg qd（监测血压，目标<140/90mmHg）\n - 阿托伐他汀钙片20mg qn（3月后复查血脂、肝功能）\n - 甲钴胺片0.5mg tid + 胞磷胆碱钠片0.2g tid\n - 银杏叶提取物片40mg tid\n2. 康复训练：继续肢体功能锻炼、日常生活活动能力训练，建议康复科门诊随访。\n3. 生活方式：低盐低脂饮食，避免情绪激动、过度劳累，保持大便通畅，适当活动，防跌倒。\n4. 复诊：2周后门诊复查血压；1月后复查肝肾功能、血脂；3月后复查头颅CT。\n5. 注意事项：如出现剧烈头痛、呕吐、意识障碍、新发肢体无力、抽搐等，立即就诊。\n6. 家庭护理：家属协助康复训练，监督服药，监测血压。\n\n医师签名：X\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2236,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4f3de34792cc3a18335628c9adf733608445f156172b1b8e66048a8a04e6cf7e","pinyin":"naochuxiehouyizheng","initials":"ncxhyz","setting":"in","caseName":"病例1：患者，女，65岁","templateNames":["入院记录","首次病程记录","病程记录","出院记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，女，65岁",60],["模板名称","入院记录 首次病程记录 病程记录 出院记录",30],["主要诊断编码","",30]]},{"id":"templates-a452764a8945685a127e","key":"v1-c9ccc21dfe2a3058|templates-a452764a8945685a127e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"压疮","category":"住院病历模板","raw":{"name":"压疮","category":"住院病历模板","case":{"case_name":"病例1：患者，男，75岁","templates":{"入院记录":"主诉：骶尾部皮肤破溃2周，加重伴渗液3天。\n\n现病史：患者老年男性，脑梗死后遗症长期卧床5年，生活不能自理。2周前家属发现患者骶尾部皮肤发红，未予重视，后逐渐出现皮肤破溃，面积约2cm×3cm，有少量渗液。家属予碘伏消毒、涂抹\"红霉素软膏\"（具体不详），症状无改善。3天前患者骶尾部破溃面积增大，约4cm×5cm，渗液增多，为黄色脓性分泌物，伴异味，周围皮肤红肿，患者精神差，食欲下降，无发热，无寒战，无胸痛呼吸困难，无腹痛腹泻。发病以来，患者精神差，食欲差，睡眠欠佳，大小便失禁，体重近1月下降约4kg。\n\n既往史：脑梗死病史5年，遗留四肢活动不利，长期卧床。高血压病史15年，最高血压180/100mmHg，长期口服硝苯地平缓释片20mg bid，血压控制在140-150/80-90mmHg。2型糖尿病病史8年，长期口服二甲双胍0.5g tid，血糖控制欠佳。否认冠心病病史。否认肝炎、结核等传染病史。否认手术、外伤、输血史。否认食物、药物过敏史。\n\n个人史及过敏史：生于本地，久居本地，无疫区旅居史。吸烟40年，每日20支，已戒5年。饮酒30年，每日白酒2两，已戒5年。否认工业毒物、粉尘、放射性物质接触史。否认药物过敏史。\n\n\n专科检查：骶尾部可见一约4cm×5cm皮肤缺损，深达皮下脂肪层，创面基底50%黄色腐肉，50%红色肉芽组织，有大量黄色脓性分泌物，伴异味。创周皮肤红肿，范围约6cm×7cm，皮温稍高，触痛阳性。双侧足跟、双侧大转子处皮肤完整，无红肿破溃。Braden评分：10分（高危）。\n\n辅助检查：血常规（本院，2026-09-05）：白细胞11.2×10⁹/L，中性粒细胞百分比78%，血红蛋白95g/L，血小板250×10⁹/L。\nCRP：55mg/L（升高）。\n降钙素原：0.3ng/ml（轻度升高）。\n血糖：10.5mmol/L（空腹）。\n白蛋白：28g/L（降低）。\n肝肾功能、电解质正常。\n创面分泌物培养：待回报。\n\n初步诊断：\n1. 压疮（骶尾部，III期）\n2. 创面感染\n3. 脑梗死后遗症（长期卧床）\n4. 高血压病3级（很高危）\n5. 2型糖尿病\n6. 低蛋白血症（营养不良）\n7. 贫血\n\n处理方案：\n1. 普外科/伤口造口护理常规，一级护理，低盐低脂糖尿病饮食，留陪护，卧床休息。\n2. 减压治疗：气垫床，定时翻身（每2小时一次），避免受压，使用减压敷料。\n3. 创面处理：\n - 清创：生理盐水冲洗创面，清除坏死组织，必要时手术清创。\n - 换药：碘伏消毒创周，创面用生理盐水冲洗，外敷泡沫敷料或水胶体敷料，每2-3天换药一次，渗液多时随时更换。\n - 感染控制：创面分泌物培养+药敏，经验性抗感染（头孢曲松钠2g + NS 100ml 静滴 qd），待药敏结果调整。\n4. 营养支持：高蛋白、高热量、高维生素饮食，补充蛋白粉、维生素C、锌制剂；必要时肠内营养制剂；白蛋白10g 静滴 qd 纠正低蛋白血症。\n5. 控制血糖：二甲双胍0.5g tid，监测血糖，目标空腹<7mmol/L，餐后2h<10mmol/L，必要时胰岛素治疗。\n6. 控制血压：硝苯地平缓释片20mg bid。\n7. 纠正贫血：铁剂、维生素B12、叶酸，必要时输血。\n8. 完善检查：创面分泌物培养+药敏（目的：明确创面致病菌及敏感药物，为局部清创换药与全身抗感染方案提供依据）、血培养（目的：排除菌血症与全身性感染，为静脉抗感染治疗及手术时机提供依据）、糖化血红蛋白（目的：明确糖尿病等血糖代谢异常，为创面愈合评估与血糖控制方案提供依据）、铁代谢+血常规（目的：评估贫血与营养储备状况，为营养支持与促愈合治疗提供依据）、心脏超声（目的：评估心功能与心内膜炎风险，为手术清创、麻醉及围手术期管理提供依据）、创面组织病理检查（目的：必要时排除癌变或特殊感染，为治疗方案选择提供依据）。\n9. 预防并发症：防坠积性肺炎（翻身拍背）、防泌尿系感染（会阴护理）、防深静脉血栓（气压治疗、被动活动）。\n10. 健康教育：家属压疮护理指导，营养支持重要性，定期复查。","首次病程记录":"2026-09-05 16:00 首次病程记录\n\n患者，男，75岁，因\"骶尾部皮肤破溃2周，加重伴渗液3天\"入院。\n\n一、病例特点：\n1. 老年男性，75岁，慢性起病，急性加重。\n2. 长期卧床（脑梗死后遗症5年），骶尾部皮肤破溃2周，加重伴渗液3天。创面4cm×5cm，深达皮下脂肪，有脓性分泌物伴异味。\n3. 既往史：脑梗死5年长期卧床，高血压15年，2型糖尿病8年，血糖控制欠佳。\n4. 体格检查：T 37.8℃，营养差，贫血貌。骶尾部4cm×5cm皮肤缺损，深达皮下脂肪，50%黄色腐肉，50%红色肉芽，大量脓性分泌物伴异味，创患者肿。Braden评分10分。\n5. 辅助检查：白细胞11.2×10⁹/L，中性粒78%，CRP 55mg/L，血糖10.5mmol/L，白蛋白28g/L，血红蛋白95g/L。\n\n二、拟诊讨论：\n（一）初步诊断：\n1. 压疮（骶尾部，III期）\n2. 创面感染\n3. 脑梗死后遗症（长期卧床）\n4. 高血压病3级（很高危）\n5. 2型糖尿病\n6. 低蛋白血症（营养不良）\n7. 贫血\n\n（二）诊断依据：\n1. 压疮（骶尾部，III期）：老年男性，长期卧床（高危因素）；骶尾部皮肤破溃2周；查体见4cm×5cm皮肤缺损，深达皮下脂肪层，创面有腐肉、肉芽组织、脓性分泌物；符合压疮III期表现（全层皮肤缺失，可见皮下脂肪，未达骨、肌腱）。\n2. 创面感染：创面有脓性分泌物伴异味，创患者肿，血常规、CRP升高。\n3. 脑梗死后遗症：脑梗死病史5年，长期卧床，四肢肌力3级。\n4. 高血压病3级：高血压病史15年，最高180/100mmHg，合并糖尿病、脑梗死。\n5. 2型糖尿病：糖尿病病史8年，空腹血糖10.5mmol/L。\n6. 低蛋白血症：白蛋白28g/L，营养差，体重下降。\n7. 贫血：血红蛋白95g/L，贫血貌。\n\n（三）鉴别诊断：\n1. 糖尿病足溃疡：多发生于足部，有糖尿病病史，表现为足部溃疡、感染，可深达骨质。本患者溃疡位于骶尾部，有长期卧床史，符合压疮特点，但糖尿病是压疮愈合不良的重要因素。\n2. 皮肤恶性肿瘤（如鳞状细胞癌）：慢性溃疡长期不愈，边缘隆起，质地硬，易出血，病理检查可确诊。本患者溃疡病程短，有明确受压史，不支持，但慢性压疮长期不愈有恶变风险，必要时活检。\n3. 带状疱疹后溃疡：多有带状疱疹病史，沿神经分布，疼痛明显。本患者无带状疱疹病史，溃疡位于受压部位，不支持。\n4. 血管性溃疡：动脉性溃疡多位于肢端，疼痛剧烈，动脉搏动减弱；静脉性溃疡多位于小腿内侧，伴静脉曲张。本患者位于骶尾部，有长期卧床史，不支持。\n\n三、诊疗计划：\n1. 伤口造口护理常规，一级护理，留陪护。\n2. 减压治疗（气垫床、定时翻身），创面处理（清创、换药）。\n3. 抗感染治疗，待药敏调整。\n4. 营养支持（高蛋白饮食、白蛋白、维生素、微量元素）。\n5. 控制血糖、血压，纠正贫血。\n6. 完善创面分泌物培养、血培养、糖化血红蛋白等检查。\n7. 预防坠积性肺炎、泌尿系感染、深静脉血栓等并发症。\n8. 家属健康教育及护理指导。\n\n医师签名：X","病程记录":"2026-09-06 09:00 病程记录\n\n患者一般情况较前好转，体温正常，精神较前改善，食欲稍增加。骶尾部创面渗液较前减少，无明显异味。\n\n查体：T 36.8℃，P 80次/分，R 18次/分，BP 140/85mmHg。神志清楚，精神较前好转。骶尾部创面4cm×5cm，腐肉较前减少，肉芽组织较前新鲜，渗液减少，创患者肿减轻。双肺呼吸音清，心率80次/分，律齐。腹软，无压痛。\n\n创面分泌物培养回报：金黄色葡萄球菌，对头孢曲松、万古霉素敏感。\n\n治疗同前，继续抗感染、创面换药、营养支持。加强翻身，避免受压。患者病情稳定，继续观察。\n\n医师签名：X\n\n2026-09-09 09:00 病程记录\n\n患者一般情况良好，无发热，精神食欲改善。骶尾部创面明显缩小，约3cm×4cm，肉芽组织新鲜，无脓性分泌物，创周无红肿。\n\n查体：T 36.5℃，P 76次/分，R 18次/分，BP 135/80mmHg。神志清楚，精神好。骶尾部创面3cm×4cm，100%红色肉芽组织，无渗液，创周正常。双肺呼吸音清，心率76次/分，律齐。\n\n复查：血常规白细胞7.5×10⁹/L，中性粒60%，CRP 10mg/L，白蛋白32g/L，血红蛋白100g/L，空腹血糖7.2mmol/L。\n\n抗感染治疗已满1周，炎症指标正常，停用抗生素。继续创面换药（改为水胶体敷料，每周2次），营养支持，控制血糖血压。加强康复训练，病情允许时尽早坐起，减少卧床时间。患者病情稳定，继续观察。\n\n医师签名：X","出院记录":"入院日期：2026-09-05\n出院日期：2026-09-16\n住院天数：11天\n\n入院诊断：\n1. 压疮（骶尾部，III期）\n2. 创面感染\n3. 脑梗死后遗症（长期卧床）\n4. 高血压病3级（很高危）\n5. 2型糖尿病\n6. 低蛋白血症（营养不良）\n7. 贫血\n\n入院情况：患者，男，75岁，因\"骶尾部皮肤破溃2周，加重伴渗液3天\"入院。长期卧床。查体：骶尾部4cm×5cm皮肤缺损，深达皮下脂肪，50%黄色腐肉，50%红色肉芽，大量脓性分泌物伴异味，创患者肿。Braden评分10分。血常规白细胞11.2×10⁹/L，CRP 55mg/L，白蛋白28g/L。\n\n诊疗经过：入院后予减压治疗（气垫床、定时翻身）、创面处理（清创、换药）、抗感染（头孢曲松，分泌物培养示金葡菌敏感）、营养支持（白蛋白、高蛋白饮食、维生素、微量元素）、控制血糖血压、纠正贫血等治疗。预防坠积性肺炎、泌尿系感染、深静脉血栓等并发症。\n\n出院情况：患者一般情况良好，无发热，精神食欲改善。骶尾部创面缩小至2cm×3cm，100%红色肉芽组织，无渗液，创周正常。血常规、CRP正常，白蛋白35g/L，血红蛋白105g/L，血糖控制可。\n\n出院诊断：\n1. 压疮（骶尾部，III期，好转）\n2. 创面感染（治愈）\n3. 脑梗死后遗症（长期卧床）\n4. 高血压病3级（很高危）\n5. 2型糖尿病\n6. 低蛋白血症（营养不良，改善）\n7. 贫血（改善）\n\n出院医嘱：1. 用药指导：\n - 头孢克肟胶囊0.1g bid 口服（继续3天）\n - 硝苯地平缓释片20mg bid（监测血压）\n - 二甲双胍0.5g tid（监测血糖）\n - 甲钴胺片0.5mg tid\n - 蛋白粉、维生素C、硫酸锌（促进创面愈合）\n2. 创面护理：\n - 继续换药：生理盐水冲洗，水胶体敷料外敷，每周2次，直至愈合\n - 定期观察创面，如有红肿、渗液、异味及时就诊\n3. 减压措施：\n - 气垫床，每2小时翻身一次，避免局部长期受压\n - 保持皮肤清洁干燥，避免潮湿、摩擦\n - 坐位时每30分钟减压一次\n4. 营养支持：高蛋白、高热量、高维生素饮食，多吃鸡蛋、牛奶、鱼肉、蔬菜水果，保证营养摄入。\n5. 康复训练：病情允许时尽早坐起、站立，减少卧床时间，被动活动四肢。\n6. 复诊：2周后门诊复查创面；1月后复查血常规、白蛋白、血糖、肝肾功能。\n7. 注意事项：压疮易复发，需长期坚持减压和营养支持；如出现创面扩大、发热、意识改变等，立即就诊。\n8. 家庭护理：家属需掌握压疮预防和护理技能，定期参加护理培训。\n\n医师签名：X\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2237,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"114b76154175757b0a0bb74a7dc7d5cc7b9e612b510461d312f7601713599049","pinyin":"yachuang","initials":"yc","setting":"in","caseName":"病例1：患者，男，75岁","templateNames":["入院记录","首次病程记录","病程记录","出院记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，75岁",60],["模板名称","入院记录 首次病程记录 病程记录 出院记录",30],["主要诊断编码","",30]]},{"id":"templates-80bb9e36a6bd6bb71c64","key":"v1-c9ccc21dfe2a3058|templates-80bb9e36a6bd6bb71c64","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泌尿系感染","category":"住院病历模板","raw":{"name":"泌尿系感染","category":"住院病历模板","case":{"case_name":"病例1：患者，女，82岁","templates":{"入院记录":"主诉：尿频、尿急伴下腹部不适3天。\n\n现病史：患者老年女性，脑梗死后遗症长期卧床4年，大小便失禁，长期留置尿管（每月更换一次）。3天前患者出现尿频、尿急，因卧床表现为烦躁不安、牵拉尿管，伴下腹部不适，尿液浑浊，无肉眼血尿，无腰痛。1天前患者出现发热，体温最高38.8℃，伴寒战，精神差，食欲下降，无恶心呕吐，无咳嗽咳痰，无胸闷胸痛，无腹痛腹泻。家属予口服\"左氧氟沙星0.2g bid\"（具体不详），症状无改善。发病以来，患者精神差，食欲差，睡眠欠佳，大便正常，尿量较前减少，体重无明显变化。\n\n既往史：脑梗死病史4年，遗留四肢活动不利，长期卧床，长期留置尿管。高血压病史18年，最高血压190/110mmHg，长期口服缬沙坦胶囊80mg qd，血压控制在140-150/80-90mmHg。2型糖尿病病史12年，长期口服格列美脲2mg qd，血糖控制欠佳。否认冠心病病史。否认肝炎、结核等传染病史。否认手术、外伤、输血史。否认食物、药物过敏史。\n\n个人史及过敏史：生于本地，久居本地，无疫区旅居史。无吸烟饮酒史。否认工业毒物、粉尘、放射性物质接触史。否认药物过敏史。\n\n\n辅助检查：血常规（本院，2026-09-06）：白细胞13.5×10⁹/L，中性粒细胞百分比88%，淋巴细胞百分比8%，血红蛋白115g/L，血小板230×10⁹/L。\n尿常规：白细胞满视野/HP，红细胞15-20/HP，蛋白（+），亚硝酸盐阳性。\nCRP：95mg/L（升高）。\n降钙素原：1.2ng/ml（升高）。\n血糖：11.2mmol/L（空腹）。\n肝肾功能、电解质正常。\n尿培养：待回报。\n血培养：待回报。\n\n初步诊断：\n1. 泌尿系感染（急性膀胱炎，导管相关性）\n2. 菌血症（待排除）\n3. 脑梗死后遗症（长期卧床，留置尿管）\n4. 高血压病3级（很高危）\n5. 2型糖尿病\n\n处理方案：\n1. 肾内科/泌尿外科护理常规，一级护理，低盐低脂糖尿病饮食，留陪护，卧床休息，多饮水（或增加补液）。\n2. 抗感染治疗：\n - 经验性抗感染：头孢曲松钠2g + NS 100ml 静滴 qd（覆盖革兰阴性菌）\n - 待尿培养+药敏结果调整抗生素\n - 疗程：导管相关性泌尿系感染至少7-14天\n3. 尿管护理：\n - 评估是否可拔除尿管，如无法拔除，更换新尿管\n - 会阴护理每日2次，保持尿道口清洁\n - 保持尿管通畅，避免扭曲、受压\n - 密闭引流，尿袋低于膀胱水平\n4. 控制血糖：格列美脲2mg qd，监测血糖，必要时胰岛素治疗，目标空腹<7mmol/L。\n5. 控制血压：缬沙坦胶囊80mg qd。\n6. 对症治疗：发热时物理降温，必要时布洛芬0.2g 口服；多饮水或静脉补液。\n7. 完善检查：尿培养+药敏（目的：明确致病菌及耐药情况，为抗生素精准选择提供依据）、血培养（目的：排除尿源性菌血症与脓毒症，为静脉抗感染及住院管理提供依据）、泌尿系超声（目的：明确有无结石、积水、肿瘤等梗阻或结构异常，为是否需解除梗阻或手术提供依据）、残余尿测定（目的：评估膀胱排空功能与尿潴留程度，为导尿、膀胱功能训练及复发风险评估提供依据）、糖化血红蛋白+肾功能（目的：明确糖尿病及肾功能状态，为抗感染药物剂量调整与病因控制提供依据）。\n8. 预防并发症：防坠积性肺炎、防压疮、防深静脉血栓。\n9. 健康教育：家属尿管护理指导，多饮水，定期更换尿管。","首次病程记录":"2026-09-06 14:00 首次病程记录\n\n患者，女，82岁，因\"尿频、尿急、尿痛3天，伴发热1天\"入院。\n\n一、病例特点：\n1. 老年女性，82岁，急性起病。\n2. 长期卧床（脑梗死后遗症4年），长期留置尿管。尿频、尿急、尿痛3天，发热1天，体温最高38.9℃，尿液浑浊。\n3. 既往史：脑梗死4年长期卧床留置尿管，高血压18年，2型糖尿病12年。\n4. 体格检查：T 38.9℃，P 96次/分，精神差。下腹部轻压痛，双肾区叩击痛阴性。留置尿管通畅，尿液浑浊。\n5. 辅助检查：血常规白细胞13.5×10⁹/L，中性粒88%，尿常规白细胞满视野，亚硝酸盐阳性，CRP 95mg/L，降钙素原1.2ng/ml，血糖11.2mmol/L。\n\n二、拟诊讨论：\n（一）初步诊断：\n1. 泌尿系感染（急性膀胱炎，导管相关性）\n2. 菌血症（待排除）\n3. 脑梗死后遗症（长期卧床，留置尿管）\n4. 高血压病3级（很高危）\n5. 2型糖尿病\n\n（二）诊断依据：\n1. 泌尿系感染（导管相关性）：老年女性，长期留置尿管（高危因素）；尿频、尿急、尿痛、发热；下腹部压痛；尿常规白细胞满视野、亚硝酸盐阳性；血常规、CRP、降钙素原升高。符合导管相关性泌尿系感染诊断。\n2. 菌血症（待排除）：患者有发热、寒战，降钙素原升高，长期留置尿管，需血培养结果确认。\n3. 脑梗死后遗症：脑梗死病史4年，长期卧床，四肢肌力3级，留置尿管。\n4. 高血压病3级：高血压病史18年，最高190/110mmHg，合并糖尿病、脑梗死。\n5. 2型糖尿病：糖尿病病史12年，空腹血糖11.2mmol/L。\n\n（三）鉴别诊断：\n1. 急性肾盂肾炎：表现为发热、腰痛、肾区叩击痛，可有尿频尿急尿痛，尿常规异常。本患者双肾区叩击痛阴性，无腰痛，考虑下尿路感染，但老年患者症状不典型，需完善泌尿系超声排除上尿路感染。\n2. 泌尿系结核：多有低热、盗汗、乏力，尿频尿急尿痛持续存在，普通抗生素治疗无效，尿找抗酸杆菌阳性，IVP可见肾盏虫蚀样改变。本患者急性起病，高热，普通感染指标升高，不支持，但需查尿找抗酸杆菌排除。\n3. 泌尿系结石合并感染：可有腰痛、血尿、尿频尿急尿痛，泌尿系超声可见结石影。本患者无腰痛、肉眼血尿，需完善泌尿系超声排除。\n4. 前列腺炎（男性）：表现为尿频、尿急、尿痛、会阴部不适，可有发热，直肠指检前列腺压痛。本患者为女性，不适用。\n5. 生殖道感染：女性患者可有阴道分泌物增多、异味、瘙痒，妇科检查可见异常。本患者以尿路症状为主，需妇科检查排除。\n\n三、诊疗计划：\n1. 肾内科护理常规，一级护理，留陪护。\n2. 经验性抗感染（头孢曲松），待尿培养调整。\n3. 尿管护理，评估是否可拔除或更换。\n4. 控制血糖、血压，对症支持治疗。\n5. 完善尿培养、血培养、泌尿系超声等检查。\n6. 预防并发症，家属健康教育。\n\n医师签名：X","病程记录":"2026-09-07 09:00 病程记录\n\n患者体温较前下降，最高37.8℃，尿频尿急症状较前减轻，精神较前好转，食欲稍改善。尿液较前清亮。\n\n查体：T 37.6℃，P 88次/分，R 20次/分，BP 135/80mmHg。神志清楚，精神较前好转。下腹部压痛较前减轻。留置尿管通畅，尿液较前清亮。双肺呼吸音清，心率88次/分，律齐。腹软，无压痛。\n\n尿培养回报：大肠埃希菌，对头孢曲松、左氧氟沙星敏感，ESBL阴性。\n血培养：待回报。\n\n治疗有效，继续头孢曲松抗感染。更换新尿管，加强会阴护理。患者病情稳定，继续观察。\n\n医师签名：X\n\n2026-09-10 09:00 病程记录\n\n患者无发热，尿频尿急尿痛症状消失，精神食欲良好，尿液清亮。\n\n查体：T 36.5℃，P 78次/分，R 18次/分，BP 130/75mmHg。神志清楚，精神好。下腹部无压痛。留置尿管通畅，尿液清亮。双肺呼吸音清，心率78次/分，律齐。\n\n复查：血常规白细胞7.2×10⁹/L，中性粒60%，CRP 8mg/L，降钙素原0.05ng/ml，尿常规白细胞3-5/HP，空腹血糖7.0mmol/L。\n血培养：无细菌生长。\n\n抗感染治疗已满7天，症状消失，炎症指标正常。考虑患者长期留置尿管，疗程延长至10天。继续当前治疗，复查尿常规、尿培养。患者病情稳定，继续观察。\n\n医师签名：X","出院记录":"入院日期：2026-09-06\n出院日期：2026-09-16\n住院天数：10天\n\n入院诊断：\n1. 泌尿系感染（急性膀胱炎，导管相关性）\n2. 菌血症（待排除）\n3. 脑梗死后遗症（长期卧床，留置尿管）\n4. 高血压病3级（很高危）\n5. 2型糖尿病\n\n入院情况：患者，女，82岁，因\"尿频、尿急、尿痛3天，伴发热1天\"入院。长期卧床，留置尿管。查体：T 38.9℃，精神差，下腹部轻压痛，尿液浑浊。血常规白细胞13.5×10⁹/L，尿常规白细胞满视野，CRP 95mg/L。\n\n诊疗经过：入院后予抗感染（头孢曲松，尿培养示大肠埃希菌敏感）、尿管护理（更换尿管、会阴护理）、控制血糖血压、对症支持等治疗。血培养阴性，排除菌血症。\n\n出院情况：患者无发热，尿频尿急尿痛症状消失，精神食欲良好。尿常规正常，血常规、CRP、降钙素原恢复正常。\n\n出院诊断：\n1. 泌尿系感染（急性膀胱炎，导管相关性，治愈）\n2. 脑梗死后遗症（长期卧床，留置尿管）\n3. 高血压病3级（很高危）\n4. 2型糖尿病\n\n出院医嘱：1. 用药指导：\n - 头孢克肟胶囊0.1g bid 口服（继续3天，总疗程10天）\n - 缬沙坦胶囊80mg qd（监测血压）\n - 格列美脲片2mg qd（监测血糖）\n - 甲钴胺片0.5mg tid\n2. 尿管护理：\n - 每日会阴护理2次，保持尿道口清洁\n - 保持尿管通畅，避免扭曲、受压\n - 尿袋低于膀胱水平，避免逆流\n - 每月更换尿管一次，如有堵塞、感染随时更换\n - 评估是否可拔除尿管，尽早拔除（如病情允许）\n3. 饮水：鼓励多饮水（如心肾功能允许），每日1500-2000ml，起到尿路冲洗作用。\n4. 复诊：2周后门诊复查尿常规、尿培养；1月后复查血糖、肝肾功能。\n5. 注意事项：如出现发热、尿频尿急尿痛加重、尿液浑浊、腰痛等，立即就诊。\n6. 预防：长期留置尿管患者易反复泌尿系感染，需严格无菌操作，定期更换，必要时定期膀胱冲洗。\n7. 家庭护理：家属需掌握尿管护理技能，注意手卫生，避免交叉感染。\n\n医师签名：X\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2238,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"73a9d553fe7129fab0f18ecbad81e769fcb688b9cefaa6573ca9593fdfd31ec6","pinyin":"miniaoxiganran","initials":"mnxgr","setting":"in","caseName":"病例1：患者，女，82岁","templateNames":["入院记录","首次病程记录","病程记录","出院记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，女，82岁",60],["模板名称","入院记录 首次病程记录 病程记录 出院记录",30],["主要诊断编码","",30]]},{"id":"templates-8ad049c5943b566fc7cf","key":"v1-c9ccc21dfe2a3058|templates-8ad049c5943b566fc7cf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"吞咽障碍","category":"住院病历模板","raw":{"name":"吞咽障碍","category":"住院病历模板","case":{"case_name":"病例1：孙德明，男，70岁","templates":{"入院记录":"主诉：脑梗死后饮水呛咳、进食困难2月，加重伴体重下降1月。\n\n现病史：患者2月前突发脑梗塞（左侧基底节区），经治疗后病情稳定，但遗留右侧肢体活动不利及吞咽困难，表现为饮水呛咳，进食流质食物时明显，固体食物尚可，伴言语不清。1月前患者吞咽困难加重，进食半流质食物也出现呛咳，进食量明显减少，伴咳嗽、咳白色黏痰，无发热，无胸闷胸痛，无恶心呕吐。家属予鼻饲饮食，但患者不配合，自行拔除胃管。近1月体重下降约8kg，精神差，乏力。为进一步诊治入院。发病以来，患者精神差，食欲差，睡眠欠佳，大小便正常。\n\n既往史：脑梗死病史2月，遗留右侧肢体活动不利、吞咽障碍、言语不清。高血压病史12年，最高血压170/100mmHg，长期口服苯磺酸氨氯地平片5mg qd，血压控制在130-140/70-80mmHg。否认糖尿病、冠心病病史。否认肝炎、结核等传染病史。否认手术、外伤、输血史。否认食物、药物过敏史。\n\n个人史及过敏史：生于本地，久居本地，无疫区旅居史。吸烟30年，每日20支，已戒2月。饮酒25年，每日白酒3两，已戒2月。否认工业毒物、粉尘、放射性物质接触史。否认药物过敏史。\n\n\n专科检查：神志清楚，构音障碍。右侧鼻唇沟变浅，伸舌右偏。咽反射减弱，软腭上抬无力。洼田饮水试验：5级（呛咳明显，不能全部咽下）。反复唾液吞咽试验：30秒内吞咽1次（正常≥3次）。右上肢肌力3级，右下肢肌力4级，左侧肢体肌力5级。右侧肢体肌张力增高，右侧腱反射亢进，右侧Babinski征阳性。右侧偏身痛觉减退。\n\n辅助检查：头颅MRI（外院，2月前）：左侧基底节区急性脑梗塞。\n头颅CT（本院，2026-09-07）：左侧基底节区脑梗塞后软化灶。\n血常规：白细胞8.5×10⁹/L，中性粒65%，血红蛋白105g/L。\n白蛋白：29g/L（降低）。\n血糖、血脂、肝肾功能、电解质正常。\n胸片：双肺纹理增多，双肺底少许炎症。\n吞咽造影（VFSS）：待完善。\n\n初步诊断：\n1. 吞咽障碍（脑梗死后遗症）\n2. 脑梗死后遗症（右侧肢体偏瘫、构音障碍）\n3. 营养不良\n4. 吸入性肺炎（轻度）\n5. 高血压病2级（很高危）\n6. 贫血\n\n处理方案：\n1. 神经内科/康复科护理常规，一级护理，低盐低脂饮食，留陪护，防误吸、防跌倒。\n2. 营养支持：\n - 重新留置鼻胃管，予肠内营养制剂500ml q6h 鼻饲，根据耐受情况逐渐加量\n - 补充蛋白粉、维生素、微量元素\n - 必要时白蛋白10g 静滴 qd 纠正低蛋白血症\n3. 吞咽功能训练：\n - 间接训练：口腔感觉训练、口腔运动训练、呼吸训练、咳嗽训练\n - 直接训练：体位调整（躯干30°仰卧位、颈部前屈）、食物性状调整（糊状食物）、一口量调整、吞咽手法（空吞咽、交互吞咽）\n - 神经肌肉电刺激治疗\n4. 治疗吸入性肺炎：\n - 抗感染：头孢曲松钠2g + NS 100ml 静滴 qd\n - 祛痰：氨溴索注射液30mg + NS 20ml 静推 bid\n5. 控制血压：苯磺酸氨氯地平片5mg qd。\n6. 营养神经：甲钴胺片0.5mg tid 口服；胞磷胆碱钠片0.2g tid 口服。\n7. 完善检查：吞咽造影（VFSS）（目的：明确吞咽障碍的时期与误吸程度，为经口进食、食物性状调整及康复训练提供依据）、胃镜（必要时）（目的：排除食管狭窄、肿瘤及反流性病变等器质性病因，为是否需胃造瘘等营养通路建立提供依据）、电解质+微量元素（目的：评估营养与代谢状况，为营养支持方案调整提供依据）、心脏超声（目的：评估心功能与基础疾病状态，为康复训练强度和误吸并发症风险控制提供依据）、胸部CT（目的：明确有无隐性误吸所致肺部感染，为抗感染治疗与进食方式选择提供依据）。\n8. 康复治疗：肢体功能锻炼、言语训练、吞咽训练。\n9. 健康教育：家属鼻饲护理指导、吞咽训练指导、防误吸知识。","首次病程记录":"2026-09-07 15:00 首次病程记录\n\n患者孙德明，男，70岁，因\"脑梗死后饮水呛咳、进食困难2月，加重伴体重下降1月\"入院。\n\n一、病例特点：\n1. 老年男性，70岁，慢性病程。\n2. 2月前脑梗塞后出现吞咽障碍，饮水呛咳，进行性加重，进食量减少，体重下降8kg。伴右侧肢体偏瘫、构音障碍。\n3. 既往史：脑梗死2月，高血压12年。\n4. 体格检查：BP 135/80mmHg，营养差，构音障碍。右侧鼻唇沟变浅，伸舌右偏。咽反射减弱，软腭上抬无力。洼田饮水试验5级，反复唾液吞咽试验1次/30秒。右上肢肌力3级，右下肢肌力4级，右侧肌张力增高，右侧Babinski征阳性。双肺底少许湿性啰音。\n5. 辅助检查：头颅CT示左侧基底节区软化灶。白蛋白29g/L，血红蛋白105g/L。胸片示双肺底少许炎症。\n\n二、拟诊讨论：\n（一）初步诊断：\n1. 吞咽障碍（脑梗死后遗症）\n2. 脑梗死后遗症（右侧肢体偏瘫、构音障碍）\n3. 营养不良\n4. 吸入性肺炎（轻度）\n5. 高血压病2级（很高危）\n6. 贫血\n\n（二）诊断依据：\n1. 吞咽障碍：脑梗死病史；饮水呛咳、进食困难；咽反射减弱、软腭上抬无力；洼田饮水试验5级；符合脑梗死后假性球麻痹所致吞咽障碍。\n2. 脑梗死后遗症：脑梗死病史2月，右侧肢体偏瘫、构音障碍，CT证实左侧基底节区软化灶。\n3. 营养不良：体重下降8kg，白蛋白29g/L，进食量减少。\n4. 吸入性肺炎：吞咽障碍病史，咳嗽、咳白色黏痰，双肺底湿性啰音，胸片示双肺底炎症。\n5. 高血压病2级：高血压病史12年，最高170/100mmHg，合并脑梗死。\n6. 贫血：血红蛋白105g/L，营养差。\n\n（三）鉴别诊断：\n1. 食管癌：表现为进行性吞咽困难，以固体食物为主，伴消瘦、贫血，胃镜可确诊。本患者有明确脑梗死病史，以流质呛咳为主，伴神经系统定位体征，不支持，但需胃镜排除。\n2. 贲门失弛缓症：表现为间歇性吞咽困难，胸骨后沉重感，食物反流，X线钡餐可见\"鸟嘴征\"。本患者急性起病，有脑梗死病史，不支持。\n3. 重症肌无力：表现为波动性肌无力，吞咽困难晨轻暮重，可伴眼睑下垂、复视，新斯的明试验阳性。本患者症状无波动，有脑梗死病史，不支持。\n4. 帕金森病：表现为静止性震颤、肌强直、运动迟缓，可伴吞咽困难、构音障碍。本患者无震颤、肌强直，有脑梗死病史，不支持。\n5. 延髓麻痹（真性球麻痹）：表现为吞咽困难、饮水呛咳、声音嘶哑、构音障碍，咽反射消失，舌肌萎缩，多由延髓病变引起。本患者咽反射减弱（非消失），无舌肌萎缩，病变在基底节区，考虑假性球麻痹。\n\n三、诊疗计划：\n1. 康复科护理常规，一级护理，留陪护，防误吸。\n2. 营养支持（鼻饲肠内营养），纠正低蛋白血症。\n3. 吞咽功能训练（间接训练+直接训练+神经肌肉电刺激）。\n4. 抗感染、祛痰治疗吸入性肺炎。\n5. 控制血压、营养神经。\n6. 完善吞咽造影、胃镜等检查。\n7. 肢体功能锻炼、言语训练。\n8. 家属健康教育及护理指导。\n\n医师签名：X","病程记录":"2026-09-08 09:00 病程记录\n\n患者一般情况较前好转，鼻饲饮食耐受良好，无呛咳、呕吐。咳嗽、咳痰较前减轻。精神较前好转。\n\n查体：T 36.6℃，P 76次/分，R 18次/分，BP 130/78mmHg。神志清楚，构音障碍。咽反射减弱，软腭上抬无力。双肺呼吸音粗，双肺底湿性啰音较前减少。心率76次/分，律齐。腹软，无压痛。右上肢肌力3级，右下肢肌力4级。\n\n已留置鼻胃管，予肠内营养制剂500ml q6h，耐受良好。开始吞咽功能训练（口腔感觉训练、口腔运动训练、呼吸训练）。继续抗感染、祛痰治疗。患者病情稳定，继续观察。\n\n医师签名：X\n\n2026-09-12 09:00 病程记录\n\n患者一般情况良好，鼻饲饮食耐受良好。咳嗽咳痰消失，精神食欲改善。吞咽功能较前好转，洼田饮水试验复查：4级（呛咳减轻）。\n\n查体：T 36.4℃，P 72次/分，R 17次/分，BP 128/75mmHg。神志清楚，构音障碍较前改善。咽反射较前灵敏，软腭上抬较前有力。双肺呼吸音清，未闻及干湿性啰音。心率72次/分，律齐。右上肢肌力3+级，右下肢肌力4+级。\n\n复查：血常规正常，白蛋白33g/L，血红蛋白110g/L。胸片示双肺炎症吸收。\n\n停用抗生素。继续吞咽功能训练，增加直接训练（糊状食物吞咽训练）。继续营养支持、肢体功能锻炼、言语训练。患者病情稳定，继续观察。\n\n医师签名：X","出院记录":"入院日期：2026-09-07\n出院日期：2026-09-18\n住院天数：11天\n\n入院诊断：\n1. 吞咽障碍（脑梗死后遗症）\n2. 脑梗死后遗症（右侧肢体偏瘫、构音障碍）\n3. 营养不良\n4. 吸入性肺炎（轻度）\n5. 高血压病2级（很高危）\n6. 贫血\n\n入院情况：患者孙德明，男，70岁，因\"脑梗死后饮水呛咳、进食困难2月，加重伴体重下降1月\"入院。查体：营养差，构音障碍，咽反射减弱，软腭上抬无力，洼田饮水试验5级。右上肢肌力3级，右下肢肌力4级。白蛋白29g/L，胸片示双肺底炎症。\n\n诊疗经过：入院后予营养支持（鼻饲肠内营养、白蛋白）、吞咽功能训练（间接训练+直接训练+神经肌肉电刺激）、抗感染（头孢曲松）、祛痰（氨溴索）、控制血压、营养神经等治疗。配合肢体功能锻炼、言语训练。\n\n出院情况：患者一般情况良好，鼻饲饮食耐受良好，可经口进食糊状食物，无明显呛咳。洼田饮水试验4级（较前改善）。双肺呼吸音清。白蛋白35g/L，血红蛋白115g/L。右上肢肌力3+级，右下肢肌力4+级。\n\n出院诊断：\n1. 吞咽障碍（脑梗死后遗症，好转）\n2. 脑梗死后遗症（右侧肢体偏瘫、构音障碍）\n3. 营养不良（改善）\n4. 吸入性肺炎（治愈）\n5. 高血压病2级（很高危）\n6. 贫血（改善）\n\n出院医嘱：1. 用药指导：\n - 苯磺酸氨氯地平片5mg qd（监测血压）\n - 甲钴胺片0.5mg tid + 胞磷胆碱钠片0.2g tid\n - 氨溴索口服液10ml tid（继续1周）\n2. 饮食指导：\n - 继续鼻饲与经口进食结合，逐渐增加经口进食量\n - 食物性状：糊状、半流质为主，避免流质和干硬食物\n - 进食体位：坐位或躯干30°仰卧位，颈部前屈\n - 一口量：少量多次，每口3-5ml，确认咽下后再喂下一口\n - 进食后保持坐位30分钟，避免立即平卧\n3. 吞咽训练：\n - 每日进行口腔运动训练（舌运动、咀嚼、空吞咽）\n - 冰刺激训练（冰棉签刺激软腭、咽后壁）\n - 呼吸训练、咳嗽训练\n - 建议康复科门诊继续吞咽训练\n4. 鼻饲护理：\n - 鼻饲前确认胃管位置，回抽胃液\n - 鼻饲时抬高床头30-45°\n - 鼻饲后保持半卧位30分钟\n - 定期更换胃管（每月一次）\n5. 复诊：2周后门诊复查吞咽功能、营养状况；1月后复查头颅CT、肝肾功能。\n6. 注意事项：如出现发热、咳嗽加重、呼吸困难、进食呛咳明显、体重继续下降等，立即就诊。\n7. 家庭护理：家属需掌握鼻饲护理、吞咽训练、防误吸急救技能（海姆立克法）。\n\n医师签名：X\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2239,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2f728fb62032ac061bffa592da546b209a6330ec9e28b25846c76d91b236cd6c","pinyin":"tunyanzhangai","initials":"tyza","setting":"in","caseName":"病例1：孙德明，男，70岁","templateNames":["入院记录","首次病程记录","病程记录","出院记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：孙德明，男，70岁",60],["模板名称","入院记录 首次病程记录 病程记录 出院记录",30],["主要诊断编码","",30]]},{"id":"templates-155a2f78a232d21a5b97","key":"v1-c9ccc21dfe2a3058|templates-155a2f78a232d21a5b97","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肌少症","category":"住院病历模板","raw":{"name":"肌少症","category":"住院病历模板","case":{"case_name":"病例1：患者，男，76岁","templates":{"入院记录":"主诉：进行性四肢无力、行走困难1年，加重伴跌倒2次1月。\n\n现病史：患者1年前无明显诱因出现四肢无力，表现为上楼困难、蹲起费力、手提重物能力下降，当时未重视。近半年患者四肢无力加重，行走速度明显减慢，步幅变小，起身需扶持，日常生活能力下降，穿衣、洗漱需家人协助。1月前患者在家中行走时不慎跌倒2次，均为臀部着地，无骨折，无头部外伤，无意识障碍。伴体重下降，近1年体重下降约10kg，食欲减退，精神差，易疲劳。无肢体麻木疼痛，无肌肉萎缩，无吞咽困难，无言语不清，无头痛头晕，无恶心呕吐，无胸闷胸痛，无发热咳嗽。发病以来，患者精神差，食欲差，睡眠欠佳，大小便正常，体重下降约10kg。\n\n既往史：高血压病史15年，最高血压170/100mmHg，长期口服缬沙坦胶囊80mg qd，血压控制在130-140/70-80mmHg。2型糖尿病病史8年，长期口服二甲双胍0.5g tid，血糖控制欠佳。冠心病病史5年，长期口服阿司匹林肠溶片100mg qd、阿托伐他汀钙片20mg qn。否认肝炎、结核等传染病史。否认手术、外伤、输血史。否认食物、药物过敏史。\n\n个人史及过敏史：生于本地，久居本地，无疫区旅居史。吸烟40年，每日20支，已戒1年。饮酒35年，每日白酒3两，已戒1年。否认工业毒物、粉尘、放射性物质接触史。否认药物过敏史。\n\n体格检查：T 36.3℃，P 72次/分，R 18次/分，BP 135/80mmHg。发育正常，营养差，神志清楚，精神差，查体合作。身高165cm，体重52kg，BMI 19.1kg/m²。全身皮肤黏膜无黄染、皮疹及出血点，浅表淋巴结未触及肿大。头颅无畸形，眼睑无水肿，结膜无充血，巩膜无黄染，双瞳孔等大等圆，直径约3mm，对光反射灵敏。耳鼻未见异常，口唇无紫绀，咽无充血，扁桃体无肿大。颈软，无抵抗，颈静脉无怒张，气管居中，甲状腺未触及肿大。胸廓对称无畸形，双肺呼吸音清，未闻及干湿性啰音。心前区无隆起，心尖搏动位于第五肋间左锁骨中线内0.5cm，未触及震颤，心界不大，心率72次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，未见胃肠型及蠕动波，未触及包块，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常，4次/分。肛门直肠及外生殖器未查。脊柱生理弯曲存在，无畸形。四肢肌肉萎缩，以四肢近端为主，双上肢肌力4级，双下肢肌力4级，肌张力正常，腱反射减弱（+），病理征阴性。感觉系统检查正常。共济运动稳准。\n\n专科检查：四肢肌肉萎缩，上肢围度：上臂22cm（正常≥25cm），前臂20cm；下肢围度：大腿38cm（正常≥40cm），小腿28cm。握力：右手18kg，左手16kg（男性正常≥28kg）。6米步行速度：0.7m/s（正常≥1.0m/s）。5次起坐试验：15秒（正常≤12秒）。SARC-F评分：6分（≥4分提示肌少症可能）。\n\n辅助检查：血常规：白细胞6.5×10⁹/L，中性粒60%，血红蛋白110g/L，血小板180×10⁹/L。\n生化：白蛋白32g/L（降低），前白蛋白180mg/L（降低），肌酐75μmol/L，eGFR 78ml/min，血糖8.5mmol/L，糖化血红蛋白7.5%。\n肌酶：CK 80U/L，LDH 150U/L（正常）。\n甲状腺功能：正常。\n维生素D：18ng/ml（缺乏，正常≥30ng/ml）。\n电解质：钾3.8mmol/L，钠138mmol/L，钙2.1mmol/L，磷1.0mmol/L。\n肌电图：待完善。\n双能X线吸收法（DXA）：四肢骨骼肌量15kg，男性骨骼肌质量指数（ASMI）5.5kg/m²（正常≥7.0kg/m²）。\n\n初步诊断：\n1. 肌少症（确诊，重度）\n2. 营养不良\n3. 高血压病2级（很高危）\n4. 2型糖尿病\n5. 冠心病\n6. 维生素D缺乏\n7. 贫血\n\n处理方案：\n1. 老年科/康复科护理常规，一级护理，低盐低脂糖尿病饮食，高蛋白饮食，留陪护，防跌倒。\n2. 营养支持：\n - 高蛋白饮食：蛋白质1.2-1.5g/kg/天，即62-78g/天\n - 补充蛋白粉20g bid\n - 补充维生素D 1000IU qd\n - 补充钙剂1000mg qd\n - 补充复合维生素B、维生素C、锌、镁\n - 必要时肠内营养制剂\n3. 运动康复：\n - 抗阻训练：哑铃、弹力带训练，每周3次，每次20-30分钟\n - 平衡训练：单腿站立、太极拳，每周3次\n - 有氧运动：步行、骑自行车，每周5次，每次30分钟\n - 循序渐进，避免运动损伤\n4. 控制基础疾病：\n - 控制血压：缬沙坦80mg qd\n - 控制血糖：二甲双胍0.5g tid，目标糖化血红蛋白<7.5%\n - 冠心病二级预防：阿司匹林100mg qd、阿托伐他汀20mg qn\n5. 药物治疗：\n - 维生素D 1000IU qd\n - 钙剂1000mg qd\n - 必要时睾酮替代治疗（如睾酮水平低）\n6. 完善检查：肌电图+神经传导速度（目的：鉴别周围神经病变或肌源性损害导致的肌力下降，为病因治疗与康复方案提供依据）、DXA体成分分析（目的：客观测定四肢骨骼肌量与脂肪比例，为肌少症诊断及营养运动干预效果评价提供依据）、睾酮水平（目的：评估性激素水平对肌肉合成的影响，为是否需激素替代治疗提供依据）、肿瘤标志物（目的：排除恶性肿瘤等消耗性疾病导致的体重下降与肌肉丢失）、慢性炎症指标（CRP、白介素-6等）（目的：评估慢性炎症状态对肌肉分解代谢的影响，为营养抗炎干预提供依据）、肝肾功能+白蛋白+维生素D（目的：评估营养储备与代谢水平，为营养支持方案制定提供依据）。\n7. 预防跌倒：环境改造（扶手、防滑垫、充足照明），辅助器具（拐杖、助行器），家庭护理指导。\n8. 健康教育：肌少症知识宣教，营养指导，运动指导，定期复查。","首次病程记录":"2026-09-08 15:00 首次病程记录\n\n患者，男，76岁，因\"进行性四肢无力、行走困难1年，加重伴跌倒2次1月\"入院。\n\n一、病例特点：\n1. 老年男性，76岁，慢性起病，进行性加重。\n2. 临床表现：进行性四肢无力1年，上楼困难、蹲起费力，行走速度减慢，日常生活能力下降。1月内跌倒2次，体重下降10kg。\n3. 既往史：高血压15年、2型糖尿病8年、冠心病5年。\n4. 体格检查：BMI 19.1kg/m²，营养差。四肢肌肉萎缩，以近端为主。四肢肌力4级，腱反射减弱。握力右手18kg、左手16kg，6米步行速度0.7m/s，5次起坐试验15秒，SARC-F评分6分。\n5. 辅助检查：白蛋白32g/L，前白蛋白180mg/L，维生素D 18ng/ml，糖化血红蛋白7.5%。DXA示ASMI 5.5kg/m²（低于正常）。\n\n二、拟诊讨论：\n（一）初步诊断：\n1. 肌少症（确诊，重度）\n2. 营养不良\n3. 高血压病2级（很高危）\n4. 2型糖尿病\n5. 冠心病\n6. 维生素D缺乏\n7. 贫血\n\n（二）诊断依据：\n1. 肌少症（重度）：老年男性，进行性四肢无力、行走困难、跌倒、体重下降；查体见四肢肌肉萎缩，肌力4级，腱反射减弱；握力降低（<28kg），步行速度减慢（<1.0m/s），5次起坐试验延长（>12秒），SARC-F评分6分（≥4分）；DXA示ASMI 5.5kg/m²（<7.0kg/m²）。符合亚洲肌少症工作组（AWGS）诊断标准：肌肉量减少+肌力下降+躯体功能下降。\n2. 营养不良：体重下降10kg，BMI 19.1kg/m²，白蛋白32g/L，前白蛋白180mg/L。\n3. 高血压病2级：高血压病史15年，最高170/100mmHg，合并糖尿病、冠心病。\n4. 2型糖尿病：糖尿病病史8年，空腹血糖8.5mmol/L，糖化血红蛋白7.5%。\n5. 冠心病：冠心病病史5年，长期口服阿司匹林、他汀。\n6. 维生素D缺乏：维生素D 18ng/ml（<20ng/ml）。\n7. 贫血：血红蛋白110g/L，营养差。\n\n（三）鉴别诊断：\n1. 甲状腺功能亢进性肌病：表现为肌无力、肌萎缩，可伴心悸、多汗、体重下降，甲状腺功能异常。本患者甲状腺功能正常，不支持。\n2. 重症肌无力：表现为波动性肌无力，晨轻暮重，可伴眼睑下垂、复视，新斯的明试验阳性，肌电图示低频重复电刺激递减。本患者症状无波动，无眼睑下垂，不支持，需肌电图排除。\n3. 多发性肌炎：表现为对称性四肢近端肌无力，可伴肌痛、皮疹，肌酶升高，肌电图示肌源性损害，肌肉活检可确诊。本患者无肌痛、皮疹，肌酶正常，不支持，需肌电图、肌酶排除。\n4. 运动神经元病（肌萎缩侧索硬化）：表现为进行性肌无力、肌萎缩，可伴肌束颤动、锥体束征，肌电图示广泛神经源性损害。本患者无肌束颤动、锥体束征，不支持，需肌电图排除。\n5. 癌性肌病：老年患者，体重下降，需排除肿瘤所致肌病，需完善肿瘤标志物、影像学检查。\n6. 药物性肌病：长期服用他汀类药物可引起肌痛、肌无力，肌酶升高。本患者长期服用阿托伐他汀，需警惕，但肌酶正常，不支持。\n\n三、诊疗计划：\n1. 老年科/康复科护理常规，一级护理，留陪护，防跌倒。\n2. 营养支持（高蛋白饮食、蛋白粉、维生素D、钙剂）。\n3. 运动康复（抗阻训练、平衡训练、有氧运动）。\n4. 控制基础疾病（血压、血糖、冠心病二级预防）。\n5. 完善肌电图、DXA、睾酮、肿瘤标志物等检查。\n6. 预防跌倒，健康教育。\n7. 必要时多学科协作（老年科、康复科、营养科）。\n\n医师签名：X","病程记录":"2026-09-09 09:00 病程记录\n\n患者一般情况较前好转，四肢无力无明显变化，精神较前改善，食欲稍增加。无跌倒，无胸闷胸痛，无呼吸困难。\n\n查体：T 36.4℃，P 70次/分，R 18次/分，BP 130/78mmHg。神志清楚，精神较前好转。四肢肌肉萎缩，四肢肌力4级，腱反射减弱。双肺呼吸音清，心率70次/分，律齐。腹软，无压痛。\n\n已开始高蛋白饮食、蛋白粉补充、维生素D及钙剂补充。开始康复评估，制定个体化运动方案。患者病情稳定，继续观察。\n\n医师签名：X\n\n2026-09-13 09:00 病程记录\n\n患者一般情况良好，四肢无力较前稍好转，精神食欲改善。已开始抗阻训练和平衡训练，耐受良好。无跌倒，无不适主诉。\n\n查体：T 36.3℃，P 68次/分，R 17次/分，BP 128/75mmHg。神志清楚，精神好。四肢肌力4级，握力较前稍增加（右手20kg，左手18kg）。双肺呼吸音清，心率68次/分，律齐。\n\n复查：白蛋白34g/L，前白蛋白200mg/L，维生素D 22ng/ml。\n肌电图：未见明显神经源性或肌源性损害。\n睾酮：350ng/dl（正常范围）。\n肿瘤标志物：正常。\n\n继续营养支持和运动康复。患者病情稳定，继续观察。\n\n医师签名：X","出院记录":"入院日期：2026-09-08\n出院日期：2026-09-19\n住院天数：11天\n\n入院诊断：\n1. 肌少症（确诊，重度）\n2. 营养不良\n3. 高血压病2级（很高危）\n4. 2型糖尿病\n5. 冠心病\n6. 维生素D缺乏\n7. 贫血\n\n入院情况：患者，男，76岁，因\"进行性四肢无力、行走困难1年，加重伴跌倒2次1月\"入院。查体：BMI 19.1kg/m²，四肢肌肉萎缩，肌力4级，腱反射减弱。握力右手18kg，6米步行速度0.7m/s，SARC-F评分6分。DXA示ASMI 5.5kg/m²。白蛋白32g/L，维生素D 18ng/ml。\n\n诊疗经过：入院后完善相关检查，予营养支持（高蛋白饮食、蛋白粉、维生素D、钙剂）、运动康复（抗阻训练、平衡训练、有氧运动）、控制基础疾病（血压、血糖、冠心病二级预防）等治疗。肌电图未见异常，排除神经肌肉疾病。\n\n出院情况：患者一般情况良好，四肢无力较前好转，精神食欲改善。握力右手20kg，6米步行速度0.8m/s。白蛋白35g/L，维生素D 25ng/ml。\n\n出院诊断：\n1. 肌少症（重度，好转）\n2. 营养不良（改善）\n3. 高血压病2级（很高危）\n4. 2型糖尿病\n5. 冠心病\n6. 维生素D缺乏（改善）\n7. 贫血（改善）\n\n出院医嘱：1. 用药指导：\n - 缬沙坦胶囊80mg qd（监测血压）\n - 二甲双胍片0.5g tid（监测血糖）\n - 阿司匹林肠溶片100mg qd（注意有无出血）\n - 阿托伐他汀钙片20mg qn（3月后复查肝功能、肌酶、血脂）\n - 维生素D滴剂1000IU qd（3月后复查维生素D）\n - 碳酸钙D3片1000mg qd\n - 蛋白粉20g bid（随餐服用）\n - 甲钴胺片0.5mg tid\n2. 营养指导：\n - 高蛋白饮食：蛋白质1.2-1.5g/kg/天，多吃鸡蛋、牛奶、鱼肉、豆制品\n - 均衡饮食：蔬菜水果、全谷物、坚果\n - 少量多餐，保证热量摄入\n - 必要时肠内营养制剂\n3. 运动指导：\n - 抗阻训练：哑铃、弹力带，每周3次，每次20-30分钟\n - 平衡训练：单腿站立、太极拳，每周3次\n - 有氧运动：步行、骑自行车，每周5次，每次30分钟\n - 循序渐进，避免运动损伤，运动前热身，运动后拉伸\n - 建议康复科门诊随访，制定个体化运动方案\n4. 预防跌倒：\n - 环境改造：卫生间安装扶手、地面防滑、充足照明\n - 辅助器具：必要时使用拐杖、助行器\n - 穿防滑鞋，避免穿拖鞋\n - 起身时慢坐慢站，避免突然体位变化\n5. 复诊：1月后门诊复查肌力、握力、步行速度、营养指标；3月后复查维生素D、DXA体成分分析。\n6. 注意事项：如出现跌倒、骨折、肌无力加重、吞咽困难、呼吸困难等，立即就诊。\n7. 家庭护理：家属协助运动训练，监督服药和饮食，定期监测体重、血压、血糖。\n8. 心理支持：鼓励患者积极参与康复，保持乐观心态，避免焦虑抑郁。\n\n医师签名：X\n\n离院方式：医嘱离院\n\n【医保结算清单要素】\n主要诊断（名称+ICD-10编码）：________________（编码待填）\n入院病情：有\n其他诊断（名称+ICD-10编码）：________________（含并发症/合并症）\n离院方式：见上文\n主要手术/操作：无\n是否主要诊断：是（主要诊断须为本次住院消耗医疗资源最多、对健康危害最大的诊断）\n（本区块供医保结算清单填写使用；编码请按国家医保局现行版本填写）\n"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2240,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"14398737512aa06d6e50bca46305dc9480803ef24e0be0668a524c3d81926fdc","pinyin":"jishaozheng","initials":"jsz","setting":"in","caseName":"病例1：患者，男，76岁","templateNames":["入院记录","首次病程记录","病程记录","出院记录"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","病例1：患者，男，76岁",60],["模板名称","入院记录 首次病程记录 病程记录 出院记录",30],["主要诊断编码","",30]]},{"id":"templates-eb324492c7764bdbae23","key":"v1-c9ccc21dfe2a3058|templates-eb324492c7764bdbae23","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"成人支气管肺炎","category":"门诊病历模板","raw":{"name":"成人支气管肺炎","category":"门诊病历模板","case":{"case_name":"门诊病历","templates":{"主诉":"咳嗽、咳痰伴发热5天，加重伴气促1天。","现病史":"患者5天前受凉后出现咳嗽、咳痰，痰为黄色黏痰，量中等，不易咳出，伴发热，体温最高38.6℃，无寒战，无胸痛咯血，无夜间阵发性呼吸困难。自服头孢克肟胶囊0.1g bid、氨溴索口服液10ml tid（具体不详），症状无明显改善。1天前患者上述症状加重，咳嗽频繁，痰量增多，为黄脓痰，伴活动后气促，无下肢水肿，无端坐呼吸。发病以来，患者精神欠佳，食欲尚可，睡眠欠佳，大小便正常，体重无明显变化。","既往史":"高血压病史8年，最高血压160/95mmHg，长期口服氨氯地平5mg qd，血压控制在130-140/70-80mmHg。否认糖尿病、冠心病病史。否认肝炎、结核等传染病史。否认手术、外伤、输血史。否认食物、药物过敏史。","个人史及过敏史":"生于本地，久居本地，无疫区旅居史。吸烟20年，每日10支，未戒烟。偶有饮酒。否认工业毒物、粉尘、放射性物质接触史。否认药物过敏史。","体格检查":"T 38.5℃，P 96次/分，R 22次/分，BP 135/85mmHg，SpO2 94%（未吸氧）。发育正常，营养中等，神志清楚，精神欠佳，急性病容，查体合作。全身皮肤黏膜无黄染、皮疹及出血点，浅表淋巴结未触及肿大。头颅无畸形，眼睑无水肿，结膜无充血，巩膜无黄染，双瞳孔等大等圆，直径约3mm，对光反射灵敏。耳鼻未见异常，口唇无紫绀，咽无充血，扁桃体无肿大。颈软，无抵抗，颈静脉无怒张，气管居中，甲状腺未触及肿大。胸廓对称无畸形，双肺呼吸音粗，双肺底可闻及散在湿性啰音，未闻及干性啰音及胸膜摩擦音。心前区无隆起，心尖搏动位于第五肋间左锁骨中线内0.5cm，未触及震颤，心界不大，心率96次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，未见胃肠型及蠕动波，未触及包块，肝脾肋下未触及，移动性浊音阴性，肠鸣音正常，4次/分。双下肢无水肿。","辅助检查":"检查计划：患者受凉后咳嗽、咳黄黏痰伴发热5天，体温最高38.6℃，1天前加重并出现活动后气促，结合双肺下叶斑片状模糊影考虑社区获得性肺炎，入院即刻完善血常规检查（白细胞12.5×10⁹/L、中性粒细胞百分比82%、淋巴细胞百分比12%、血红蛋白130g/L、血小板220×10⁹/L），明确感染程度并排除贫血、血小板减少；查CRP（65mg/L，升高）评估炎症反应强度，指导抗感染疗程与疗效判断；查降钙素原鉴别细菌感染与病毒、非感染性炎症，指导是否使用抗菌药物；完善胸部正侧位X线检查（双肺下叶斑片状模糊影，考虑支气管肺炎）明确病变部位与范围，若治疗3-5天体温不退或气促加重，复查胸片或完善胸部CT检查，排除肺脓肿、胸腔积液及肺部占位；患者咳黄脓痰且不易咳出，完善痰涂片革兰染色及痰培养加药物敏感试验，明确病原菌并指导目标性抗感染治疗；因气促、痰量增多，查动脉血气分析，明确有无低氧血症及二氧化碳潴留，评估呼吸功能；患者有高血压病史8年，长期口服氨氯地平，完善肝肾功能及血电解质检查，排除肝肾功能不全、电解质紊乱，并为用药安全性提供依据；查血糖、血脂及心电图，了解有无糖脂代谢异常及心肌缺血，评估心血管基础状况，指导综合治疗与血压管理。\n\n（检查清单）\n血常规（本院，2026-09-10）：白细胞12.5×10⁹/L，中性粒细胞百分比82%，淋巴细胞百分比12%，血红蛋白130g/L，血小板220×10⁹/L。\nCRP：65mg/L（升高）。\n胸片（本院，2026-09-10）：双肺下叶斑片状模糊影，考虑支气管肺炎。","初步诊断":"1. 成人支气管肺炎（社区获得性）\n2. 高血压病2级（很高危）","处理方案":"1. 抗感染：阿莫西林克拉维酸钾片0.375g tid 口服（青霉素过敏者改用左氧氟沙星0.5g qd），疗程7-10天。\n2. 祛痰：氨溴索口服液10ml tid 口服；或乙酰半胱氨酸泡腾片0.6g qd 口服。\n3. 退热：体温>38.5℃时布洛芬缓释胶囊0.3g 口服，多饮水，物理降温。\n4. 止咳：咳嗽剧烈影响睡眠时右美沙芬愈创甘油醚糖浆10ml tid 口服（痰多者不宜强力镇咳）。\n5. 控制血压：氨氯地平5mg qd 口服，监测血压。\n6. 完善检查：痰培养+药敏（必要时）、降钙素原、血气分析（SpO2<92%时）。\n7. 生活指导：戒烟，注意休息，多饮水，清淡饮食，保持室内通风。\n8. 复诊：3天后复诊，如症状加重（高热不退、呼吸困难、胸痛、意识改变）立即就诊。\n9. 预防接种：建议接种肺炎疫苗、流感疫苗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2241,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a8e0e82e2ccf82caa9d1b7b6f905e7d2698d116670406391709932387ecd4951","pinyin":"chengrenzhiqiguanfeiyan","initials":"crzqgfy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7520203471208bc92c13","key":"v1-c9ccc21dfe2a3058|templates-7520203471208bc92c13","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"2型糖尿病足","category":"烧伤整形科","raw":{"name":"2型糖尿病足","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】下肢麻木、刺痛、烧灼感或感觉减退/消失；足部畸形（爪形趾、夏科足）；皮肤干燥、脱屑、皲裂；足部溃疡（多位于足底、趾间、骨突部位）；创面可有渗液、坏死组织、异味；合并感染时红肿热痛、脓性分泌物、发热；严重时坏疽（干性/湿性）。。\n【待人工确认·本机素材无此段原文】","现病史":"糖尿病患者因合并神经病变及各种不同程度末梢血管病变而导致下肢感染、溃疡形成和/或深部组织破坏。是糖尿病最严重和治疗费用最高的慢性并发症之一，重者可导致截肢。\n常见表现：下肢麻木、刺痛、烧灼感或感觉减退/消失；足部畸形（爪形趾、夏科足）；皮肤干燥、脱屑、皲裂；足部溃疡（多位于足底、趾间、骨突部位）；创面可有渗液、坏死组织、异味；合并感染时红肿热痛、脓性分泌物、发热；严重时坏疽（干性/湿性）。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"足部视诊：畸形、胼胝、溃疡部位大小深度、有无坏死组织、分泌物性状气味；触诊：皮温（升高提示感染/动脉缺血时降低）、足背动脉/胫后动脉搏动（减弱或消失）、振动觉/针刺觉/10g尼龙丝触觉（神经病变评估）；踝肱指数(ABI)测定；关节活动度。","辅助检查":"空腹血糖、糖化血红蛋白(HbA1c)；血常规、CRP、PCT（感染评估）；创面分泌物细菌培养+药敏；肝肾功能、电解质、白蛋白；凝血功能；下肢血管彩超/CTA/MRA（评估血管病变）；足部X线（骨髓炎、骨破坏、夏科关节）；必要时MRI（深部脓肿、骨髓炎）。","初步诊断":"糖尿病病史 + 足部溃疡/感染/坏疽 + 神经病变体征（感觉减退）+ 血管病变体征（动脉搏动减弱、ABI异常）；Wagner分级：0级-高危足，1级-浅表溃疡，2级-深达肌腱、骨或关节囊（无脓肿/骨髓炎），3级-深部脓肿/骨髓炎，4级-局限性坏疽，5级-全足坏疽。疑深部感染/骨髓炎者行探骨试验（probe-to-bone，探及骨质为阳性），阳性提示骨髓炎可能，需X线/MRI等影像证实。\n1. 2型糖尿病足（ICD-10：E11.621）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n【抗感染】根据药敏选择，经验性：头孢类+甲硝唑/克林霉素（覆盖厌氧菌），严重感染：哌拉西林他唑巴坦4.5g q8h ivgtt 或 美罗培南1g q8h ivgtt；【改善循环】前列地尔10-20μg qd ivgtt 或 丁咯地尔0.2g qd ivgtt；【营养神经】甲钴胺0.5mg qd ivgtt 或 硫辛酸600mg qd ivgtt；【控制血糖】胰岛素静脉泵入或皮下注射（血糖控制目标：空腹4.4-7.0mmol/L，非空腹<10.0mmol/L）；【支持治疗】白蛋白、复方氨基酸（低蛋白血症时）。\n\n【药物治疗·口服】\n【降糖】二甲双胍0.5g tid（肾功能正常时）+ SGLT2抑制剂（如达格列净10mg qd，注意泌尿生殖感染风险）或DPP-4抑制剂；【抗血小板】阿司匹林100mg qd 或 氯吡格雷75mg qd；【调脂】阿托伐他汀20mg qn；【改善循环】贝前列素钠40μg tid 或 西洛他唑50mg bid；【营养神经】甲钴胺0.5mg tid、依帕司他50mg tid；【止痛】普瑞巴林75mg bid（神经病理性疼痛）或 加巴喷丁0.3g qn起始渐加。\n\n【治疗】\n【创面处理】①清创：清除坏死组织，保留有活力组织；②敷料选择：渗液多用泡沫敷料/藻酸盐敷料，肉芽生长期用水胶体/凝胶敷料，感染创面用银离子敷料；③负压封闭引流(VSD)：深部脓肿、大量渗液时；④减压：全接触石膏(TCC)或可拆卸行走靴，避免溃疡部位受压；⑤血管重建：严重下肢缺血时行介入治疗（球囊扩张/支架）或外科旁路手术；⑥骨髓炎：手术清创+长期抗生素（6-8周）；⑦坏疽：截肢/截趾。\n\n【处理要点】\n【血糖管理】胰岛素强化治疗，密切监测血糖；【感染控制】根据药敏调整抗生素，疗程：浅表感染1-2周，深部感染2-4周，骨髓炎6-8周；【创面管理】定期换药（1-2天/次），评估创面愈合情况；【血管评估】ABI<0.5提示严重缺血，需血管外科会诊；【营养支持】高蛋白饮食，必要时肠内营养；【教育】足部护理指导：每日检查足部、温水洗脚（水温<37℃）、穿宽松鞋袜、避免赤脚行走、定期修剪指甲。\n\n【护理】\n每日评估创面大小、深度、渗液、肉芽组织情况；抬高患肢促进静脉回流；保持创面敷料清洁干燥；监测血糖（空腹+三餐前后+睡前）；观察足部皮温、颜色、感觉变化；指导患者正确剪指甲（平直剪，避免剪伤甲沟）；卧床患者定时翻身避免足跟受压。\n\n【饮食】\n糖尿病饮食：控制总热量，碳水化合物占50-60%，蛋白质1.0-1.2g/kg/d（肾功能正常），脂肪<30%；低盐（<5g/d）；增加膳食纤维；戒烟限酒；合并低蛋白血症时增加优质蛋白（鸡蛋、牛奶、鱼）。\n\n【注意事项】\n①糖尿病足溃疡愈合缓慢，需耐心治疗，平均愈合时间3-6个月；②避免使用刺激性强的消毒剂（碘酒、酒精）直接接触创面；③禁用热水袋/电热毯直接热敷足部（感觉减退易烫伤）；④戒烟至关重要（吸烟加重血管病变）；⑤ABI>1.3提示血管钙化（糖尿病常见），需结合趾肱指数(TBI)判断；⑥所有糖尿病患者应定期足部筛查（至少每年1次）。\n\n【急诊/急救】\n【急性感染加重】高热、寒战、足部迅速红肿扩散、脓性分泌物增多、意识改变→立即查血培养、广谱抗生素、急诊清创；【急性下肢缺血】突发足部剧痛、苍白、发凉、麻木、动脉搏动消失→血管外科急诊，6小时内血运重建；【低血糖】心慌出汗手抖→立即口服葡萄糖/糖果，意识障碍时静脉推注50%葡萄糖40-60ml。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"E11.621","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2242,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"952b58b683419c9b9eed1338c60985f3bb72e80959ee07ca39111c6fd192c377","pinyin":"2xingtangniaobingzu","initials":"2xtnbz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E11.621",30]]},{"id":"templates-b19d7ab625c523cea8e3","key":"v1-c9ccc21dfe2a3058|templates-b19d7ab625c523cea8e3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"一氧化碳中毒(煤气)","category":"中毒/理化","raw":{"name":"一氧化碳中毒(煤气)","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】轻度（COHb 10-30%）：头痛、头晕、恶心、呕吐、心悸、乏力、视物模糊、中度（COHb 30-50%）：面色潮红、口唇樱桃红色、烦躁、步态不稳、意识模糊、虚脱、重度（COHb >50%）：深昏迷、抽搐、呼吸困难、呼吸抑制、休克、心律失常、肺水肿、严重者：多器官功能衰竭、脑疝、死亡、迟发性脑病：意识恢复后2-60天（平均2周）出现痴呆、帕金森综合征、偏瘫、失语、癫痫等、皮肤可出现水疱、红斑（压迫部位）、心肌缺血、心律失常（合并冠心病者风险高）。\n【待人工确认·本机素材无此段原文】","现病史":"一氧化碳（CO，煤气）与血红蛋白亲和力是氧的200-300倍，形成碳氧血红蛋白（COHb），导致组织严重缺氧。典型表现为口唇樱桃红色、意识障碍。高压氧治疗是关键，可预防迟发性脑病。\n常见表现：轻度（COHb 10-30%）：头痛、头晕、恶心、呕吐、心悸、乏力、视物模糊、中度（COHb 30-50%）：面色潮红、口唇樱桃红色、烦躁、步态不稳、意识模糊、虚脱、重度（COHb >50%）：深昏迷、抽搐、呼吸困难、呼吸抑制、休克、心律失常、肺水肿、严重者：多器官功能衰竭、脑疝、死亡、迟发性脑病：意识恢复后2-60天（平均2周）出现痴呆、帕金森综合征、偏瘫、失语、癫痫等、皮肤可出现水疱、红斑（压迫部位）、心肌缺血、心律失常（合并冠心病者风险高）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 动脉血气分析＋血碳氧血红蛋白（COHb）浓度测定：入院即刻、高压氧治疗前采血，动态复查以评估疗效与中毒程度\n2. 头颅CT：急诊即查，排除脑水肿、颅内出血；意识障碍重或疑迟发性脑病者，病情稳定后行头颅MRI评估脑白质病变\n3. 心电图＋心肌酶谱、肌钙蛋白：急诊完成，筛查心肌损伤及心律失常\n4. 血常规、电解质、肝肾功能、血糖：入院基础检查，监测酸碱失衡与脏器损伤\n5. 脑电图：意识恢复缓慢或清醒后再次出现精神神经症状（疑迟发性脑病）时检查","初步诊断":"1. 一氧化碳接触史（煤气泄漏、燃煤取暖、汽车尾气、火灾烟雾）\n2. 同环境多人同时发病（重要线索）\n3. 口唇樱桃红色（特征性，但不是所有患者都有）\n4. 血COHb测定升高（>10%有意义，吸烟者可偏高）\n5. 血气分析：氧分压正常或降低，血氧饱和度降低\n6. 头颅CT/MRI：【住址】\n7. 脑电图：弥漫性慢波\n8. 排除其他原因昏迷（药物中毒、脑血管意外、低血糖等）\n1. 一氧化碳中毒(煤气)（ICD-10：T58）","鉴别诊断":"1. 排除其他原因昏迷（药物中毒、脑血管意外、低血糖等）\n2. 口唇樱桃红色不是所有患者都有，不能以此排除诊断","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：高流量吸氧（8-10L/min），最好面罩吸氧\n\n方案2：\n 用法：20%甘露醇 125-250ml静滴 q6-8h（脑水肿）\n\n方案3：\n 用法：呋塞米 20-40mg静注（辅助降颅压）\n\n方案4：\n 用法：地塞米松 10-20mg静注（减轻脑水肿）\n\n方案5：\n 用法：纳洛酮 0.4-0.8mg静注（促醒）\n\n方案6：\n 用法：胞磷胆碱 0.5g静滴（脑保护）\n\n方案7：\n 用法：脑蛋白水解物/依达拉奉（脑保护，酌情）\n\n方案8：\n 用法：5%葡萄糖+维生素C 静滴（促进代谢）\n\n方案9：\n 用法：呼吸兴奋剂（呼吸抑制时）\n\n方案10：\n 用法：抗心律失常药物（根据心律失常类型）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：胞磷胆碱钠片 0.2g tid（恢复期）\n\n药物2：\n 用法：维生素B1、B6、B12（营养神经）\n\n药物3：\n 用法：银杏叶片（改善脑循环，恢复期）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即将患者转移至空气新鲜处，解开衣领，保持呼吸道通畅\n高流量吸氧（8-10L/min），最好面罩吸氧\n尽快行高压氧治疗；指征包括：昏迷或意识障碍、血COHb≥25%、神经系统症状/体征（共济失调、认知障碍等）、心肌缺血或心律失常、孕妇（COHb≥15-20%）、严重代谢性酸中毒；症状轻且无上述指征者也应就医评估并随访观察（警惕迟发性脑病）。高压氧可显著降低迟发性脑病发生率\n高压氧治疗方案：2-2.5ATA，每次60-90分钟，每日1-2次，疗程10-20次或更长\n防治脑水肿：甘露醇+呋塞米+地塞米松\n控制抽搐：地西泮10-20mg静注\n对症支持：维持呼吸循环功能、纠正酸中毒、保护心肌、防治感染\n昏迷者保持呼吸道通畅，必要时气管插管机械通气\n恢复期给予营养神经、改善脑循环药物，康复训练\n所有患者均需随访，警惕迟发性脑病\n\n【处理要点】\n立即打开门窗通风，将患者转移至空气新鲜处\n关闭煤气阀门，切断气源，禁止开关电器（防止爆炸）\n解开衣领，保持呼吸道通畅，头偏向一侧\n呼吸心跳停止者立即心肺复苏\n高流量吸氧，尽快送医行高压氧治疗\n记录中毒时间、环境、意识状态\n昏迷者注意保暖，防止误吸\n即使症状轻也要就医观察（迟发性脑病风险）\n同环境其他人也要检查，无症状者也需观察\n\n【护理】\n氧疗护理：立即高流量面罩吸氧（10L/min以上），重度中毒尽早配合高压氧舱治疗，做好舱内生命体征监护\n严密监测意识状态（GCS评分、瞳孔、四肢肌张力）及生命体征，警惕迟发性脑病：清醒后再次出现认知障碍、运动障碍、精神异常\n保持呼吸道通畅：昏迷者去枕平卧、头偏向一侧，及时吸痰防误吸窒息，必要时备气管插管\n安全防护：烦躁、共济失调者加床栏防坠床跌倒，防止自伤、走失，夜间加强巡视\n并发症预防：加强翻身拍背防压疮与坠积性肺炎，长期卧床者预防下肢深静脉血栓\n\n【饮食】\n昏迷、意识障碍期间禁食，予静脉补液维持水电解质平衡；清醒无呕吐后先试温凉流质\n进食以高蛋白、高维生素、易消化饮食为主（蛋、奶、瘦肉、新鲜蔬果），促进脑组织修复\n多饮水、保证尿量充足，促进代谢产物排出\n忌烟、酒及浓茶咖啡，避免增加耗氧与神经系统兴奋\n合并心肌损伤者低盐低脂饮食，少食多餐、避免饱餐\n\n【注意事项】\n一氧化碳中毒最严重的并发症是迟发性脑病，即使症状轻也应高压氧治疗并随访\n高压氧是治疗CO中毒最有效的方法，应尽早进行，中重度中毒必须做\n口唇樱桃红色不是所有患者都有，不能以此排除诊断\nCOHb半衰期在室内空气下约4-5小时，吸纯氧可缩短至40-80分钟，高压氧可缩短至20-30分钟\n轻度中毒也可能发生迟发性脑病，不能因症状轻而忽视\n冬季燃煤取暖、燃气热水器是常见中毒原因，注意通风\n汽车在密闭车库内怠速运行也可导致CO中毒\n恢复期出现智力下降、步态不稳、性格改变等，应警惕迟发性脑病，及时就医\n\n【急诊/急救】\n立即转移至空气新鲜处，打开门窗通风\n关闭煤气，禁止开关电器\n解开衣领，保持呼吸道通畅\n高流量吸氧\n呼吸心跳停止者立即心肺复苏\n尽快送医行高压氧治疗","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「一氧化碳中毒(煤气)」原文）"},"icd10_diagnosis":"T58","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2243,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6608be6fd2a8baf40c905caa4e800cf9c1f84cb09f490a98f3f339a642b2aeef","pinyin":"yiyanghuatanzhongdu(meiqi)","initials":"yyhtzd(mq)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T58",30]]},{"id":"templates-d2dca52266ed667d9b86","key":"v1-c9ccc21dfe2a3058|templates-d2dca52266ed667d9b86","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"三叉神经良性肿瘤","category":"神经外科临床路径（2019年版）","raw":{"name":"三叉神经良性肿瘤","category":"神经外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\r（1）血常规、尿常规，血型。\r（2）凝血功能、肝肾功能、血电解质、血糖、感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）。\r（3）心电图、胸部X线平片。\r（4）头颅CT、MRI。\r（5）神经电生理检查：视觉诱发电位、听觉诱发电位、体感诱发电位、运动诱发电位、面肌电图。\r（6）其他检查：纯音测听、视力视野、前庭功能检查。\r2.根据患者病情，必要时行心肺功能检查、DTI、DWI检查和认知功能评定。\r（七）预防性抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则》（国卫办医发〔2015〕43号）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n神经外科学分册》（中华医学会编著，人民卫生出版社）、《临床技术操作规范\n神经外科分册》（中华医学会编著，人民军医出版社）、《王忠诚神经外科学》（王忠诚主编，湖北科学技术出版社）、《神经外科学》（赵继宗主编，人民卫生出版社）。\r1.临床表现\r（1）三叉神经症状：最多见，多为首发症状, 表现为患侧面部及口腔麻木感、痛觉减退、角膜反射迟钝或消失；其次出现阵发性疼痛（三叉神经痛），疼痛常局限于三叉神经感觉根分布区，多以单侧牙痛或颜面、下颌、鼻旁疼痛起病，以后可逐渐出现咀嚼肌、颞肌无力或萎缩。\r（2）临近结构受侵犯表现：包括颅神经、脑干、小脑受压迫产生的症状，如肿瘤位于颅后窝者可逐渐出现复视、周围性面肌麻痹和进行性耳聋，晚期可有小脑症状、颅内压增高和后组颅神经症状；位于颅中窝者可逐渐出现视力障碍、动眼神经麻痹、同侧眼球突出等症状；肿瘤骑跨于颅中、后窝者可引起对侧轻偏瘫及小脑症状。\r（3）颅内压增高症状：头痛、呕吐等，由肿瘤体积增大引起。\r2.辅助检查\r（1）头颅CT：肿瘤呈等密度或低密度卵圆形或哑铃形影像，常骑跨颅中、后窝，骨窗像可显示颅中窝或岩骨骨质破坏吸收。\r（2）头颅MRI：肿瘤典型征象为骑跨颅中、后窝生长，边界清楚的哑铃形肿物；T1加权像呈低或等信号，T2加权像呈高或等信号\n，注射造影剂后可被强化，少数囊变者环形强化，瘤周一般无水肿。MRI可显示肿瘤与临近结构如脑干、海绵窦等的关系。\r（3）颅神经电生理检查。\r（三）\n1. 三叉神经良性肿瘤（ICD-10：D33）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n神经外科学分册》（中华医学会编著，人民卫生出版社）、《临床技术操作规范\n神经外科分册》（中华医学会编著，人民军医出版社）、《王忠诚神经外科学》（王忠诚主编，湖北科学技术出版社）、《神经外科学》（赵继宗主编，人民卫生出版社）。\r1.临床诊断为三叉神经良性肿瘤，有颅内压增高症状或局灶性症状者需手术治疗，手术方法是开颅三叉神经肿瘤切除术。\r2.手术风险较大者（高龄、妊娠期、合并较严重内科疾病），需向患者或家属交代病情；如不同意手术，应当充分告知风险，履行签字手续，并予严密观察。\r（四）\n\n【临床路径·选择用药】\n选择用药。建议使用第一、二代头孢菌素；明确感染患者，可根据药敏试验结果调整抗菌药物。\r2.预防性用抗菌药物，时间为术前30分钟。\r（八）手术日为入院第4天\r1.麻醉方式：全身麻醉。\r2.手术方式：开颅三叉神经肿瘤切除术，术中行神经电生理监测，根据患者病情，可选用手术相关设备包括神经导航系统、超声吸引器系统等。\r3.手术置入物：颅骨、硬脑膜修复材料、止血材料，颅骨固定材料。\r4.术中用药：激素、脱水药、抗菌药物。\r5.输血：根据手术失血情况决定。\r（九）术后住院恢复7～8天\r1.必须复查的检查项目：头颅CT或MRI扫描，血常规、肝肾功能、血电解质等。\r2.根据患者病情，必要时行心肺功能、认知功能评定，DTI、DWI、视力视野、神经电生理检查、纯音测听、前庭功能检查等检查。\r3.术后用药：脱水药、激素、抗菌药物，可根据患者病情患者抗癫痫、镇痛、止吐药物。\r（十）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：D33三叉神经良性肿瘤疾病编码。\r2.当患者同时具有其他疾病诊断，但在住院期间不需特殊处理、不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备3天\r1.","临床路径·标准住院日":"标准住院日为10～12天\r（五）","临床路径·出院标准":"出院标准\r1.患者病情稳定，体温正常，手术切口愈合良好；生命体征平稳。\r2.没有需要住院处理的并发症和（或）合并症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.术中或术后继发手术部位或其他部位颅内血肿、脑水肿等并发症，严重者需要二次手术，导致住院时间延长、费用增加。\r2.术后继发脑脊液漏、切口感染或延期愈合、颅内感染和神经血管损伤，导致住院时间延长、费用增加。\r3.术后伴发其他内、外科疾病需进一步诊治，导致住院时间延长。\r\f二、三叉神经良性肿瘤","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 神经外科临床路径（2019年版） · 三叉神经良性肿瘤临床路径（2019年版）.doc"},"icd10_diagnosis":"D33","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2244,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"edac0e69a68b1ed3413d148e2c64f70ad4cbf2186426168ec7488e72b8e9b7d8","pinyin":"sanchashenjingliangxingzhongliu","initials":"scsjlxzl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","D33",30]]},{"id":"templates-dd0041b9d7a601192062","key":"v1-c9ccc21dfe2a3058|templates-dd0041b9d7a601192062","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"上消化道大出血","category":"院前急救","raw":{"name":"上消化道大出血","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】呕血（鲜红或咖啡渣样）、黑便（柏油样）、头晕、乏力、心慌、出冷汗、面色苍白、血压下降、心率增快、晕厥、意识障碍、少尿。\n【待人工确认·本机素材无此段原文】","现病史":"屈氏韧带以上消化道出血，数小时内失血量>1000ml或循环血量20%，表现为呕血、黑便、休克，病死率高。\n常见表现：呕血（鲜红或咖啡渣样）、黑便（柏油样）、头晕、乏力、心慌、出冷汗、面色苍白、血压下降、心率增快、晕厥、意识障碍、少尿。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 血常规+血型+交叉配血（急查，评估贫血程度并备血，Hb<70g/L或休克者立即输血）\n2. 急诊胃镜（生命体征稳定后尽早行，24h内最佳；活动性出血或药物止血失败可急诊镜下止血）\n3. 血气分析+血乳酸（评估失血性休克程度与组织灌注，指导复苏）\n4. 电解质+肝肾功能+凝血功能（PT/APTT、D-二聚体）（鉴别肝病/凝血障碍病因，指导成分输血）\n5. 心电图+肌钙蛋白（排除心肌梗死致应激性溃疡及评估高龄患者心脏代偿能力）\n6. 腹部CT增强（怀疑静脉曲张破裂但内镜禁忌或失败时评估，或用于鉴别主动脉肠瘘等少见病因）","初步诊断":"1. 呕血/黑便史\n2. 失血性休克表现\n3. Hb进行性下降\n4. 肠鸣音活跃\n5. 胃管抽吸有血\n6. 胃镜可确诊出血部位\n1. 上消化道大出血（ICD-10：K92.2）","鉴别诊断":"1. 诊断要点：呕血/黑便史\n2. 诊断要点：失血性休克表现\n3. 诊断要点：Hb进行性下降\n4. 诊断要点：胃管抽吸有血\n5. 诊断要点：胃镜可确诊出血部位\n6. 先救命（抗休克）后治病\n7. 不要单独使用红细胞悬液，需配合血浆\n8. 肝硬化患者避免过量补液（防止再出血）\n9. 呕血时头偏一侧，防止窒息\n10. 阿司匹林/华法林等抗凝药需评估停用","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：0.9%氯化钠注射液/复方氯化钠 快速静滴（先晶后胶）\n\n方案2：\n 用法：奥美拉唑 80mg 静推后 8mg/h 泵入（PPI）\n\n方案3：\n 用法：生长抑素 250μg 静推后 250μg/h 泵入（疑食管胃底静脉曲张）\n\n方案4：\n 用法：必要时输血（Hb<70g/L）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：禁食水\n\n药物2：\n 用法：去甲肾上腺素 8mg + 冰盐水 100ml 口服/胃管注入（局部止血）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n禁食、卧床、吸氧\n快速补液输血抗休克\nPPI抑制胃酸\n生长抑素（静脉曲张出血）\n急诊胃镜止血\n三腔二囊管压迫（静脉曲张大出血）\n介入/手术治疗\n\n【处理要点】\n立即平卧，头偏一侧防误吸，吸氧\n禁食水，留置胃管\n建立两条大口径静脉通路，快速补液\n抽血查血型、交叉配血、血常规、凝血、生化\nPPI静推+维持\n监测生命体征、尿量、意识\n记录呕血/便血量\n休克者紧急输血\n急诊胃镜（出血后24h内）\n疑静脉曲张加生长抑素，备三腔二囊管\n\n【护理】\n建立双路静脉通道，采用16G以上留置针快速补液，动态评估休克指数、血压、心率及尿量（<30ml/h提示灌注不足）\n绝对卧床、头偏一侧防误吸，持续低流量吸氧，备好吸引器、气管插管及三腔二囊管\n严密监测呕血/黑便量、颜色及频率，记录24h出入量；放置胃管者每2h抽吸观察\n急性大出血期禁食并暂停口服药，静脉泵入PPI（如奥美拉唑80mg负荷后8mg/h维持）、生长抑素（250μg/h）等抢救药物并观察疗效\n防治并发症：意识障碍者防坠床，保暖并防DIC，随时监测胃管脱出、气囊漏气及再出血征象（呕血加重、腹胀、便血频次增多）\n\n【饮食】\n急性出血期（活动性呕血/黑便）严格禁食禁水，静脉营养支持\n出血停止24~48h后试进温凉流质（米汤、藕粉），每次50~100ml，少量多次，避免过热刺激\n流质耐受2~3天后过渡至半流质（烂面条、粥、蒸蛋羹），细软少渣，忌粗糙、坚硬及刺激性食物\n恢复期忌烟酒、浓茶、咖啡、辛辣及过酸过甜食物，避免损伤黏膜诱发再出血\n肝硬化食管静脉曲张者长期软食为主，细嚼慢咽，避免鱼刺、骨头渣等硬物划伤曲张静脉\n\n【注意事项】\n先救命（抗休克）后治病\n不要单独使用红细胞悬液，需配合血浆\n肝硬化患者避免过量补液（防止再出血）\n呕血时头偏一侧，防止窒息\n阿司匹林/华法林等抗凝药需评估停用\n\n【急诊/急救】\n平卧头偏一侧，吸氧，禁食\n建立两条大口径静脉通路，快速输注晶体液\n奥美拉唑80mg静推，随后8mg/h持续泵入\n疑食管胃底静脉曲张：生长抑素250μg静推后250μg/h泵入\n抽血查血型交叉配血，Hb<70g/L紧急输血\n冰盐水+去甲肾上腺素8mg胃管注入/口服\n监测血压心率尿量，休克体位\n紧急联系消化科急诊胃镜止血\n静脉曲张大出血药物无效时三腔二囊管压迫","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「上消化道大出血」原文）"},"icd10_diagnosis":"K92.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2245,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f6a09967cb0aa5cd52f55e1d1e110f1d1135e85a3756c0e85cbe478ca2e6b088","pinyin":"shangxiaohuadaodachuxue","initials":"sxhddcx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K92.2",30]]},{"id":"templates-8b8b512bc2cb95d19b06","key":"v1-c9ccc21dfe2a3058|templates-8b8b512bc2cb95d19b06","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"上消化道大出血(外科处理)","category":"胃肠外科","raw":{"name":"上消化道大出血(外科处理)","category":"胃肠外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】呕血（鲜红或咖啡渣样）、黑便（柏油样）或暗红色血便（出血量大、肠蠕动快）、头晕、心悸、乏力、出汗、口渴（失血表现），重者晕厥、面色苍白、脉搏细速、血压下降、四肢湿冷（失血性休克）、上腹疼痛或不适（溃疡病）、肝病体征（肝硬化门静脉高压）、出血后可有氮质血症（肠内血液吸收）、发热（低热）。\n【待人工确认·本机素材无此段原文】","现病史":"上消化道大出血指屈氏韧带以上消化道（食管、胃、十二指肠、胰胆）大量出血，表现为呕血与/或黑便，可致失血性休克。常见病因：胃十二指肠溃疡、食管胃底静脉曲张破裂、胃癌、急性胃黏膜病变、贲门黏膜撕裂（Mallory-Weiss）。外科处理针对内科与内镜治疗失败、持续或反复大出血者。\n常见表现：呕血（鲜红或咖啡渣样）、黑便（柏油样）或暗红色血便（出血量大、肠蠕动快）、头晕、心悸、乏力、出汗、口渴（失血表现），重者晕厥、面色苍白、脉搏细速、血压下降、四肢湿冷（失血性休克）、上腹疼痛或不适（溃疡病）、肝病体征（肝硬化门静脉高压）、出血后可有氮质血症（肠内血液吸收）、发热（低热）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率、呼吸、意识（休克与出血量评估）\n一般情况：面色苍白、皮肤湿冷、口渴、尿量减少、体位（平卧不愿活动）\n皮肤黏膜：黄疸、蜘蛛痣、肝掌（肝硬化）、贫血貌、出血点\n腹部视诊：腹壁静脉曲张、腹部膨隆（腹水）、手术瘢痕\n腹部触诊：上腹压痛（溃疡）、肝脾大小与质地、有无腹块（肿瘤）\n腹部叩诊与听诊：移动性浊音、肝浊音界、肠鸣音（活跃提示继续出血）\n直肠指检：黑便或暗红色血便（出血量评估）","辅助检查":"1. 血常规+红细胞压积（动态每1～2小时）：评估出血速度与程度（早期可正常）\n2. 血型+交叉配血+凝血功能+血小板：备血与凝血状态评估\n3. 肝功能+白蛋白+胆红素+血氨：肝硬化与肝储备评估（决定治疗策略）\n4. 尿素氮+肌酐：BUN升高（BUN/Cr>30）提示上消化道出血\n5. 电解质+血气分析+乳酸：评估休克与酸碱失衡\n6. 急诊胃镜（24小时内）：明确出血部位与病因，同时内镜下止血\n7. 肝炎病毒标志物+HBV-DNA：肝硬化病因与抗病毒治疗依据","初步诊断":"1. 血流动力学与出血量评估：血压、心率、尿量、意识；血红蛋白与红细胞压积（早期可正常）\n2. 急诊胃镜（24小时内）：诊断与治疗首选，明确出血部位与病因，可行内镜下止血\n3. 血常规+血型+交叉配血+凝血功能：动态监测与备血\n4. 肝功能+白蛋白+胆红素+血氨：评估肝硬化与肝储备\n5. 腹部超声/CT：评估肝硬化、门静脉内径、有无肿瘤\n6. 肠系膜血管造影：内镜未明确且持续出血时（可同时栓塞止血）\n7. 尿素氮+肌酐：肠内血液吸收致BUN升高（BUN/Cr比值>30提示上消化道出血）\n1. 上消化道大出血(外科处理)（ICD-10：K92.2）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 抢救用药，患者监护下按病情选择！\n\n方案1（抑酸，溃疡/糜烂出血首选）：\n 用法：艾司奥美拉唑 80mg 静推（负荷）后 8mg/h 持续泵入 72小时；或 40mg 静推 q12h\n\n方案2（降门脉压，静脉曲张出血）：\n 用法：生长抑素 250μg 静推后 3mg/12h 泵入；或奥曲肽 0.1mg 静推后 25～50μg/h 泵入（疗程3～5天）\n\n方案3（液体复苏与输血）：\n 用法：平衡盐溶液/0.9%氯化钠 快速补液；输注红细胞悬液（目标Hb 70～90g/L）、新鲜冰冻血浆、血小板；肝硬化者避免过量输液（防门脉压升高再出血）\n\n方案4（止血药物与预防性抗感染）：\n 用法：氨甲环酸 1g 静滴（必要时）；维生素K1 10mg 静滴（肝硬化/凝血差者）；头孢曲松 1～2g 静滴 qd（肝硬化出血常规预防感染）\n\n📌 抢救与内镜准备同步进行；避免使用吗啡、NSAIDs等加重出血药物。\n\n【药物治疗·口服】\n⚠️ 止血后序贯用药，按医嘱选择：\n\n药物1（抑酸序贯）：\n 用法：艾司奥美拉唑 20mg qd 或 雷贝拉唑 10mg qd（疗程4～8周）\n\n药物2（降门脉压预防再出血）：\n 用法：普萘洛尔 10mg bid 起（调整至静息心率55～60次/分）或 卡维地洛 6.25mg bid\n\n药物3（胃黏膜保护与抗幽门螺杆菌）：\n 用法：铝碳酸镁 1.0g tid；根除Hp：阿莫西林1.0g bid + 克拉霉素0.5g bid + 艾司奥美拉唑20mg bid + 铋剂（疗程14天）\n\n药物4（乳果糖，肝硬化防肝性脑病）：\n 用法：乳果糖 15～30ml bid～tid（调整至每日2～3次软便）\n\n📌 溃疡出血者需根除幽门螺杆菌（Hp）以防复发；肝硬化者需长期降门脉压治疗与胃镜随访。\n\n【治疗】\n补充血容量抗休克：建立两条以上静脉通路，快速补液输血，维持Hb 70～90g/L（肝硬化者不宜过高）\n抑酸治疗：静脉大剂量PPI（溃疡/糜烂出血），维持胃内pH>6促进血凝块稳定\n内镜下止血：首选——注射止血（肾上腺素）、电凝、钛夹、套扎（静脉曲张），可重复内镜\n门静脉高压出血：生长抑素/奥曲肽+内镜套扎；失败者行三腔二囊管压迫、TIPS或手术断流/分流\n外科手术指征：内科与内镜治疗失败持续出血、溃疡穿孔或梗阻、大血管破裂（Dieulafoy病）、胃癌出血\n介入治疗：胃左动脉/胃十二指肠动脉栓塞（内镜失败且不宜手术者）\n病因治疗：根除Hp、停用NSAIDs/抗凝药（评估后）、护肝与抗病毒（肝硬化）\n术后管理：监测再出血（引流、呕血黑便）、继续抑酸、营养支持\n\n【处理要点】\n休克期监测：每15～30分钟测血压、心率、尿量，记录呕血与黑便量与性状\n体位与气道：平卧头偏一侧防误吸，呕血时禁食（活动性出血期）\n双通道补液：粗针或中心静脉通路，按医嘱输血输液，观察有无输血反应\n内镜准备：出血后24小时内完成急诊胃镜，术前禁食、必要时洗胃（冰盐水或去甲肾上腺素盐水）\n三腔二囊管护理（如使用）：妥善牵引固定、标记刻度、定时放气（每12～24小时），观察有无窒息与黏膜损伤\n活动性出血停止后：逐步从温凉流质开始进食，避免粗糙硬食与刺激性食物\n再出血观察：监测生命体征、呕血黑便、肠鸣音与血红蛋白变化；肝硬化者预防肝性脑病（乳果糖、通便）\n\n【护理】\n休克护理：绝对卧床、平卧头偏一侧，快速建立静脉通路，每15～30分钟监测生命体征与尿量\n出血观察与记录：记录呕血与黑便的次数、量、颜色（鲜红提示活动性出血），观察肠鸣音与血红蛋白\n气道护理：呕血时头偏一侧防误吸，及时清理口腔，必要时吸氧\n三腔二囊管护理（如使用）：牵引固定、标记刻度、定时放气，观察鼻腔黏膜与有无胸痛呼吸困难\n饮食护理：活动性出血期禁食；停止出血后从温凉流质（米汤）开始，忌粗糙、坚硬、过热食物\n心理护理：出血场面易致恐惧，安抚患者并解释治疗，减少紧张（紧张可加重出血）\n\n【饮食】\n活动性出血期严格禁食禁水（必要时胃肠减压）\n出血停止24～48小时后：温凉流质（米汤、藕粉、温牛奶），少量多餐\n过渡期：流质→半流质→软食，避免粗糙、坚硬、带刺与过热食物\n溃疡患者：规律进食、少量多餐，避免辛辣、浓茶、咖啡与酒类\n肝硬化患者：限盐（<2g/日）、适量优质蛋白（肝性脑病期遵医嘱），保持大便通畅\n\n【注意事项】\n上消化道大出血的处理原则：先稳定生命体征，再明确病因并止血（内镜为首选）\n肝硬化患者出血后易并发感染、肝性脑病与肝肾综合征，需预防性抗感染与护肝\n溃疡出血止血后必须根除幽门螺杆菌并停用NSAIDs，否则复发率高\n输血目标Hb 70～90g/L（过低影响组织灌注，过高增加门脉压与再出血风险）\n外科手术是二线选择（内镜/介入失败），术前应尽量明确出血部位\n\n【急诊/急救】\n大量呕血、血压下降、心率>120次/分（失血性休克）→ 立即双通道补液输血、急诊内镜\n内镜止血失败持续出血或反复出血 → 急诊介入栓塞或手术\n肝硬化出血后出现意识改变、扑翼样震颤（肝性脑病）→ 乳果糖、降血氨、限制蛋白\n呕血致窒息、误吸 → 立即清理气道、侧卧、吸氧","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"K92.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2246,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"754f2fd1927af7e18ce1ae8f84c148cc924b1e7c642b30b1c48b6e1c385ac693","pinyin":"shangxiaohuadaodachuxue(waikechuli)","initials":"sxhddcx(wkcl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K92.2",30]]},{"id":"templates-db0976944ec4838b7ae3","key":"v1-c9ccc21dfe2a3058|templates-db0976944ec4838b7ae3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"下消化道出血","category":"内科-消化","raw":{"name":"下消化道出血","category":"内科-消化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】鲜血便（直肠与肛门病变）、暗红色血便（结肠病变）、果酱样便（肠套叠、阿米巴）、黑便（小肠出血、血液停留时间长）、腹痛（缺血性结肠炎、肠套叠、炎症性肠病）伴腹泻或便秘、头晕、心悸、乏力与晕厥（大量出血致失血性休克）、伴随症状：消瘦与排便习惯改变（肿瘤）、发热与里急后重（感染性结肠炎）。\n【待人工确认·本机素材无此段原文】","现病史":"下消化道出血指屈氏韧带以下消化道（小肠、结肠、直肠与肛门）出血，表现为便血（鲜红色、暗红色或果酱样）、黑便（小肠出血）与贫血。常见病因：结肠息肉与肿瘤、结肠炎（缺血性、溃疡性、感染性）、血管畸形、痔与肛裂、小肠病变（血管畸形、肿瘤、克罗恩病）。\n常见表现：鲜血便（直肠与肛门病变）、暗红色血便（结肠病变）、果酱样便（肠套叠、阿米巴）、黑便（小肠出血、血液停留时间长）、腹痛（缺血性结肠炎、肠套叠、炎症性肠病）伴腹泻或便秘、头晕、心悸、乏力与晕厥（大量出血致失血性休克）、伴随症状：消瘦与排便习惯改变（肿瘤）、发热与里急后重（感染性结肠炎）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率、呼吸、意识（休克评估）\n一般情况：面色苍白、皮肤湿冷、脱水征、营养状态\n腹部：腹胀、压痛部位、腹块（肿瘤/肠套叠）、肠鸣音（亢进或减弱）\n直肠指检：痔、肛裂、直肠肿物、指套染血（暗红或鲜红）\n皮肤黏膜：黄疸、出血点与瘀斑、贫血貌、蜘蛛痣（肝病）\n肛门视诊：痔核、肛裂、瘘口（出血来源）\n其他：淋巴结肿大（肿瘤转移）、下肢水肿（低蛋白）","辅助检查":"1. 血常规+血型+交叉配血+凝血功能：动态监测血红蛋白（每4～6小时）与备血\n2. 粪便常规+隐血+培养+寄生虫检查：感染性与寄生虫病因\n3. 结肠镜+活检（首选）：定位与病因诊断，同时可行内镜下止血\n4. CT血管造影/腹部增强CT：活动性出血定位与肿瘤评估\n5. 胶囊内镜/小肠镜（结肠镜阴性者）：小肠出血评估\n6. 核素扫描（99mTc红细胞，间断出血）：定位不精确但敏感\n7. 肝肾功能+电解质+白蛋白：病情与营养评估","初步诊断":"1. 生命体征与出血量评估：血压、心率、尿量与意识（大量出血需紧急处理）\n2. 血常规+血型+交叉配血+凝血功能：动态监测血红蛋白与备血\n3. 直肠指检与肛门镜：痔、肛裂与直肠病变（简单有效，勿遗漏）\n4. 结肠镜（首选，24小时内）：明确结肠病变并可行内镜下止血（活动性出血者肠道准备受限时可先行CT血管造影）\n5. CT血管造影（CTA）：活动性出血（>0.5ml/min）定位（介入栓塞前评估）\n6. 小肠评估：胶囊内镜、小肠镜、CT/MR小肠成像（结肠镜阴性且出血持续）\n7. 核素扫描（99mTc标记红细胞）：间断出血定位（敏感性高、定位不精确）\n8. 血管造影（DSA）：活动性出血定位与栓塞治疗（介入）\n1. 下消化道出血（ICD-10：K92.2）","鉴别诊断":"1. 诊断要点：生命体征与出血量评估：血压、心率、尿量与意识（大量出血需紧急处理）\n2. 诊断要点：血常规+血型+交叉配血+凝血功能：动态监测血红蛋白与备血\n3. 诊断要点：直肠指检与肛门镜：痔、肛裂与直肠病变（简单有效，勿遗漏）\n4. 诊断要点：结肠镜（首选，24小时内）：明确结肠病变并可行内镜下止血（活动性出血者肠道准备受限时可先行CT血管造影）\n5. 诊断要点：CT血管造影（CTA）：活动性出血（>0.5ml/min）定位（介入栓塞前评估）\n6. 诊断要点：小肠评估：胶囊内镜、小肠镜、CT/MR小肠成像（结肠镜阴性且出血持续）\n7. 诊断要点：核素扫描（99mTc标记红细胞）：间断出血定位（敏感性高、定位不精确）\n8. 诊断要点：血管造影（DSA）：活动性出血定位与栓塞治疗（介入）\n9. 下消化道出血的定位首选结肠镜（可同时止血）；活动性大出血时应先稳定生命体征，必要时行CT血管造影\n10. 直肠指检与肛门镜是简单有效的第一步检查（痔与肛裂常见且易被忽视）\n11. 结肠镜阴性且持续出血者需评估小肠（胶囊内镜、小肠镜或CT/MRI小肠成像）\n12. 缺血性结肠炎多见于老年与动脉硬化者，表现为腹痛+便血，多数可保守治疗（重症需手术）","处理方案":"【药物治疗·输液】\n⚠️ 按出血量与病因选择，须先稳定生命体征！\n\n方案1（液体复苏与输血）：\n 用法：平衡盐溶液/0.9%氯化钠 快速补液；红细胞悬液（目标Hb 70～90g/L，冠心病者80～100g/L）；必要时新鲜冰冻血浆（凝血障碍）\n\n方案2（止血药物）：\n 用法：氨甲环酸 1g 静滴（8小时内，慎用于血栓风险者）；生长抑素 3mg/12h 泵入（小肠出血/血管畸形，遵医嘱）；维生素K1 10mg 静滴（凝血障碍）\n\n方案3（抑酸与肠道休息）：\n 用法：艾司奥美拉唑 40mg 静推 q12h（合并上消化道出血或应激性溃疡）；0.9%氯化钠 静滴维持\n\n方案4（病因治疗）：\n 用法：感染性结肠炎——左氧氟沙星 0.5g 静滴 qd + 甲硝唑 0.5g 静滴 q8h；缺血性结肠炎——补液、禁食、抗感染、必要时手术；炎症性肠病——激素或生物制剂（专科）\n\n📌 下消化道出血处理顺序：稳定生命体征→定位（结肠镜/CTA）→止血（内镜/介入/手术）；避免盲目使用止血药与抗生素。\n\n【药物治疗·口服】\n⚠️ 出血期禁食或流质，稳定后用药：\n\n药物1（止血与黏膜保护）：\n 用法：凝血酶冻干粉 口服/灌肠（局部止血，遵医嘱）；蒙脱石散 3g tid（黏膜保护）\n\n药物2（病因治疗）：\n 用法：溃疡性结肠炎——美沙拉嗪 1g qid（口服）+ 局部灌肠剂；感染——诺氟沙星 0.3g bid + 甲硝唑 0.4g tid（疗程3～5天）\n\n药物3（补铁，慢性失血性贫血）：\n 用法：琥珀酸亚铁 0.1g bid～tid + 维生素C 0.2g tid\n\n药物4（对症）：\n 用法：对乙酰氨基酚 0.5g 必要时（避免NSAIDs）；益生菌（双歧杆菌 2粒 bid）\n\n📌 避免NSAIDs与抗凝/抗血小板药物（加重出血）；痔出血者局部用药（复方角菜酸酯栓）与坐浴。\n\n【治疗】\n生命体征稳定与复苏：建立静脉通路、补液输血、纠正凝血障碍（第一步）\n定位诊断：结肠镜（首选，可同时内镜下止血：钛夹、电凝、肾上腺素注射）；活动性出血可行CT血管造影\n介入治疗：DSA血管造影+栓塞（活动性出血不能内镜处理者）\n手术治疗：内镜与介入失败、持续大量出血、肿瘤、缺血性肠坏死或穿孔者行手术切除\n病因治疗：结肠息肉（内镜切除）、肿瘤（手术+肿瘤治疗）、缺血性结肠炎（支持治疗±手术）、炎症性肠病（专科用药）、感染性结肠炎（抗感染）\n痔与肛裂出血：保守治疗（坐浴、通便、局部用药），必要时手术（痔切除、内痔套扎）\n支持治疗：补铁（慢性失血）、营养支持、必要时输注红细胞\n随访：结肠镜复查（息肉与肿瘤术后）、贫血纠正评估、避免NSAIDs与抗凝药滥用\n\n【处理要点】\n出血监测：记录便血次数、量与颜色，监测生命体征与血红蛋白（每4～6小时），异常立即报告\n肠道准备与检查配合：按医嘱完成肠道准备（活动性大出血者避免口服清肠液，配合CT血管造影）\n禁食与饮食过渡：活动性出血期禁食、静脉补液；出血停止后从温凉流质逐步过渡\n用药观察：止血药与抗感染治疗观察疗效与不良反应；避免NSAIDs与抗凝药物\n贫血与营养管理：监测血红蛋白与铁代谢，遵医嘱补铁；必要时输血并观察输血反应\n宣教与随访：按时复查结肠镜与血常规、避免剧烈活动与用力排便（防再出血）、痔疮患者生活方式调整（多纤维、多饮水、避免久坐）\n\n【护理】\n出血观察与记录：记录便血与黑便的次数、颜色与量，监测生命体征与血红蛋白并报告异常\n补液输血护理：保持静脉通路畅通，按医嘱补液输血并观察输血反应\n饮食与肠道准备护理：活动性出血禁食，之后温凉流质逐步过渡；按医嘱配合肠道准备或CTA检查\n肠道休息与症状观察：观察腹痛、腹胀与肠鸣音（缺血性结肠炎/肠梗阻），异常立即报告\n用药护理：止血药与抗感染按时给予；避免NSAIDs与抗凝药；观察药物不良反应\n宣教：按时复查结肠镜、多纤维多饮水避免便秘、痔疮患者避免久坐与用力排便、出现便血及时就诊\n\n【饮食】\n活动性出血期：禁食禁水、静脉补液\n出血停止后：温凉流质（米汤、藕粉）→ 少渣半流质 → 软食逐步过渡\n恢复期：高蛋白、高维生素饮食促进恢复；避免粗糙、坚硬与刺激性食物\n炎症性肠病与缺血性结肠炎：低渣、低脂饮食；感染性结肠炎避免乳制品与高纤维\n痔与肛裂：多饮水（每日2000ml以上）、多纤维饮食（蔬菜水果粗粮）保持大便通畅，忌辛辣与酒类\n\n【注意事项】\n下消化道出血的定位首选结肠镜（可同时止血）；活动性大出血时应先稳定生命体征，必要时行CT血管造影\n直肠指检与肛门镜是简单有效的第一步检查（痔与肛裂常见且易被忽视）\n结肠镜阴性且持续出血者需评估小肠（胶囊内镜、小肠镜或CT/MRI小肠成像）\n缺血性结肠炎多见于老年与动脉硬化者，表现为腹痛+便血，多数可保守治疗（重症需手术）\n避免在出血期盲目使用止血药与抗生素（应先明确病因）\n\n【急诊/急救】\n大量便血伴血压下降、心率增快（失血性休克）→ 立即双通道补液输血，稳定后急诊结肠镜/CTA\n持续活动性出血不能内镜控制（>0.5ml/min）→ 急诊DSA栓塞或手术\n腹痛剧烈伴腹膜刺激征与便血（肠坏死/穿孔）→ 急诊手术探查\n便血伴高热与里急后重（暴发性结肠炎/中毒性巨结肠）→ 急诊评估与处理（禁泻药、抗感染、必要时手术）\n儿童阵发性腹痛伴果酱样便与腹部包块（肠套叠）→ 急诊超声+空气灌肠复位","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「下消化道出血」原文）"},"icd10_diagnosis":"K92.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2247,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2901d2bcadd8c5bf34e70b5d8b7d55bfd3c11fe4053f98aa5e211aa144a615ad","pinyin":"xiaxiaohuadaochuxie","initials":"xxhdcx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K92.2",30]]},{"id":"templates-cb3d8ba542750360bca7","key":"v1-c9ccc21dfe2a3058|templates-cb3d8ba542750360bca7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"下肢慢性静脉功能不全","category":"血管外科","raw":{"name":"下肢慢性静脉功能不全","category":"血管外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】下肢沉重、酸胀、乏力（久站久坐加重）、下肢静脉曲张（蚓状迂曲扩张）、踝部水肿（晨轻暮重）、皮肤色素沉着、脂质硬化、瘙痒、静脉性溃疡（好发内踝上方）。\n【待人工确认·本机素材无此段原文】","现病史":"下肢静脉瓣膜功能不全/静脉高压致静脉曲张、水肿及皮肤营养改变（CEAP分级）\n常见表现：下肢沉重、酸胀、乏力（久站久坐加重）、下肢静脉曲张（蚓状迂曲扩张）、踝部水肿（晨轻暮重）、皮肤色素沉着、脂质硬化、瘙痒、静脉性溃疡（好发内踝上方）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"站立位检查：静脉曲张分布（大/小隐静脉走行区）\n皮肤营养改变：色素沉着、脂质硬化、白色萎缩\n溃疡检查：部位（内踝上方）、大小、基底及渗液\n水肿评估：踝部凹陷性水肿程度\nABI测定：排除合并动脉缺血","辅助检查":"1. 下肢静脉彩超：静脉反流程度（反流时间）、深静脉通畅性（首选）\n2. ABI：排除动脉缺血（溃疡鉴别）\n3. 静脉造影/CTV：复杂病例或术前评估\n4. D-二聚体：疑合并血栓时筛查","初步诊断":"1. 病史+查体（CEAP分级评估）\n2. 静脉彩超（反流及深静脉通畅性检查）\n3. 静脉造影（复杂/术前评估，必要时）\n4. ABI（排除合并动脉缺血）\n1. 下肢慢性静脉功能不全（ICD-10：I83.9）","鉴别诊断":"1. ABI（排除合并动脉缺血）\n2. 静脉性溃疡好发内踝上方，动脉性溃疡好发足趾/足跟（鉴别需ABI）\n3.与深静脉血栓后遗症（PTS）鉴别：后者有DVT病史","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（合并血栓/术后）：\n 用法：低分子肝素4000IU ih q12h（围术期或合并浅静脉血栓过渡抗凝）\n\n方案2（溃疡感染）：\n 用法：NS100ml+头孢唑林2g ivdrip q8h（蜂窝织炎抗感染）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：地奥司明450mg bid（静脉活性药物，改善症状）\n\n药物2：\n 用法：阿司匹林100mg qd（合并动脉硬化或术后抗血小板）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n压力治疗：医用弹力袜（基础治疗）\n静脉活性药物：地奥司明、马栗种子提取物\n微创/手术：硬化剂注射、腔内激光/射频消融、大隐静脉高位结扎剥脱\n溃疡治疗：清创换药+压力治疗，控制感染\n抬高患肢、避免久站久坐\n\n【处理要点】\n每日规律穿戴弹力袜（白天穿戴）\n抬高患肢（高于心脏水平，每日数次）\n踝泵运动促进回流\n皮肤保湿护理，防抓挠破损\n定期随访，控制体重\n\n【护理】\n压力治疗护理：指导正确穿脱弹力袜（晨起穿戴）、压力分级选择\n溃疡护理：无菌换药、观察渗液颜色气味、控制感染\n抬高患肢：休息时抬高，促进回流\n皮肤护理：保湿、避免抓挠及外伤\n术后护理（激光/射频/剥脱）：观察穿刺点、加压包扎、早期下床防血栓\n\n【饮食】\n高纤维饮食：预防便秘（腹压增高加重静脉反流）\n低盐饮食：减轻水肿\n控制体重：肥胖加重静脉高压\n优质蛋白：促进溃疡愈合\n\n【注意事项】\n静脉性溃疡好发内踝上方，动脉性溃疡好发足趾/足跟（鉴别需ABI）与深静脉血栓后遗症（PTS）鉴别：后者有DVT病史\n曲张静脉破裂出血需立即抬高患肢加压包扎\nCEAP分级指导治疗：C4以上需专科干预\n\n【急诊/急救】\n静脉曲张破裂出血：立即抬高患肢、加压包扎，急诊处理\n溃疡合并蜂窝织炎/丹毒：抗感染治疗\n突发单侧肢体肿胀疼痛：排除急性深静脉血栓","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「下肢慢性静脉功能不全」原文）"},"icd10_diagnosis":"I83.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2248,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6254fb9ad3316057fd226e9c6a1b914a10d2cbd85060a787ae4bf55c9fee2336","pinyin":"xiazhimanxingjingmaigongnengbuquan","initials":"xzmxjmgnbq","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I83.9",30]]},{"id":"templates-bc87170b88063e73752f","key":"v1-c9ccc21dfe2a3058|templates-bc87170b88063e73752f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"下颌前突畸形","category":"口腔医学临床路径（2019年版）","raw":{"name":"下颌前突畸形","category":"口腔医学临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者下颌向前突出、前牙反合、后牙近中关系，面下1/3较长、软组织颏前点前移，为明确畸形性质及有无骨性下颌前突，完善X线头影测量（头颅定位正侧位片），了解SNA、SNB、ANB角变化，明确下颌前突程度及是否合并上颌发育不足，这是正畸与正颌方案设计的核心依据；查全口曲面体层片（口腔全景片），了解牙根形态、牙列拥挤程度、有无埋伏牙及第三磨牙情况，排除牙源性因素所致反合；完善锥形束CT或颌面部CT检查，明确髁突形态、下颌升支与体部骨质情况、颞下颌关节结构及下颌神经管走行，评估骨性畸形三维形态；取牙列模型并行模型分析，评估咬合关系与上颌牙弓宽度，指导正畸去代偿及手术方案制定；查颞下颌关节MRI，了解关节盘位置及有无关节退变，评估关节功能状态；因拟行正颌手术，术前完善血常规、凝血功能、肝肾功能、血型及感染筛查（乙肝、丙肝、梅毒、HIV），排除贫血、凝血异常及感染性疾病，明确手术耐受性；完善心电图、胸部X线检查，评估心肺功能，必要时行超声心动图及肺功能检查；必要时查甲状腺功能及生长激素水平，鉴别内分泌因素所致下颌前突。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社，2016）。\r1.下颌向前突出，前牙反合，后牙近中关系（Angle \n类）。\r2.面下1/3较长，软组织颏前点前移。\r3.X线头影测量：\nSNA正常，\nSNB大于正常，\nANB小于正常或为负角。\r（三）\n1. 下颌前突畸形（ICD-10：K07.108）","鉴别诊断":"1. 2.对极少数下颌前突畸形患者，应行神经外科会诊，以排除脑垂体瘤等病因，避免术后复发","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社,2016）。\r选择双侧下颌升支矢状劈开截骨术(BSSRO），其适应证为：\r1.骨性\n类错颌畸形。\r2.全身无手术禁忌证。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K07.108下颌前突畸形疾病编码。\r2.患者同时具有其他疾病诊断，如在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备（术前评估）2～3天\r必须检查的项目：\r1. 影像学检查（X线胸片、X线头颅正侧位定位片、全口曲面断层片、锥形束CT或螺旋CT）。\r2. X线头影测量分析、术前虚拟治疗方案设计、模型外科、咬合导板的制作。 \r3.血常规、凝血功能、血型。\r4.尿常规、大便常规。\r5.肝肾功能。\r6.感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）。\r7.心电图。\r（七）预防性抗菌药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。\r2.选择青霉素类或其他类抗菌药物，预防性用药时间为手术开始前30分钟。\r（八）手术日为入院第3～4天\r1.麻醉方式：经鼻气管插管全身麻醉。\r2.手术内固定物：小型/微型钛板、钛钉。\r3.术中用药：麻醉常规用药、抗菌药物和止血药。\r4.输血：视术中情况和出血量而定，一般不考虑输血。\r（九）术后住院恢复5～6天\r1.必须复查的检查项目：影像学检查（X线头颅正侧位定位片，全口曲面断层片，锥形束CT或螺旋CT）。\r2.术后预防性使用抗菌药物：用药时间3～5天。根据病情决定使用止血、消肿类及镇痛类药物的时间。 \r（十）","临床路径·标准住院日":"标准住院日为\n10天\r（五）","临床路径·出院标准":"出院标准\r1.一般情况良好、可进流质饮食、活动自如；面部肿胀逐渐消退。\r2.上下牙列就位于咬合导板内，咬合关系稳定。\r3. CT及X线片显示：无意外骨折，各骨段位置符合设计要求；各骨内固定物就位良好；髁突位置在正常范围。\r4.手术创口在愈合中，无脓性分泌物；手术区无明显积液。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.若有影响手术的全身情况，需要进行相关会诊，除外手术禁忌证。\r2.对极少数下颌前突畸形患者，应行神经外科会诊，以排除脑垂体瘤等病因，避免术后复发。\r\f二、下颌前突畸形","资料来源":"鉴别诊断库 ddx_local.json（条目「下颌前突畸形」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 下颌前突畸形临床路径（2019年版）.doc"},"icd10_diagnosis":"K07.108","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2249,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"137daf020ea3ac367c6cccd9e892670b8804fedd875f54cbae3916a502aa3f00","pinyin":"xiaheqiantujixing","initials":"xhqtjx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K07.108",30]]},{"id":"templates-69d660c9fcdceba32d71","key":"v1-c9ccc21dfe2a3058|templates-69d660c9fcdceba32d71","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"下颌骨骨折","category":"口腔医学临床路径（2019年版）","raw":{"name":"下颌骨骨折","category":"口腔医学临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者有明确外伤史，临床检查存在下颌骨骨折表现，为明确骨折部位、数目及移位情况，急诊完成颌面部CT平扫加三维重建检查，明确骨折线走行、断端移位方向及是否累及下颌神经管，这是制定复位与内固定方案的直接依据；查全口曲面体层片（口腔全景片）及下颌骨正侧位X线片，了解下颌骨整体轮廓、髁突与下颌角区骨折情况，排查CT薄层可能遗漏的线性骨折；因外伤常合并颅面部多部位损伤，完善头颅CT检查，排除颅脑损伤、颅底骨折及上颌骨、颧骨骨折，避免漏诊；查颈椎CT或颈椎正侧位X线，排除颈椎损伤，为麻醉插管及体位摆放提供依据；对疑有髁突骨折或颞下颌关节脱位者，完善颞下颌关节CT或MRI检查，明确关节盘及髁突位置，评估关节功能；查口腔颌面部软组织超声，了解有无血肿、异物残留及腮腺导管、面神经损伤；因拟行骨折复位内固定手术，术前完善血常规、血型、凝血功能、肝肾功能及感染筛查（乙肝、丙肝、梅毒、HIV），排除贫血、凝血障碍及感染性疾病，明确手术耐受性；完善心电图、胸部X线检查，评估心肺功能，中老年或有基础疾病者加查超声心动图、肺功能及动脉血气分析；术后定期复查颌面部CT或全景片，评估骨折愈合与内固定位置。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社，2016）。\r1.有明确的外伤史。\r2.临床检查存在下颌骨骨折的临床表现。\r3.影像学检查可见明确的骨折影像。\r（三）\n1. 下颌骨骨折（ICD-10：S02.6）","鉴别诊断":"1. 摄术后X线片（原则上应与术前所摄片位相同）\u0007出院医嘱","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社,2016）。 \r选择下颌骨骨折切开复位内固定术，其适应证为：\r1.有外伤史，下颌骨骨折诊断明确。\r2.全身情况可耐受麻醉和手术，危及生命的全身合并损伤已经得到有效处置，生命体征稳定。\r3.下颌骨骨折段错位明显，咬合关系紊乱。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：S02.6下颌骨骨折疾病编码。\r2.患者同时具有其他疾病诊断，如在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备（术前评估）2天\r必须检查的项目：\r1.血常规、尿常规、便常规、血型、凝血功能、肝肾功能。\r2.感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）。 \r3.心电图。\r4.影像学检查（颅颌面及全身影像检查）。\r（七）预防性抗菌药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。\r2.选用青霉素类或其他类抗菌药物，预防性用药时间为术前30分钟（另可根据是否为开放性损伤以及感染的程度决定抗菌药物的选用和患者的时间）。\r（八）手术日为入院第2～5天\r1.麻醉方式：全身麻醉或局部麻醉。 \r2.手术内固定物：骨折接骨板、钉和其他类骨折内固定物，颌间固定螺钉等。 \r3.术中用药：青霉素类或其他类抗菌药物。 \r4.输血：视术中出血情况而定，一般不考虑输血。\r（九）术后住院恢复5～7天\r1.必须复查的检查项目:血细胞分析和影像学检查。\r2.术后选用青霉素类或其他类抗菌药物，用药时间根据骨折及感染的严重程度决定。\r3.术后骨折固定效果的影像学评估：如曲面体层片、CT检查。\r（十）","临床路径·标准住院日":"标准住院日为\n14天\r（五）","临床路径·出院标准":"出院标准\r1.全身一般情况稳定。\r2.切口\n/甲（口外切口）和（或）\n/甲（口内或开放性伤口）愈合。\r3.咬合关系恢复。\r4.影像学检查显示骨折复位固定良好。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.需手术治疗的下颌髁突骨折，下颌粉碎性骨折，下颌骨骨折合并面中部骨折，下颌骨病理性骨折不进入该路径。\r2.急诊患者不进入该路径。\r\r\r\r二、下颌骨骨折","资料来源":"鉴别诊断库 ddx_local.json（条目「下颌骨骨折」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 下颌骨骨折临床路径（2019年版）.doc"},"icd10_diagnosis":"S02.6","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2250,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"88cf28eefd45aadeadd46a555982feb5ccdca8ff1f5e5e8febd2e6e68d883883","pinyin":"xiaheguguzhe","initials":"xhggz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","S02.6",30]]},{"id":"templates-cf3b927fed9fc2e01b7a","key":"v1-c9ccc21dfe2a3058|templates-cf3b927fed9fc2e01b7a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不孕症(中医辨证)","category":"中医","raw":{"name":"不孕症(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肾阳虚：婚久不孕，月经后期，量少色淡，或闭经，面色晄白，腰膝酸软，性欲淡漠，小便清长，大便溏薄，舌淡苔白，脉沉迟、肾阴虚：婚久不孕，月经先期，量少色红，或闭经，形体消瘦，腰膝酸软，头晕耳鸣，五心烦热，舌红少苔，脉细数、肝气郁结：婚久不孕，月经先后无定期，经行不畅，量少色暗，有小血块，经前乳房胀痛，精神抑郁，善太息，舌暗红苔薄白，脉弦、瘀滞胞宫：婚久不孕，月经多推后，经行腹痛拒按，经色紫暗有血块，块下痛减，舌紫暗有瘀点，脉弦涩、痰湿内阻：婚久不孕，形体肥胖，经行延后，甚则闭经，带下量多，色白质黏，头晕心悸，胸闷泛恶，苔白腻，脉滑。\n【待人工确认·本机素材无此段原文】","现病史":"女子婚后与配偶同居1年以上，有正常性生活且未避孕而未受孕者，称不孕症。分肾虚（肾阳虚/肾阴虚）、肝气郁结、瘀滞胞宫、痰湿内阻等证型。\n常见表现：肾阳虚：婚久不孕，月经后期，量少色淡，或闭经，面色晄白，腰膝酸软，性欲淡漠，小便清长，大便溏薄，舌淡苔白，脉沉迟、肾阴虚：婚久不孕，月经先期，量少色红，或闭经，形体消瘦，腰膝酸软，头晕耳鸣，五心烦热，舌红少苔，脉细数、肝气郁结：婚久不孕，月经先后无定期，经行不畅，量少色暗，有小血块，经前乳房胀痛，精神抑郁，善太息，舌暗红苔薄白，脉弦、瘀滞胞宫：婚久不孕，月经多推后，经行腹痛拒按，经色紫暗有血块，块下痛减，舌紫暗有瘀点，脉弦涩、痰湿内阻：婚久不孕，形体肥胖，经行延后，甚则闭经，带下量多，色白质黏，头晕心悸，胸闷泛恶，苔白腻，脉滑。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：面色、神、舌诊（舌质/舌苔）、月经（量色质）、带下（量色质气味）\n闻诊：声音、经带气味\n问诊：月经史（初潮/周期/经期/经量/色质）、带下史、婚育史、既往史、十问歌\n切诊：脉诊、腹诊（小腹压痛/包块）\n辨证：脏腑辨证（肝肾脾）、气血辨证、冲任督带辨证","辅助检查":"检查计划：患者婚后与配偶同居1年以上、有正常性生活且未避孕而未受孕，属不孕症范畴，明确病因是治疗关键，须男女双方同步系统检查；女方于月经第2-3天查性激素六项（促卵泡激素、促黄体生成素、雌二醇、孕酮、睾酮、催乳素），了解卵巢储备功能及内分泌状态，为中医肾虚、肝郁、痰湿等证型辨证提供客观依据；查抗苗勒管激素评估卵巢储备，明确卵巢功能减退所致不孕；行基础体温测定及经阴道B超卵泡监测，了解有无排卵及卵泡发育情况，明确排卵障碍；于月经干净后3-7天行子宫输卵管造影，了解输卵管通畅性及宫腔形态，排除输卵管阻塞、宫腔粘连及子宫畸形；完善妇科B超检查，了解子宫大小、内膜厚度、有无子宫肌瘤、子宫内膜息肉及卵巢囊肿，排除器质性病变；对月经后期、量少色淡或闭经者，查甲状腺功能及空腹血糖、胰岛素，排除甲状腺功能异常、糖尿病及多囊卵巢综合征所致不孕；对形体肥胖、带下量多、苔白腻者，查血脂及体重指数，评估痰湿内阻证与代谢异常的相关性；男方查精液常规及形态学分析，必要时行精子DNA碎片率检测，排除男性因素所致不孕；对疑似子宫内膜异位症或盆腔粘连者，必要时行腹腔镜检查以进一步明确诊断；同时完善血常规、肝肾功能检查，为后续促排卵或中药长期治疗的安全性提供依据。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 婚后1年以上未避孕未孕\n2. 夫妻双方系统检查（男方精液、女方排卵监测/输卵管造影/性激素等）\n3. 明确病因是治疗关键\n1. 不孕症(中医辨证)（ICD-10：N97.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药调理为主\n\n方案2（出血量多/贫血明显）：\n 用法：5%GS250ml+酚磺乙胺1.0g ivgtt qd；NS500ml+维生素C2.0g ivgtt qd\n\n方案3（合并感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。妊娠期、哺乳期用药务必谨慎！\n\n药物1（肾阳虚）：金匮肾气丸6g bid，或艾附暖宫丸1丸 bid\n药物2（肾阴虚）：六味地黄丸6g bid，或左归丸1丸 bid\n药物3（肝气郁结）：逍遥丸6g bid\n药物4（瘀滞胞宫）：血府逐瘀胶囊4粒 tid\n药物5（痰湿内阻）：苍附导痰丸6g tid\n药物6（配合）：多囊卵巢综合征者遵医嘱促排卵\n\n【治疗】\n肾阳虚：温肾暖宫，调补冲任，温胞饮加减\n肾阴虚：滋肾养血，调补冲任，养精种玉汤加减\n肝气郁结：疏肝解郁，理血调经，开郁种玉汤加减\n瘀滞胞宫：逐瘀荡胞，调经助孕，少腹逐瘀汤加减\n痰湿内阻：燥湿化痰，理气调经，启宫丸加减\n\n【处理要点】\n规律作息，避免熬夜、烟酒\n保持情志舒畅，缓解压力\n控制体重，适度运动，均衡营养\n\n【护理】\n情志护理：不孕患者多伴焦虑忧郁，肝郁气滞证尤甚，宜多开导劝慰、讲解调经种子之理，鼓励夫妻同治，忌忧思郁怒扰动冲任，以免气机郁滞加重。\n起居调护：肾虚者避风寒、忌过劳耗精，节房事、慎于经期同房；经期注意保暖，忌冒雨涉水、久坐湿地，腹部及腰骶部避免受凉。\n病情观察：观察月经周期、经期、经量、经色及带下性状变化，指导患者每日晨起测基础体温（BBT）并记录，观察有无双相体温；瘀滞胞宫者注意经行腹痛、血块情况。\n煎药服药护理：补肾调经方药宜温服，于经后卵泡期按时服用勿漏服；中药保留灌肠或少腹热敷者，药液温度以37℃左右为宜，保留30分钟以上，外敷防烫伤；艾灸、穴位贴敷后避风保暖，观察局部皮肤。\n外治护理：针刺促排卵者注意局部消毒与晕针处理；督脉艾灸、涌泉穴贴敷后宜静卧片刻，观察有无过敏、水疱。\n\n【饮食】\n辨证忌口：肾阳虚者忌生冷寒凉、冰镇瓜果冷饮；肾阴虚者忌辛辣香燥（辣椒、烈酒、火锅）及羊肉狗肉等温热燥烈之品；痰湿内阻者忌肥甘厚腻、甜食奶制品；瘀滞胞宫者忌寒凉凝滞之物。\n适宜食物：肾阳虚者宜温补肾阳之品，如羊肉、核桃、韭菜、桂圆、山药、栗子；肾阴虚者宜滋阴填精之品，如黑芝麻、桑葚、枸杞、银耳、鸭肉、甲鱼。\n肝气郁结者宜疏肝理气之品，可用玫瑰花、佛手、陈皮、合欢花泡茶代饮，少食油炸滋腻以免碍脾生痰。\n痰湿阻滞者宜健脾燥湿化痰，多食薏苡仁、赤小豆、冬瓜、白扁豆、茯苓、山药，忌晚餐过饱、睡前加餐。\n药膳食疗：肾虚者经后宜当归生姜羊肉汤或菟丝子粥温养冲任；气血两虚者用枸杞红枣乌鸡汤、黄芪山药粥；血瘀者经前经期用山楂红糖水或桃仁粥活血调经，经期慎用寒凉药膳。\n\n【注意事项】\n35岁以上试孕6个月未孕即应系统检查\n明确病因后针对性治疗（输卵管、排卵、男方因素等）\n中医调理配合西医监测排卵提高受孕率\n\n【急诊/急救】\n一般不需急救\n大出血伴休克：立即急诊抢救\n宫外孕破裂/急性腹痛：立即转妇科急诊","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】不孕症\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肾阳虚\n    症状舌脉：婚久不孕，月经后期量少色淡，腰膝酸冷，畏寒肢冷，性欲淡漠，带下清稀，小便清长，舌淡胖苔白，脉沉细\n    治法：温肾暖宫、调补冲任\n    方剂：毓麟珠\n\n二、肾阴虚\n    症状舌脉：婚久不孕，月经先期量少色红，头晕耳鸣，腰膝酸软，五心烦热，心悸失眠，口干咽燥，舌红少苔，脉细数\n    治法：滋肾填精、养阴调冲\n    方剂：养精种玉汤\n\n三、肝郁气滞\n    症状舌脉：婚久不孕，月经先后无定期，经前乳房胀痛，胸胁胀满，善太息，烦躁易怒，苔薄白，脉弦\n    治法：疏肝解郁、理气调冲\n    方剂：开郁种玉汤\n\n四、痰湿内阻\n    症状舌脉：婚久不孕，形体肥胖，月经后期甚则闭经，带下量多色白质黏，胸闷泛恶，头晕心悸，舌淡胖苔白腻，脉滑\n    治法：燥湿化痰、理气调冲\n    方剂：苍附导痰丸\n\n五、血瘀\n    症状舌脉：婚久不孕，月经后期量少色暗有块，经行小腹刺痛拒按，块下痛减，舌紫暗有瘀点，脉弦涩\n    治法：活血化瘀、温经通络\n    方剂：少腹逐瘀汤\n\n【方剂参考】\n  养精种玉汤：组成 熟地黄30g、当归12g、白芍12g、山茱萸12g；功效 滋肾养血，调冲种子\n      用法：水煎温服，日一剂，分二次服。\n      注意：脾虚湿盛、食少便溏者慎用（熟地黄滋腻）；痰湿、血瘀之不孕非本方所宜；须先明确不孕病因。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补阴）；原方出自《傅青主女科·卷上·种子》\n  开郁种玉汤：组成 白芍15g、香附9g、当归9g、白术9g、牡丹皮9g、茯苓9g、天花粉12g；功效 疏肝解郁，调经种子\n      用法：水煎温服，日一剂，分二次服。\n      注意：须先明确不孕病因（男方因素、输卵管因素、排卵障碍等），不可仅恃本方；阴虚火旺者不宜久服。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂；原方出自《傅青主女科·卷上·种子》\n  苍附导痰丸：组成 苍术9g、香附9g、陈皮9g、半夏9g、茯苓9g、枳壳6g、胆南星6g、炙甘草6g、生姜3片；功效 燥湿化痰，行气解郁，开痰散结\n      用法：研末，以生姜自然汁浸饼为丸，每次6-9g，淡姜汤送服，日二次；亦可作汤剂，加生姜3片水煎温服。\n      注意：阴虚血少、虚火偏旺者不宜；服药期间忌生冷、肥甘厚味；经闭属气血亏虚而非痰湿者忌用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛痰剂（燥湿化痰）；原方出自《叶氏女科证治》（组成及是否含胆南星各家记载不一，待核）\n  少腹逐瘀汤：组成 小茴香1.5g（炒）、干姜3g（炒）、延胡索3g、没药6g（研）、当归9g、川芎6g、肉桂3g、赤芍6g、蒲黄9g（生）、五灵脂6g（炒）；功效 活血祛瘀，温经止痛\n      用法：水煎温服，日一剂，分二次服；亦可研末为散，每次6g，温酒送服。\n      注意：孕妇忌用（本方原书用于安胎，须身体壮实、确有瘀血可据者，且应遵医嘱）；月经过多、有出血倾向者慎用；体虚无瘀者不宜。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《医林改错·卷下》\n\n【西医诊断】\n  女性不孕症\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"N97.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2251,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8e875509541d0add947513ce1b5d6bc6619f729261e798db390a99afea0a0a94","pinyin":"buyunzheng(zhongyibianzheng)","initials":"byz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","N97.9",30]]},{"id":"templates-7de8ce92abe3ebc7d5be","key":"v1-c9ccc21dfe2a3058|templates-7de8ce92abe3ebc7d5be","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不寐(失眠中医辨证)","category":"中医","raw":{"name":"不寐(失眠中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】心火：心烦不寐，口舌生疮，舌尖红、肝郁：急躁易怒，不寐多梦，胸胁胀满，口苦、痰热：胸闷痰多，心烦不寐，头重目眩，苔黄腻、阴虚：心烦不寐，心悸健忘，五心烦热，潮热盗汗、心脾两虚：多梦易醒，心悸健忘，神疲食少，面色少华、心胆气虚：虚烦不寐，触事易惊，终日惕惕。\n【待人工确认·本机素材无此段原文】","现病史":"以经常不能获得正常睡眠为特征，表现为入睡困难、寐而易醒、醒后不寐、彻夜不眠。分心火亢盛、肝郁化火、痰热内扰、阴虚火旺、心脾两虚、心胆气虚等证型。\n常见表现：心火：心烦不寐，口舌生疮，舌尖红、肝郁：急躁易怒，不寐多梦，胸胁胀满，口苦、痰热：胸闷痰多，心烦不寐，头重目眩，苔黄腻、阴虚：心烦不寐，心悸健忘，五心烦热，潮热盗汗、心脾两虚：多梦易醒，心悸健忘，神疲食少，面色少华、心胆气虚：虚烦不寐，触事易惊，终日惕惕。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以入睡困难、寐而易醒、醒后不寐为主要表现，病程持续3周以上，诊断须先排除躯体疾病与精神疾病所致失眠，首先完善多导睡眠监测，了解睡眠结构、睡眠效率及有无睡眠呼吸暂停，明确失眠类型与严重程度，并可鉴别睡眠呼吸暂停低通气综合征、周期性肢体运动障碍等；查甲状腺功能，排除甲状腺功能亢进所致心悸不寐、急躁易怒，与肝郁化火证相鉴别；查空腹血糖及糖化血红蛋白，排除糖尿病所致夜尿增多、口干心烦而影响睡眠；完善血常规、肝肾功能及血电解质检查，排除贫血、肝肾功能不全及电解质紊乱所致虚烦不寐，并为长期服用安神中药的安全性提供依据；对心烦不寐、心悸健忘者，查心电图及动态心电图，排除心律失常、心肌缺血所致夜间心悸惊醒，必要时行心脏彩超了解心功能；对多梦易醒、神疲食少、面色少华者，查胃镜及幽门螺杆菌检测，排除慢性胃炎、胃食管反流所致夜间反酸、腹胀影响睡眠；查头颅CT或MRI，排除颅内病变所致睡眠节律紊乱；同时完善焦虑自评量表、抑郁自评量表及匹兹堡睡眠质量指数评估，客观评价情绪状态与睡眠质量，鉴别焦虑、抑郁等精神心理因素所致失眠，指导中医辨证分型与治疗方案。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 以失眠为主要症状，持续≥3周\n2. 排除躯体疾病和精神疾病导致的失眠\n3. 睡眠监测辅助评估\n1. 不寐(失眠中医辨证)（ICD-10：G47.0）","鉴别诊断":"1. 排除躯体疾病和精神疾病导致的失眠","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液\n\n方案2（严重失眠伴焦虑）：\n 用法：NS250ml+丹参注射液20ml ivgtt qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（心火）：\n 用法：朱砂安神丸1丸 qn，或导赤散1袋 tid\n\n药物2（肝郁）：\n 用法：龙胆泻肝丸1袋 tid，或解郁安神颗粒1袋 tid\n\n药物3（痰热）：\n 用法：黄连温胆汤1袋 tid，或礞石滚痰丸1袋 tid\n\n药物4（阴虚）：\n 用法：天王补心丹1丸 qn，或知柏地黄丸1丸 tid\n\n药物5（心脾两虚）：\n 用法：归脾丸1丸 tid，或人参归脾丸1丸 tid\n\n药物6（心胆气虚）：\n 用法：安神定志丸1丸 tid，或酸枣仁颗粒1袋 qn\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n心火：清心泻火，安神定志，朱砂安神丸\n肝郁：疏肝泻火，镇心安神，龙胆泻肝汤\n痰热：清化痰热，和中安神，黄连温胆汤\n阴虚：滋阴降火，交通心肾，六味地黄丸合黄连阿胶汤\n心脾两虚：补益心脾，养血安神，归脾汤\n心胆气虚：益气镇惊，安神定志，安神定志丸\n\n【处理要点】\n规律作息，睡前不玩手机\n睡前温水泡脚\n避免浓茶、咖啡\n适当运动，保持心情舒畅\n\n【护理】\n情志护理：辨证察情致因——肝火扰心者忌恼怒躁急，宜疏泄劝导、避免睡前争执；心脾两虚者多思虑忧思，宜以移情易性法（舒缓民乐、养花弄草）转移其念；心胆气虚者易惊易恐，忌惊吓刺激，宜家人陪伴安抚以安心神。\n起居调护：固定作息，于亥时（21～23时）前卧床，睡前1小时停用手机等电子设备，卧室宜暗、静、温凉适宜；心肾不交者忌熬夜劳神，午后午睡勿过久；晨起适度活动（太极拳、八段锦）调畅气机，促昼醒夜眠节律恢复。\n病情观察：重点观察入睡时间、夜醒次数、多梦与否及伴随症状——肝火扰心者察头痛目赤、急躁易怒程度，痰热扰心者察胸闷脘痞、痰多色黄，心脾两虚者察面色、食欲、乏力，心肾不交者察心烦、盗汗、耳鸣；记录安神中药及助眠西药服用后的睡眠改善情况。\n煎药服药护理：安神类汤剂宜睡前1小时温服；重镇安神之品（龙骨、牡蛎、磁石）及酸枣仁须先煎或捣碎入煎以助有效成分溶出；服药期间忌与浓茶、咖啡同服，以免拮抗安神之力。\n外治护理：睡前温水沐足20分钟，按揉涌泉、太溪以引火归元（尤宜心肾不交、肝火扰心者）；按压安眠穴、神门穴各3～5分钟，手法宜轻缓；痰热扰心者不宜艾灸助热，可予心俞、脾俞刮痧以清化湿热。\n\n【饮食】\n辨证忌口：肝火扰心者忌辛辣炙煿、油炸及咖啡浓茶，以免助火扰神；痰热扰心者忌肥甘厚味、甜腻及酒，以免酿湿生痰；心脾两虚者忌生冷瓜果、暴饮暴食，以免损伤脾胃；心肾不交者忌烟酒及辛辣动火之品。\n适宜食物：宜食健脾宁心安神之品，如小米、莲子、百合、龙眼肉、大枣、山药、茯苓；晚餐宜清淡、七分饱，睡前2小时内不进饮食，以免\"胃不和则卧不安\"。\n药膳食疗：酸枣仁粥（酸枣仁15g捣碎煎汁，加大米煮粥，睡前温食）养心安神，适宜心脾两虚、虚烦不眠者；百合莲子银耳羹清心安神，适宜心肾不交、肝火扰心者；甘麦大枣汤（浮小麦30g、甘草9g、大枣5枚）养心缓急，适宜心胆气虚、易惊善恐者。\n禁忌提点：下午3点后忌浓茶、咖啡、可乐等兴奋性饮品；痰热扰心者忌睡前进食甜食及奶制品等助湿生痰之品；晚餐忌辛辣油腻与过量饮酒。\n\n【注意事项】\n辨证用药，勿依赖安眠药\n长期失眠需排查抑郁焦虑\n孕妇慎用朱砂、磁石等含重金属药物\n\n【急诊/急救】\n一般不需急救\n严重失眠伴自杀倾向：精神科会诊","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「不寐（失眠中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】不寐\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肝火扰心\n    症状舌脉：不寐多梦，甚则彻夜不眠，急躁易怒，头晕头胀，目赤耳鸣，口干口苦，便秘溲赤，舌红苔黄，脉弦数\n    治法：清肝泻火、镇心安神\n    方剂：龙胆泻肝汤\n\n二、痰热扰心\n    症状舌脉：心烦不寐，胸闷脘痞，泛恶嗳气，头重目眩，口苦痰多，舌红苔黄腻，脉滑数\n    治法：清化痰热、和中安神\n    方剂：黄连温胆汤\n\n三、心脾两虚\n    症状舌脉：不易入睡，多梦易醒，心悸健忘，神疲食少，头晕目眩，面色少华，腹胀便溏，舌淡苔薄白，脉细弱\n    治法：补益心脾、养血安神\n    方剂：归脾汤\n\n四、心肾不交\n    症状舌脉：心烦不寐，入睡困难，心悸多梦，头晕耳鸣，腰膝酸软，潮热盗汗，五心烦热，舌红少苔，脉细数\n    治法：滋阴降火、交通心肾\n    方剂：交泰丸合六味地黄丸\n\n五、心胆气虚\n    症状舌脉：虚烦不寐，多梦易惊醒，胆怯心悸，遇事善惊，气短倦怠，自汗，舌淡苔薄白，脉弦细\n    治法：益气镇惊、安神定志\n    方剂：安神定志丸合酸枣仁汤\n\n【方剂参考】\n  龙胆泻肝汤：组成 龙胆草6g、黄芩9g、栀子9g、泽泻12g、川木通6g（禁用关木通）、车前子9g、当归3g、生地黄9g、柴胡6g、生甘草6g；功效 清泻肝胆实火，清利肝经湿热\n      用法：水煎温服，日二次，饭后服；亦可制丸，每次6-9g，日二次。\n      注意：脾胃虚寒、孕妇及阴虚阳亢者忌用；苦寒渗利之品久服伤胃耗阴，一般不超过7-14剂；木通用量宜小。木通须用川木通；关木通含马兜铃酸、2005 年起取消药用标准，禁止使用。\n  黄连温胆汤：组成 黄连6g、半夏6g、竹茹6g、枳实6g、陈皮9g、茯苓4.5g、炙甘草3g、生姜3片、大枣1枚；功效 清热化痰，理气和中，宁心安神\n      用法：加生姜3片、大枣1枚，水煎温服，日一剂，分二次服；黄连用量可随热势轻重增减。\n      注意：阴虚火旺、脾胃虚寒及痰中带血者不宜；孕妇慎用半夏；不宜久服，热清痰化即当停药或改用平和之剂。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛痰剂（清热化痰）；本方系温胆汤加黄连，温胆汤原方出自《三因极一病证方论》\n  归脾汤：组成 白术9g、当归9g、白茯苓9g、黄芪12g、龙眼肉12g、远志6g、酸枣仁12g、人参9g、木香6g、炙甘草3g、生姜3片、大枣3枚；功效 益气补血，健脾养心\n      用法：加生姜3片、大枣3枚，水煎温服，日二次；亦可服归脾丸，每次6-9g，日二次。\n      注意：痰湿内盛、肝火扰心之失眠及外感发热者不宜；本方偏温补，有实火者忌用。\n  六味地黄丸：组成 熟地黄24g、山茱萸12g、山药12g、泽泻9g、牡丹皮9g、茯苓9g；功效 滋补肝肾\n      用法：上药为末，炼蜜为丸，每次6-9g，空腹温开水或淡盐汤送服，日二至三次；亦可作汤剂（六味地黄汤）。\n      注意：脾虚便溏、痰湿内盛及感冒发热者忌用；本品滋腻，久服宜配健脾理气之品；肾阳虚（畏寒肢冷）者不宜。\n  酸枣仁汤：组成 酸枣仁15g、甘草3g、知母6g、茯苓6g、川芎6g；功效 养血安神，清热除烦\n      用法：酸枣仁先煎（或炒熟捣碎），再入余药同煎，去滓温服，日三次，睡前一次不可少。\n      注意：痰热扰心、肝火亢盛之失眠者不宜单用；脾虚便溏者慎用知母；孕妇慎用川芎。\n\n【西医诊断】\n  失眠障碍\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"G47.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2252,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9a610ad648ddf54918d2e329a9f231447726bda501f9df8853fbd85828f2b92b","pinyin":"bumei(shimianzhongyibianzheng)","initials":"bm(smzybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","G47.0",30]]},{"id":"templates-4b559f2cffabc5ebb23f","key":"v1-c9ccc21dfe2a3058|templates-4b559f2cffabc5ebb23f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不稳定性心绞痛","category":"鉴别诊断速查","raw":{"name":"不稳定性心绞痛","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】新发心绞痛或原有心绞痛加重、休息时也可发作、持续时间延长>10分钟、硝酸甘油缓解不明显、可伴出汗、恶心。\n【待人工确认·本机素材无此段原文】","现病史":"多见于中老年患者，可有糖尿病、高血压等基础病，可反复发作，临床表现为阵发性胸痛、胸闷，压榨性，持续数分钟不等，一般不超过半小时，含服硝酸甘油或休息时可自行缓解。查心电图可发现心肌缺血，查冠脉造影可明确诊断。\n常见表现：新发心绞痛或原有心绞痛加重、休息时也可发作、持续时间延长>10分钟、硝酸甘油缓解不明显、可伴出汗、恶心。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏（注意频率、节律、强弱）、呼吸、血压（双侧对比）、血氧饱和度\n一般情况：神志、精神状态、面色（苍白/潮红/发绀）、体位、有无呼吸困难\n皮肤黏膜：有无发绀、苍白、黄染、出血点、水肿（下肢/腰骶部）\n心脏检查：心前区有无隆起、心尖搏动位置及范围、心界大小（叩诊）、心率心律、心音强弱、各瓣膜听诊区有无杂音（部位、性质、时期、强度、传导方向）、有无心包摩擦音\n血管检查：桡动脉节律及强弱、有无奇脉/交替脉/水冲脉、毛细血管搏动征、枪击音、Duroziez双重杂音、颈静脉怒张、肝颈静脉回流征\n肺部检查：呼吸频率节律、双肺呼吸音、有无干湿啰音（心衰肺水肿表现）\n腹部检查：肝脾肿大（右心衰肝淤血）、腹水征、腹部搏动\n四肢：有无水肿（凹陷性/非凹陷性）、杵状指、关节红肿","辅助检查":"1. 心电图：胸痛发作时立即描记18导联心电图，并于缓解后复查，动态观察ST-T演变\n2. 心肌损伤标志物（肌钙蛋白I/T、CK-MB）：入院即刻及发病后3~6h、12h、24h动态复查，排除非ST段抬高型心肌梗死\n3. 血常规、凝血功能、D-二聚体、血脂、空腹血糖及糖化血红蛋白：入院24h内完成，评估危险分层\n4. 超声心动图：入院24h内评估节段性室壁运动异常及左心功能（LVEF）\n5. 24小时动态心电图：捕捉无症状心肌缺血及心律失常，评估缺血负荷\n6. 冠脉影像：中高危患者尽早行冠脉造影（或冠脉CTA）明确冠脉病变，指导血运重建","初步诊断":"1. 典型缺血性胸痛\n2. 心电图ST段压低或T波倒置\n3. 心肌酶正常或轻度升高\n4. 冠脉造影可见不稳定斑块\n5. 肌钙蛋白可轻度升高\n1. 不稳定性心绞痛（ICD-10：I20.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：硝酸甘油10mg+5%GS 250ml ivgtt（根据血压调速）\n\n方案2：\n 用法：肝素钠1.25万U+5%GS 500ml ivgtt（监测APTT）\n\n方案3：\n 用法：替罗非班按体重泵入\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：阿司匹林300mg负荷量后100mg qd\n\n药物2：\n 用法：氯吡格雷300mg负荷量后75mg qd\n\n药物3：\n 用法：阿托伐他汀40mg qn\n\n药物4：\n 用法：美托洛尔25mg bid\n\n药物5：\n 用法：依诺肝素4000U q12h皮下注射\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n1. 双联抗血小板：阿司匹林+氯吡格雷\n2. 抗凝：低分子肝素\n3. 抗心肌缺血：硝酸酯类+β受体阻滞剂\n4. 调脂：患者度他汀\n5. 冠脉造影+PCI\n\n【处理要点】\n卧床休息，心电监护，吸氧，监测心肌酶和心电图变化，保持大便通畅，避免情绪激动\n\n【护理】\n持续心电监护，密切观察胸痛性质、持续时间及心电图ST-T变化，警惕进展为急性心肌梗死\n急性发作期绝对卧床休息，取半卧位或端坐位，予鼻导管吸氧（2~4L/min），缓解期逐渐增加活动量\n遵医嘱硝酸甘油含服或静脉泵入，用药前后监测血压，预防低血压及反射性心动过速\n严密监测心率、血压、呼吸，记录出入量，观察有无心衰、恶性心律失常等并发症；做好心理护理，消除紧张恐惧，避免用力排便（必要时予缓泻剂）\n\n【饮食】\n低盐低脂饮食，每日食盐<5g，减少饱和脂肪酸及反式脂肪摄入，戒烟限酒\n急性期进食易消化半流质或软食，少食多餐、每餐七八分饱，避免过饱诱发心绞痛\n忌浓茶、咖啡及辛辣刺激食物，避免过冷过热饮食，餐后勿立即活动或劳作\n推荐富含膳食纤维的蔬菜、水果及全谷物，适量深海鱼（富含ω-3脂肪酸），合并糖尿病者按糖尿病饮食严格控制糖分摄入\n控制体重，规律进餐，不暴饮暴食；饮用咖啡、酒精前需经医师评估\n\n【注意事项】\n【鉴别要点】多见于中老年患者，可有糖尿病、高血压等基础病，可反复发作，临床表现为阵发性胸痛、胸闷，压榨性，持续数分钟不等，一般不超过半小时，含服硝酸甘油或休息时可自行缓解。查心电图可发现心肌缺血，查冠脉造影可明确诊断。\n不稳定型心绞痛属急性冠脉综合征，需住院治疗，高危患者应尽早行冠脉造影\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n胸痛持续不缓解伴ST段抬高，考虑急性心肌梗死，立即启动心梗急救流程","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"I20.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2253,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ea110a2d8043c34bc5cd8f38dfed18657b41f24b9e516af02a1846b1317698ba","pinyin":"buwendingxingxinjiaotong","initials":"bwdxxjt","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I20.9",30]]},{"id":"templates-425eb86152c0ec33c8ea","key":"v1-c9ccc21dfe2a3058|templates-425eb86152c0ec33c8ea","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"丙型肝炎","category":"内科-感染","raw":{"name":"丙型肝炎","category":"内科-感染","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】乏力、食欲减退、恶心、肝区不适。\n【待人工确认·本机素材无此段原文】","现病史":"丙型肝炎病毒引起的慢性肝病，可进展为肝硬化和肝癌\n常见表现：乏力、食欲减退、恶心、肝区不适。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压可正常\n皮肤黏膜：可有蜘蛛痣、肝掌（肝硬化时）\n腹部：肝大，叩击痛，脾大（肝硬化时）","辅助检查":"1. 丙肝抗体（抗-HCV）：初筛必查，阳性需进一步确认\n2. HCV-RNA定量：确诊及疗效判断，治疗前及停药后12周复查\n3. 肝功能+凝血功能：评估肝损伤程度，治疗前及治疗中每4-8周复查\n4. 肝脏弹性成像或FibroScan：评估肝纤维化程度，指导抗病毒疗程及随访\n5. 甲胎蛋白+肝脏彩超：肝硬化者每6个月筛查肝癌","初步诊断":"1. 抗-HCV阳性\n2. HCV-RNA阳性\n3. 转氨酶升高\n1. 丙型肝炎（ICD-10：B18.2）","鉴别诊断":"1. 诊断要点：抗-HCV阳性\n2. 诊断要点：HCV-RNA阳性\n3. DAA治疗前评估肝硬化程度\n4. 治疗结束后12周复查HCV-RNA判断SVR","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：NS250ml+甘草酸二铵150mg ivgtt qd（保肝）\n\n方案2：\n 用法：NS100ml+还原型谷胱甘肽1.2g ivgtt qd（保肝）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：索磷布韦/维帕他韦1片 qd（基因型1-6型，12周）\n\n药物2：\n 用法：多烯磷脂酰胆碱胶囊456mg tid（保肝）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n抗病毒治疗（DAA方案）\n保肝治疗\n监测肝功能及病毒载量\n\n【处理要点】\n戒酒\n避免使用肝毒性药物\n定期复查HCV-RNA及肝功能\n\n【护理】\n病情观察：观察乏力、食欲、黄疸变化，肝硬化患者注意腹围、体重及有无出血倾向\n用药护理：指导按时服药，DAA治疗期间观察有无头痛、乏力等不良反应\n隔离与防护：血液体液隔离，告知患者不共用牙刷、剃须刀，避免血液传播\n健康宣教：戒酒、避免劳累，规律作息，定期门诊随访\n\n【饮食】\n高蛋白高维生素饮食：瘦肉、鱼、蛋、豆制品及新鲜蔬果，保证营养\n限制脂肪摄入：避免油炸、肥腻食物，减轻肝脏负担\n肝硬化腹水者低盐饮食（每日<3g），限制液体入量\n忌酒及肝毒性食物（发霉食物、生鱼片等），避免食用含黄曲霉素食物\n少食多餐，细嚼慢咽，避免过饱\n\n【注意事项】\nDAA治疗前评估肝硬化程度\n治疗结束后12周复查HCV-RNA判断SVR\n\n【急诊/急救】\n一般不涉及院前急救\n肝衰竭表现（黄疸加重、腹水、意识障碍）：及时转院","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「丙型肝炎」原文）"},"icd10_diagnosis":"B18.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2254,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"92c1f1294afbafebd977a081295970deaebb3ba1ff2d202f76a7129938094974","pinyin":"bingxingganyan","initials":"bxgy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","B18.2",30]]},{"id":"templates-0bdf68de65852d53e8a2","key":"v1-c9ccc21dfe2a3058|templates-0bdf68de65852d53e8a2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"严重创伤/外伤","category":"院前急救","raw":{"name":"严重创伤/外伤","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】出血（外出血/内出血）、疼痛、肿胀、畸形、功能障碍、休克表现（苍白、冷汗、脉搏快、血压低）、意识障碍、呼吸困难。\n【待人工确认·本机素材无此段原文】","现病史":"机械因素导致人体组织器官损伤，需先救命后治伤。\n常见表现：出血（外出血/内出血）、疼痛、肿胀、畸形、功能障碍、休克表现（苍白、冷汗、脉搏快、血压低）、意识障碍、呼吸困难。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 床旁FAST创伤超声：入院即刻于抢救室床旁完成，评估心包积液、腹腔/胸腔游离液体及气胸，用于快速决策\n2. 全身CT（头颅+颈椎+胸腹盆平扫，视伤情加增强）：生命体征相对稳定后尽快完成，明确实质脏器损伤、大血管损伤及脊柱骨折\n3. 动脉血气分析+血乳酸：入院即查并动态复查，评估休克程度、酸碱失衡及复苏效果\n4. 血常规+血型鉴定+交叉配血：立即抽取并送备血，动态复查血红蛋白变化\n5. 凝血功能（PT/APTT/纤维蛋白原/D-二聚体）+血栓弹力图：筛查创伤性凝血病，指导血液制品输注\n6. 急诊生化（电解质、肝肾功能、肌钙蛋白）：排除低钾等电解质紊乱及心肌损伤；怀疑中毒或挤压伤时加查毒物检测、肌红蛋白","初步诊断":"1. 外伤史\n2. 体格检查：ABCDE原则\n3. 注意多发伤、复合伤\n4. 警惕隐匿性出血\n1. 严重创伤/外伤（ICD-10：T14.9）","鉴别诊断":"1. 诊断要点：体格检查：ABCDE原则\n2. 诊断要点：注意多发伤、复合伤\n3. 诊断要点：警惕隐匿性出血\n4. 先救命后治伤\n5. 不要随意拔出刺入物\n6. 止血带记录时间，每小时放松1-2分钟\n7. 脊柱损伤必须轴线搬运\n8. 警惕隐匿性内出血","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：建立2条大口径静脉通路\n\n方案2（快速补液）：\n 用法：NS/乳酸林格液 1000-2000ml\n\n方案3（失血性休克）：\n 用法：输血（必要时）\n\n方案4（止血带休克）：\n 用法：避免\n\n方案5（疼痛）：\n 用法：吗啡5-10mg iv（血压稳定时）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：院前以静脉用药为主\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\nABCDE原则：A气道、B呼吸、C循环、D神经、E暴露\n气道：清除异物，必要时气管插管\n呼吸：开放性气胸封闭伤口，张力性气胸穿刺排气\n循环：止血（直接压迫、止血带），快速补液\n脊柱损伤：轴线翻身，颈托固定\n骨折：夹板固定\n颅脑损伤：保持气道通畅，降颅压（甘露醇）\n抗休克：平卧，抬高下肢，保暖\n疼痛管理：吗啡（血压稳定时）\n120转院\n\n【处理要点】\n先救命后治伤\n快速评估ABCDE\n控制明显出血\n脊柱损伤避免搬动\n骨折临时固定\n保暖，避免低体温\n记录受伤时间、机制、症状\n\n【护理】\n气道管理：立即评估气道通畅性与呼吸状态，必要时协助气管插管或环甲膜穿刺，高流量吸氧，持续SpO₂监测\n生命体征与病情观察：每5-15分钟监测血压、心率、呼吸、体温，动态评估意识、瞳孔及末梢循环，早期识别失血性休克\n抢救配合：建立两条以上大静脉通路（首选肘前静脉），配合加压快速输液输血，使用保温毯/加温输液预防低体温\n出血控制与制动：活动性出血处加压包扎或遵医嘱止血带（记录时间），骨折肢体夹板固定制动，减少搬动并记录出血量\n防并发症：留置导尿监测每小时尿量（≥30ml/h提示灌注良好），遵医嘱注射破伤风抗毒素/疫苗，密切观察有无张力性气胸、气道梗阻及再出血征象\n\n【饮食】\n伤后早期一律暂禁食禁水（至少8-12小时），为急诊手术、气管插管及复苏期误吸预防做准备\n疑有腹腔脏器损伤或拟行急诊手术者持续禁食，遵医嘱行胃肠减压，评估肠鸣音情况\n排除消化道损伤且生命体征稳定后，先试饮少量温开水，无恶心呕吐再过渡至清流质（米汤、藕粉、果汁）\n恢复期逐步过渡至半流质、软食，优先高蛋白易消化食物（蒸蛋羹、鱼汤、瘦肉粥、豆腐），促进组织修复\n忌辛辣、油腻、生冷食物及烟酒，少食多餐防腹胀；大剂量复苏补液后注意观察有无腹胀及肠功能恢复情况\n\n【注意事项】\n先救命后治伤\n不要随意拔出刺入物\n止血带记录时间，每小时放松1-2分钟\n脊柱损伤必须轴线搬运\n警惕隐匿性内出血\n\n【急诊/急救】\nABCDE快速评估：气道、呼吸、循环、神经、暴露\n气道：清除异物，防误吸\n呼吸：开放性气胸封闭，张力性气胸穿刺排气\n循环：直接压迫止血，止血带（记录时间）\n建立2条静脉通路，快速补液NS 1000ml\n脊柱损伤：颈托固定，轴线搬运\n骨折：夹板固定\n休克：平卧抬高下肢，保暖\n120转院","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「严重创伤/外伤」原文）"},"icd10_diagnosis":"T14.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2255,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"86e9be66a8badf7b05089514e7300982408eeb98021d57cc41e66f8e3a8d6ad7","pinyin":"yanzhongchuangshang/waishang","initials":"yzcs/ws","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T14.9",30]]},{"id":"templates-ff758026010d6d59558c","key":"v1-c9ccc21dfe2a3058|templates-ff758026010d6d59558c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"中枢神经系统兴奋性鼠药中毒","category":"鉴别诊断速查","raw":{"name":"中枢神经系统兴奋性鼠药中毒","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】潜伏期短（10分钟-1小时），口服后迅速出现症状、神经系统：头痛头晕、乏力、口唇麻木、烦躁不安、意识模糊、典型表现：反复癫痫大发作（全身强直性阵挛抽搐、口吐白沫、意识丧失、大小便失禁）、抽搐持续状态可导致呼吸肌痉挛、窒息、发绀、消化系统：恶心呕吐、上腹部烧灼感、腹痛、心血管系统：心悸、胸闷、心律失常、血压升高或下降、严重者：昏迷、呼吸衰竭、心力衰竭、多器官功能衰竭、精神症状：部分患者恢复期出现幻觉、妄想等精神障碍。\n【待人工确认·本机素材无此段原文】","现病史":"以惊厥、昏迷、抽搐为表现，心电图有心肌损伤表现。\n常见表现：潜伏期短（10分钟-1小时），口服后迅速出现症状、神经系统：头痛头晕、乏力、口唇麻木、烦躁不安、意识模糊、典型表现：反复癫痫大发作（全身强直性阵挛抽搐、口吐白沫、意识丧失、大小便失禁）、抽搐持续状态可导致呼吸肌痉挛、窒息、发绀、消化系统：恶心呕吐、上腹部烧灼感、腹痛、心血管系统：心悸、胸闷、心律失常、血压升高或下降、严重者：昏迷、呼吸衰竭、心力衰竭、多器官功能衰竭、精神症状：部分患者恢复期出现幻觉、妄想等精神障碍。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 毒物检测：血液、尿液毒鼠强及氟乙酰胺定性/定量检测（GC-MS），洗胃后留取胃内容物同步送检，明确毒物种类与浓度，评估中毒严重程度\n2. 动脉血气分析：入院即刻及抽搐发作期、患者地西泮/苯巴比妥后动态复查，评估低氧血症与酸碱失衡\n3. 血电解质（K⁺、Na⁺、Cl⁻、Ca²⁺）及心肌酶谱：动态复查，警惕低钾、低钙血症及心肌损伤\n4. 心电图（12导联）：入院即刻及用药期间动态监测，观察心律失常、QT间期延长及ST-T改变\n5. 肝肾功能、凝血功能：入院后及乙酰胺（解氟灵）用药期间定期复查，评估脏器损伤及药物影响\n6. 头颅CT/脑电图：反复或难控制抽搐者完善检查，排除脑器质性病变并评估中毒性脑损伤程度","初步诊断":"1. 毒鼠强服用/接触史（白色粉末/颗粒，常拌在食物中）\n2. 典型反复癫痫大发作，常规抗癫痫药效果不佳\n3. 血/尿/呕吐物/食物中检出毒鼠强（气相色谱/质谱）\n4. 脑电图：癫痫样放电\n5. 心肌酶升高（CK、CK-MB、LDH）\n6. 白细胞升高，肝肾功能异常（严重者）\n1. 中枢神经系统兴奋性鼠药中毒（ICD-10：T60.4）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：地西泮 10-20mg缓慢静注（抽搐时），必要时15-30分钟重复，24小时总量不超过100mg\n\n方案2：\n 用法：丙戊酸钠 0.4g静滴 q8h（维持抗癫痫）\n\n方案3：\n 用法：苯巴比妥钠 0.1-0.2g肌注 q6-8h（与地西泮交替）\n\n方案4：\n 用法：20%甘露醇 125-250ml静滴 q6-8h（脑水肿）\n\n方案5：\n 用法：呋塞米 20-40mg静注（促进排泄）\n\n方案6：\n 用法：维生素B6 1-2g静滴（辅助，促进脑代谢）\n\n方案7：\n 用法：纳洛酮 0.4-0.8mg静注（意识障碍时）\n\n方案8：\n 用法：5%碳酸氢钠 静滴（纠正酸中毒）\n\n方案9（营养心肌药物）：\n 用法：极化液、维生素C等\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：丙戊酸钠片 0.2-0.4g tid（恢复期维持抗癫痫）\n\n药物2：\n 用法：苯巴比妥片 30-60mg tid（维持）\n\n药物3：\n 用法：维生素B6片 10mg tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n口服者立即催吐、洗胃（清水/1:5000高锰酸钾），洗胃后活性炭30-50g吸附，硫酸钠导泻\n控制抽搐是首要任务：地西泮静注，无效时丙泊酚/咪达唑仑静脉泵入\n苯巴比妥钠肌注与地西泮交替使用\n保持呼吸道通畅，吸氧，抽搐持续状态时气管插管机械通气\n尽早行血液灌流（HP），可有效清除毒鼠强，重度者可多次灌流\n对症支持：降颅压、营养心肌、保护肝肾、纠正水电解质紊乱\n防治感染，维持内环境稳定\n精神症状明显者给予抗精神病药物\n恢复期进行康复治疗和心理疏导\n\n【处理要点】\n口服者立即刺激咽喉催吐，尽快送医洗胃\n抽搐发作时：将患者平卧，头偏向一侧，解开衣领，清除口鼻分泌物，防止舌咬伤（用牙垫/毛巾）\n不要强行按压抽搐肢体，防止骨折\n保持呼吸道通畅，防止窒息和误吸\n记录抽搐开始时间、持续时间、发作频率\n保留剩余毒饵、呕吐物送检\n抽搐频繁者需专人看护，防止坠床和意外伤害\n严密监测生命体征、血氧饱和度、意识状态\n\n【护理】\n洗胃配合：中毒后6小时内尽早彻底洗胃，用温清水或活性炭混悬液反复冲洗至洗出液澄清，洗胃后经胃管注入活性炭50g吸附残余毒物，遵医嘱予甘露醇导泻；洗胃时头偏一侧、防误吸\n解毒剂观察：遵医嘱静滴乙酰胺（解氟灵）2.5~5g，每日2~4次（重症首剂加倍），观察有无注射部位红肿、过敏反应，用药期间配合监测肝肾功能\n生命体征与抽搐监测：持续心电监护心率、血压、血氧饱和度，重点记录抽搐发作的频率、持续时间及发作时意识、瞳孔变化；床旁备开口器、压舌板、吸痰装置及地西泮等止痉药物\n气道管理：抽搐发作时立即头偏向一侧，及时吸除口鼻分泌物，防舌后坠及误吸窒息；抽搐难以控制或气道不畅者配合气管插管、机械通气\n并发症观察：记录24小时出入量，观察尿量变化警惕急性肾损伤；观察呕血、黑便等应激性溃疡表现；加床栏、约束保护防坠床与自伤\n\n【饮食】\n洗胃后暂禁食水4~6小时，观察有无恶心、呕吐、腹痛及消化道出血（洗胃损伤、应激性溃疡），确认平稳后再逐步恢复进食\n恢复进食初期予温凉流质（米汤、藕粉、无渣果汁），少量多餐，每2~3小时一次，每次100~200ml\n病情稳定后过渡至半流质、软食（粥、烂面条、蛋羹），避免粗糙、辛辣、过冷过热及油腻食物刺激胃黏膜\n保证充足补液：不能口服者遵医嘱静脉补液（平衡液、葡萄糖液）维持水电解质平衡，可口服者少量多次温水促进毒物排泄\n抽搐频繁或意识障碍期间予静脉营养支持，暂不口服进食以防误吸；忌浓茶、咖啡、酒精及碳酸饮料\n\n【注意事项】\n【鉴别要点】以惊厥、昏迷、抽搐为表现，心电图有心肌损伤表现。\n毒鼠强剧毒，人口服致死量约0.1-0.2mg/kg，无特效解毒剂\n毒鼠强化学性质稳定，可造成二次中毒（猫/狗吃了中毒老鼠也会中毒）\n控制抽搐是抢救成功的关键，地西泮+苯巴比妥联合效果好\n血液灌流是最有效的清除手段，应尽早进行，可重复\n毒鼠强排泄慢，可在体内存留数月，需长期随访\n国家已明令禁止生产、销售、使用毒鼠强\n恢复期可能出现精神症状，需精神科干预\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n立即催吐，尽快清水/高锰酸钾洗胃\n抽搐发作时保持呼吸道通畅，防止舌咬伤\n地西泮10-20mg缓慢静注，必要时重复\n苯巴比妥钠0.1-0.2g肌注\n吸氧，发绀者人工呼吸\n尽快送医行血液灌流","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T60.4","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2256,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"09ca19f7d4a7cb41824d09b28d1d84a2b84d6487384c3e6bfc884de8b8f0c8aa","pinyin":"zhongshushenjingxitongxingfenxingshuyaozhongdu","initials":"zssjxtxfxsyzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T60.4",30]]},{"id":"templates-c2ec9b39b6f9624510c1","key":"v1-c9ccc21dfe2a3058|templates-c2ec9b39b6f9624510c1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"中风(中医辨证)","category":"中医","raw":{"name":"中风(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】中经络：半身不遂，口眼歪斜，语言不利，意识清楚、风痰瘀阻：头晕目眩，痰多而黏，舌质暗淡苔薄白腻、风阳上扰：眩晕头痛，面红目赤，口苦咽干，心烦易怒、阴虚风动：手足蠕动，肢体麻木，五心烦热，失眠多梦、中脏腑：突然昏仆，不省人事，牙关紧闭，两手握固（闭证），或目合口张，手撒肢冷（脱证）。\n【待人工确认·本机素材无此段原文】","现病史":"以猝然昏仆、不省人事、半身不遂、口眼歪斜、语言不利为主症，亦称脑卒中。分中经络（无神志改变）和中脏腑（有神志障碍），恢复期需辨证康复。\n常见表现：中经络：半身不遂，口眼歪斜，语言不利，意识清楚、风痰瘀阻：头晕目眩，痰多而黏，舌质暗淡苔薄白腻、风阳上扰：眩晕头痛，面红目赤，口苦咽干，心烦易怒、阴虚风动：手足蠕动，肢体麻木，五心烦热，失眠多梦、中脏腑：突然昏仆，不省人事，牙关紧闭，两手握固（闭证），或目合口张，手撒肢冷（脱证）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者急性起病，出现半身不遂、口眼歪斜、语言不利等局灶性神经功能缺损表现，为明确出血或缺血性质，急诊完成头颅CT平扫检查，排除脑出血及蛛网膜下腔出血，这是决定能否溶栓治疗的关键；若发病在时间窗内且拟行静脉溶栓，须同时完善血糖、血常规、凝血功能及肝肾功能检查，排除低血糖、血小板减少、凝血功能障碍等溶栓禁忌证；为明确梗死部位、范围及有无责任血管病变，急性期完善头颅MRI加弥散加权成像检查，对小脑、脑干梗死及超早期梗死较CT更为敏感；完善头颈部CT血管成像或磁共振血管成像，了解颅内大血管有无狭窄、闭塞及动脉瘤，明确缺血性卒中的血管病因，指导抗血小板、抗凝或血管内治疗决策；查颈动脉超声及经颅多普勒，评估颈动脉斑块性质与颅内血流情况，了解脑灌注状态；因心源性栓塞是重要病因，完善心电图、动态心电图及心脏彩超，明确有无心房颤动、附壁血栓及瓣膜病变，排除心源性栓塞；查血脂、同型半胱氨酸及糖化血红蛋白，了解血脂、血糖水平及代谢危险因素，指导降脂与二级预防方案；对风痰瘀阻、头晕目眩者完善脑电图，鉴别癫痫发作所致意识障碍；急性期动态监测电解质、血气分析及神经功能评分，评估病情演变；病情稳定后完善吞咽功能评估、认知功能筛查及康复评定，指导中医辨证康复治疗。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 急性起病，局灶性神经功能缺损\n2. 头颅CT/MRI明确出血或梗死\n3.与癫痫、晕厥鉴别\n1. 中风(中医辨证)（ICD-10：I64）","鉴别诊断":"1.与癫痫、晕厥鉴别","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（脑梗死）：\n 用法：NS250ml+丹参川芎嗪10ml ivgtt qd，或NS250ml+银杏达莫20ml ivgtt qd\n\n方案2（脑出血）：\n 用法：NS250ml+清开灵40ml ivgtt qd\n\n方案3（恢复期）：\n 用法：NS250ml+脑蛋白水解物60mg ivgtt qd\n\n方案4（脱证）：\n 用法：参附注射液40ml iv 或 ivgtt\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（风痰瘀阻）：\n 用法：华佗再造丸8g tid，或通心络胶囊4粒 tid\n\n药物2（风阳上扰）：\n 用法：天麻钩藤颗粒1袋 tid，或镇肝熄风颗粒1袋 tid\n\n药物3（阴虚风动）：\n 用法：大定风珠1袋 tid，或知柏地黄丸1丸 tid\n\n药物4（气虚血瘀）：\n 用法：补阳还五颗粒1袋 tid，或脑心通胶囊4粒 tid\n\n药物5（中脏腑闭证）：\n 用法：安宫牛黄丸1丸鼻饲，或至宝丹1丸鼻饲\n\n药物6（脱证）：\n 用法：参附汤鼻饲\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n中经络：平肝息风，化痰祛瘀通络\n中脏腑闭证：息风清火，豁痰开窍，安宫牛黄丸\n中脏腑脱证：回阳救阴，参附汤合生脉散\n恢复期：益气活血，化瘀通络，补阳还五汤\n\n【处理要点】\n急性期卧床，保持呼吸道通畅\n控制血压、血糖\n早期康复训练\n低盐低脂饮食，戒烟限酒\n\n【护理】\n病情观察：密切观察神志、瞳孔、言语、肢体及血压变化，若神志由清转昏、瞳仁大小不等、血压骤升，为病情加重之兆，立即报告医师；肝阳暴亢者尤须警惕再发；痰热腑实者观察大便与舌苔，保持腑气通畅；肢体水肿或伴心衰者准确记录24小时出入量。\n起居调护：急性期绝对卧床休息，头部稍抬高，避免搬动及用力屏气；气虚血瘀者注意保暖，避风寒，勿过劳耗气；恢复期协助循序渐进进行肢体功能锻炼，专人陪护防跌倒坠床。\n情志护理：中风患者多急躁易怒或悲观抑郁，肝阳上亢者忌恼怒激动，以防肝阳暴张诱发再中；多予开导鼓励，移情易性，使其树立康复信心，避免情绪剧烈波动。\n煎药服药护理：中药宜温服，通腑泻热之剂（痰热腑实证）中病即止，观察泻后神志是否转清；吞咽困难者鼻饲给药并注意药液温度适宜，防呛咳误吸；服活血化瘀药期间观察有无出血倾向（牙龈、皮下瘀斑、便血）。\n外治护理：肢体偏瘫者予针刺、穴位按摩（取百会、内关、足三里、三阴交等），气虚血瘀者可用艾灸温经通络，注意掌握温度防烫伤；定时翻身拍背，按摩受压部位，防压疮及坠积性肺炎。\n\n【饮食】\n辨证忌口：肝阳暴亢、风火上扰者忌辛辣、烟酒、咖啡等助火动风之品，忌肥甘厚味；风痰阻络、痰热腑实者忌油腻、甜腻生痰之品；阴虚风动者忌辛辣温燥之品以免伤阴动风。\n适宜食物：宜清淡易消化、富含膳食纤维之品，多食新鲜蔬菜水果，如芹菜、冬瓜、黄瓜、木耳、山楂、海带等，保持大便通畅，忌用力努责以防再中。\n药膳食疗：肝阳上亢者可用菊花、决明子泡茶，芹菜汁平肝潜阳；痰浊内盛者用薏苡仁、陈皮、荷叶煮粥健脾化痰；阴虚风动者用百合、麦冬、枸杞煲粥养阴息风；气虚血瘀者用黄芪炖鸡或黄芪山药粥补气行血。\n进食调护：吞咽困难者予糊状、软烂易吞咽饮食，少量多餐，防呛咳误吸；低盐低脂饮食，每日食盐摄入宜少于5g，血压高者尤须严格控制；注意补充水分，多饮水，防止血液黏稠诱发再中风。\n\n【注意事项】\n时间就是大脑，急性卒中立即拨打120\n溶栓时间窗内尽早溶栓\n二级预防：抗血小板、他汀、控制危险因素\n\n【急诊/急救】\n立即拨打120\n保持呼吸道通畅，侧卧位防误吸\n监测血压、血糖\n脑梗死4.5小时内可静脉溶栓\n脑出血：控制血压，避免搬动","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「中风（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】中风\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、气虚血瘀\n    症状舌脉：半身不遂，肢软无力，口舌歪斜，言语謇涩，面色㿠白，气短乏力，自汗，患肢麻木肿胀，舌淡暗有瘀斑、苔薄白，脉细涩\n    治法：益气活血、化瘀通络\n    方剂：补阳还五汤\n\n二、风痰阻络\n    症状舌脉：半身不遂，口舌歪斜，舌强言謇或不语，头晕目眩，痰多，舌淡胖苔白腻，脉弦滑\n    治法：搜风化痰、通络开窍\n    方剂：解语丹合半夏白术天麻汤\n\n三、肝阳上亢\n    症状舌脉：半身不遂，患侧僵硬拘挛，头痛头晕，面红目赤，耳鸣，心烦易怒，口苦咽干，舌红苔黄，脉弦有力\n    治法：平肝潜阳、息风通络\n    方剂：天麻钩藤饮\n\n四、阴虚风动\n    症状舌脉：半身不遂，肢体麻木，手足心热，烦躁失眠，眩晕耳鸣，腰膝酸软，舌红少苔，脉弦细数\n    治法：滋阴潜阳、息风通络\n    方剂：镇肝熄风汤\n\n五、痰热腑实\n    症状舌脉：半身不遂，口舌歪斜，腹胀便秘，痰多色黄，头晕痰鸣，心烦不寐，舌红苔黄腻，脉弦滑而数\n    治法：通腑泄热、化痰通络\n    方剂：星蒌承气汤\n\n【方剂参考】\n  补阳还五汤：组成 黄芪120g、当归尾6g、赤芍4.5g、地龙3g、川芎3g、桃仁3g、红花3g；功效 补气，活血，通络\n      用法：水煎温服，日二次；黄芪宜由小量（30-60g）渐增至120g，久服方效（连服1-3个月）。\n      注意：中风急性期（出血性、血压极高）及阴虚阳亢、痰热壅盛者不宜；孕妇忌用；须待血压稳定后使用。\n  半夏白术天麻汤：组成 半夏9g、天麻6g、茯苓6g、橘红6g、白术15g、甘草3g、生姜1片、大枣2枚；功效 化痰熄风，健脾祛湿\n      用法：加生姜1片、大枣2枚，水煎温服，日二次，食后服。\n      注意：肝阳上亢、肝肾阴虚之眩晕（舌红少苔、脉弦细数）忌用；孕妇慎用半夏；眩晕剧烈须排除脑血管病变。\n  天麻钩藤饮：组成 天麻9g、钩藤12g、石决明18g、栀子9g、黄芩9g、川牛膝12g、杜仲9g、益母草9g、桑寄生9g、夜交藤9g、朱茯神9g；功效 平肝熄风，清热活血，补益肝肾\n      用法：水煎温服，日一剂分二次；石决明先煎，钩藤后下（不宜久煎，以免有效成分破坏）。\n      注意：纯阴虚风动而无肝阳上亢者不宜单用；低血压、孕妇及脾胃虚寒者慎用；须监测血压。\n  镇肝熄风汤：组成 怀牛膝30g、生赭石30g、生龙骨15g、生牡蛎15g、生龟甲15g、生杭芍15g、玄参15g、天冬15g、川楝子6g、生麦芽6g、茵陈6g、甘草4.5g；功效 镇肝熄风，滋阴潜阳\n      用法：水煎温服，日一剂分二次；龙骨、牡蛎、龟甲、代赭石先煎，川楝子后下；心中热甚者加生石膏。\n      注意：气虚血瘀之中风（补阳还五汤证）及孕妇忌用；方中重镇潜降，脾胃虚弱、痰湿壅盛者慎用；须确属肝阳上亢方可用。\n  星蒌承气汤：组成 全瓜蒌24g、胆南星9g、生大黄9g（后下）、芒硝9g（冲服）；功效 清热化痰，通腑泄热\n      用法：水煎，生大黄后下，芒硝冲服，温服或鼻饲，日一剂，分二次服；得泻即止。\n      注意：⚠ 本方为中风急性期急救用方，须在医师指导下使用，不可自行服用；孕妇禁用；脾胃虚寒、无腑实者忌用；有出血倾向（脑出血急性期）者须由医师权衡；大黄、芒硝峻下，得泻即止，不可久服。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·泻下剂（寒下）；原方为现代临床经验方（《中医内科学》教材收载）\n\n【西医诊断】\n  脑梗死（恢复期）\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"I64","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2257,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"04bd3610a60f410e8f9a3fccfb4a40c886b9fe7fd8d0d3af698a52bc7229dd17","pinyin":"zhongfeng(zhongyibianzheng)","initials":"zf(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","I64",30]]},{"id":"templates-dd53c6142a64ade12703","key":"v1-c9ccc21dfe2a3058|templates-dd53c6142a64ade12703","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"丹毒(中医辨证)","category":"中医","raw":{"name":"丹毒(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】风热火毒（头面）：发于头面部，皮肤焮红灼热，肿胀疼痛，甚则眼睑肿胀难睁，伴恶寒发热，舌红苔薄黄，脉浮数、肝脾湿火（胁腹）：发于胸腹腰胁，红肿蔓延，灼热疼痛，口苦咽干，舌红苔黄腻，脉弦滑数、湿热化火（下肢）：发于小腿足部，红肿灼热，痛如火烧，常反复发作，可形成大脚风（象皮腿），舌红苔黄腻，脉滑数。\n【待人工确认·本机素材无此段原文】","现病史":"丹毒是皮肤突然发红、色如涂丹、迅速蔓延的急性感染性疾病，多发于小腿及头面部。分风热火毒、肝脾湿火、湿热化火等证型。可见于溶血性链球菌感染。\n常见表现：风热火毒（头面）：发于头面部，皮肤焮红灼热，肿胀疼痛，甚则眼睑肿胀难睁，伴恶寒发热，舌红苔薄黄，脉浮数、肝脾湿火（胁腹）：发于胸腹腰胁，红肿蔓延，灼热疼痛，口苦咽干，舌红苔黄腻，脉弦滑数、湿热化火（下肢）：发于小腿足部，红肿灼热，痛如火烧，常反复发作，可形成大脚风（象皮腿），舌红苔黄腻，脉滑数。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者皮肤突然片状红斑、色如涂丹、边界清楚、灼热疼痛且蔓延迅速，结合溶血性链球菌感染的病因特点，入院即刻完善血常规检查，了解白细胞及中性粒细胞升高程度，明确感染严重程度并排除中性粒细胞减少；查血沉及CRP，评估炎症反应强度，动态监测疗效并指导抗感染疗程；对发热、寒战明显者，于抗菌药物使用前完善血培养及药敏试验，明确致病菌，指导目标性抗感染治疗；因下肢丹毒常由足癣、趾间皮肤破损继发，且反复发作可形成象皮腿，完善下肢静脉超声检查，明确有无下肢静脉功能不全、深静脉血栓及静脉曲张，排除静脉回流障碍所致肿胀；对反复发作的下肢丹毒，查空腹血糖及糖化血红蛋白，排除糖尿病所致皮肤感染易感性；完善肝肾功能及血电解质检查，排除肝肾功能不全并评估用药安全性；对头面部丹毒伴眼睑肿胀难睁者，完善眼眶CT检查，排除眶蜂窝织炎、海绵窦血栓形成等严重并发症；对红肿蔓延迅速、疑似坏死性筋膜炎者，完善皮肤软组织超声或MRI检查，明确有无深部脓肿及筋膜受累，必要时行皮肤活检以鉴别接触性皮炎、蜂窝织炎等；查心电图，评估心肺基础状况；患肢抬高并定期测量周径，动态评估疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 皮肤片状红斑，色如涂丹，边界清楚，灼热疼痛，蔓延迅速\n2. 血常规（白细胞升高）、血沉、CRP\n3. 反复发作的下肢丹毒需排查足癣、静脉功能不全\n1. 丹毒(中医辨证)（ICD-10：A46）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1：六神丸10粒 tid，或牛黄解毒片3片 tid\n药物2（配合）：青霉素V钾0.5g tid（无过敏时，遵医嘱），或头孢呋辛0.5g bid\n药物3（外治）：金黄散调敷，或鲜马齿苋捣敷\n\n【治疗】\n风热火毒：疏风清热解毒，普济消毒饮加减\n肝脾湿火：清肝泻火，利湿解毒，龙胆泻肝汤加减\n湿热化火：清热利湿，解毒消肿，五神汤合萆薢渗湿汤加减\n\n【处理要点】\n卧床休息，抬高患肢\n局部用硫酸镁湿敷\n积极治疗足癣、皮肤破损等诱因\n\n【护理】\n病情观察：密切监测体温变化，观察患处红肿范围、边界及灼热程度，注意有无水疱、大疱或皮肤坏死；若见高热不退、烦躁不安、神昏谵语，为毒热内陷之候，立即报告医生并配合抢救。\n外治护理：红肿期用金黄散或玉露散以凉开水调敷患处，保持药层湿润，每日1～2次；水疱未破者勿自行挑破，破溃后予无菌换药；下肢丹毒宜抬高患肢30°，以利静脉回流、减轻肿胀。\n起居调护：急性期卧床休息、减少走动，避免劳累耗伤正气；保持皮肤清洁干燥，防止搔抓破损继发感染；衣裤床单宜柔软透气，避免摩擦患处；注意消毒隔离，防止接触传染。\n情志护理：本病易反复发作、病程缠绵，患者多烦躁焦虑，应耐心解释病情与转归，疏导情志，嘱其戒怒，避免肝郁化火、助长火毒而加重病情。\n煎药服药护理：清热解毒凉血之剂宜温凉分次频服；外敷药物注意观察局部有无过敏、瘙痒；下肢反复发作者，嘱其积极治疗足癣、脚湿气等原发病灶，防止复发。\n\n【饮食】\n忌口：忌食辛辣刺激（辣椒、葱蒜、韭菜、芥末）、肥甘厚味（油炸、肥肉、甜腻之品）、鱼虾蟹等海鲜发物及酒类，以免助热生火、助湿酿毒，加重病情。\n适宜食物：宜清淡凉性之品，如冬瓜、丝瓜、黄瓜、苦瓜、芹菜、绿豆、赤小豆、薏苡仁等，以助清热、利湿、解毒。\n多饮汤水：鼓励多饮温开水或淡绿茶，每日1500～2000ml，使毒邪从小便而解；可常饮绿豆汤、金银花茶、菊花茶以清热泻火。\n药膳食疗：湿热毒蕴者可用赤小豆薏苡仁粥（赤小豆、薏苡仁各30g，加粳米适量煮粥）；红肿灼热明显者可用马齿苋煎水代茶饮或凉拌佐餐，以清热解毒。\n调摄原则：进食规律、少食多餐；发热期间宜进绿豆粥、荷叶粥等半流质饮食；平素脾胃虚弱者不宜过食生冷寒凉，以免败伤胃气。\n\n【注意事项】\n丹毒蔓延迅速或伴高热寒战者住院治疗\n头面丹毒警惕颅内感染\n反复发作者防象皮腿，穿弹力袜\n\n【急诊/急救】\n一般不需急救\n脓毒血症/高热寒战/神志改变：立即急诊\n疔疮走黄（火毒内陷）为危候，立即转院","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】丹毒\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、风热毒蕴（发于头面部）\n    症状舌脉：皮肤焮红灼热，肿胀疼痛，甚则发生水疱，眼胞肿胀难睁，伴恶寒发热，头痛，舌质红、苔薄黄，脉浮数\n    治法：疏风清热解毒\n    方剂：普济消毒饮\n\n二、肝脾湿火（发于胸腹腰胯部）\n    症状舌脉：皮肤红肿蔓延，摸之灼手，肿胀疼痛，伴口苦口干，胸闷纳呆，舌红、苔黄腻，脉弦滑数\n    治法：清肝泻火利湿\n    方剂：柴胡清肝汤\n\n三、湿热毒蕴（发于下肢）\n    症状舌脉：皮肤红赤肿胀，灼热疼痛，或见水疱、紫斑，甚至结毒化脓或皮肤坏死，伴发热，胃纳不香，舌红、苔黄腻，脉滑数\n    治法：利湿清热解毒\n    方剂：五神汤合萆薢渗湿汤\n\n四、胎火蕴毒（发于新生儿）\n    症状舌脉：多见于新生儿臀部，局部红肿灼热，常呈游走性，伴壮热烦躁，甚则神昏谵语，恶心呕吐\n    治法：凉血清热解毒\n    方剂：犀角地黄汤合黄连解毒汤（现代以水牛角代犀角）。来源：《中医外科学》（中国中医药出版社“十四五”规划教材）·疮疡·丹毒\n\n【方剂参考】\n  普济消毒饮：组成 黄芩15g、黄连15g、连翘3g、薄荷3g、马勃3g、牛蒡子3g、玄参6g、僵蚕2g、升麻2g、柴胡6g、桔梗6g、甘草6g、板蓝根3g、陈皮6g；功效 清热解毒，疏风散邪\n      用法：上药为末，每次15g，水煎，食后徐徐温服（或含漱后咽下）；亦可作汤剂，日二次。\n      注意：虚寒体质及脾胃虚弱者慎用；孕妇慎用；本方苦寒，中病即止。（本方黄连15g、黄芩15g超《中国药典》2020年版一部用量，系教材原方折算，临床宜酌减）\n  萆薢渗湿汤：组成 萆薢12g、薏苡仁15g、黄柏9g、赤茯苓12g、牡丹皮9g、泽泻9g、滑石15g（包煎）、通草6g；功效 清热利湿，分清别浊\n      用法：水煎，滑石包煎，温服，日一剂，分二次服。\n      注意：脾肾虚寒、阴虚者不宜；须配合局部处理；孕妇慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛湿剂（清热祛湿）；原方出自《疡科心得集·补遗》\n  黄连解毒汤：组成 黄连9g、黄芩6g、黄柏6g、栀子9g；功效 泻火解毒\n      用法：水煎温服，日二至三次；亦可为末制水丸，每次6g，温开水送服。\n      注意：苦寒伤胃，脾胃虚寒、阴虚火旺及非火毒炽盛者忌用；孕妇慎用；不宜久服，中病即止。\n\n【西医诊断】\n  丹毒（皮肤及皮下组织感染）\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"A46","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2258,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"22be541600c6baf112b2d7150dfcc6d3d2b25a38fad455a05aa2fb90e227f929","pinyin":"dandu(zhongyibianzheng)","initials":"dd(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","A46",30]]},{"id":"templates-3568fddcdfb363adf8a1","key":"v1-c9ccc21dfe2a3058|templates-3568fddcdfb363adf8a1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉夹层(内科)","category":"心血管系统临床路径（2019年版）","raw":{"name":"主动脉夹层(内科)","category":"心血管系统临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【卫健委临床路径原文】（1）突发的持续剧烈疼痛，呈刀割或者撕裂样，向前胸和背部放射，亦可以延伸至腹部、腰部、下肢和颈部。\r（2）有夹层累及主动脉及主要分支的临床表现和体征，如四肢特别是双上肢血压不对称。\r2.辅助检查：\r（1）CTA、MRA或组织多普勒超声证实主动脉夹层。\r（2）多数患者的红细胞沉降率、C反应蛋白、D。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：（1）突发的持续剧烈疼痛，呈刀割或者撕裂样，向前胸和背部放射，亦可以延伸至腹部、腰部、下肢和颈部。\r（2）有夹层累及主动脉及主要分支的临床表现和体征，如四肢特别是双上肢血压不对称。\r2.辅助检查：\r（1）CTA、MRA或组织多普勒超声证实主动脉夹层。\r（2）多数患者的红细胞沉降率、C反应蛋白、D。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者突发持续剧烈疼痛，呈刀割或撕裂样，向前胸和背部放射，并延伸至腹部、腰部、下肢及颈部，且双上肢血压不对称，为在最短时间内明确有无主动脉夹层，入院即刻或急诊完成主动脉CTA检查；若患者因肾功能不全或碘对比剂过敏不宜行CTA，查主动脉MRA以明确夹层范围及分支血管受累情况；同步行床旁超声心动图及多普勒超声检查，了解主动脉根部、升主动脉以及有无心包积液和主动脉瓣反流，为急诊手术决策提供依据；患者剧烈疼痛与夹层本身均可造成心肌损伤，查心肌酶及肌钙蛋白以排除急性心肌梗死；夹层累及冠状动脉或心包时可出现心电图动态演变，查心电图以鉴别急性冠脉综合征并观察有无动态演变；查D-二聚体以了解纤溶激活程度，其明显升高支持夹层诊断、明显正常有助于排除；查红细胞沉降率与C反应蛋白以了解血管壁炎性反应程度，并用于与其他大动脉炎性病变鉴别；完善血常规以排除感染、贫血及失血所致血流动力学不稳定；急诊手术与强化降压治疗均需以脏器功能与内环境为基础，完善肝肾功能、电解质及凝血功能检查，评估肝肾代谢与凝血状态、指导降压与抗凝方案；同时查血型并备血，为可能急诊手术做好准备。\n\n（检查清单）\n【临床路径·住院期间检查项目】\n住院期间检查项目\r1.","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n心血管分册》（中华医学会编著，人民卫生出版社，2009年）、《主动脉疾病诊治指南》（欧洲心脏病学会年会ESC，2014年）\r1.临床表现：\r（1）突发的持续剧烈疼痛，呈刀割或者撕裂样，向前胸和背部放射，亦可以延伸至腹部、腰部、下肢和颈部。\r（2）有夹层累及主动脉及主要分支的临床表现和体征，如四肢特别是双上肢血压不对称。\r2.辅助检查：\r（1）CTA、MRA或组织多普勒超声证实主动脉夹层。\r（2）多数患者的红细胞沉降率、C反应蛋白、D\n二聚体明显升高。\r（三）\n1. 主动脉夹层(内科)","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n心血管分册》（中华医学会编著，人民卫生出版社，2009年）、《主动脉疾病诊治指南》（欧洲心脏病学会年会ESC，2014年）。\r处理原则：本临床路径主要针对主动脉夹层的高血压危象内科治疗部分。一旦确诊本病，应当立即开始内科处理。根据影像学结果，对患者Debakey\n型和\n型夹层患者，为防止夹层恶化和破裂，应当尽早外科手术治疗。对Debakey\n型患者，如病情稳定，不伴有并发症，可选择内科综合治疗。\r1.控制疼痛：可选用吗啡、杜冷丁和镇静剂等，镇痛有助于控制血压和心率。根据疼痛控制情况，可每6～8小时重复使用1次。缺点是有可能成瘾。疼痛剧烈的患者，可采用镇痛泵。\r2. 2.尽快控制血压和心率至可耐受的低限，二者同步进行：\n1受体阻滞剂和血管扩张剂联合患者。首先选用静脉给药路径：硝普钠（或乌拉地尔）加美托洛尔（或艾司洛尔）等，快速（10分钟内）将血压降至120/90mmHg以下，心率至70次/分以下；若病情允许，患者能耐受，逐渐调整剂量，将血压和心率降至100/70mmHg和50次/分左右。稳定后，可逐步改用口服降压药物，如在\n受体阻滞剂和（或）非二氢吡啶类钙通道阻滞剂的基础上，加用二氢吡啶类钙通道阻滞剂、ARB、ACEI、利尿剂等。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD－10:I71.0主动脉夹层疾病编码。\r2. 如患有其他疾病，但在住院期间不需特殊处理（检查和治疗），也不影响第一诊断时，可以进入路径。\r（六）","临床路径·标准住院日":"标准住院日为5～7天\r（五）","临床路径·出院标准":"出院标准\r1.疼痛明显缓解或消失，口服降压药物血压降至100～120/60～80mmHg，心率控制在50～70次/分。\r2.红细胞沉降率、C反应蛋白明显下降或恢复正常。\r3.没有急诊或近期进行外科手术或腔内介入治疗的指征。\r（九）","临床路径·变异及原因分析":"变异及原因分析\r1.病情不稳定，夹层进展。\r2.合并严重并发症。\r3.需要外科手术或介入治疗。\r\f二、主动脉夹层","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管系统临床路径（2019年版） · 主动脉夹层（内科）临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2259,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5fd26459c7ad451ae3dd03ab01e959b0f03eb0b9c7667880a52657c045b8a7b2","pinyin":"zhudongmaijiaceng(neike)","initials":"zdmjc(nk)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-2deb2ab89d76f431aff0","key":"v1-c9ccc21dfe2a3058|templates-2deb2ab89d76f431aff0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉夹层(急诊识别与处理)","category":"血管外科","raw":{"name":"主动脉夹层(急诊识别与处理)","category":"血管外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】突发前胸、后背或腹部剧烈撕裂样/刀割样疼痛，向腰背部或下肢放射，镇痛药难以缓解、双上肢血压差异>20mmHg 或脉搏不对称（重要体征）、高血压或低血压/休克（提示心包填塞、主动脉破裂）、脏器缺血表现：脑缺血（晕厥、偏瘫）、脊髓缺血（截瘫）、肾缺血（少尿、无尿）、肠缺血（剧烈腹痛）、下肢缺血（肢体凉、麻、无脉）、主动脉瓣关闭不全杂音（A型夹层）、心包摩擦音或颈静脉怒张（心包填塞）。\n【待人工确认·本机素材无此段原文】","现病史":"主动脉夹层是主动脉内膜撕裂后血液进入中膜形成假腔，并沿主动脉纵轴延伸的危重急症，48小时内病死率极高。典型表现为突发剧烈撕裂样胸背痛，可伴血压差异、脏器缺血（脑、肾、肠、下肢）。Stanford A型（累及升主动脉）需急诊手术，B型多先内科保守或腔内治疗。\n常见表现：突发前胸、后背或腹部剧烈撕裂样/刀割样疼痛，向腰背部或下肢放射，镇痛药难以缓解、双上肢血压差异>20mmHg 或脉搏不对称（重要体征）、高血压或低血压/休克（提示心包填塞、主动脉破裂）、脏器缺血表现：脑缺血（晕厥、偏瘫）、脊髓缺血（截瘫）、肾缺血（少尿、无尿）、肠缺血（剧烈腹痛）、下肢缺血（肢体凉、麻、无脉）、主动脉瓣关闭不全杂音（A型夹层）、心包摩擦音或颈静脉怒张（心包填塞）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：四肢血压（双侧对比，差异>20mmHg有意义）、心率、呼吸、血氧\n一般情况：痛苦面容、烦躁、意识状态（脑缺血）、皮肤湿冷（休克）\n心脏：心界、心率心律、主动脉瓣区舒张期杂音（反流）、心音遥远与颈静脉怒张（心包填塞）\n血管：颈动脉、桡动脉、股动脉、足背动脉搏动（双侧对比），有无搏动消失与血管杂音\n神经系统：意识、瞳孔、肢体肌力（脑缺血/截瘫评估）、脊髓缺血平面\n腹部：压痛、肠鸣音（肠缺血可减弱）、有无腹块（动脉瘤）\n四肢：皮温、颜色、毛细血管充盈、下肢缺血表现","辅助检查":"1. 主动脉CTA（首选）：明确分型、范围、真假腔、分支受累与心包积液\n2. 床旁超声心动图：评估升主动脉、心包积液与主动脉瓣反流（A型筛查）\n3. D-二聚体：显著升高支持诊断，阴性有助排除（低危患者）\n4. 血常规+凝血功能+血型+交叉配血：术前准备与凝血评估\n5. 心肌酶（肌钙蛋白）+心电图：与急性心肌梗死鉴别（夹层可累及冠脉）\n6. 肝肾功能+乳酸+血气分析：评估脏器缺血与灌注\n7. 尿量+尿常规：肾缺血评估（少尿提示肾受累）","初步诊断":"1. 主动脉CTA（首选）：明确分型、范围、真假腔、分支受累与有无心包积液\n2. 床旁超声心动图：评估升主动脉、心包积液、主动脉瓣反流（A型夹层快速筛查）\n3. 胸部X线：纵隔增宽（敏感性低，不能排除）\n4. 心电图：排除急性心肌梗死（夹层可累及冠脉致心电图改变）\n5. D-二聚体：显著升高（>5000ng/ml高度提示），阴性有助排除\n6. 血常规+凝血+肝肾功能+心肌酶+乳酸：评估器官缺血与凝血状态\n7. 双上肢与双下肢血压、脉搏对比：诊断重要线索（首次接触即应测量）\n1. 主动脉夹层(急诊识别与处理)（ICD-10：I71.0）","鉴别诊断":"1. 胸部X线：纵隔增宽（敏感性低，不能排除）\n2. 心电图：排除急性心肌梗死（夹层可累及冠脉致心电图改变）\n3. D-二聚体：显著升高（>5000ng/ml高度提示），阴性有助排除\n4. 夹层禁用抗凝、抗血小板与溶栓药物（与急性心肌梗死处理截然不同，需仔细鉴别）","处理方案":"【药物治疗·输液】\n⚠️ 抢救用药，患者监护下严格控制！\n\n方案1（控制心率与血压，首要）：\n 用法：艾司洛尔 负荷0.5mg/kg 静推后 50～200μg/kg/min 泵入（目标心率60次/分以下）；乌拉地尔 12.5～25mg 静推后 100～400μg/min 泵入（目标收缩压100～120mmHg）\n\n方案2（镇痛）：\n 用法：吗啡 3～5mg 静推（必要时重复）；或芬太尼 0.05mg 静推（充分镇痛可降低交感兴奋与血压）\n\n方案3（休克/心包填塞）：\n 用法：谨慎补液（避免加重心包填塞）；去甲肾上腺素 0.05～0.5μg/kg/min 泵入维持重要脏器灌注；立即心外科会诊\n\n方案4（A型夹层术前准备）：\n 用法：0.9%氯化钠 静滴；备血、备皮，紧急手术准备\n\n📌 目标：心率<60次/分、收缩压100～120mmHg（保证脏器灌注的最低有效血压）；禁用抗凝、溶栓与抗血小板药物。\n\n【药物治疗·口服】\n⚠️ 急性期以静脉用药为主；稳定期与出院后长期用药：\n\n药物1（β受体阻滞剂，长期首选）：\n 用法：美托洛尔缓释片 23.75～47.5mg qd 或 比索洛尔 2.5～5mg qd（目标静息心率55～60次/分）\n\n药物2（降压，联合）：\n 用法：缬沙坦 80mg qd 或 氨氯地平 5mg qd（目标血压<130/80mmHg）\n\n药物3（镇痛与通便，防血压波动）：\n 用法：对乙酰氨基酚 0.5g 必要时；乳果糖 15ml bid（避免用力排便升高血压）\n\n药物4（他汀，稳定斑块）：\n 用法：阿托伐他汀 20mg qn\n\n📌 夹层患者需终身严格控制血压与心率，血压波动是再发夹层与动脉瘤破裂的重要诱因。\n\n【治疗】\nA型（累及升主动脉）：确诊后立即急诊外科手术（升主动脉替换±全弓置换+支架象鼻术），术前严格控制心率血压与镇痛\nB型（不累及升主动脉）：首选内科保守（控制心率血压、镇痛），出现并发症（破裂、脏器缺血、持续疼痛、血压难控）行腔内支架修复（TEVAR）或开放手术\n强化内科治疗：β受体阻滞剂+血管扩张剂控制心率（<60次/分）与血压（100～120mmHg），充分镇痛，绝对卧床\n并发症处理：心包填塞（急诊手术/心包穿刺）、急性主动脉瓣反流（手术）、脏器缺血（血管重建或腔内治疗）、截瘫（脑脊液引流）\n长期随访：定期CTA（术后1、3、6、12个月，之后每年），监测残余夹层、动脉瘤样扩张与再发夹层\n危险因素控制：严格控制血压（<130/80mmHg）、心率、血脂，戒烟，避免剧烈运动与重体力劳动\n遗传性结缔组织病筛查（马凡综合征等）：家族史者行基因与家系筛查\n\n【处理要点】\n绝对卧床、住ICU监护：持续心电、血压（有创动脉压更佳）、血氧监护，避免一切增加腹压与血压的活动\n疼痛管理：使用吗啡等强效镇痛药，评估疼痛评分，疼痛加剧提示夹层进展或破裂\n血压心率控制：按医嘱调整泵入药物剂量，记录每小时尿量（>0.5ml/kg/h）\n禁止用力：避免用力排便（用缓泻剂）、剧烈咳嗽与搬动；翻身时保持躯干平直\n脏器缺血监测：意识、肢体脉搏与皮温、尿量、腹痛与肠鸣音（肠缺血）、神经功能（截瘫）\n术前准备（A型）：迅速完成备血、备皮、禁食、家属沟通与手术同意签署\n术后管理：监测血压、引流量、神经功能与肾功能；控制心率血压、镇痛、预防感染\n\n【护理】\n绝对卧床与监护：住ICU，持续心电血压监护，避免一切用力（翻身平直、禁止下床）\n疼痛观察与镇痛：评估疼痛部位、性质与程度，按医嘱给予镇痛药并观察效果（疼痛加剧需立即报告）\n血压心率管理：遵医嘱精确调整泵入药物速度，记录每小时血压、心率与尿量\n心理安抚：剧烈疼痛与濒死感致极度恐惧，需语言安抚、解释治疗、保持环境安静\n术前准备（A型）：快速禁食、备皮、备血、留置尿管，配合完成知情同意\n并发症观察：意识改变、肢体脉搏消失、尿量减少、腹痛加剧（脏器缺血）；颈静脉怒张（心包填塞）\n\n【饮食】\n急性期禁食禁水（可能急诊手术）\n病情稳定后：低盐（<5g/日，血压控制要点）、低脂、易消化软食\n保持大便通畅：多饮水、多食蔬菜水果与粗纤维，必要时用缓泻剂（避免用力排便）\n避免浓茶、咖啡、酒精与辛辣刺激（防止血压心率波动）\n长期：控制体重、戒烟、限酒，规律服药，避免暴饮暴食\n\n【注意事项】\n急性主动脉夹层是致命急症，A型48小时内病死率可达50%，确诊后必须争分夺秒手术\n双上肢血压差异>20mmHg是重要线索，接诊胸背痛患者应常规测量四肢血压\n夹层禁用抗凝、抗血小板与溶栓药物（与急性心肌梗死处理截然不同，需仔细鉴别）\n充分镇痛与控制心率血压（而非单纯降压）是急性期最重要的内科措施\n长期严格控制血压与心率（<130/80mmHg、静息心率55～60次/分）是预防再发的关键\n\n【急诊/急救】\n突发撕裂样胸背痛伴血压差异、脉搏不对称（疑似夹层）→ 立即控制心率血压、镇痛、急查CTA\n心包填塞表现（颈静脉怒张、心音遥远、血压下降）→ 立即心外科急诊手术/心包穿刺\n下肢急性缺血（凉、麻、无脉）、少尿无尿（肾缺血）、剧烈腹痛（肠缺血）→ 急诊评估血管重建\n意识障碍、偏瘫（脑缺血）→ 立即评估并保护气道","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「主动脉夹层（急诊识别与处理）」原文）"},"icd10_diagnosis":"I71.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2260,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8bf9a6fb06ee34624a50fb254d88dcbb32ca1bf7a734e187294e2825eb8afcdd","pinyin":"zhudongmaijiaceng(jizhenshibieyuchuli)","initials":"zdmjc(jzsbycl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I71.0",30]]},{"id":"templates-b1a3b88006b942aca016","key":"v1-c9ccc21dfe2a3058|templates-b1a3b88006b942aca016","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉瓣病变人工机械瓣置换术","category":"心血管外科临床路径（2019年版）","raw":{"name":"主动脉瓣病变人工机械瓣置换术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\n（1）血常规、尿常规、大便常规。\n（2）肝功能、肾功能，血电解质，血型、凝血功能，风湿活动筛查、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）。\n（3）心电图、胸部X线平片、超声心动图、多排CT胸部平扫。\n2.根据患者具体情况可选择的检查项目：如心肌酶、免疫学检查（怀疑白塞综合征等）、24小时动态心电图、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、血气分析和肺功能检查（高龄或既往有肺部病史者）、外周血管超声检查等。\n（六）预防性抗菌药物选择与使用时机\n按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者病情决定抗菌药物的选择与使用时间。\n（七）手术日为入院2～8天\n1.麻醉方式：全身麻醉。\n2.体外循环辅助。\n3.手术切口：常规胸骨正中切口或胸骨上段小切口等无需特殊设备的微创切口。\n4.手术植入物：人工机械瓣、胸骨固定钢丝等。\n5.手术操作\n（1）升主动脉切口，切除病变瓣膜。\n（2）经测量选择合适大小瓣膜，间断缝合或连续缝合植入瓣膜。\n（3）直视下测试瓣膜启闭功能，缝合升主动脉切口。\n（4）常规放置心外膜临时起搏导线。\n6.术中用药：麻醉及体外循环常规用药。\n7.输血及血液制品：视术中情况而定。\n8.术中经食管超声（TEE）\n（1）手术前TEE进一步明确病变情况、心脏功能等。\n（2）手术后TEE指导心脏排气，监测有无瓣周漏、瓣膜功能及心脏功能等。\n（八）术后住院恢复6～17天\n1.术后转监护病房，持续监测治疗。\n2.患者清醒后早期拔出气管插管。\n3.病情平稳后转回普通病房。\n2.必须复查的检查项目：血常规、血电解质、血糖、肝肾功能、抗凝监测、心电图、胸部X线平片，超声心动图。\n3.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\n4.抗血小板治疗。\n5.抗凝：根据所测INR值调整抗凝药用量，终身抗凝治疗。\n6.根据病情需要可能进行强心、利尿等治疗。\n（九）","初步诊断":"1. 主动脉瓣病变人工机械瓣置换术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","临床路径·进入路径标准":"进入路径标准\n第一次接受单纯主动脉瓣位人工机械瓣置换术（北京版RC022-ICD-9:35.22）。\n（五）术前准备\n7天\n1.","临床路径·标准住院日":"标准住院日一般\n18天\n（四）","临床路径·出院标准":"出院标准\n1.体温正常，血常规、电解质无明显异常。\n2.引流管拔除、切口愈合良好，无感染。\n3.无需要住院处理的并发症和（或）其他合并症。\n4.抗凝基本稳定。\n5.胸部X线平片未见气胸、积液或肺部感染等。\n6.心电图无完全性房室传导阻滞或其他严重心律失常。\n7.超声心动图证实人工机械瓣功能良好，无瓣周漏、心包积液等相关并发症。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.围术期并发症：主动脉根部出血、人工瓣功能障碍、心功能不全、瓣周漏、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\n2.合并有其他系统疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\n3.术前心功能及其他重要脏器功能不全需调整，特殊原因（如稀有血型短缺等）造成的住院时间延长费用增加等。\n4.医师认可的其他变异原因。","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 主动脉瓣病变人工机械瓣置换术临床路径（2019年版）.docx"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2261,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2668f93d17e88d45d0ca7758051d9e0a9ff6b6d3fb0fde46eff965b77a71b6e3","pinyin":"zhudongmaibanbingbianrengongjixiebanzhihuanshu","initials":"zdmbbbrgjxbzhs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-13f789748f7608b4b754","key":"v1-c9ccc21dfe2a3058|templates-13f789748f7608b4b754","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉瓣病变人工生物瓣置换术","category":"心血管外科临床路径（2019年版）","raw":{"name":"主动脉瓣病变人工生物瓣置换术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规、大便常规。\r（2）肝功能、肾功能，血电解质，血型、凝血功能，风湿活动筛查、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）。\r（3）心电图、胸部X线平片、超声心动图、多排CT胸部平扫。\r2.根据患者具体情况可选择的检查项目：如心肌酶、免疫学检查（怀疑白塞综合征等）、24小时动态心电图、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、血气分析和肺功能检查（高龄或既往有肺部病史者）、外周血管超声检查等。\r（六）预防性抗菌药物选择与使用时机\r按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者病情决定抗菌药物的选择与使用时间。\r（七）手术日为入院2～8天\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术切口：常规胸骨正中切口或胸骨上段小切口等无需特殊设备的微创切口。\r4.手术植入物：人工生物瓣、胸骨固定钢丝等。\r5.手术操作\r（1）升主动脉切口，切除病变瓣膜。\r（2）经测量选择合适大小瓣膜，间断缝合或连续缝合植入瓣膜。\r（3）直视下测试瓣膜启闭功能，缝合升主动脉切口。\r（4）常规放置心外膜临时起搏导线。\r6.术中用药：麻醉及体外循环常规用药。\r7.输血及血液制品：视术中情况而定。\r8.术中经食管超声（TEE）\r（1）手术前TEE进一步明确病变情况、心脏功能等。\r（2）手术后TEE指导心脏排气，监测有无瓣周漏、瓣膜功能及心脏功能等。\r（八）术后住院恢复6～17天\r1.术后转监护病房，持续监测治疗。\r2.患者清醒后早期拔出气管插管。\r3.病情平稳后转回普通病房\r2.必须复查的检查项目：血常规、血电解质、血糖、肝肾功能、抗凝监测、心电图、胸部X线平片，超声心动图。\r3.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r4.抗凝：根据所测INR值调整抗凝药用量，抗凝治疗3～6个月。\r5.根据病情需要可能进行强心、利尿等治疗。\r（十）","初步诊断":"1. 主动脉瓣病变人工生物瓣置换术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","临床路径·进入路径标准":"进入路径标准\r第一次接受单纯主动脉瓣位人工生物瓣置换术（北京版RC022-ICD-9:35.21）。\r（五）术前准备\n7天\r1.","临床路径·标准住院日":"标准住院日一般\n18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管拔除、切口愈合良好，无感染。\r3.没有需要住院处理的并发症和（或）其他合并症。\r4.抗凝基本稳定。\r5.胸部X线平片未见气胸、中到大量胸腔积液、心包积液或肺部感染等。\r6.心电图无完全性房室传导阻滞或其他严重心律失常。\r7.超声心动图证实人工机生物功能良好，无瓣周漏、心包积液等相关并发症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：主动脉根部出血、人工瓣功能障碍、心功能不全、瓣周漏、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\r2.合并有其他系统疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r3.术前心功能及其他重要脏器功能不全需调整，特殊原因（如稀有血型短缺等）造成的住院时间延长费用增加等。\r4.医师认可的其他变异原因。\r\f二、心脏主动脉瓣病变人工生物瓣置换术","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 主动脉瓣病变人工生物瓣置换术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2262,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1f8f36eab356e6772fcf9517c04266211b39bf54c2b4f73fba64288602541ce5","pinyin":"zhudongmaibanbingbianrengongshengwubanzhihuanshu","initials":"zdmbbbrgswbzhs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-73aa4ac92cd12524d757","key":"v1-c9ccc21dfe2a3058|templates-73aa4ac92cd12524d757","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉瓣置换及升主动脉置换术","category":"心血管外科临床路径（2019年版）","raw":{"name":"主动脉瓣置换及升主动脉置换术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\r（1）血常规、尿常规。\r（2）肝功能、肾功能、血电解质、血型、凝血功能，感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）。\r（3）心电图、胸部X线平片、超声心动图、CT或MRI。\r2.根据患者病情可选择的检查项目：如心肌酶、大便常规、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、血气分析和肺功能检查（高龄或既往有肺部病史者）、腹部及外周血管超声检查等。\r（七）预防性抗菌药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）","初步诊断":"1. 主动脉瓣置换及升主动脉置换术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·选择用药】\n选择用药。\r2.预防性用抗菌药物，时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时。\r（八）手术日第2～4天\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术植入物：人工瓣膜及人工血管、胸骨固定钢丝等。\r4. 手术操作\r（1）切除病变主动脉瓣，植入人工瓣膜替换。\r（2）切除病变升主动脉，植入人工血管替换。\r5.术中用药：麻醉及体外循环常规用药。\r6.输血及血液制品：视术中情况而定。\r（九）术后住院恢复9～14天\r1.术后转监护病房，持续监测治疗。\r2.术后患者清醒后早期拔除气管插管\r3.病情平稳后转回普通病房。\r4.必须复查的检查项目：血常规、血电解质＋肝肾功能＋血糖，X线胸片、心电图、超声心动图，CT或MRI。\r5.根据患者新发症状或常规检查项目异常结果，必要时可进行心肌酶、头颅CT或细菌培养等检查。\r6.抗菌药物使用：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r7.抗凝：根据所测INR值调整抗凝药用量，根据患者情况确定抗凝治疗方案。\r（十）","临床路径·进入路径标准":"进入路径标准\r接受主动脉瓣置换及升主动脉人工血管置换术ICD-9-CM-3:38.45，主动脉瓣置换伴升主动脉置换术[Wheat\ns手术](ICD-9-CM-3:35.2 1003)。 \r（六）术前准备1～3天\r1.","临床路径·标准住院日":"标准住院日11～18天\r（五）","临床路径·出院标准":"出院标准\r1.患者一般情况良好，体温正常，完成复查项目。\r2.切口愈合好：引流管拔除，伤口无感染。\r3.无需要住院处理的并发症，CT或MRI证实人工血管通畅。\r4.心脏超声证实瓣膜功能正常。\r（十一）出院医嘱\r1.出院带药：降压药，\n受体阻滞剂，他汀类药物等应按需带药。\r2.患者教育。\r（十二）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：心功能不全、出血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\r2.合并有其他系统疾病，可能出现合并疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r3.人工血管的选择：根据患者的病情，使用不同的人工血管，导致住院费用存在差异。\r4.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长费用增加。\r\f二、主动脉瓣置换及升主动脉置换术","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 主动脉瓣置换及升主动脉置换术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2263,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ef66a1741ce1e72c4fef2f10fec7b370b3ac921c440e81726425917a23e7d286","pinyin":"zhudongmaibanzhihuanjishengzhudongmaizhihuanshu","initials":"zdmbzhjszdmzhs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-1cb5ef1fe3e814f037a9","key":"v1-c9ccc21dfe2a3058|templates-1cb5ef1fe3e814f037a9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乐果中毒(有机磷)","category":"中毒/理化","raw":{"name":"乐果中毒(有机磷)","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】毒蕈碱样(M样)：瞳孔缩小、大汗、流涎、流泪、肺部湿啰音、呼吸困难、恶心呕吐、腹痛腹泻、大小便失禁、烟碱样(N样)：肌肉震颤、肌无力、肌痉挛、呼吸肌麻痹、中枢神经系统：头痛头晕、烦躁、谵妄、抽搐、昏迷、呼吸中枢抑制、口服者消化道症状明显、乐果中毒潜伏期较长（可延迟至数小时），症状重，持续时间长、重度中毒：昏迷、肺水肿、呼吸衰竭、脑水肿、乐果中毒易发生反跳（症状好转后突然加重）、中间综合征发生率较高。\n【待人工确认·本机素材无此段原文】","现病史":"乐果是中等毒类有机磷农药，口服/皮肤接触均可中毒。乐果在体内氧化为氧化乐果，毒性增强，且代谢慢，中毒后易反跳。阿托品+氯解磷定治疗，乐果对复能剂效果较差，以阿托品为主。\n常见表现：毒蕈碱样(M样)：瞳孔缩小、大汗、流涎、流泪、肺部湿啰音、呼吸困难、恶心呕吐、腹痛腹泻、大小便失禁、烟碱样(N样)：肌肉震颤、肌无力、肌痉挛、呼吸肌麻痹、中枢神经系统：头痛头晕、烦躁、谵妄、抽搐、昏迷、呼吸中枢抑制、口服者消化道症状明显、乐果中毒潜伏期较长（可延迟至数小时），症状重，持续时间长、重度中毒：昏迷、肺水肿、呼吸衰竭、脑水肿、乐果中毒易发生反跳（症状好转后突然加重）、中间综合征发生率较高。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 血清胆碱酯酶活力（全血ChE及红细胞AChE）——确诊与中毒分度核心指标，入院即刻查，2~4小时复查1次，动态监测至恢复正常\n2. 毒物检测：血、胃内容物有机磷定性定量检测（乐果原体及代谢物），洗胃后留取洗出液送检，明确中毒剂量\n3. 血气分析——入院即刻查，乐果中毒易致迟发性呼吸衰竭，病情变化时随时复查，监测低氧血症及代谢性酸中毒\n4. 血常规、肝肾功能、电解质、血糖——入院即刻查，乐果经肝代谢、肾排泄，动态复查肝肾功能及电解质（低钾低钠）\n5. 心电图——入院即刻查并动态复查，监测QT间期延长、各种心律失常\n6. 血、尿淀粉酶及脂肪酶——入院查基线，此后每日复查，监测急性胰腺炎并发症","初步诊断":"1. 乐果接触/服用史（黄色液体，有蒜臭味）\n2. 典型M样+N样+中枢症状\n3. 全血胆碱酯酶活力降低\n4. 呕吐物/呼吸道分泌物有蒜臭味\n5. 血/尿中可检出乐果及其代谢产物\n6. 阿托品试验阳性\n7. 乐果中毒潜伏期长，早期症状可能不典型\n1. 乐果中毒(有机磷)（ICD-10：T60.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：阿托品 首剂2-5mg静注（重度5-10mg），每10-30分钟重复至阿托品化，维持时间要长（至少5-7天）\n\n方案2：\n 用法：氯解磷定 首剂0.5-1g静注（重度1-2g），乐果对复能剂效果较差，可酌情使用\n\n方案3：\n 用法：复方氯解磷定注射液（解磷注射液）\n\n方案4：\n 用法：甘露醇 125ml静滴 q6-8h（脑水肿）\n\n方案5：\n 用法：地西泮 10-20mg静注（抽搐时）\n\n方案6：\n 用法：5%碳酸氢钠 静滴（酸中毒）\n\n方案7：\n 用法：呼吸兴奋剂（呼吸抑制时）\n\n方案8：\n 用法：营养心肌药物\n\n方案9：\n 用法：抗生素（防治肺部感染）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：阿托品片（维持阶段）\n\n药物2：\n 用法：氯解磷定（辅助）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即脱离现场，脱去污染衣物，肥皂水彻底清洗皮肤\n口服者：立即用清水/2%碳酸氢钠反复洗胃（乐果可用碱性液），直至洗出液清亮\n洗胃后活性炭吸附，硫酸钠导泻\n早期足量阿托品，快速阿托品化，维持时间要长（乐果易反跳）\n胆碱酯酶复能剂（乐果效果较差，可酌情使用）\n保持呼吸道通畅，吸氧，必要时机械通气\n对症支持：抗抽搐、降颅压、纠正酸中毒、防治感染\n重度中毒可行血液灌流\n严密观察7-10天，防止反跳和中间综合征\n乐果中毒反跳发生率高，阿托品减量要慢，维持时间要长\n\n【处理要点】\n口服者立即催吐，尽快送医洗胃\n皮肤接触者脱去衣物，肥皂水清洗\n保持呼吸道通畅，头偏向一侧\n乐果中毒潜伏期长，即使早期症状轻也要住院观察\n记录服用剂量、时间\n阿托品化判断同其他有机磷中毒\n乐果中毒易反跳，症状好转后不可过早停药\n中间综合征需立即机械通气\n至少观察7-10天\n\n【护理】\n洗胃护理：尽早彻底洗胃，用温清水或2%碳酸氢钠液（禁用热水、忌油脂类灌入），洗胃液量2~5万ml至洗出液澄清无味；洗胃时头偏向一侧、低压吸引防误吸，洗毕保留胃管行持续胃肠减压\n解毒剂观察：密切观察阿托品化（瞳孔散大、口干、皮肤干燥、心率增快、肺部啰音消失），准确记录阿托品每次用量及时间，防止阿托品过量中毒；氯解磷定静注后观察局部刺激及不良反应\n生命体征与气道管理：持续心电、血氧饱和度及呼吸监测，床旁备气管插管及呼吸机；重点观察呼吸频率、深度、神志变化，警惕中间综合征及病情反跳（好转后再加重），发现呼吸抑制立即报告医生\n并发症预防：观察有无腹痛、腹胀、恶心呕吐、血尿，警惕胰腺炎与肝肾功能损害；准确记录24h出入量，每日核对尿量\n\n【饮食】\n洗胃后暂禁食禁水4~6小时，确认无恶心呕吐、消化道出血后开始进食\n由流质（米汤、稀藕粉）逐步过渡到半流质、软食，少量多餐，循序渐进\n忌油脂及含脂食物（牛奶、豆浆、蛋类、动物脂肪、油炸食品）——乐果为脂溶性毒物，脂肪可促进其吸收，恢复期仍须避免高脂饮食\n忌辛辣、生冷及粗糙食物，避免刺激受损胃黏膜，防止再出血\n适量补充水分及电解质（口服补液或静脉输注葡萄糖盐水），尿少、肾功能异常时遵医嘱调整补液量\n\n【注意事项】\n乐果在体内氧化为氧化乐果，毒性增强数倍，且代谢慢\n乐果中毒潜伏期长，可延迟至数小时发病，早期症状可能不重\n乐果对胆碱酯酶复能剂效果较差，治疗以阿托品为主\n乐果中毒反跳发生率高，阿托品维持时间要长（至少5-7天），减量要慢\n乐果中毒中间综合征发生率较高，需警惕\n乐果中毒禁用高锰酸钾洗胃（会氧化增毒）\n重度中毒应尽早行血液灌流\n乐果中毒病死率较高，需严密监护\n\n【急诊/急救】\n立即脱离接触，肥皂水清洗皮肤\n口服者立即催吐，尽快清水/碳酸氢钠洗胃\n保持呼吸道通畅，吸氧\n阿托品2-5mg静注（重度5-10mg），重复至阿托品化\n氯解磷定0.5-1g静注\n抽搐者地西泮静注\n呼吸衰竭者机械通气","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T60.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2264,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1f5d82097cdfe376b2e61a539669121f611fe195e2df9f4684b211636d55b8e1","pinyin":"leguozhongdu(youjilin)","initials":"lgzd(yjl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T60.0",30]]},{"id":"templates-039f8f786fa4fb14a0b6","key":"v1-c9ccc21dfe2a3058|templates-039f8f786fa4fb14a0b6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乙二醇中毒","category":"中毒/理化","raw":{"name":"乙二醇中毒","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】第一阶段（摄入后0.5-12小时）中枢神经系统：神志清楚，言语流利，高级智能活动正常。双侧瞳孔等大等圆，对光反射灵敏，眼球运动各方向到位，无眼震。四肢肌力5级，肌张力正常，腱反射对称存在，双侧病理反射未引出，共济运动稳准，脑膜刺激征阴性。\n【待人工确认·本机素材无此段原文】","现病史":"乙二醇是防冻液、冷却液等的主要成分，误服或自伤摄入后经乙醇脱氢酶代谢为乙醇酸、乙醛酸与草酸等毒性产物，引起似醉酒样中枢抑制、严重高阴离子间隙代谢性酸中毒与急性肾损伤。早期渗透压间隙升高、随后阴离子间隙升高以及草酸钙结晶尿是识别要点。治疗核心是尽早用甲吡唑（或乙醇）抑制代谢并纠正酸中毒，重症及时血液透析。\n常见表现：第一阶段（摄入后0.5-12小时）中枢神经系统：神志清楚，言语流利，高级智能活动正常。双侧瞳孔等大等圆，对光反射灵敏，眼球运动各方向到位，无眼震。四肢肌力5级，肌张力正常，腱反射对称存在，双侧病理反射未引出，共济运动稳准，脑膜刺激征阴性。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者有防冻液、冷却液、刹车油等误服或自伤摄入史，或出现与血酒精浓度不符的醉酒样表现，入院即刻查动脉血气分析，明确有无高阴离子间隙代谢性酸中毒并了解血碳酸氢盐水平，以确诊酸中毒并指导碳酸氢钠纠正治疗；同步查血电解质与渗透压，计算渗透压间隙及阴离子间隙，摄入后数小时内渗透压间隙升高而随后阴离子间隙相应升高，两者时间上互补，用于评估中毒时相与病情进展；查血肌酐、尿素氮及血钙、血钾等生化指标，了解有无急性肾损伤与低钙血症，评估血液透析指征；查尿常规及尿沉渣寻找草酸钙结晶，草酸钙结晶尿是识别乙二醇中毒的重要线索，但结晶阴性不能排除诊断；条件允许时测定血乙二醇浓度，血乙二醇超过20mg/dL提示中毒、达到或超过50mg/dL为血液透析的参考指征，并同测甲醇与乙醇以鉴别混合中毒；因乙二醇经乙醇脱氢酶代谢为乙醇酸、乙醛酸与草酸等毒性产物，需完善肝功能检查评估肝代谢与解毒功能；查乳酸以了解有无组织低灌注，并注意乙醇酸、乙醛酸可使部分血气分析仪乳酸结果假性升高，需结合临床解读；查血糖以排除糖尿病酮症酸中毒，查心电图并动态监测以排除其他原因所致酸中毒与心律失常。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 病史线索：防冻液、冷却液、刹车油等误服或自伤摄入史，或醉酒样表现与血酒精浓度不符且闻不到酒味。\n2. 动脉血气：高阴离子间隙代谢性酸中毒（可早发且严重），血碳酸氢盐明显降低。\n3. 渗透压间隙：摄入后数小时内升高（通常超过10mOsm/kg），随毒物被代谢而回落，而阴离子间隙相应升高——两者变化在时间上互补；渗透压间隙正常不能排除就诊较晚者。\n4. 尿液检查：草酸钙结晶（单水草酸钙呈信封样或细针样），可伴血尿；结晶阴性不能排除诊断。\n5. 生化：血钙可降低、血钾可异常、血肌酐随病程升高；部分血气分析仪乳酸结果可假性升高（乙醇酸、乙醛酸干扰）。\n6. 毒物检测：条件允许时测定血乙二醇浓度——超过20mg/dL提示中毒，达到或超过50mg/dL为血液透析的参考指征；怀疑混合中毒时同测甲醇与乙醇。\n7. 鉴别诊断：糖尿病酮症酸中毒、乳酸酸中毒、尿毒症、甲醇或其他醇类中毒、水杨酸中毒。\n1. 乙二醇中毒（ICD-10：T52.8）","鉴别诊断":"1. 渗透压间隙正常不能排除就诊较晚者\n2. 结晶阴性不能排除诊断\n3. 鉴别诊断：糖尿病酮症酸中毒、乳酸酸中毒、尿毒症、甲醇或其他醇类中毒、水杨酸中毒\n4.与普通醉酒鉴别：乙二醇中毒无酒味，且出现不相称的严重高阴离子间隙酸中毒\n5. 渗透压间隙检测有严格时间窗，且需排除其他高渗物质（乙醇、甲醇、丙二醇、甘露醇）干扰\n6. 结果正常不能排除就诊较晚者","处理方案":"【药物治疗·输液】\n甲吡唑（乙醇脱氢酶抑制剂，首选解毒剂）：负荷15mg/kg静脉输注（30分钟以上），其后10mg/kg每12小时1次共4剂，再改为15mg/kg每12小时1次；行血液透析期间给药间隔需缩短（如每4小时1次），具体按中毒专科方案调整。\n无甲吡唑时使用乙醇解毒：10%乙醇静脉滴注，负荷约0.6g/kg，目标血乙醇浓度100-150mg/dL（约22-33mmol/L），维持量按是否慢性酗酒个体化（非酗酒者约66mg/kg/h、酗酒者约154mg/kg/h，透析期间需上调约1倍）——必患者毒理或药学指导下并监测血糖与血浓度进行，警惕乙醇所致低血糖与中枢抑制。\n碳酸氢钠：存在重度酸中毒（pH低于7.25-7.30）时开始静脉补碱，目标维持pH不低于7.30；按血气分次给予，注意补碱引起低钾、低钙与容量过负荷。\n维生素B1 100mg加维生素B6（吡哆醇）50-100mg静脉注射，每6小时1次直至酸中毒纠正：促使乙醛酸经旁路代谢、减少草酸生成。\n钙剂仅用于症状性低钙（手足搐搦、明显QT延长或心律失常）：如10%葡萄糖酸钙10ml稀释后缓慢静脉注射，必要时重复；无症状性低钙不常规补钙，以免加重草酸钙沉积。\n符合指征者应尽早联系具备血液透析或血液净化能力的ICU/医院并安排转运。\n\n【药物治疗·口服】\n乙二醇中毒以静脉解毒与血液透析为核心，一般无需口服药物治疗。\n仅在无法建立静脉通路且无甲吡唑的极端情况下，可在严密监测下短期经口或胃管给予乙醇制剂（目标浓度同静脉方案），须由中毒专科指导执行。\n\n【治疗】\nABC优先：昏迷者气管插管保护气道防误吸，建立静脉通路并心电、血氧监护；大量摄入且就诊早（1小时内）者在气道保护前提下洗胃，活性炭对乙二醇吸附有限、不作为常规。\n特异性解毒：首选甲吡唑，无药时用乙醇；两者均通过抑制乙醇脱氢酶阻止毒性代谢物生成，越早越好，用药前先留血标本测定乙二醇浓度与渗透压。\n纠正酸中毒：重度酸中毒时静脉碳酸氢钠维持pH不低于7.30，并纠正低钾、低镁。\n辅助代谢治疗：维生素B1加维生素B6静脉给药以减少草酸生成。\n血液透析指征：血乙二醇浓度达到或超过50mg/dL（约8mmol/L）；或存在严重难治性代谢性酸中毒、急性肾损伤或尿少无尿、严重电解质紊乱、昏迷等明显器官功能障碍——即使无浓度结果也应尽早透析。\n透析终点：酸中毒纠正且血乙二醇浓度降至20mg/dL以下（或检测不到）。\n已使用甲吡唑且无严重酸中毒、肾功能正常、乙二醇浓度低于50mg/dL的轻症患者，可在严密监护下行内科解毒观察而不必透析（由专科判断）。\n症状性低钙时静脉补钙；记录摄入时间与剂量，动态复查血气、电解质、渗透压间隙、血肌酐与尿量直至恢复正常。\n\n【处理要点】\n重症患者收入ICU：每1-4小时评估意识、呼吸与生命体征，持续心电监护观察QT间期。\n动态复查（每4-12小时）血气、电解质（钾、钙、镁）、渗透压间隙、血肌酐与尿量，直至酸中毒纠正且肾功能稳定。\n定期复查尿沉渣草酸钙结晶与血钙，警惕急性肾损伤的高峰演变（多在摄入后24-72小时）。\n有条件者监测血乙二醇浓度以指导解毒剂停药与透析终点；无条件时以酸中毒与肾功能变化作为判断依据。\n发生急性肾损伤者安排血液透析或连续性肾脏替代支持，多数患者肾功能可逐步恢复，出院后随访至稳定。\n自伤意图者清醒后转精神心理科评估与随访；儿童误服家庭开展安全宣教（防冻液、溶剂等妥善存放）。\n职业接触者加强个人防护宣教，避免再次暴露。\n\n【注意事项】与普通醉酒鉴别：乙二醇中毒无酒味，且出现不相称的严重高阴离子间隙酸中毒；渗透压间隙升高与阴离子间隙升高在时间上互补（早期以前者为主、后期以后者为主）。\n渗透压间隙检测有严格时间窗，且需排除其他高渗物质（乙醇、甲醇、丙二醇、甘露醇）干扰；结果正常不能排除就诊较晚者。\n乙醇方案必患者住院环境下进行并监测血糖与血乙醇浓度：乙醇本身可致低血糖（尤其儿童）、中枢抑制，禁止院外自行使用。\n甲吡唑可能引起头痛、恶心及一过性肝酶升高，用药期间监测肝功能；多数医院需协调备药，缺药时应先用乙醇过渡并尽快转运。\n无症状性低钙不补钙：补充钙剂会增加草酸钙在肾小管沉积从而加重肾损伤，仅症状性低钙才静脉补钙。\n碳酸氢钠快速大量补碱可引起低钾、低钙与容量过负荷，应分次给予并按血气调整。\n活性炭对乙二醇无效且可能延误抢救，不作为常规；洗胃仅限早期大量摄入并在气道保护下进行。\n自伤、职业或儿童误服暴露应同步完成心理评估与家庭、作业环境安全干预，防止再次发生。\n编码说明：乙二醇属二醇类有机溶剂，临床常用T52.8（其他有机溶剂的毒性效应）编码，较T51.8（醇类）更贴切；合并急性肾损伤时可加标N17.9\n\n【急诊/急救】\n昏迷、抽搐、呼吸抑制或气道保护困难：立即气管插管并收入ICU。\n严重难治性代谢性酸中毒（pH低于7.2）、肺水肿或心力衰竭表现、恶性心律失常（低钙性QT延长、尖端扭转型室速）：紧急抢救并联系血液净化中心。\n少尿、无尿进行性加重或血肌酐快速升高（草酸钙沉积所致急性肾损伤）：尽早启动血液透析。\n高度怀疑乙二醇、甲醇等醇类中毒而确诊手段有限时，应先行解毒治疗并尽快转运至有条件医院，勿等待毒物检测结果。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「乙二醇中毒」原文）"},"icd10_diagnosis":"T52.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2265,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cde5af1932c53bab53ff9eab559a261246217f8fd500aa043b79c9b624963c51","pinyin":"yierchunzhongdu","initials":"yeczd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T52.8",30]]},{"id":"templates-2f6c779753315cf93733","key":"v1-c9ccc21dfe2a3058|templates-2f6c779753315cf93733","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳牙中龋","category":"口腔医学临床路径（2019年版）","raw":{"name":"乳牙中龋","category":"口腔医学临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患儿一般无自觉症状，或偶有冷热酸甜敏感而无自发痛史，为明确龋损是否已波及牙髓、指导去腐充填方案，先以探针行视诊与探诊检查，了解牙齿表面颜色改变、墨浸样变及质地粗糙松软的程度；查咬合翼片，明确发生于邻面的龋损，了解釉质及牙本质浅层透影区范围与龋坏深度；查牙髓活力测试，评估牙髓状态，与乳牙慢性牙髓炎、乳牙深龋相鉴别，避免误行牙髓治疗；对邻面龋损或隐匿龋，查根尖片明确龋损与牙髓腔的关系、了解乳牙牙根发育及根尖周组织情况；必要时查全口曲面体层片，了解全口牙齿龋坏数目、恒牙胚发育与萌出情况，评估患龋风险并指导口腔健康宣教；患儿处于乳恒牙替换期，还需完善口腔卫生状况与菌斑评估，了解刷牙效果及含糖饮食情况，为制定充填后复查与防龋方案提供依据。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社，2016）。\r1.症状：一般无自觉症状，或偶有冷热酸甜敏感,无自发痛史。\r2.检查：表面可有颜色改变或呈墨浸样变，牙齿表面完整性破坏，质地粗糙、松软。\r3.咬合翼片有助于显示发生于邻面的龋损，釉质及牙本质浅层可见透影区。\r（三）\n1. 乳牙中龋（ICD-10：K02.1）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社,2016）。\r对乳牙中龋的治疗指征为：\r1.凡有以上症状者应进行治疗。\r2.征得患儿及其监护人的同意。\r（四）临床路径标准治疗疗程为1次\r（五）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K02.1乳牙中龋疾病编码。\r2.当患儿同时具有其他疾病诊断时，但在治疗期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）治愈标准或疗效好转标准\r1.治愈：患牙无自觉症状，功能良好。\r2.未愈：充填体折断或脱落。\r（七）","临床路径·变异及原因分析":"变异及原因分析\r1.患牙大面积缺损、固位较差，需行预成冠等治疗。\r2.患儿因身心原因不能耐受或配合治疗时，需在征得监护人同意后采取全身麻醉、镇静或束缚下的治疗方式，此前需完成必要的相关检查。\r\f二、乳牙中龋","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 乳牙中龋临床路径（2019年版）.doc"},"icd10_diagnosis":"K02.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2266,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"788e57f28e1a61afc8b6d13df68cbc2b2e9f37d8909b46280af3461bdb787743","pinyin":"ruyazhongqu","initials":"ryzq","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K02.1",30]]},{"id":"templates-d52f3c6603d50646de25","key":"v1-c9ccc21dfe2a3058|templates-d52f3c6603d50646de25","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳牙慢性牙髓炎","category":"口腔医学临床路径（2019年版）","raw":{"name":"乳牙慢性牙髓炎","category":"口腔医学临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患儿可无疼痛史，或表现为咀嚼食物嵌塞窝洞时不适、较轻的隐痛钝痛、一过性冷热刺激痛，甚或自发痛、放散痛、阵发痛，为明确牙髓病变程度，先以视诊、探诊及叩诊检查，了解牙齿表面颜色改变、墨浸样变、近髓龋洞及探诊疼痛，明确叩诊有无明显疼痛或仅稍感不适，以与根尖周炎相鉴别；查牙髓活力测试，评估牙髓活力状态，指导乳牙牙髓切断术或根管治疗方案的选择；查X线片，了解牙齿冠部透影区范围，明确根尖周组织有无病理性改变及乳牙牙根发育与吸收情况，为判断可否保留患牙提供依据；查根尖片进一步明确龋损与髓腔的关系；必要时查全口曲面体层片，了解全口患牙数目、恒牙胚发育与萌出情况，评估对继承恒牙的影响；患儿为乳牙列，还需完善口腔卫生与菌斑评估，了解口腔卫生习惯，指导治疗后的口腔护理与定期复查。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社,2016）。\r1.症状：可无疼痛史；若有自觉症状，可表现为：\r（1）咀嚼食物嵌塞窝洞时有不适感。\r（2）较轻的隐痛、钝痛。 \r（3）一过性冷热刺激痛或不适。\r（4）自发痛、放散痛、阵发痛。\r2.检查：表面可有颜色改变或呈墨浸样变，牙齿表面完整性破坏，可见近髓龋洞，探诊可有疼痛；叩诊时无明显疼痛或稍感不适。\r3.X线片牙齿冠部可有透影区，根尖周组织无病理性改变。\r（三）\n1. 乳牙慢性牙髓炎（ICD-10：K04.002）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社,2016）。\r对乳牙慢性牙髓炎的治疗指征为：\r1.凡确诊为慢性牙髓炎的患牙，牙根生理性吸收未超过1/3，应当选择根管治疗。\r2.征得患儿及其监护人的同意。\r（四）临床路径标准治疗疗程为1～3次\r（五）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K04.002乳牙慢性牙髓炎疾病编码。\r2.当患儿同时具有其他疾病诊断时，但在治疗期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）治愈标准或疗效好转标准\r1.治愈：无自觉症状，功能良好，修复体完好，X线片提示根充物完好，根尖周组织无病理性改变。\r2.好转：无明显自觉症状，功能基本恢复，修复体基本完好，X线片示根充物基本完好，根尖周组织无病理性改变。\r3.未愈：症状未消失或加重，X线片示根尖周组织出现明显病理性改变。\r（七）","临床路径·变异及原因分析":"变异及原因分析\r\n禋啧商8\n摨\n伀\n倀\n漀\n伀\n倀\n儀\n愀\n漀\n摨\n伀\n倀\n儀\n愀\n漀\n鵨\n伀\n倀\n儀\n愀\n漀\n謠\n伀\n倀\n儀\n愀\n漀\n伀\n倀\n儀\n愀\n漀\n脈\n憁\n漀\n摨\n脈\n憁\n漀\n脈\n憁\n漀\n摨\n脈\n伀\n儀\n尀脈\n,\n瀁h\n脈\n,\n,\n萑\n搒\n葠\n摧\n肄\n桤\n圀\n怀肄愂\n摧燖\n萑\n搒\n葠\n摧燖\n萑\n搒\n葠\n摧燖\n搒\n愀\n摧壂k\n红槬\ni\n穨\n憁\n瀀h\n穨\n憁\n漀\n桰\n蕨\n憁\n漀\n桰\n鉽\n脈\n,\n,\n伀\n倀\n尀脈\n缮\n伀\n倀\n尀脈\n穨\n伀\n倀\n尀脈\n伀\n倀\n尀脈\n伀\n倀\n尀脈\n伀\n倀\n愀\n漀\n脈\n憁\n漀\n韋涂艙\n穨\n憁\n瀀h\n穨\n憁\n漀\n桰\n蕨\n憁\n漀\n桰\n脈\n憁\n漀\n伀\n倀\n尀脈\n伀\n倀\n尀脈\n伀\n倀\n尀脈\n伀\n倀\n尀脈\n蕨\n憁\n瀀h\n讛\n橹嵹\n穨\n伀\n倀\n尀脈\n穨\n伀\n倀\n尀脈\n穨\n伀\n倀\n尀脈\n焭\n脈\n憁\n漀\n脈\n憁\n漀\n脈\n憁\n漀\n焭\n伀\n倀\n尀脈\n伀\n倀\n尀脈\n伀\n倀\n尀脈\n穨\n伀\n倀\n尀脈\n晉\n摧偱\n萑\n葠\n摧燖\n摧燖\n萑\n搒\n葠\n摧燖\n搒\n摧燖\n萑\n搒\n葠\n摧燖\n萑\n搒\n葠\n摧燖\n颠袐獿彧罳媐\n漀\n穨\n伀\n儀\n伀\n儀\n漀\n嵨ｅ\n伀\n儀\n漀\n伀\n儀\n漀\n漀\n漀\n鵨\n漀\n騟\n伀\n倀\n尀脈\n騟\n伀\n倀\n儀\n尀脈\n唃\n脈\n憁\n漀\n伀\n倀\n尀脈\n伀\n倀\n尀脈\n1.患牙大面积缺损，无法修复者。\r2.患牙大面积缺损、固位较差，需行预成冠等治疗。\r3.患儿因身心原因不能耐受或配合治疗时，需在征得监护人同意后采取全身麻醉、镇静或束缚下的治疗方式，此前需完成必要的相关检查。\r\f二、乳牙慢性牙髓炎","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 乳牙慢性牙髓炎临床路径（2019年版）.doc"},"icd10_diagnosis":"K04.002","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2267,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b7c9c430a6f6f93e27a360a4139dbc17159929e2551fa7ce72b3364e99943f07","pinyin":"ruyamanxingyasuiyan","initials":"rymxysy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K04.002",30]]},{"id":"templates-d500f3abe59e7ff40e7a","key":"v1-c9ccc21dfe2a3058|templates-d500f3abe59e7ff40e7a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳痈(中医辨证)","category":"中医","raw":{"name":"乳痈(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】乳房红肿热痛、乳汁排出不畅、结块、发热恶寒、腋窝淋巴结肿大。\n【待人工确认·本机素材无此段原文】","现病史":"乳痈是由热毒入侵乳房而引起的急性化脓性疾病，相当于西医的急性乳腺炎。\n常见表现：乳房红肿热痛、乳汁排出不畅、结块、发热恶寒、腋窝淋巴结肿大。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者产后哺乳期出现乳房红肿热痛、结块、乳汁排出不畅，伴发热恶寒、腋窝淋巴结肿大，入院即刻完善血常规检查，了解白细胞总数及中性粒细胞是否增高，明确乳痈热毒内蕴与感染程度；查C反应蛋白及降钙素原，评估炎症反应程度与感染性质，指导抗菌药物使用；查乳腺彩超检查，明确有无脓肿形成及脓肿的部位、大小与数目，为是否切开排脓引流提供依据，并与炎性乳腺癌、乳房良性肿块相鉴别；查乳汁或脓液细菌培养及药敏试验，明确致病菌并指导抗感染方案；发热患者查体温与血培养，明确有无全身血流感染；因清热解毒中药需经肝肾代谢、且哺乳期用药需顾及母婴安全，完善肝肾功能检查，排除肝肾功能不全所致用药受限；查电解质以了解发热、纳差、呕吐所致水电解质紊乱情况；查乳房局部情况并必要时行钼靶检查，与乳腺恶性病变相鉴别。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 多见于产后哺乳的产妇，尤以初产妇多见。\n2. 乳房局部红肿热痛，结块，乳汁排出不畅。\n3. 可伴发热恶寒，头痛骨楚，或恶心呕吐，纳差。\n4. 同侧腋窝淋巴结肿大压痛。\n5. 血常规检查白细胞总数及中性粒细胞增高。\n1. 乳痈(中医辨证)（ICD-10：L02.9）","鉴别诊断":"1. 乳痈与乳发鉴别：乳发病变范围较乳痈大，焮红漫肿，迅速腐烂，病情较重","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（气滞热壅）：\n 用法：清开灵注射液40ml+5%GS250ml静滴qd\n\n方案2（热毒炽盛）：\n 用法：鱼腥草注射液50ml+5%GS250ml静滴qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（气滞热壅）：\n 用法：瓜蒌牛蒡汤加减（瓜蒌15g 牛蒡子9g 天花粉9g 黄芩9g 栀子9g 金银花9g 连翘9g 皂角刺9g 青皮6g 陈皮6g 柴胡9g 甘草3g）\n\n药物2（热毒炽盛）：\n 用法：透脓散加减（黄芪15g 当归9g 皂角刺12g 川芎6g 金银花9g 连翘9g 蒲公英15g 紫花地丁9g）（注：穿山甲为国家一级保护动物、已依法禁止入药，原方去之，皂角刺增量以透脓托毒）\n\n药物3（正虚毒恋）：\n 用法：托里消毒散加减（人参6g 黄芪15g 当归9g 川芎6g 白芍9g 白术9g 茯苓9g 金银花9g 白芷6g 皂角刺9g 桔梗6g 甘草3g）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n针灸：取膻中、乳根、期门、内关、肩井；发热加曲池、合谷，胀痛加太冲\n外治：初起用金黄膏或玉露膏外敷；成脓切开排脓；溃后用八二丹或九一丹药线引流\n推拿：揉膻中、乳根、期门，推揉乳房结块处，疏通乳络\n热敷：初起可用热敷，促进炎症消散\n\n【处理要点】\n保持乳头清洁，防止乳头破损\n定时哺乳，避免乳汁淤积\n哺乳期保持心情舒畅\n饮食清淡，忌辛辣油腻\n\n【护理】\n情志护理：乳痈多因情志不畅、肝气郁结致乳汁壅滞，宜多予疏导安慰，嘱其勿恼怒忧郁，保持情志舒畅，避免郁怒加重肝胃郁热、阻碍乳络通畅。\n排乳与起居调护：指导哺乳卫生，哺乳前后清洗乳头，乳头皲裂、内陷者及时处理；患侧暂停止直接哺乳，用吸乳器定时排空乳汁，排乳不畅时可自乳根向乳头方向轻柔按摩并热敷后再排，切忌暴力挤压；用胸罩或吊带托起乳房，穿宽松内衣，保持局部清洁干燥。\n病情观察：密切观察乳房红肿热痛范围、皮色变化、有无波动感及脓液色质气味，监测体温，成脓期及时报告医师穿刺或切开排脓；观察乳汁排泄是否通畅，防止乳汁淤积加重病情。\n外治护理：初起未成脓者遵医嘱以金黄散、仙人掌捣烂或芒硝外敷患处，观察局部有无过敏起疹；已成脓切开引流者保持引流口通畅，观察引流液量、色、质，及时更换敷料并严格无菌操作；溃后期脓尽者可用生肌散促进收口。\n煎药服药护理：疏肝清热、通络消肿之剂（如瓜蒌牛蒡汤）宜温服，服药后观察乳汁排出及肿块变化；服用清热解毒通下之品时注意大便与体温情况，药渣可热敷患处以助药力达所。\n\n【饮食】\n忌口：忌食辛辣炙煿、油炸及肥甘厚味（辣椒、酒、羊肉、油炸食品等），忌海鲜发物（鱼、虾、蟹），以免助热生火、壅滞化痈；成脓溃后亦忌滋腻厚补，防余毒难清、反复迁延。\n宜食清淡易消化、清热通乳之品：丝瓜、冬瓜、苦瓜、莲藕、芹菜、绿豆、赤小豆等，多饮温开水，保持大便通畅，使热毒从下而解。\n药膳食疗：初起可饮蒲公英茶或双花饮（金银花、菊花煎水）清热消肿；丝瓜络煮水、橘核煎汤代茶饮助通乳散结；绿豆百合粥清解热毒。\n溃后期脓去正虚者宜益气养血、托毒生肌：黄芪炖母鸡汤、山药红枣粥、猪蹄花生汤等，少量多餐、循序渐进，忌骤然大补，防余毒复燃。\n\n【注意事项】\n乳痈与乳发鉴别：乳发病变范围较乳痈大，焮红漫肿，迅速腐烂，病情较重；乳痈病变较局限，以结块、红肿热痛为主。\n\n【急诊/急救】\n乳痈伴高热、寒战、乳房迅速肿大、皮肤发紫，可能为乳发或败血症，立即急诊。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「乳痈（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】乳痈\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、气滞热壅（初期）\n    症状舌脉：乳汁淤积结块，皮色不变或微红，肿胀疼痛，伴有恶寒发热，头痛，周身酸楚，口渴，便秘，苔薄，脉数\n    治法：疏肝清胃、通乳消肿\n    方剂：瓜蒌牛蒡汤\n\n二、热毒炽盛（成脓期）\n    症状舌脉：乳房肿痛，皮肤焮红灼热，肿块变软，有应指感，或切开排脓后引流不畅、红肿热痛不消、有“传囊”现象，壮热，舌红、苔黄腻，脉洪数\n    治法：清热解毒、托里透脓\n    方剂：透脓散\n\n三、正虚毒恋（溃后期）\n    症状舌脉：溃脓后乳房肿痛虽轻，但疮口脓水不断、脓汁清稀、愈合缓慢或形成乳漏，全身乏力，面色少华，或低热不退，饮食减少，舌淡、苔薄，脉弱无力\n    治法：益气和营托毒\n    方剂：托里消毒散。来源：《中医外科学》（中国中医药出版社“十四五”规划教材）·乳房疾病·乳痈。提示：哺乳期须保持乳头清洁、排空乳汁；已成脓者须切开引流\n\n【方剂参考】\n\n【西医诊断】\n  急性乳腺炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"L02.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2268,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fd3b7094511abd06d7b8c8ca04b9c7dc7d743dff8b96eec0b4f14c52558a6a2a","pinyin":"ruyong(zhongyibianzheng)","initials":"ry(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","L02.9",30]]},{"id":"templates-4416a8ebb54f0efb97a0","key":"v1-c9ccc21dfe2a3058|templates-4416a8ebb54f0efb97a0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳癖(中医辨证)","category":"中医","raw":{"name":"乳癖(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肝郁痰凝：乳房胀痛或刺痛，肿块随喜怒消长，胸闷胁胀，善郁易怒，失眠多梦，心烦口苦，苔薄黄，脉弦滑、冲任失调：乳房肿块疼痛，月经前加重，经后缓解，伴腰膝酸软，神疲倦怠，月经先后无定期，量少色淡，舌淡苔白，脉沉细。\n【待人工确认·本机素材无此段原文】","现病史":"乳癖是乳腺组织的良性增生性疾病，以乳房疼痛、肿块为主要表现，其肿块随喜怒消长。分肝郁痰凝、冲任失调等证型。可见于乳腺增生病。\n常见表现：肝郁痰凝：乳房胀痛或刺痛，肿块随喜怒消长，胸闷胁胀，善郁易怒，失眠多梦，心烦口苦，苔薄黄，脉弦滑、冲任失调：乳房肿块疼痛，月经前加重，经后缓解，伴腰膝酸软，神疲倦怠，月经先后无定期，量少色淡，舌淡苔白，脉沉细。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者乳房胀痛或刺痛、可触及肿块，且肿块随喜怒消长，部分患者肿块疼痛于月经前加重、经后缓解，为明确乳癖（乳腺增生病）诊断并与乳腺癌相鉴别，首诊即行乳腺彩超检查，了解肿块大小、形态、边界、内部回声及血流情况，并按BI-RADS分级评估良恶性风险，指导后续随访或活检决策；患者年龄偏大、或肿块质硬、边界不清、伴乳头溢液者，查乳腺钼靶X线检查，了解有无恶性钙化及结构扭曲，与超声互为补充；对肿块质硬、边界不清或乳头溢血者，及时行肿块穿刺活检，明确病理性质；查性激素相关检查评估内分泌状态，了解雌孕激素水平与冲任失调型乳癖的关系，指导疏肝理气、调摄冲任的中医药治疗方案；查甲状腺功能，排除甲状腺功能异常所致乳房胀痛；因患者善郁易怒、失眠多梦，完善肝肾功能检查，为长期口服中药提供用药安全依据，并定期复查乳腺彩超，观察肿块大小与BI-RADS分级有无变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 乳房疼痛、肿块，多与月经周期及情志相关\n2. 乳腺B超（BI-RADS分级）、钼靶（必要时）排除恶性\n3. 肿块质硬、边界不清、乳头溢血者及时活检\n1. 乳癖(中医辨证)（ICD-10：N60.9）","鉴别诊断":"1. 乳腺B超（BI-RADS分级）、钼靶（必要时）排除恶性","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（肝郁痰凝）：乳癖消片5片 tid，或逍遥丸6g bid\n药物2（冲任失调）：乳增宁片4片 tid，或六味地黄丸6g bid\n药物3（配合）：维生素E 0.1g tid\n\n【治疗】\n肝郁痰凝：疏肝解郁，化痰散结，逍遥蒌贝散加减\n冲任失调：调摄冲任，软坚散结，二仙汤合四物汤加减\n\n【处理要点】\n保持情志舒畅，忌恼怒\n穿戴合适文胸\n低脂饮食，忌咖啡浓茶\n\n【护理】\n情志护理：乳癖以肝郁气滞为基本病机，情志波动可致乳痛、结块加重。嘱患者保持情绪舒畅，遇事多向家人倾诉，避免郁怒忧思；可指导听舒缓音乐、散步、练习八段锦以疏肝解郁，家属宜多予安慰开导，忌对病情过度焦虑而加重肝郁。\n起居调护：起居规律，保证充足睡眠，忌熬夜耗伤肝血；经前乳胀明显者宜减少重体力劳作，穿戴松紧适宜的胸罩，避免挤压乳房；平时适度运动（太极拳、慢跑）以助气血流通，防止痰瘀互结。\n病情观察：注意观察乳房肿块大小、质地、边界及有无压痛，记录疼痛与月经周期的关系（经前加重、经后缓解为典型表现）；若肿块短期迅速增大、质地坚硬、活动度差或出现乳头溢液、乳房皮肤橘皮样改变，应立即报告医师并建议进一步检查，以防恶变漏诊。\n煎药服药护理：疏肝理气、化痰散结之剂宜温服，服后稍事休息；经期活血化瘀药须遵医嘱酌情停用，避免经量过多；服药期间忌同时服用滋补碍胃之品，以免影响药效吸收。\n外治护理：外用中药（如消癖散、金黄散敷贴）前先清洁局部皮肤，观察有无红疹、瘙痒等过敏反应，如有则停用；肿块局部可配合温毛巾热敷或轻手法按揉（以酸胀为度、不宜重按猛揉），经期及妊娠期禁用外敷活血药。\n\n【饮食】\n忌口：忌辛辣燥烈之品（辣椒、胡椒、烈酒、羊肉），以免助火生痰、加重乳胀；忌肥甘厚味及煎炸食品（肥肉、油炸物、动物内脏），以免酿生痰湿、痰瘀凝结；慎食含雌激素样物质之品（蜂王浆、雪蛤、花粉制剂），避免刺激乳腺增生。\n适宜食物：宜多食疏肝理气、化痰散结之品，如玫瑰花、茉莉花、佛手、陈皮、橘络、山楂、海带、紫菜、夏枯草苗、丝瓜等；冲任失调者（经前乳胀、腰酸）可加食黑豆、桑葚、枸杞以调补冲任。\n药膳食疗：玫瑰花陈皮茶（玫瑰花6g、陈皮6g沸水冲泡代茶饮），每日1剂，适用于肝郁气滞型乳胀者；海带萝卜汤（海带50g、白萝卜100g煮汤），软坚散结，适用于痰凝型结块；经前乳胀明显者可用佛手10g、香橼6g煮水代茶，经后即止。\n饮食有节：三餐定时定量，少食多餐，忌暴饮暴食及临睡进食，以免脾胃运化失常、聚湿生痰；戒饮咖啡、浓茶及碳酸饮料，因其可兴奋情绪、加重经前乳胀不适。\n\n【注意事项】\n定期复查乳腺B超（每6-12个月）\n肿块增大、质地改变、乳头溢液者立即专科检查\n40岁以上加做钼靶，高危人群遵医嘱\n\n【急诊/急救】\n一般不需急救\n若乳房红、肿、热、痛伴发热提示急性乳腺炎或脓肿：乳腺外科就诊，评估抗感染与引流","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「乳癖（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】乳癖\n⚠️ 本条为通用辨证参考，尚未逐条核对教材原文，请务必结合患者实际四诊资料，\n   并核对相应教材（中医外科学/中医儿科学/中医内科学）后再使用；\n   方剂仅列组成药味，具体剂量请依药典、患者体质及本院药房规格确定。\n\n一、肝郁痰凝\n    症状舌脉：乳房肿块随喜怒消长，胀痛或刺痛，经前加重、经后减轻；伴胸闷胁胀、善郁易怒、失眠多梦；舌淡红、苔薄白，脉弦滑\n    治法：疏肝解郁、化痰散结\n    方剂：逍遥蒌贝散加减（柴胡、当归、白芍、白术、茯苓、瓜蒌、贝母、半夏、南星、生牡蛎、山慈菇）\n\n二、冲任失调\n    症状舌脉：乳房肿块经前增大、经后缩小，常伴月经紊乱、腰膝酸软、神疲乏力、夜寐欠佳；舌淡红、苔薄白，脉濡细\n    治法：调摄冲任、理气散结\n    方剂：二仙汤合四物汤加减（仙茅、仙灵脾、当归、巴戟天、黄柏、知母、熟地黄、白芍、川芎、贝母、牡蛎）\n\n【西医诊断】\n  乳腺增生症\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n须先排除乳腺癌\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"N60.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2269,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"71ac9b617b20f188582147d5e316359a979913b73a1ba904bcd0b431799fcdaa","pinyin":"rupi(zhongyibianzheng)","initials":"rp(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","N60.9",30]]},{"id":"templates-9dd32b0665dc20bbb623","key":"v1-c9ccc21dfe2a3058|templates-9dd32b0665dc20bbb623","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳腺脓肿(哺乳期)","category":"甲状腺乳腺外科","raw":{"name":"乳腺脓肿(哺乳期)","category":"甲状腺乳腺外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】乳房局部红肿、灼热、剧痛，可触及波动性包块、发热、寒战、乏力，体温可达38.5℃以上、患侧乳房排乳不畅或乳汁呈絮状、脓性、同侧腋窝淋巴结肿大伴压痛、脓肿破溃后可见脓液流出，疼痛缓解。\n【待人工确认·本机素材无此段原文】","现病史":"乳腺脓肿是哺乳期急性乳腺炎未及时控制、炎症局限液化形成的脓腔，多见于初产妇产后3～4周。表现为乳房局部红肿热痛、波动感包块，伴发热，需及时切开引流并保持排乳通畅。\n常见表现：乳房局部红肿、灼热、剧痛，可触及波动性包块、发热、寒战、乏力，体温可达38.5℃以上、患侧乳房排乳不畅或乳汁呈絮状、脓性、同侧腋窝淋巴结肿大伴压痛、脓肿破溃后可见脓液流出，疼痛缓解。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、血压（评估感染程度）\n一般情况：精神状态、有无脱水及中毒症状\n乳房视诊：红肿范围、皮肤颜色（有无发紫发黑）、破溃口、乳头皲裂或内陷\n乳房触诊：包块部位、大小、边界、波动感、压痛程度、有无多房分隔\n腋窝触诊：淋巴结大小、数目、压痛（同侧腋窝）\n对侧乳房检查：有无对称病变或积乳\n哺乳情况询问：哺乳频次、含接姿势、有无乳头损伤","辅助检查":"1. 血常规+CRP：入院急查评估感染程度，治疗后3～5天复查\n2. 乳汁/脓液细菌培养+药敏：用药前留取，指导目标性抗感染（多为金黄色葡萄球菌）\n3. 乳房超声：明确脓肿数目、大小、部位及是否多房，超声引导穿刺/引流\n4. PCT+血培养（高热寒战者）：排除脓毒症\n5. 血糖：反复发作或愈合差者排查糖尿病\n6. 肝功能+肾功能：选择抗生素前评估脏器功能（哺乳期用药安全）","初步诊断":"1. 乳房超声：首选，明确脓肿部位、大小、数目、是否多房（可引导穿刺）\n2. 血常规+CRP：白细胞升高、CRP升高\n3. 乳汁/脓液细菌培养及药敏：指导抗生素选择（金黄色葡萄球菌最常见）\n4. 必要时穿刺抽脓：既诊断又治疗（浅表脓肿）\n5. 体温与局部体征动态评估：判断是否形成脓肿（波动感是重要体征）\n1. 乳腺脓肿(哺乳期)（ICD-10：O91.1）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 兼顾哺乳安全，选择方案时注意药物是否影响哺乳！\n\n方案1（抗感染，哺乳期可用）：\n 用法：头孢呋辛 1.5g 静滴 q8h 或 头孢曲松 2g 静滴 qd（哺乳期相对安全）\n\n方案2（青霉素过敏）：\n 用法：克林霉素 0.6g 静滴 q8h（哺乳期可用）\n\n方案3（支持/退热）：\n 用法：0.9%氯化钠 静滴；对乙酰氨基酚 0.5g 必要时（哺乳期安全）\n\n📌 避免使用四环素类、喹诺酮类、磺胺类（影响婴儿）；用药期间可按医嘱继续哺乳或暂停患侧哺乳。\n\n【药物治疗·口服】\n⚠️ 哺乳期用药，选择对婴儿安全的药物！\n\n药物1（抗感染序贯）：\n 用法：头孢呋辛酯 0.25g bid 或 阿莫西林克拉维酸 0.625g tid\n\n药物2（青霉素过敏）：\n 用法：克林霉素 0.3g tid\n\n药物3（对症）：\n 用法：对乙酰氨基酚 0.5g 必要时（退热镇痛，哺乳期安全）\n\n📌 避免使用喹诺酮类、四环素类、磺胺类及甲硝唑大剂量；服药期间观察婴儿有无腹泻、皮疹。\n\n【治疗】\n切开引流：脓肿形成后主要治疗手段，行放射状切口（避免损伤乳管）、充分分离多房脓腔、放置引流条\n穿刺抽脓：适用于直径<5cm的浅表单房脓肿（超声引导下），可反复穿刺+冲洗\n抗感染：选择哺乳期安全抗生素，疗程10～14天，按药敏调整\n保持排乳通畅：患侧继续排乳（可挤奶弃去或按医嘱哺乳），避免乳汁淤积\n退热镇痛：对乙酰氨基酚或布洛芬（哺乳期可用）\n脓肿破溃或引流后：每日换药，观察引流是否通畅\n\n【处理要点】\n排乳管理：指导正确哺乳姿势与含接方式，哺乳后手法挤奶或用吸奶器排空患侧\n切口换药：观察引流液量与性状，引流条逐渐拔除，保持引流通畅\n哺乳指导：患侧可继续哺乳（除非脓液污染乳头），健侧正常哺乳，用药按医嘱\n疼痛管理：哺乳前热敷、哺乳后冷敷，必要时遵医嘱镇痛\n观察体温与局部红肿变化，警惕脓肿复发或多房脓肿残留\n纠正乳头皲裂（哺乳后涂乳汁或羊脂膏）以防复发\n\n【护理】\n乳房护理：按医嘱热敷/冷敷，指导哺乳前后排空乳汁，保持乳头清洁干燥\n切口护理：换药时观察引流液色质量，保持引流条通畅，注意无菌操作\n体温监测：每4小时测体温，高热时物理降温并遵医嘱用药\n哺乳指导：示范正确含接与哺乳姿势，教会手法挤奶，避免乳汁淤积\n心理护理：哺乳期患者焦虑明显，解释继续哺乳的益处，减轻负罪感与压力\n\n【饮食】\n清淡易消化饮食，高蛋白（鱼、瘦肉、蛋、奶）促进炎症修复\n多饮水（每日2000ml以上），保证乳汁分泌\n多食新鲜蔬菜水果补充维生素C，增强抵抗力\n忌辛辣刺激、油腻及酒类\n保证充足热量摄入（哺乳期需额外300～500kcal/日）\n\n【注意事项】\n哺乳期乳腺炎的关键是'排空乳汁+抗感染'，脓肿形成必须引流，抗生素不能替代引流\n切口应取放射状以减少乳管损伤；乳晕部脓肿取乳晕边缘弧形切口\n超声显示多房脓肿或脓腔分隔时应充分分离，避免残留导致复发\n继续哺乳不会使婴儿感染（致病菌多为金黄色葡萄球菌），反而有利于恢复\n\n【急诊/急救】\n高热寒战伴乳房红肿迅速扩大、皮肤发紫黑（乳房的坏死性筋膜炎）→ 急诊手术清创\n脓肿破溃大出血或引流后持续高热 → 急诊评估并调整治疗\n出现感染性休克征象 → 立即抢救","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"O91.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2270,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0eee561b56eb55211ab33a2027144f5925fd29c146e0f157aebec83874fa71e2","pinyin":"ruxiannongzhong(buruqi)","initials":"rxnz(brq)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","O91.1",30]]},{"id":"templates-516b834b0ad4fe9c899c","key":"v1-c9ccc21dfe2a3058|templates-516b834b0ad4fe9c899c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"乳腺良性肿瘤","category":"普通外科临床路径（2019年版）","raw":{"name":"乳腺良性肿瘤","category":"普通外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\n（1）血常规、尿常规；\n（2）肝功能、肾功能、电解质、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）；\n（3）心电图、胸部X线检查；\n（4）乳腺彩超及术前定位。\n2.根据患者病情可选择：\n（1）钼靶检查或乳腺MRI；\n（2）乳管镜检查或乳管造影；\n（3）肺功能、超声心动图等。\n（七）预防性抗菌药物选择与使用时机\n按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。通常不需预防用抗菌药物。\n（八）手术日为入院第2～3天\n1.麻醉方式：局部麻醉（必要时区域阻滞麻醉或全身麻醉）。\n2.手术方式：乳腺肿物切除术或病变导管切除术。\n3.术中用药：麻醉常规用药。\n4.手术内固定物：无。\n5.输血：根据术前血红蛋白状况及术中出血情况而定。\n6.病理: 术后标本送病理学检查（视术中情况行术中冷冻病理检查）。\n（九）术后住院恢复0～1天\n1.必要时复查的检查项目：血常规。\n2.术后用药：\n抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。通常不需预防用抗菌药物。\n3.严密观察有无出血等并发症，并作相应处理。\n（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《临床诊疗指南\n外科学分册》（中华医学会编著，人民卫生出版社，2006年12月，第1版），本组疾病包括乳房纤维腺瘤、乳管内乳头状瘤等。\n1.症状：乳房肿物，乳头溢液或溢血。 \n2.体征：乳房单发或多发肿物，质地韧，表面光滑，活动度可；边界清楚，可呈分叶状；挤压乳晕周围，病变乳管可出现溢液。\n3.影像学检查：超声和（或）钼靶检查。\n4.病理检查：乳头溢液细胞学检查未见恶性细胞。\n（三）\n1. 乳腺良性肿瘤（ICD-10：D24）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\n根据《临床技术操作规范\n普通外科分册》（中华医学会编著，人民军医出版社，2007年，第1版）。\n1.乳房肿物切除术：体检可扪及或影像学检查发现的乳房肿物。\n2.乳腺病变导管切除术：适合乳管内乳头状瘤。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.第一诊断为乳腺良性肿瘤（ICD-10：D24）,乳腺发育不良（ICD-10：N60）疾病编码。\n2.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\n（六）术前准备1～2天\n1.","临床路径·标准住院日":"标准住院日为2～4天\n（五）","临床路径·出院标准":"出院标准\n1.伤口愈合好：无积血，无感染征象。 \n2.没有需要住院处理的并发症和（或）合并症。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.有影响手术的合并症，需要进行相关的诊断和治疗。\n2.病理报告为恶性病变，需要按照乳腺癌进入相应路径治疗。","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 普通外科临床路径（2019年版） · 乳腺良性肿瘤临床路径（2019年版）.docx"},"icd10_diagnosis":"D24","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2271,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e17be5e19a6a048881520dcc540207f8049520c5e65d7cfa405fe3492ce8de9c","pinyin":"ruxianliangxingzhongliu","initials":"rxlxzl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","D24",30]]},{"id":"templates-1e7757c2e023eca866bd","key":"v1-c9ccc21dfe2a3058|templates-1e7757c2e023eca866bd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣关闭不全三尖瓣关闭不全成形修复术","category":"心血管外科临床路径（2019年版）","raw":{"name":"二尖瓣关闭不全三尖瓣关闭不全成形修复术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因二尖瓣关闭不全合并三尖瓣关闭不全拟行成形修复术，术前须明确瓣膜病变性质及心功能状态，查经胸超声心动图，了解瓣膜形态、反流程度、瓣环大小、心室大小及射血分数，为二尖瓣关闭不全三尖瓣关闭不全成形修复术式选择提供依据；必要时查经食管超声心动图，进一步明确瓣叶脱垂部位、反流机制及有无左心房血栓，并与术中经食管超声检查相衔接；查心电图，了解有无心房颤动、传导阻滞及心肌缺血改变，评估手术风险；患者长期瓣膜反流可致心肌受损，查心肌酶及肌钙蛋白以排除急性心肌损伤；完善血常规、尿常规、便常规及血型检查，了解有无贫血、感染并为术中输血备血；查肝肾功能、电解质及血糖，评估重要脏器功能，指导体外循环围术期用药；查凝血功能，了解凝血状态，评估体外循环肝素化及术后抗凝出血风险；完善乙型肝炎、丙型肝炎、梅毒及艾滋病等感染筛查，防范血源性传播；查胸部X线及肺功能，了解心脏大小、肺淤血与肺通气储备，评估手术耐受性；必要时查冠状动脉造影，明确有无合并冠心病，避免术中漏诊；病情稳定后复查超声心动图，评估成形修复效果与心功能恢复情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 二尖瓣关闭不全三尖瓣关闭不全成形修复术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","临床路径·进入路径标准":"进入路径标准\r因心脏二尖瓣病变合并三尖瓣病变行二尖瓣直视下成形术（ICD-9-CM-3：35.33001）（或）二尖瓣人工瓣环成形术（ICD-9-CM-3：35.12001）及三尖瓣成形术（ICD-9-CM-3：35.14001）。\r当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（五）术前准备（评估）不超过7天\r1.必须完成的检查项目\r（1）血常规、尿常规、大便常规、肝肾功能、电解质、凝血功能、术前感染疾病筛查、血型＋术前配血。\r（2）X线胸片、心电图、超声心动图。\r2.根据患者病情可选择的检查项目\r（1）血气分析和肺功能（高龄或既往有肺部病史者）、冠状动脉造影（年龄\n50岁；存在相关危险因素年龄可提前）、冠状动脉CTA。\r（2）有其他专业疾病者及时请相关科室会诊。\r（七）预防性抗菌药物选择与使用时机\r抗菌药物使用：根据《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。并根据患者的病情决定抗菌药物的选择与使用时间。\r（八）手术日为入院7天以内\r1.麻醉方式：全身麻醉体外循环。\r2.手术植入物：二尖瓣成形环三尖瓣成形环、胸骨固定钢丝等。 \r3.术中用药：心脏外科、麻醉及体外循环常规用药。\r4.输血及血液制品：视术中病情需要决定。\r（九）术后住院恢复\n11天\r1.术后早期持续监测治疗，观察生命体征。\r2.必须复查的检查项目\r（1）血常规、电解质、肝肾功能、抗凝监测。\r（2）心电图、胸部X线片、超声心动图。\r3.术后用药\r（1）抗菌药物使用：根据《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。\r（2）抗凝：根据所测INR值调整抗凝药用量，根据患者情况确定抗凝治疗方案。\r（3）根据病情需要进行强心、利尿治疗。\r（十）","临床路径·标准住院日":"标准住院日\n18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管已拔除、手术切口愈合无出院禁忌。\r3.无需要住院处理的并发症和（或）其他合并症。\r4. 胸部X线平片、超声心动图证实二尖瓣关闭良好，无相关并发症;三尖瓣无中度及以上反流，无相关并发症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：左室破裂、术后二尖瓣关闭不全需二次手术、心功能不全、低心排血量综合征、出血、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染等造成住院日延长和费用增加。\r2.合并有其他系统疾病，可能导致这些疾病加重而需要治疗，从而延长治疗时间和增加住院费用;另外三尖瓣修复时是否使用人工成形环均会导致住院费用存在差异。成形环的价格不同导致的住院费用差异。\r3.非常规路径(胸骨正中切口)的各类微创术式，治疗费用存在差异。胸腔镜辅助或全胸腔镜下手术者不进入本路径。\r4.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长费用增加。\r\f二、二尖瓣关闭不全合并三尖瓣成形手术临床路径","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 二尖瓣关闭不全，三尖瓣关闭不全成形修复术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2272,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6ca8b22a27cd6ff93e97e084a84ae28a328fc6b8b5a46a4413e671582ec3152a","pinyin":"erjianbanguanbibuquansanjianbanguanbibuquanchengxingxiufushu","initials":"ejbgbbqsjbgbbqcxxfs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-c2c2a150c2cb3e9a539a","key":"v1-c9ccc21dfe2a3058|templates-c2c2a150c2cb3e9a539a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣关闭不全成形修复术","category":"心血管外科临床路径（2019年版）","raw":{"name":"二尖瓣关闭不全成形修复术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者因二尖瓣关闭不全拟行成形修复术，术前须明确瓣膜病变性质与心功能状态，查经胸超声心动图，了解二尖瓣瓣叶形态、反流程度与机制、瓣环大小、左心室大小及射血分数，为二尖瓣关闭不全成形修复术式选择提供依据；必要时查经食管超声心动图，进一步明确瓣叶脱垂部位与反流机制，了解有无左心房血栓，并与术中经食管超声检查相衔接；查心电图，了解有无心房颤动、传导阻滞及心肌缺血改变，评估手术风险；患者长期二尖瓣反流可致心肌受损，查心肌酶及肌钙蛋白以排除急性心肌损伤；完善血常规、尿常规、便常规及血型检查，了解有无贫血、感染并为术中输血备血；查肝肾功能、电解质及血糖，评估重要脏器功能，指导体外循环围术期用药；查凝血功能，了解凝血状态，评估体外循环肝素化及术后抗凝出血风险；完善乙型肝炎、丙型肝炎、梅毒及艾滋病等感染筛查，防范血源性传播；查胸部X线及肺功能，了解心脏大小、肺淤血与肺通气储备，评估手术耐受性；必要时查冠状动脉造影，明确有无合并冠心病，避免术中漏诊；病情稳定后复查超声心动图，评估成形修复效果与心功能恢复情况。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 二尖瓣关闭不全成形修复术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","临床路径·进入路径标准":"进入路径标准\r\n因二尖瓣关闭不全行二尖瓣直视下成形术或(/和)二尖瓣人工瓣环成形术( ICD-9-CM-3 : 35.12004,35.33001）。\r当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（五）术前准备（评估）不超过7天\r1.必须完成的检查项目\r（1）血常规、尿常规、大便常规、肝肾功能、电解质、凝血功能、术前感染疾病筛查、血型＋术前配血。\r（2）Ｘ线胸片、心电图、超声心动图。\r2.根据患者病情可选择的检查项目\r（1）血气分析和肺功能（高龄或既往有肺部病史者）、冠状动脉造影（年龄\n50岁；存在相关危险因素年龄可提前）。\r（2）有其他专业疾病者及时请相关科室会诊。\r（3）胸部CT、冠状动脉CTA。\r（六）预防性抗菌药物选择与使用时机\r抗菌药物使用：根据《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。并根据患者的病情决定抗菌药物的选择与使用时间。\r（七）手术日为入院7天以内\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术植入物：二尖瓣成形环。 \r4.术中操作：术中使用经食管超声评估瓣膜功能。\r5.术中用药：心脏外科、麻醉及体外循环常规用药。\r6.输血及血液制品：尽可能减少术中输血和血制品的使用。\r（八）术后住院恢复\n11天\r1.术后早期持续监测治疗，观察生命体征。\r2.必须复查的检查项目\r（1）血常规、电解质、肝肾功能、抗凝监测；\r（2）心电图、胸部X线片、超声心动图。\r3.术后用药\r（1）抗菌药物使用：根据《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。\r（2）抗凝：根据所测INR值调整抗凝药用量，根据患者情况确定抗凝治疗方案。\r（3）根据病情需要进行强心、利尿治疗。\r（九）","临床路径·标准住院日":"标准住院日\n18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管已拔除、手术切口愈合无出院禁忌。\r3.无需要住院处理的并发症和（或）其他合并症。\r4. 胸部X线平片、超声心动图证实二尖瓣关闭良好，无相关并发症。\r（十）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：左室破裂、术后二尖瓣关闭不全需二次手术、心功能不全、低心排血量综合征、出血、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染等造成住院日延长和费用增加。\r2.合并有其他系统疾病，可能导致这些疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r3.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长费用增加。使用不同的人工瓣膜成形环（国产或进口），会导致住院费用存在差异。\r4.非常规路径(胸骨正中切口)的各类微创术式，治疗费用存在差异。胸腔镜辅助或全胸腔镜下手术者不进入本路径。\r\r\f二、二尖瓣关闭不全","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 二尖瓣关闭不全成形修复术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2273,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"58b3c41235cc081b4811bded46cae61c85982250e6ca6427cb601f78902bba65","pinyin":"erjianbanguanbibuquanchengxingxiufushu","initials":"ejbgbbqcxxfs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-17bdf67268ee19748bb5","key":"v1-c9ccc21dfe2a3058|templates-17bdf67268ee19748bb5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣合并主动脉瓣人工瓣替换及三尖瓣成形术","category":"心血管外科临床路径（2019年版）","raw":{"name":"二尖瓣合并主动脉瓣人工瓣替换及三尖瓣成形术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\r（1）血常规、尿常规、大便常规。\r（2）肝功能、肾功能，电解质，血型、凝血功能，感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）、血气分析。\r（3）心电图、胸部X线平片、超声心动图。\r2.根据患者具体情况可选择的检查项目：如心肌酶、风湿活动筛查、24小时动态心电图、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、头颅CT平扫、主动脉增强CT和肺功能检查（高龄或既往有肺部病史者）、外周血管超声检查等。\r（六）预防性抗菌药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）","初步诊断":"1. 二尖瓣合并主动脉瓣人工瓣替换及三尖瓣成形术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·选择用药】\n选择用药。可以考虑使用第一、二代头孢菌素。\r2.预防性用抗菌药物：时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时，感染性瓣膜病可延长至术后4～6周。\r（七）手术日为入院5个工作日左右\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术植入物：人工瓣、瓣膜成形环、胸骨固定钢丝等。 \r4.术后食管超声评估人工瓣膜功能。\r5.术中用药：麻醉及体外循环常规用药。\r6.输血及血液制品：视术中情况而定。\r（八）术后住院恢复7～13天\r1.术后早期持续监测治疗，观察生命体征。\r2.术后患者清醒后早期拔除气管插管。\r3.病情平稳后从术后恢复室转回普通病房。\r4.必须复查的检查项目：血常规、血电解质、肝肾功能、抗凝监测、心电图、胸部X线平片、超声心动图。\r5.根据患者新发症状或常规检查项目异常结果，必要时可进行心肌酶、头颅CT或细菌培养等检查。\r6.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r7.抗凝：根据所测INR值调整抗凝药用量，替换生物瓣膜华法林抗凝治疗至少3个月，以后改为阿司匹林75～100mg，机械瓣膜终身抗凝。\r8.根据病情需要进行强心、利尿等治疗。\r（九）","临床路径·进入路径标准":"进入路径标准\r因心脏二尖瓣和主动脉瓣疾患病变合并三尖瓣病变而行二尖瓣人工瓣替换术（机械瓣：ICD-9-CM-3:35.241；生物瓣：ICD-9-CM-3:35.231）合并主动脉瓣人工瓣膜置换术（机械瓣：ICD-9-CM-3:35.221；生物瓣：ICD-9-CM-3:35.\r211）及三尖瓣成形术（ICD-9-CM-3:35.141）。\r当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（五）术前准备（评估）1～5天\r1.","临床路径·标准住院日":"标准住院日通常10～18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管拔除、切口愈合无感染。\r3.无需要住院处理的并发症和（或）其他合并症。\r4.抗凝基本稳定。\r5.胸部X线平片、超声心动图证实人工生物瓣功能良好，无相关并发症。\r（十）出院带药\r1.强心、利尿药、补钾及华法林等。\r2.出院教育及华法林抗凝方法及门诊随访。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：左室破裂、人工瓣功能障碍、心功能不全、出血、瓣周漏、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\r2.合并有其他系统疾病，可能出现合并疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r3.人工瓣的选择：根据患者的病情，使用不同的人工瓣（国产和进口），导致住院费用存在差异。\r4.合并心房颤动等严重心律失常者，需要同期行消融手术者，不进入本路径。\r5.非常规路径(胸骨正中切口)的各类微创术式，治疗费用存在差异。\r6.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长，费用增加。\r\f二、心脏二尖瓣合并主动脉瓣人工瓣替换及三尖瓣手术","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 二尖瓣合并主动脉瓣人工瓣替换及三尖瓣成形术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2274,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d2f020c5c55ebbd7b7fd16e1d9851b3a240c60b8872503dee769b6310e786da","pinyin":"erjianbanhebingzhudongmaibanrengongbantihuanjisanjianbanchengxingshu","initials":"ejbhbzdmbrgbthjsjbcxs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-13db4a2c385bb2bbcc13","key":"v1-c9ccc21dfe2a3058|templates-13db4a2c385bb2bbcc13","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣合并主动脉瓣人工瓣替换术","category":"心血管外科临床路径（2019年版）","raw":{"name":"二尖瓣合并主动脉瓣人工瓣替换术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\r（1）血常规、尿常规、大便常规、血气分析、胸部CT平扫和二维超声心动图。\r（2）肝功能、肾功能、血电解质、血型、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）。\r（3）心电图、胸部X线平片、超声心动图。\r2.根据患者具体情况可选择的检查项目：如心肌酶、风湿活动筛查、24小时动态心电图、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、头颅CT平扫、主动脉增强CT和肺功能检查（高龄或既往有肺部病史者）、外周血管超声检查等。\r（六）预防性抗菌药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）","初步诊断":"1. 二尖瓣合并主动脉瓣人工瓣替换术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·选择用药】\n选择用药。\r2.预防性用抗菌药物：时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时，感染性瓣膜病可延长至术后4～6周。\r（七）手术日为入院5个工作日左右\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术植入物：人工瓣、瓣膜成形环、胸骨固定钢丝等。4.术中食管超声评估人工瓣膜功能。\r4.术中用药：麻醉及体外循环常规用药。\r5.输血及血液制品：视术中情况而定。\r（八）术后住院恢复7～13天\r1.术后早期持续监测治疗，观察生命体征。\r2.术后患者清醒后早期拔除气管插管。\r3.病情平稳后从术后恢复室转回普通病房。\r4.必须复查的检查项目：血常规、血电解质、肝肾功能、抗凝监测、心电图、胸部X线平片、超声心动图。\r5.根据患者新发症状或常规检查项目异常结果，必要时可进行心肌酶、头颅CT或细菌培养等检查。\r6.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r7.抗凝：根据所测INR值调整抗凝药用量，替换生物瓣膜华法林抗凝治疗至少3个月，以后改为阿司匹林75～100mg，机械瓣膜终身抗凝。\r8.根据病情需要进行强心、利尿等治疗。\r（九）","临床路径·进入路径标准":"进入路径标准\r行二尖瓣人工瓣替换术（机械瓣：ICD-9-CM-3:35.241 ；生物瓣：ICD-9-CM-3:35.231）合并主动脉瓣人工瓣膜置换术（机械瓣：ICD-9-CM-3:35.221；生物瓣：ICD-9-CM-3:35.211）\r当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（五）术前准备（评估）1～5天\r1.","临床路径·标准住院日":"标准住院日通常在10～18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管拔除、切口愈合无感染。\r3.无需要住院处理的并发症和（或）其他合并症。\r4.抗凝治疗基本稳定。\r5.胸部X线平片、超声心动图证实人工生物瓣功能良好，无相关并发症。\r（十）出院带药\r1.强心、利尿药、补钾及华法林等。\r2.出院教育及华法林抗凝方法及门诊随访。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：左室破裂、人工瓣功能障碍、心功能不全、出血、瓣周漏、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\r2.合并有其他系统疾病，可能出现合并疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r3.人工瓣的选择：根据患者的病情，使用不同的人工瓣（国产和进口），导致住院费用存在差异。\r4.合并心房颤动等严重心律失常者，需要同期行消融手术者，不进入本路径。\r5.非常规路径(胸骨正中切口)的各类微创术式，治疗费用存在差异。\r6.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长，费用增加。\r\f二、心脏二尖瓣合并主动脉瓣人工瓣替换手术","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 二尖瓣合并主动脉瓣人工瓣替换术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2275,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d63e2b7313cbe974ccb32c9ebf064310d9659ecc1bff2d821210643e215e4d0e","pinyin":"erjianbanhebingzhudongmaibanrengongbantihuanshu","initials":"ejbhbzdmbrgbths","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-3aaccc8b705db95f9d68","key":"v1-c9ccc21dfe2a3058|templates-3aaccc8b705db95f9d68","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣手术三尖瓣手术和房颤手术","category":"心血管外科临床路径（2019年版）","raw":{"name":"二尖瓣手术三尖瓣手术和房颤手术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\r（1）血常规、尿常规。\r（2）肝功能、肾功能、血电解质、血型、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）；\r（3）24小时动态心电图、心电图、胸部X线平片、超声心动图、头颅CT或MR检查。\r2.根据患者具体情况可选择的检查项目：如心肌酶、风湿活动筛查、大便常规、24小时动态心电图、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、血气分析和肺功能检查（高龄或既往有肺部病史者）、外周血管超声检查、B型脑利钠肽等。\r（七）预防性抗菌药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）","初步诊断":"1. 二尖瓣手术三尖瓣手术和房颤手术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·选择用药】\n选择用药。\r2.预防性用抗菌药物，时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时。\r（八）手术日为入院5个工作日以内\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术植入物：人工腱索、人工瓣环、人工瓣膜（机械瓣或生物瓣）、胸骨固定钢丝等。 \r4.术中用药：麻醉及体外循环常规用药。\r5.输血及血液制品：视术中情况而定。\r（九）术后住院恢复\n13天\r1.术后早期持续监测治疗，观察生命体征。\r2.必须复查的检查项目：血常规、血电解质、肝肾功能、抗凝监测、心电图、胸部X线平片、超声心动图，24小时心电图。\r3.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r4.抗凝：根据所测INR值调整抗凝药用量，根据植入物的类型决定抗凝治疗的时长。\r5.根据病情需要进行强心、利尿、补钾等治疗。\r（十）","临床路径·进入路径标准":"进入路径标准\r因二尖瓣、三尖瓣病变合并心房颤动需要行二尖瓣成形或置换术 (北京版RC022-ICD-9：35.02001，35.02003，35.12001，35.12002，35.23001，35.24001，35.33001)、三尖瓣（北京版RC022-ICD-9：35.04，35.14）合并经胸心脏射频消融改良迷宫术（北京版RC022-ICD-9：37.33001）。\r当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（五）术前准备（评估）\n5个工作日\r1.","临床路径·标准住院日":"标准住院日通常\n18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管拔除、切口愈合无感染。\r3.无需要住院处理的并发症和（或）其他合并症。\r4.抗凝治疗基本稳定。\r5.胸部X线平片、超声心动图证实二尖瓣成形术后二尖瓣启闭良好，或瓣膜置换术后人工瓣膜功能良好，无瓣周漏，无相关并发症。\r6.动态心电图未提示有需植入起搏器的心律失常。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.围手术期并发症：左室破裂、人工瓣功能障碍、心功能不全、出血、瓣周漏、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\r2.二尖瓣成形术后，二尖瓣中大量反流，需要二次手术的患者，住院时间及费用增加。\r3.心房颤动射频消融术后，需要安装永久起搏器的，住院时间及费用增加。\r4.合并有其他系统疾病，可能出现合并疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r5.非常规路径(胸骨正中切口)的各类微创术式，治疗费用存在差异。\r6.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长，费用增加。\r\f二、心脏二尖瓣病变","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 二尖瓣手术，三尖瓣手术和房颤手术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2276,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0f847dd58f37ffd6b7ef7247bbf2f99efb9f0af9a88521f7b82fedad96f1a697","pinyin":"erjianbanshoushusanjianbanshoushuhefangchanshoushu","initials":"ejbsssjbsshfcss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-4027e5b489cf8fbac9d8","key":"v1-c9ccc21dfe2a3058|templates-4027e5b489cf8fbac9d8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣手术和房颤手术","category":"心血管外科临床路径（2019年版）","raw":{"name":"二尖瓣手术和房颤手术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\r（1）血常规、尿常规。\r（2）肝功能、肾功能、血电解质、血型、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）。\r（3）心电图、胸部X线平片、超声心动图、24小时动态心电图、头颅CT或MR检查。\r2.根据患者具体情况可选择的检查项目：如心肌酶、风湿活动筛查、大便常规、24小时动态心电图、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、血气分析和肺功能检查（高龄或既往有肺部病史者）、外周血管超声检查等。\r（七）预防性抗菌药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）","初步诊断":"1. 二尖瓣手术和房颤手术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·选择用药】\n选择用药。\r2.预防性用抗菌药物，时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时。\r（八）手术日为入院5个工作日以内\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术植入物：人工腱索、人工瓣环、人工瓣膜（机械瓣或生物瓣）、胸骨固定钢丝等。 \r4.术中用药：麻醉及体外循环常规用药。\r5.输血及血液制品：视术中情况而定。\r（九）术后住院恢复\n13天\r1.术后早期持续监测治疗，观察生命体征。\r2.必须复查的检查项目：血常规、血电解质、肝肾功能、抗凝监测、心电图、胸部X线平片、超声心动图，24小时心电图。\r3.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r4.抗凝：根据所测INR值调整抗凝药用量，根据植入物的类型决定抗凝治疗的时长。\r5.根据病情需要进行强心、利尿、补钾等治疗。\r（十）","临床路径·进入路径标准":"进入路径标准\r因二尖瓣病变合并心房颤动需要行二尖瓣成形或置换术 (ICD-9-CM-3：35.02001，35.02003，35.12001，35.12002，35.23001，35.24001，35.33001)合并经胸心脏射频消融改良迷宫术（ICD-9-CM-3：37.33001）。\r当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（五）术前准备（评估）\n5个工作日\r1.","临床路径·标准住院日":"标准住院日通常\n18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管拔除、切口愈合无感染。\r3.无需要住院处理的并发症和（或）其他合并症。\r4.抗凝治疗基本稳定。\r5.胸部X线平片、超声心动图证实二尖瓣成形术后二，或瓣膜置换术后人工瓣膜功能良好，无瓣周漏，无相关并发症。\r6.动态心电图未提示有需植入起搏器的心律失常。\r尖瓣启闭良好\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：左室破裂、人工瓣功能障碍、心功能不全、出血、瓣周漏、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\r2.二尖瓣成形术后，二尖瓣中大量返流，需要二次手术的患者，住院时间及费用增加。\r3.心房颤动射频消融术后，需要安装永久起搏器的，住院时间及费用增加。\r4.合并有其他系统疾病，可能出现合并疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r5.非常规路径(胸骨正中切口)的各类微创术式，治疗费用存在差异。\r6.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长，费用增加。\r\f二、心脏二尖瓣病变","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 二尖瓣手术和房颤手术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2277,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"62090c8a81fd31cd59a381885005e5603dcb5322725d7b497673dca1353160c0","pinyin":"erjianbanshoushuhefangchanshoushu","initials":"ejbsshfcss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-34f6d056cb2555287875","key":"v1-c9ccc21dfe2a3058|templates-34f6d056cb2555287875","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣病变人工生物瓣置换术","category":"心血管外科临床路径（2019年版）","raw":{"name":"二尖瓣病变人工生物瓣置换术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\r（1）血常规、尿常规。\r（2）肝功能、肾功能、血电解质、血糖、血脂、血型、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）。\r（3）心电图、胸部X线平片、超声心动图。\r2.根据患者具体情况可选择的检查项目：如心肌酶、风湿活动筛查、大便常规、24小时动态心电图、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、血气分析和肺功能检查（高龄或既往有肺部病史者）、外周血管超声检查等。\r（六）预防性抗菌药物选择与使用时机\r1.抗菌药物使用：根据《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。并根据患者的病情决定抗菌药物的选择与使用时间。可以考虑使用第一、二代头孢菌素。\r2.预防性用抗菌药物，时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时。\r（七）手术日为入院5个工作日以内\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术植入物：人工生物瓣、胸骨固定钢丝等。\r4.术中操作：术中使用经食管超声评估瓣膜功能。\r5.术中用药：麻醉及体外循环常规用药。\r6.输血及血液制品：视术中情况而定，尽可能减少输血和血制品使用。\r（八）术后住院恢复\n13天\r1.术后早期持续监测治疗，观察生命体征。\r2.术后48小时内拔除气管插管。\r3.必须复查的检查项目：超声心动图、抗凝监测、血常规、血电解质、肝肾功能、心电图、胸部X线平片。\r4.根据患者新发症状或常规检查项目异常结果，必要时可进行头颅CT或细菌培养等检查。\r5.抗菌药物使用：根据《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。并根据患者的病情决定抗菌药物的选择与使用时间。\r6.抗凝：根据所测INR值调整抗凝药用量，抗凝治疗至少3个月。\r7.根据病情需要进行强心、利尿等治疗。\r（九）","初步诊断":"1. 二尖瓣病变人工生物瓣置换术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","临床路径·进入路径标准":"进入路径标准\r因心脏二尖瓣病变行二尖瓣生物瓣膜置换术（北京版RC022-ICD-9：35.23）。\r当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（五）术前准备（评估）\n5个工作日\r1.","临床路径·标准住院日":"标准住院日通常\n18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管拔除、切口愈合无感染。\r3.没有需要住院处理的并发症和（或）其他合并症。\r4.抗凝治疗基本稳定。\r5.胸部X线平片、超声心动图证实人工生物瓣功能良好，无相关并发症。\r6.出院医嘱\r出院带药：华法林，新型口服抗凝药，其他合并疾病治疗药物。\r患者教育：华法令抗凝方法及门诊随访。\r（十）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：左室破裂、人工瓣功能障碍、心功能不全、出血、瓣周漏、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\r2.合并有其他系统疾病，可能出现合并疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r3.人工生物瓣的选择：根据患者的病情，使用不同的生物瓣（国产和进口），导致住院费用存在差异。\r4.合并心房纤颤等严重心律失常者，需要同期行消融手术者，不进入本路径。\r5.非常规路径(胸骨正中切口)的各类微创术式，治疗费用存在差异。胸腔镜辅助或全胸腔镜下手术者不进入本路径。\r6.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长，费用增加。\r\f二、心脏二尖瓣病变","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 二尖瓣病变人工生物瓣置换术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2278,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e01f8ba2a0bbac8623df6bb42d75773c100f6a028490e34122cfcffb2a966c79","pinyin":"erjianbanbingbianrengongshengwubanzhihuanshu","initials":"ejbbbrgswbzhs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-8ab86627f72089b99d91","key":"v1-c9ccc21dfe2a3058|templates-8ab86627f72089b99d91","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二尖瓣置换合并三尖瓣成形手术","category":"心血管外科临床路径（2019年版）","raw":{"name":"二尖瓣置换合并三尖瓣成形手术","category":"心血管外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\r（1）血常规、尿常规。\r（2）肝功能、肾功能、血电解质、血糖、血脂、血型、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）。\r（3）心电图、胸部X线平片、超声心动图。\r2.根据患者具体情况可选择的检查项目：如心肌酶、风湿活动筛查、大便常规、24小时动态心电图、冠状动脉影像学检查(CT或造影)（有冠心病发病危险因素及年龄\n50岁患者）、血气分析和肺功能检查（高龄或既往有肺部病史者）、外周血管超声检查等。\r（六）预防性抗菌药物选择与使用时机\r1. 抗菌药物使用：根据《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。并根据患者的病情决定抗菌药物的选择与使用时间。\r2.预防性用抗菌药物：时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时。\r（七）手术日为入院7个工作日以内\r1.麻醉方式：全身麻醉。\r2.体外循环辅助。\r3.手术植入物：二尖瓣位人工生物瓣或机械瓣、三尖瓣成形环或成型带、胸骨固定钢丝等。 \r4.术中操作：术中使用经食管超声评估瓣膜功能\r5.术中用药：麻醉及体外循环常规用药。\r6.输血及血液制品：视术中情况而定，尽可能减少输血和血制品使用。\r（八）术后住院恢复\n11天\r1.术后早期持续监测治疗，观察生命体征。\r2.术后48小时内拔除气管插管。\r3.必须复查的检查项目：超声心动图、抗凝监测、血常规、血电解质、肝肾功能、心电图、胸部X线平片。\r4.根据患者新发症状或常规检查项目异常结果，必要时可进行头颅CT或细菌培养等检查。\r5. 抗菌药物使用：根据《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行。并根据患者的病情决定抗菌药物的选择与使用时间。\r6.抗凝：根据所测INR值调整抗凝药用量，生物瓣抗凝治疗至少3个月，机械瓣则终身抗凝。\r7.根据病情需要进行强心、利尿等治疗。\r（九）","初步诊断":"1. 二尖瓣置换合并三尖瓣成形手术","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n心脏外科学分册》（中华医学会编著，人民卫生出版社，2009年），《临床技术操作规范\n心血管外科学分册》（中华医学会编著，人民军医出版社，2009年）, 《2014年AHA/ACC瓣膜性心脏病管理指南》（美国心脏协会和美国心脏病学会编著，Journal of the American College of Cardiology，2014年）；《2017年AHA/ACC瓣膜性心脏病管理指南》（美国心脏病学会，美国心脏协会编著，Circulation，2017年），2017年欧洲瓣膜性心脏病指南（欧洲心脏病学会，欧洲心胸外科学会，European Heart Journal， 2017年）。\r1.诊断：二尖瓣病变，二尖瓣狭窄或关闭不全。\r2.完成超声检查，有下列之一者\r（1）二尖瓣狭窄，二尖瓣瓣口面积\n1.5m2。\r（2）无症状二尖瓣关闭不全，30%＜LVEF\n60%或LVESD\n40mm。\r（3）有症状的二尖瓣关闭不全，LVEF＞30%。\r3.存在三尖瓣瓣环扩大，且行二尖瓣手术同时加做三尖瓣成形术并不增加手术风险。\r（三）","临床路径·进入路径标准":"进入路径标准\r因心脏二尖瓣病变合并三尖瓣病变行二尖瓣置换术（ICD-9-CM-3：35.23001/35.24001）及三尖瓣成形术（ICD-9-CM-3：35.14001）。\r当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（五）术前准备（评估）\n7个工作日\r1.","临床路径·标准住院日":"标准住院日通常\n18天\r（四）","临床路径·出院标准":"出院标准\r1.体温正常，血常规、电解质无明显异常。\r2.引流管拔除、切口愈合无感染。\r3.无需要住院处理的并发症和（或）其他合并症。\r4.抗凝治疗基本稳定。\r5.胸部X线平片、超声心动图证实人工瓣膜功能良好三尖瓣无中度及以上反流，无相关并发症。\r6.出院医嘱\r（1）出院带药：华法林，新型口服抗凝药，其他合并疾病治疗药物\r（2）患者教育：华法林抗凝方法及门诊随访。\r（十）","临床路径·变异及原因分析":"变异及原因分析\r1.围术期并发症：左室破裂、人工瓣功能障碍、心功能不全、出血、瓣周漏、与抗凝相关的血栓栓塞和出血、溶血、感染性心内膜炎、术后伤口感染、重要脏器功能不全等造成住院日延长和费用增加。\r2.合并有其他系统疾病，可能出现合并疾病加重而需要治疗，从而延长治疗时间和增加住院费用。\r3.人工瓣膜的选择：根据患者的病情，使用不同的人工瓣膜（国产或进口），另外三尖瓣修复时是否使用人工成形环均会导致住院费用存在差异。\r4.合并心房颤动等严重心律失常者，需要同期行消融手术者，不进入本路径。\r5.非常规路径(胸骨正中切口)的各类微创术式，治疗费用存在差异。胸腔镜辅助或全胸腔镜下手术者不进入本路径。\r6.其他因素：术前心功能及其他重要脏器功能不全需调整；特殊原因（如稀有血型短缺等）造成的住院时间延长，费用增加。\r\f二、二尖瓣置换合并三尖瓣成形手术","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 心血管外科临床路径（2019年版） · 二尖瓣置换合并三尖瓣成形手术临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2279,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f266b7627d66405d1f6386cd50a294a3bbebdd167d9f531e52eca6f51d5db7c9","pinyin":"erjianbanzhihuanhebingsanjianbanchengxingshoushu","initials":"ejbzhhbsjbcxss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-f4c7c767edabb038c5ec","key":"v1-c9ccc21dfe2a3058|templates-f4c7c767edabb038c5ec","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"二甲双胍过量(降糖药)","category":"中毒/理化","raw":{"name":"二甲双胍过量(降糖药)","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】胃肠道反应：恶心、呕吐、腹痛、腹泻、食欲减退（常见）、低血糖：心慌、出汗、手抖、饥饿、头晕、意识模糊（过量时可出现）、乳酸性酸中毒（最严重）：乏力、嗜睡、呼吸深快（Kussmaul呼吸）、恶心呕吐、腹痛、意识障碍、昏迷、脱水、低血压、休克、心律失常（电解质紊乱诱发）、严重者：多器官功能衰竭、死亡、肝肾功能不全者更易发生乳酸性酸中毒。\n【待人工确认·本机素材无此段原文】","现病史":"二甲双胍（商品名格华止、美迪康、迪化唐锭）是常用双胍类降糖药，过量可引起乳酸性酸中毒（最严重并发症）、低血糖、胃肠道反应。乳酸性酸中毒病死率高，需早期识别和血液净化治疗。\n常见表现：胃肠道反应：恶心、呕吐、腹痛、腹泻、食欲减退（常见）、低血糖：心慌、出汗、手抖、饥饿、头晕、意识模糊（过量时可出现）、乳酸性酸中毒（最严重）：乏力、嗜睡、呼吸深快（Kussmaul呼吸）、恶心呕吐、腹痛、意识障碍、昏迷、脱水、低血压、休克、心律失常（电解质紊乱诱发）、严重者：多器官功能衰竭、死亡、肝肾功能不全者更易发生乳酸性酸中毒。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 动脉血气分析（含血乳酸、碳酸氢盐、AG）：入院即查，此后每2~4小时复查，评估乳酸酸中毒程度及纠酸疗效（pH<7.35伴乳酸升高为典型表现）\n2. 静脉血生化（血糖、血乳酸、K⁺、Na⁺、Cl⁻、Ca²⁺、肌酐、尿素氮、肝酶）：入院即查，每6~8小时复查；肌酐为血液透析指征评估的关键指标\n3. 血清二甲双胍浓度（本院可行时）：服药后4~6小时采血，浓度＞5μg/mL提示中毒，用于确诊及预后判断\n4. 床旁心电图＋持续心电监护：入院即查，动态复查，筛查高钾血症及心律失常\n5. 血常规、凝血功能、尿常规（含酮体）：入院即查，排除感染、出血及糖尿病酮症酸中毒","初步诊断":"1. 二甲双胍过量服用史\n2. 低血糖症状（血糖<2.8mmol/L）\n3. 乳酸性酸中毒：血乳酸>5mmol/L，阴离子间隙增大，代谢性酸中毒\n4. 血气分析：pH降低，HCO3-降低\n5. 血糖降低或正常\n6. 肝肾功能检查（评估基础疾病）\n7. 电解质：低钾/高钾（酸中毒时）\n8. 排除其他原因乳酸酸中毒（休克、缺氧、肝衰等）\n1. 二甲双胍过量(降糖药)（ICD-10：T38.3）","鉴别诊断":"1. 排除其他原因乳酸酸中毒（休克、缺氧、肝衰等）\n2. 诊断要点：二甲双胍过量服用史\n3. 诊断要点：低血糖症状（血糖<2.8mmol/L）\n4. 诊断要点：乳酸性酸中毒：血乳酸>5mmol/L，阴离子间隙增大，代谢性酸中毒\n5. 诊断要点：血气分析：pH降低，HCO3-降低\n6. 诊断要点：血糖降低或正常\n7. 诊断要点：肝肾功能检查（评估基础疾病）","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：50%葡萄糖 40-60ml静注（低血糖时），随后10%葡萄糖维持\n\n方案2：\n 用法：5%碳酸氢钠 静滴（乳酸性酸中毒，pH<7.2时）\n\n方案3：\n 用法：生理盐水/林格液 静滴（补液、纠正脱水）\n\n方案4：\n 用法：氯化钾 静滴（纠正低钾，注意监测）\n\n方案5：\n 用法：维生素B1 100mg肌注/静注（预防Wernicke脑病，慢性酗酒者）\n\n方案6：\n 用法：纳洛酮 0.4-0.8mg静注（意识障碍时）\n\n方案7：\n 用法：升压药（休克时）\n\n方案8：\n 用法：胰岛素（高血糖时，小剂量）\n\n方案9：\n 用法：呼吸兴奋剂（呼吸抑制时）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：葡萄糖水/糖果（低血糖清醒者口服）\n\n药物2：\n 用法：碳酸氢钠片（轻症酸中毒）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n口服者立即催吐、洗胃（温水），洗胃后活性炭吸附，导泻\n低血糖者：清醒者口服糖水/糖果，昏迷者50%葡萄糖静注，随后10%葡萄糖维持\n乳酸性酸中毒：大量补液、纠正酸中毒（碳酸氢钠）、维持循环功能\n严重乳酸性酸中毒者尽早行血液透析（可清除二甲双胍和乳酸）\n对症支持：纠正电解质紊乱、保护肝肾功能、防治感染\n持续监测血糖、血气、乳酸、电解质\n呼吸衰竭者机械通气\n休克者抗休克治疗\n禁用：乳酸林格液（加重乳酸负荷）\n恢复期调整降糖方案\n\n【处理要点】\n口服者立即催吐，尽快送医洗胃\n低血糖清醒者立即口服糖水/糖果/饼干\n昏迷者不要喂食（防止误吸），立即送医静注葡萄糖\n监测血糖变化\n记录服药剂量、时间、平时血糖控制情况\n观察呼吸频率和深度（Kussmaul呼吸提示酸中毒）\n监测血压、心率、意识状态\n老年人、肝肾功能不全者风险更高\n告知患者降糖药应按医嘱服用，不可自行加量\n\n【护理】\n洗胃配合：服药后1~2小时内就诊且神志清醒者配合催吐或洗胃；意识不清、有误吸风险者先协助气管插管再洗胃，洗胃液用温清水，洗胃后保留胃管观察有无出血\n解毒剂观察：二甲双胍无特效解毒剂，重点观察5%碳酸氢钠纠酸过程中的pH、血乳酸、血钾变化及输液外渗；密切观察深大呼吸（Kussmaul呼吸）、意识改变、低血压等乳酸酸中毒征象，及时报告\n生命体征与血糖监测：每15~30分钟监测生命体征，每1小时测末梢血糖，鉴别低血糖与酸中毒所致神志改变；记录24小时出入量，警惕少尿及肾功能恶化\n气道与防误吸：意识障碍者取侧卧位或头偏向一侧，床边备吸引器；频繁呕吐者暂禁食，必要时胃肠减压，防止误吸及吸入性肺炎\n并发症观察：监测心律及血压变化，观察消化道出血、感染、休克征象；严重酸中毒（pH<7.1）、肾衰竭者配合血液透析/CRRT治疗及管路护理\n\n【饮食】\n洗胃或胃肠减压后暂禁食4~6小时，观察无恶心、呕吐、腹痛后再逐步恢复进食\n恢复进食以温凉流质（米汤、稀粥、藕粉）为主，少量多餐，避免生冷、辛辣及过热食物刺激胃黏膜\n监测血糖调整饮食：进食后继续定时测血糖，血糖偏低时及时进食含糖食物（糖水、饼干）或遵医嘱静脉输注葡萄糖\n补液：清醒患者鼓励少量多次口服温水或口服补液盐，配合静脉补液纠正脱水与循环不足；监测尿量，保持尿量＞30ml/h\n忌饮酒及含酒精饮料（加重乳酸酸中毒），忌暴饮暴食；肾功能异常者遵医嘱限制蛋白质及高钾食物\n\n【注意事项】\n二甲双胍本身不引起低血糖，但过量时可出现低血糖\n乳酸性酸中毒是二甲双胍最严重的并发症，病死率高（>50%）\n乳酸性酸中毒诱因：肝肾功能不全、心衰、缺氧、严重感染、酗酒、大剂量\n血乳酸>5mmol/L伴酸中毒即可诊断乳酸性酸中毒\n血液透析是严重乳酸性酸中毒的有效治疗手段\n造影检查前后48小时应暂停二甲双胍（造影剂肾病风险）\n老年人、肝肾功能不全者应减量或禁用\n服用二甲双胍期间应定期监测肾功能、乳酸\n\n【急诊/急救】\n口服者立即催吐，尽快温水洗胃\n低血糖者口服糖水/糖果，昏迷者50%葡萄糖静注\n保持呼吸道通畅\n监测血糖、血气、乳酸\n乳酸性酸中毒者碳酸氢钠静滴\n严重者尽快血液透析","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「二甲双胍过量(降糖药)」原文）"},"icd10_diagnosis":"T38.3","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2280,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"87cd61e62e5e3475c1d8f22f3f2d4b03861b003f7cafef59f4e96e52b592b27f","pinyin":"erjiashuangguaguoliang(jiangtangyao)","initials":"ejsggl(jty)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T38.3",30]]},{"id":"templates-d3c641d5928f28aeda55","key":"v1-c9ccc21dfe2a3058|templates-d3c641d5928f28aeda55","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"亚硝酸盐中毒","category":"院前急救","raw":{"name":"亚硝酸盐中毒","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】口唇、指甲、面部发绀（青紫色，特征性）、头晕、头痛、乏力、胸闷、呼吸困难、心悸、心率快、恶心呕吐、严重者：血压下降、心律失常、抽搐、昏迷、呼吸循环衰竭、发绀与呼吸困难不成比例（吸氧不缓解）。\n【待人工确认·本机素材无此段原文】","现病史":"亚硝酸盐使血红蛋白氧化为高铁血红蛋白，失去携氧能力，致组织缺氧。常见于食用腌制不透的蔬菜、变质蔬菜、误将亚硝酸盐当食盐。\n常见表现：口唇、指甲、面部发绀（青紫色，特征性）、头晕、头痛、乏力、胸闷、呼吸困难、心悸、心率快、恶心呕吐、严重者：血压下降、心律失常、抽搐、昏迷、呼吸循环衰竭、发绀与呼吸困难不成比例（吸氧不缓解）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 血常规+高铁血红蛋白（MetHb）定量测定——首诊必查，评估缺氧程度及亚甲蓝用药指征（MetHb>30%或症状明显时立即给药，治疗中动态复查）\n2. 动脉血气分析（含乳酸、MetHb）——评估缺氧、酸中毒及组织灌注，监测疗效\n3. 血清电解质+肝肾功能+血糖——排除低氧性损伤及代谢紊乱，指导补液与纠酸\n4. 毒物检测（剩余可疑食物/水源、呕吐物送毒理分析，查亚硝酸盐/硝酸盐含量）——明确毒源，评估共同进食者风险\n5. 心电图——排查缺氧所致心肌缺血、心律失常；重症者持续心电监护\n6. 胸部CT或胸片——用于可疑呕吐误吸或重症低氧、怀疑ARDS者","初步诊断":"1. 进食腌制/变质蔬菜、卤味、苦井水史（同食者多人发病）\n2. 特征性发绀（口唇指甲青紫色）\n3. 发绀但呼吸困难不重，吸氧不能缓解\n4. 高铁血红蛋白测定（>10%）\n5. 亚硝酸盐定性试验\n1. 亚硝酸盐中毒（ICD-10：T65.0）","鉴别诊断":"1. 诊断要点：进食腌制/变质蔬菜、卤味、苦井水史（同食者多人发病）\n2. 诊断要点：特征性发绀（口唇指甲青紫色）\n3. 诊断要点：发绀但呼吸困难不重，吸氧不能缓解\n4. 诊断要点：高铁血红蛋白测定（>10%）\n5. 诊断要点：亚硝酸盐定性试验\n6. 亚甲蓝是特效解毒剂，1-2mg/kg缓慢静推\n7. 亚甲蓝小剂量是还原剂（治疗），大剂量是氧化剂（加重中毒），不要过量\n8. 发绀吸氧不缓解+进食腌菜/卤味史应高度怀疑\n9. 维生素C和葡萄糖是辅助治疗\n10. 亚硝酸盐中毒又称肠源性发绀","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：亚甲蓝（美蓝）1-2mg/kg + 5%GS 20ml 缓慢静推（特效解毒剂，>10min）\n\n方案2：\n 用法：维生素C 2-3g + 5%GS 500ml 静滴（辅助还原）\n\n方案3：\n 用法：0.9%氯化钠 静滴\n\n方案4：\n 用法：50%葡萄糖 40-60ml 静推\n\n方案5：\n 用法：地塞米松 10-20mg 静滴（重症）\n\n方案6：\n 用法：必要时输血/换血（严重者）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：温水催吐（清醒者）\n\n药物2：\n 用法：维生素C片\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n脱离毒源，催吐、洗胃、导泻\n亚甲蓝（特效解毒剂）\n维生素C+葡萄糖辅助\n吸氧\n重症：输血/换血、血液净化\n对症支持（升压、抗抽搐）\n\n【处理要点】\n立即催吐（清醒者），温水洗胃，硫酸镁导泻\n吸氧（发绀明显者）\n建立静脉通路\n亚甲蓝1-2mg/kg（1%溶液5-10ml）+5%GS 20ml缓慢静推（>10min），发绀通常15-30min缓解，1-2h可重复半量\n维生素C 2-3g+5%GS静滴\n高渗葡萄糖\n地塞米松（重症）\n监测：高铁血红蛋白、血气、生命体征\n抽搐：地西泮\n严重中毒（高铁Hb>50%）：输血/换血疗法\n识别中毒来源（腌菜、卤味、苦井水、误作食盐），防止继续食用\n亚甲蓝注意：剂量过大（>7mg/kg）反而加重高铁血红蛋白血症\n\n【护理】\n立即予高流量面罩吸氧（6-10L/min），监测SpO2及神志、皮肤黏膜发绀变化；SpO2下降或烦躁加重时立即通知医师准备亚甲蓝静脉注射\n严密监测生命体征（血压、心率、呼吸、SpO2）及心电图，每15-30分钟记录一次，发现低血压、心律失常或呼吸抑制立即报告并配合抢救\n开放两条静脉通路（一条专用输注亚甲蓝，需避光保存、缓慢静推，注意药液外渗），同时建立急救配合流程：备好气管插管、呼吸机及升压药物\n评估恶心、呕吐情况，保持头偏向一侧防误吸，及时清理口腔分泌物；必要时留置胃管洗胃，洗胃液观察颜色（亚硝酸盐中毒可呈咖啡色）\n记录出入量，避免过量补液诱发肺水肿；重症患者监测每小时尿量，警惕急性肾功能损伤及弥散性血管内凝血（DIC）征象（皮肤瘀点、穿刺部位渗血）\n\n【饮食】\n中毒急性期（洗胃后、神志未完全清醒或恶心呕吐明显者）暂禁食，经静脉补液维持水电解质平衡\n神志清醒、呕吐缓解后予温凉流质饮食（米汤、藕粉、稀粥），少量多餐，避免过烫刺激\n忌食腌制食品（咸菜、腊肉、香肠）、久置剩菜及含亚硝酸盐食物，恢复期1周内禁食菠菜、甜菜根等含硝酸盐较高的蔬菜\n适量补充维生素C（口服或经医嘱静脉给予），多吃新鲜水果蔬菜以还原高铁血红蛋白、促进恢复\n恢复期逐步过渡至半流质、软食，保证充足饮水（每日1500-2000ml），促进代谢产物排泄；若为水源性中毒，改用安全饮水\n\n【注意事项】\n亚甲蓝是特效解毒剂，1-2mg/kg缓慢静推\n亚甲蓝小剂量是还原剂（治疗），大剂量是氧化剂（加重中毒），不要过量\n发绀吸氧不缓解+进食腌菜/卤味史应高度怀疑\n维生素C和葡萄糖是辅助治疗\n亚硝酸盐中毒又称肠源性发绀\n\n【急诊/急救】\n催吐、温水洗胃、硫酸镁导泻\n吸氧，建立静脉通路\n亚甲蓝1-2mg/kg（1%溶液5-10ml）+5%GS 20ml缓慢静推（>10min），15-30min见效，1-2h可重复半量\n维生素C 2-3g+5%GS 500ml静滴+50%葡萄糖40-60ml静推\n地塞米松10-20mg静滴（重症）\n抽搐：地西泮10mg静推\n高铁Hb>50%或亚甲蓝无效→输血/换血\n查找中毒来源，同食者均需观察","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「亚硝酸盐中毒」原文）"},"icd10_diagnosis":"T65.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2281,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"aad755f90c0641f221c6f9cb4f78fc10064454e315c077da58dad88e493d9b42","pinyin":"yaxiaosuanyanzhongdu","initials":"yxsyzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T65.0",30]]},{"id":"templates-577324733693f5b4dc51","key":"v1-c9ccc21dfe2a3058|templates-577324733693f5b4dc51","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"亚硝酸盐中毒(工业盐)","category":"中毒/理化","raw":{"name":"亚硝酸盐中毒(工业盐)","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】潜伏期：10分钟-3小时、口唇、指甲、面部发绀（蓝灰色/紫褐色，特征性表现）、头痛头晕、乏力、恶心呕吐、腹痛腹泻、胸闷、气短、呼吸困难、心悸、中度中毒：皮肤黏膜明显发绀，精神萎靡，反应迟钝、重度中毒：严重发绀，昏迷、抽搐、休克、呼吸衰竭、心律失常、严重者可因呼吸循环衰竭死亡、静脉血呈蓝褐色/巧克力色（特征性）。\n【待人工确认·本机素材无此段原文】","现病史":"亚硝酸盐（工业盐、亚硝酸钠，常见于腌制食品、变质蔬菜、工业盐冒充食盐）将血红蛋白中二价铁氧化为三价铁，形成高铁血红蛋白，导致组织缺氧。典型表现为发绀、呼吸困难。亚甲蓝（美蓝）是特效解毒剂。\n常见表现：潜伏期：10分钟-3小时、口唇、指甲、面部发绀（蓝灰色/紫褐色，特征性表现）、头痛头晕、乏力、恶心呕吐、腹痛腹泻、胸闷、气短、呼吸困难、心悸、中度中毒：皮肤黏膜明显发绀，精神萎靡，反应迟钝、重度中毒：严重发绀，昏迷、抽搐、休克、呼吸衰竭、心律失常、严重者可因呼吸循环衰竭死亡、静脉血呈蓝褐色/巧克力色（特征性）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 血高铁血红蛋白（MetHb）浓度测定：动脉血，治疗前采血送检，亚甲蓝患者后1～2小时复查评估疗效\n2. 动脉血气分析（含SaO2、乳酸）：评估缺氧及组织灌注；注意SpO2可假性偏高，与发绀程度不符时以血气为准\n3. 残余可疑食物、呕吐物亚硝酸盐定性/定量检测（送疾控或毒物分析机构）\n4. 血常规：观察红细胞形态，筛查高铁血红蛋白血症继发溶血\n5. 肝肾功能、电解质、血糖：评估多器官受累，指导补液及纠酸\n6. 心电图及心肌酶：监测心律失常、心肌缺血（重度缺氧时易出现）","初步诊断":"1. 亚硝酸盐摄入史（工业盐、腌制食品、变质蔬菜、苦井水）\n2. 典型发绀表现（口唇指甲蓝灰色），与呼吸困难不成比例\n3. 高铁血红蛋白测定>10%（正常<1%）\n4. 静脉血呈蓝褐色，在空气中振荡不变红（与正常血区别）\n5. 血气分析：氧分压正常或降低，血氧饱和度降低\n6. 剩余食物/呕吐物/尿中亚硝酸盐检测阳性\n7. 亚甲蓝治疗有效（支持诊断）\n1. 亚硝酸盐中毒(工业盐)（ICD-10：T65.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：亚甲蓝（美蓝）1-2mg/kg（1%溶液5-10ml）+25%葡萄糖20-40ml缓慢静注（10-15分钟），特效解毒剂\n\n方案2：\n 用法：如1-2小时后发绀不消退，可重复半量\n\n方案3：\n 用法：维生素C 1-2g+葡萄糖静滴（辅助还原高铁血红蛋白）\n\n方案4：\n 用法：高渗葡萄糖+胰岛素静滴（促进代谢）\n\n方案5：\n 用法：辅酶A 50-100U肌注/静滴（增强亚甲蓝疗效）\n\n方案6：\n 用法：维生素B12 肌注（辅助）\n\n方案7：\n 用法：吸氧（高流量）\n\n方案8：\n 用法：呼吸兴奋剂（呼吸抑制时）\n\n方案9：\n 用法：升压药（休克时）\n\n方案10：\n 用法：20%甘露醇（脑水肿时）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：维生素C片 0.2g tid（恢复期）\n\n药物2：\n 用法：亚甲蓝片（轻症可口服，3-5mg/kg）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即停止食用可疑食物，催吐、洗胃（温水/1:5000高锰酸钾），导泻\n高流量吸氧，保持呼吸道通畅\n亚甲蓝是特效解毒剂，早期足量使用\n维生素C静滴辅助治疗\n对症支持：纠正休克、呼吸衰竭、脑水肿\n严重者可输新鲜血或换血疗法\n监测高铁血红蛋白水平，指导治疗\n保留剩余食物、呕吐物送检\n同时治疗一起进食的其他人（集体发病）\n\n【处理要点】\n立即停止食用可疑食物，保留剩余食物送检\n口服者立即催吐，尽快送医洗胃\n让患者平卧，吸氧，减少活动，降低耗氧\n观察口唇、指甲颜色变化（发绀程度）\n记录进食时间、食物种类、发病时间\n集体发病时同时治疗所有患者\n监测生命体征、血氧饱和度\n呼吸困难者立即人工呼吸，尽快送医\n\n【护理】\n高流量面罩吸氧（6～10L/min），持续心电、血压、呼吸、SpO2监测；发绀明显而SpO2不低提示高铁血红蛋白血症，勿延误亚甲蓝治疗\n亚甲蓝给药护理：1～2mg/kg缓慢静注，严格观察注射部位防止外渗（可致组织坏死），用药后观察发绀消退情况并配合复查MetHb；注意恶心、胸闷及大剂量（>7mg/kg）致溶血等不良反应\n早期（服毒2小时内）洗胃配合：左侧卧位、头低脚高位防误吸，洗胃后保持气道通畅，观察呕吐物有无咖啡渣样物及上消化道出血\n建立大静脉通道，配合补液纠正低血压；记录尿量、尿色，警惕溶血后酱油色尿及急性肾损伤\n\n【饮食】\n洗胃后暂禁食2～4小时，恶心呕吐缓解后予温流质（米汤、稀粥），少量多餐\n鼓励多饮水或遵医嘱静脉补液，促进亚硝酸盐经尿排出\n饮食宜清淡，多食富含维生素C的新鲜蔬果汁，可配合口服维生素C辅助还原高铁血红蛋白\n忌饮酒及辛辣刺激性食物；住院期间及出院后避免腌制、熏制等含亚硝酸盐食品\n\n【注意事项】\n亚硝酸盐中毒又称肠源性紫绀，特效解毒剂是亚甲蓝（美蓝）\n亚甲蓝剂量要准确：小剂量（1-2mg/kg）是还原剂（治疗），大剂量（>5mg/kg）是氧化剂（加重中毒）\n亚甲蓝静注过快可引起恶心、呕吐、胸闷、头晕\n亚甲蓝可使尿液呈蓝色，属正常现象\nG6PD缺乏者禁用亚甲蓝（可引起溶血），可用维生素C+输新鲜血\n腌制食品、变质蔬菜、苦井水含亚硝酸盐较高，不宜食用\n工业盐（亚硝酸钠）外观与食盐相似，严禁当食盐使用\n\n【急诊/急救】\n立即停止食用可疑食物，催吐洗胃\n高流量吸氧\n亚甲蓝1-2mg/kg+25%葡萄糖缓慢静注（特效）\n维生素C 1-2g静滴\n呼吸困难者人工呼吸\n保留剩余食物送检","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T65.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2282,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"83cf9c15d70e07c12835d3107083717dfe9276b6b8a2242341ae2ef833dcf6ad","pinyin":"yaxiaosuanyanzhongdu(gongyeyan)","initials":"yxsyzd(gyy)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T65.0",30]]},{"id":"templates-08245121d49409ec297e","key":"v1-c9ccc21dfe2a3058|templates-08245121d49409ec297e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"产后大出血","category":"院前急救","raw":{"name":"产后大出血","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】阴道大量流血、头晕、心慌、出冷汗、面色苍白、血压下降、心率增快、子宫软、轮廓不清（宫缩乏力）、胎盘娩出不全、阴道/宫颈裂伤、伤口渗血不止（凝血障碍）。\n【待人工确认·本机素材无此段原文】","现病史":"胎儿娩出后24h内阴道流血>500ml（剖宫产>1000ml），是我国孕产妇死亡首位原因。四大原因：宫缩乏力、胎盘因素、软产道损伤、凝血障碍。\n常见表现：阴道大量流血、头晕、心慌、出冷汗、面色苍白、血压下降、心率增快、子宫软、轮廓不清（宫缩乏力）、胎盘娩出不全、阴道/宫颈裂伤、伤口渗血不止（凝血障碍）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 血常规（急诊必查，动态监测Hb、Hct、血小板，评估失血程度，每1~2小时复查一次）\n2. 血型鉴定及交叉配血（紧急配血，同步启动备血流程，准备红细胞、血浆、血小板）\n3. 凝血功能（PT、APTT、Fib、D-二聚体，筛查消耗性凝血病及羊水栓塞，必要时行血栓弹力图TEG）\n4. 动脉血气分析（含乳酸，评估休克深度、酸碱失衡及组织灌注，酌情动态复查）\n5. 血生化（电解质、肝肾功能、血钙、血糖，指导补液与纠酸补钙）\n6. 床旁超声（评估宫腔积血、胎盘胎膜残留及子宫收缩情况；疑子宫破裂时加查腹盆腔超声并评估腹腔积液）","初步诊断":"1. 胎儿娩出后阴道流血\n2. 失血性休克表现\n3. 检查子宫硬度、胎盘完整性、软产道、凝血功能\n4. 宫缩乏力：子宫软、按摩后变硬出血减少\n5. 胎盘因素：胎盘残留/植入\n6. 软产道损伤：胎儿娩出后立即出血、鲜红\n1. 产后大出血（ICD-10：O72.1）","鉴别诊断":"1. 诊断要点：胎儿娩出后阴道流血\n2. 诊断要点：失血性休克表现\n3. 诊断要点：检查子宫硬度、胎盘完整性、软产道、凝血功能\n4. 诊断要点：宫缩乏力：子宫软、按摩后变硬出血减少\n5. 诊断要点：胎盘因素：胎盘残留/植入\n6. 诊断要点：软产道损伤：胎儿娩出后立即出血、鲜红\n7. 产后出血重在预防和早期识别\n8. 出血量估计常偏少（目测约为实际一半）\n9. 宫缩乏力最常见（70%-80%）\n10. 不要只关注阴道流血，内出血（宫腔积血）也可休克\n11. 卡前列素哮喘/青光眼禁用","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：0.9%氯化钠/复方氯化钠 快速静滴\n\n方案2：\n 用法：缩宫素 10-20U 宫体注射/静滴\n\n方案3：\n 用法：卡前列素氨丁三醇（欣母沛）250μg 肌注（宫缩乏力）\n\n方案4：\n 用法：甲硝唑/头孢类预防感染\n\n方案5：\n 用法：大量输血（红细胞+血浆+血小板按比例）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：米索前列醇 400-600μg 舌下/直肠给药（宫缩乏力）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n针对病因处理（4T：Tone张力、Tissue组织、Trauma损伤、Thrombin凝血）\n子宫按摩+宫缩剂\n清宫（胎盘残留）\n缝合软产道裂伤\n纠正凝血障碍\n抗休克、输血\n子宫动脉栓塞/子宫切除（难治性）\n\n【处理要点】\n立即按摩子宫（双手法）\n缩宫素10-20U静滴/宫体注射\n检查胎盘是否完整，残留则清宫\n检查宫颈、阴道壁有无裂伤，立即缝合\n建立两条大口径静脉通路，快速补液\n抽血查血型、交叉配血、凝血功能\n紧急输血\n留置尿管记尿量\n卡前列素/米索前列醇加强宫缩\n凝血障碍补充凝血因子、血小板\n监测生命体征\n经上述处理无效：子宫动脉栓塞或子宫切除\n\n【护理】\n建立至少两条粗大静脉通道（16~18G留置针），快速输注晶体液及配血输血，严格执行输血查对制度，准确记录出入量\n心电监护，每5~15分钟监测血压、心率、呼吸、血氧饱和度及体温，密切观察神志、面色、四肢皮温及末梢循环，早期识别休克征象（脉细速、皮肤湿冷、少尿）\n留置尿管记录每小时尿量（维持≥30ml/h），采用称重法/容积法准确评估阴道出血量，观察血液颜色及有无凝血块，警惕隐性出血\n配合医生行宫底按摩、徒手压迫、宫腔球囊填塞等止血操作，备好缩宫素、卡前列素氨丁三醇等药物并遵医嘱及时给药\n保持呼吸道通畅，去枕平卧或头低足高位，面罩高流量吸氧，呕吐时头偏向一侧防误吸；保暖，预防坠床及二次损伤\n\n【饮食】\n活动性出血未控制及抢救期：禁食禁水，以防误吸并为急诊手术、麻醉及宫腔操作留出安全空间\n出血控制、生命体征平稳后：先试少量温开水，无恶心呕吐再过渡至清流质（米汤、藕粉），少量多餐\n流质期忌牛奶、豆浆及含糖产气饮食，避免腹胀加重胃肠负担；同时经静脉补液维持水电解质平衡\n恢复期给予高蛋白、高维生素、富含铁饮食（瘦肉、动物肝脏、蛋类、深色蔬菜），补充造血原料，配合口服铁剂及维生素C促进吸收\n饮食过渡期间观察有无恶心、腹胀、腹痛，进食量不足或贫血明显者继续静脉营养及成分输血支持\n\n【注意事项】\n产后出血重在预防和早期识别\n出血量估计常偏少（目测约为实际一半）\n宫缩乏力最常见（70%-80%）\n不要只关注阴道流血，内出血（宫腔积血）也可休克\n卡前列素哮喘/青光眼禁用\n\n【急诊/急救】\n立即双手按摩子宫（一手阴道前穹窿顶起子宫，一手经腹按摩宫底）\n缩宫素10-20U+5%GS 500ml静滴，或10U宫体注射\n卡前列素氨丁三醇250μg肌注（哮喘禁用），可15-30min重复，总量≤2mg\n米索前列醇600μg舌下/直肠给药\n检查胎盘完整性，残留立即清宫\n检查软产道，裂伤立即缝合\n建立两条大口径静脉通路，快速补液+紧急配血输血\n抽血查凝血功能、DIC筛查\n留置尿管监测尿量\n凝血障碍：补充新鲜冰冻血浆、血小板、纤维蛋白原\n无效：子宫动脉栓塞或子宫切除（保命）","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「产后大出血」原文）"},"icd10_diagnosis":"O72.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2283,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"86964d7d65659101ea6059a0906915bccf5df2622bb3cef4e28311d48d5b3d6e","pinyin":"chanhoudachuxue","initials":"chdcx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","O72.1",30]]},{"id":"templates-527b2f6b8d0730314b0a","key":"v1-c9ccc21dfe2a3058|templates-527b2f6b8d0730314b0a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"产后恶露不绝(中医辨证)","category":"中医","raw":{"name":"产后恶露不绝(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】气虚：产后恶露过期不止，量多，色淡红，质清稀，无臭味，精神倦怠，四肢无力，气短懒言，小腹空坠，舌淡苔薄白，脉细弱、血热：产后恶露过期不止，量较多，色深红，质稠黏，有臭秽气，面色潮红，口燥咽干，舌红苔黄，脉细数、血瘀：产后恶露淋漓涩滞不畅，量时多时少，色紫暗，有血块，小腹疼痛拒按，舌紫暗或有瘀点，脉弦涩。\n【待人工确认·本机素材无此段原文】","现病史":"产后恶露持续3周以上仍淋漓不尽者，称产后恶露不绝。分气虚、血热、血瘀等证型。可见于子宫复旧不全、宫腔残留、产褥感染等。\n常见表现：气虚：产后恶露过期不止，量多，色淡红，质清稀，无臭味，精神倦怠，四肢无力，气短懒言，小腹空坠，舌淡苔薄白，脉细弱、血热：产后恶露过期不止，量较多，色深红，质稠黏，有臭秽气，面色潮红，口燥咽干，舌红苔黄，脉细数、血瘀：产后恶露淋漓涩滞不畅，量时多时少，色紫暗，有血块，小腹疼痛拒按，舌紫暗或有瘀点，脉弦涩。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：面色、神、舌诊（舌质/舌苔）、月经（量色质）、带下（量色质气味）\n闻诊：声音、经带气味\n问诊：月经史（初潮/周期/经期/经量/色质）、带下史、婚育史、既往史、十问歌\n切诊：脉诊、腹诊（小腹压痛/包块）\n辨证：脏腑辨证（肝肾脾）、气血辨证、冲任督带辨证","辅助检查":"检查计划：患者产后恶露持续3周以上仍淋漓不尽，量多色淡红、质清稀者属气虚，色深红质稠黏、有臭秽气者属血热，色紫暗有血块、小腹疼痛拒按者属血瘀，可见于子宫复旧不全、宫腔残留、产褥感染等，需先明确病因再辨证施治。完善血常规检查了解有无感染及贫血情况，恶露臭秽伴发热者尤需据此评估产褥感染；完善妇科B超检查了解宫腔有无残留物、子宫复旧情况及内膜回声，以明确是否存在胎盘胎膜残留及宫腔积血；完善凝血功能检查排除凝血机制异常所致出血；恶露量多、持续时间长者完善肝肾功能与电解质检查，为后续用药及补液方案提供依据；查血HCG或尿妊娠试验排除妊娠滋养细胞疾病所致阴道流血；对恶露臭秽、发热、下腹压痛明显者完善CRP、降钙素原检查了解感染程度，并完善宫颈分泌物培养及药物敏感试验，明确致病菌以指导抗感染用药；必要时完善宫腔镜检查明确宫腔内病变性质，同时行诊断性刮宫加内膜病理检查以排除子宫内膜病变；入院即刻完善心电图及血压、体温等生命体征监测，评估贫血及感染对循环的影响。同时观察舌质舌苔与脉象的动态变化，为气虚、血热、血瘀的辨证分型及中药方剂调整提供依据。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 产后恶露持续>3周仍淋漓不尽\n2. 妇科B超（排除宫腔残留）、血常规（感染/贫血评估）\n3. 恶露臭秽、发热者警惕产褥感染\n1. 产后恶露不绝(中医辨证)（ICD-10：O72.3）","鉴别诊断":"1. 妇科B超（排除宫腔残留）、血常规（感染/贫血评估）","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药调理为主\n\n方案2（出血量多/贫血明显）：\n 用法：5%GS250ml+酚磺乙胺1.0g ivgtt qd；NS500ml+维生素C2.0g ivgtt qd\n\n方案3（合并感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。妊娠期、哺乳期用药务必谨慎！\n\n药物1（气虚）：补中益气丸6g tid，或八珍颗粒6g tid\n药物2（血热）：宫血宁胶囊3粒 tid，或断血流片4片 tid\n药物3（血瘀）：生化丸1丸 tid，或益母草颗粒15g tid\n药物4（配合）：缩宫素10U im qd（促进宫缩，遵医嘱）\n\n【治疗】\n气虚：补气摄血，固冲止漏，补中益气汤加减\n血热：养阴清热，凉血止血，保阴煎加减\n血瘀：活血化瘀，理血归经，生化汤加减\n\n【处理要点】\n注意休息，避免过早劳动\n保持外阴清洁，勤换卫生巾，禁盆浴、性生活\n加强营养，多食含铁食物\n\n【护理】\n病情观察：每日观察并记录恶露的量、色、质、气味及有无血块，恶露由红转淡、由多变少为顺；若突然增多、色鲜红夹大血块、气味臭秽或伴发热腹痛，立即报告医师，警惕产后大出血及产褥感染。\n气虚证施护：以静养为主，卧床休息，避免久站、久坐、过早操劳及大声说话耗气，以防劳则气耗、摄血无力；劝导勿过度忧思，保持大便通畅，勿努责下气。\n血瘀证施护：注意小腹保暖，避免受寒，可用热水袋温敷或温灸关元、气海以温经活血、促进瘀血排出；观察血块排出后腹痛是否减轻，若腹痛不减反剧、恶露涩少，及时报告。\n血热证施护：嘱忌劳累、忌熬夜伤阴，静心安神、戒恼怒急躁，以免气火上冲、迫血妄行；恶露量多色鲜红时嘱绝对卧床并及时报告，避免过多活动。\n煎药服药护理：温经活血之品（如益母草、生化汤类）宜温服，清热凉血之品宜温凉服，忌冷服伤中；服药后观察恶露排出情况，出现腹痛加剧或血量骤增立即停药并报告。\n\n【饮食】\n气虚证：宜食益气摄血、温补易消化之品，如山药、大枣、小米、乌鸡、牛肉、鸡蛋；忌生冷瓜果、冷饮及肥甘碍胃之品；药膳可选黄芪炖母鸡、党参山药红枣粥。\n血瘀证：宜食活血化瘀、温通行滞之品，如山楂、红糖、益母草、桃仁、黑木耳；忌生冷寒凉及酸涩收敛之品（如酸梅、乌梅、柿子），以免寒凝气滞、血行不畅；药膳可选益母草红糖饮、山楂红糖水。\n血热证：宜食清热凉血、养阴生津之品，如鲜藕、荸荠、梨、百合、芹菜、绿豆；忌辛辣温燥助热之品（如辣椒、胡椒、羊肉、桂圆、荔枝及酒），忌盲目进补温补药膳；药膳可选鲜藕汁、生地粥、荸荠汁。\n共性调护：饮食宜清淡细软、少食多餐，保证营养以助气血生化；忌辛辣刺激、肥甘厚味及生冷不洁之食，忌活血与收敛固涩之品混杂服用，观察食欲及恶露变化以调整膳食。\n\n【注意事项】\n恶露臭秽、发热腹痛者警惕产褥感染，及时就医\nB超示宫腔残留明显者需清宫\n出血量多伴休克立即急诊\n\n【急诊/急救】\n一般不需急救\n大出血伴休克：立即急诊抢救\n宫外孕破裂/急性腹痛：立即转妇科急诊","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「产后恶露不绝（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】产后恶露不绝\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、气虚\n    症状舌脉：恶露过期不尽，量多，色淡，质稀，无臭气，面色㿠白，神疲懒言，四肢无力，小腹空坠，舌淡、苔薄白，脉缓弱\n    治法：补气摄血固冲\n    方剂：补中益气汤\n\n二、血热\n    症状舌脉：恶露过期不尽，量较多，色深红，质黏稠，气臭秽，口燥咽干，面色潮红，舌红、苔少，脉细数无力\n    治法：养阴清热止血\n    方剂：保阴煎\n\n三、血瘀\n    症状舌脉：恶露过期不尽，量时少时多，色暗有块，小腹疼痛拒按，舌紫暗或边有瘀点，脉沉涩\n    治法：活血化瘀止血\n    方剂：生化汤。来源：《中医妇科学》（中国中医药出版社“十四五”规划教材）·产后病·恶露不绝。提示：恶露不绝须超声排除宫腔残留、感染与滋养细胞疾病\n\n【方剂参考】\n  补中益气汤：组成 黄芪18g、炙甘草9g、人参6g、当归3g、橘皮6g、升麻6g、柴胡6g、白术9g；功效 补中益气，升阳举陷\n      用法：水煎温服，日二次，食远（饭后较久）服；亦可作丸剂，每次6-9g，日二次，姜枣汤或温开水送下。\n      注意：阴虚火旺、肝阳上亢及感冒发热者忌用（甘温易助热）；升麻、柴胡升提，高血压及气逆喘满者慎用。\n  保阴煎：组成 生地黄12g、熟地黄12g、黄芩9g、黄柏9g、白芍12g、山药12g、续断12g、甘草6g；功效 滋阴清热，凉血止血\n      用法：水煎温服，日一剂，分二次服。\n      注意：脾胃虚寒、阳虚出血者忌用；黄芩、黄柏苦寒，久服易伤脾胃；服药期间忌辛辣燥热之品。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补阴）；原方出自《景岳全书·新方八阵·寒阵》\n  生化汤：组成 当归24g、川芎9g、桃仁6g、炮姜2g、炙甘草2g；功效 养血祛瘀，温经止痛\n      用法：水煎温服，或加黄酒（或童便）少许同煎，日一剂，分二次温服；产后连服3-7剂。\n      注意：产后血热而有瘀滞发热者不宜；恶露已净、无瘀滞者及非产后之孕妇忌用；不可久服。\n\n【西医诊断】\n  产后恶露不尽\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"O72.3","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2284,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f9a85329c174dadc4b47833719f6e3b9e3a207523fb7926f67d2ea09283aa0d4","pinyin":"chanhouelubujue(zhongyibianzheng)","initials":"chelbj(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","O72.3",30]]},{"id":"templates-aca4ec3c8816a2976ba5","key":"v1-c9ccc21dfe2a3058|templates-aca4ec3c8816a2976ba5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"产后抑郁症","category":"妇产科","raw":{"name":"产后抑郁症","category":"妇产科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】持续情绪低落、易哭泣、兴趣与愉悦感丧失（≥2周）、疲劳与精力不足（超出产后生理性疲劳）、睡眠障碍（难以入睡或早醒，即使婴儿熟睡）、焦虑与过度担忧婴儿健康、易激惹、注意力不集中、自责与无用感、对婴儿缺乏情感连接或过度焦虑、严重者：伤害婴儿或自杀意念、幻觉与妄想（产后精神病，属急症）。\n【待人工确认·本机素材无此段原文】","现病史":"产后抑郁症是分娩后出现的以持续情绪低落、兴趣减退、疲劳与焦虑为核心症状的精神障碍，多在产后4～6周内起病（可延至1年），发生率约10%～15%。与产后情绪低落（baby blues，产后3～5天短暂）不同，产后抑郁需≥2周的症状并影响功能，严重者可出现伤害婴儿或自杀意念（需紧急干预）。\n常见表现：持续情绪低落、易哭泣、兴趣与愉悦感丧失（≥2周）、疲劳与精力不足（超出产后生理性疲劳）、睡眠障碍（难以入睡或早醒，即使婴儿熟睡）、焦虑与过度担忧婴儿健康、易激惹、注意力不集中、自责与无用感、对婴儿缺乏情感连接或过度焦虑、严重者：伤害婴儿或自杀意念、幻觉与妄想（产后精神病，属急症）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率、体温、体重（营养与甲减评估）\n精神状态：情绪（低落/易激惹）、言语与思维、注意力、自知力\n自杀与伤婴风险评估：意念、计划与准备行为（必查）\n甲状腺与贫血体征：甲状腺肿大、皮肤干燥、结膜苍白、心率变化\n产科评估：子宫复旧、恶露（产后感染）、会阴或腹部伤口愈合、乳房（哺乳情况）\n睡眠与疲劳评估：入睡困难、早醒与睡眠时长\n母婴互动评估：对婴儿的情感连接、照护能力与焦虑程度","辅助检查":"1. 爱丁堡产后抑郁量表（EPDS）：筛查与随访复评（≥13需专业评估）\n2. 甲状腺功能（TSH、FT4）：甲减致抑郁样症状（产后甲状腺炎常见）\n3. 血常规+铁代谢：贫血与产后疲劳评估\n4. 电解质+白蛋白+血糖：拒食与营养不良评估\n5. 维生素D+维生素B12+叶酸：营养相关情绪影响评估\n6. 必要时性激素水平（雌激素）：产后激素波动评估（不作常规）\n7. 精神科量表（PHQ-9、GAD-7）与自杀风险评估工具：专业评估配套","初步诊断":"1. 爱丁堡产后抑郁量表（EPDS≥10提示可能抑郁，≥13提示需专业评估；第10题阳性提示自伤风险需立即干预）\n2. 精神科评估（DSM-5标准）：症状持续≥2周、功能受损、排除物质与躯体疾病所致\n3. 甲状腺功能（TSH、FT4）+血常规+铁代谢：甲减与贫血可致类似症状（须排除）\n4. 筛查自伤与伤婴风险：直接询问自杀与伤害婴儿意念（必做，决定干预级别）\n5. 评估社会心理因素：婚姻关系、家庭支持、经济压力、婴儿健康问题与既往精神病史\n6. 鉴别诊断：产后情绪低落（短暂自限）、产后精神病（起病急、幻觉妄想，需精神科急诊）、焦虑障碍与双相障碍\n7. 必要时躯体评估：产后感染、贫血、甲状腺疾病与药物影响\n1. 产后抑郁症（ICD-10：F53.0）","鉴别诊断":"1. 精神科评估（DSM-5标准）：症状持续≥2周、功能受损、排除物质与躯体疾病所致\n2. 甲状腺功能（TSH、FT4）+血常规+铁代谢：甲减与贫血可致类似症状（须排除）\n3. 鉴别诊断：产后情绪低落（短暂自限）、产后精神病（起病急、幻觉妄想，需精神科急诊）、焦虑障碍与双相障碍","处理方案":"【药物治疗·输液】\n⚠️ 以心理治疗与口服抗抑郁药为主，静脉用药用于重症与并发症！\n\n方案1（重症伴拒食/脱水/严重失眠）：\n 用法：0.9%氯化钠/葡萄糖 静滴（补液与营养支持）；必要时复合维生素与电解质补充\n\n方案2（产后精神病或严重自杀/伤婴风险）：\n 用法：抗精神病药（奥氮平 5～10mg 肌注/口服 或 氟哌啶醇 5mg 肌注）+ 苯二氮卓类（劳拉西泮 1～2mg 静推，短期）——精神科急会诊，必要时住院（母婴同室或分离评估）\n\n方案3（甲状腺功能减退相关）：\n 用法：左甲状腺素钠 按TSH调整（口服为主）；贫血者蔗糖铁 100mg 静滴（重度缺铁）\n\n方案4（营养支持）：\n 用法：0.9%氯化钠 静滴；维生素B族与维生素D补充；必要时肠内营养（拒食者）\n\n📌 产后抑郁的治疗以心理治疗（认知行为治疗/人际心理治疗）与SSRI类抗抑郁药为主；哺乳期用药需权衡（舍曲林与帕罗西汀相对安全）；出现自杀或伤婴意念须立即精神科干预。\n\n【药物治疗·口服】\n⚠️ 哺乳期用药需权衡婴儿安全（优先舍曲林/帕罗西汀）：\n\n药物1（抗抑郁药，SSRI一线）：\n 用法：舍曲林 50mg qd 起（哺乳期相对安全）或 帕罗西汀 20mg qd；效果不佳可加量或换用文拉法辛；起效需2～4周\n\n药物2（焦虑与失眠短期）：\n 用法：劳拉西泮 0.5～1mg qn（短期，哺乳期慎用）；或 唑吡坦 5mg qn（短期，按医嘱）\n\n药物3（重症/产后精神病，精神科指导）：\n 用法：奥氮平 5～10mg qn 或 喹硫平 25～50mg qn（监测嗜睡与代谢）；必要时联合抗抑郁药\n\n药物4（营养与辅助）：\n 用法：复合维生素B 2片 tid；维生素D 800IU/日；铁剂（贫血者）；omega-3（辅助，证据有限）\n\n📌 抗抑郁药起效需2～4周（需坚持服用），停药需逐渐减量；哺乳期用药应选安全性高的药物并观察婴儿反应（嗜睡、喂养差）。\n\n【治疗】\n心理治疗（一线）：认知行为治疗（CBT）、人际心理治疗（IPT）与支持性心理治疗（轻中度首选）\n抗抑郁药：中重度或心理治疗效果不佳者使用SSRI（舍曲林、帕罗西汀等），需2～4周起效并坚持6～12个月（防复发）\n社会支持干预：家庭支持、母婴关系干预、育儿支持与同伴支持小组；减轻育儿压力与睡眠剥夺\n睡眠干预：保障产妇睡眠（家属分担夜间照护）、睡眠卫生指导\n重症与急症处理：产后精神病（抗精神病药+住院）、自杀或伤婴意念（立即精神科急诊与安全监护）\n母婴安全评估：评估母婴互动与婴儿安全（必要时由家属临时照护）\n内科因素纠正：甲状腺功能减退、贫血与营养不良的纠正\n随访与复发预防：产后6周、3个月、6个月随访（EPDS复评）；既往有抑郁史者重点监测，再次妊娠需提前评估\n\n【处理要点】\n情绪与风险筛查：入院与产后访视使用EPDS筛查，直接询问自杀与伤害婴儿意念（每班/每次访视评估）\n安全监护：有自伤或伤婴风险者安排家属24小时陪伴、移除危险物品、必要时精神科住院与母婴分离评估\n心理护理：倾听与共情、不加评判、正常化其感受（产后情绪波动常见）、鼓励表达与求助\n睡眠与休息支持：安排家属分担夜间照护、保障产妇连续睡眠时段（睡眠剥夺加重抑郁）\n社会支持动员：评估家庭关系与经济压力、联系社区与心理支持资源、组织同伴支持\n用药护理：哺乳期抗抑郁药需观察婴儿反应（嗜睡、喂养差、体重增长）、按时服药与随访调整\n宣教：产后抑郁是疾病而非'矫情'、可治疗且预后良好、坚持治疗6～12个月（防复发）、出现自伤或伤婴意念立即求助\n\n【护理】\n情绪与风险筛查：每次访视使用EPDS并直接询问自伤与伤婴意念，阳性者立即报告并加强监护\n安全护理：有风险者安排家属24小时陪伴、移除危险物品、必要时母婴分离并由他人照护婴儿\n心理护理：倾听共情、不加评判、正常化情绪体验、鼓励表达与求助、避免说教与否定感受\n睡眠与休息支持：协调家属分担夜间照护，保障产妇连续睡眠（睡眠剥夺显著加重症状）\n用药护理（哺乳期）：观察婴儿嗜睡与喂养情况、记录情绪与不良反应，按时随访调整\n母婴互动支持：指导喂养与照护技巧、肯定母亲能力、必要时安排母婴关系干预\n宣教：产后抑郁是疾病可治、坚持治疗6～12个月防复发、家庭支持的重要性、出现危险念头立即求助（提供心理热线与就诊途径）\n\n【饮食】\n均衡营养：高蛋白、高维生素与充足热量（哺乳期需求增加）\n富含ω-3脂肪酸食物（深海鱼）与B族维生素（全谷物、绿叶蔬菜）有助情绪调节\n补充铁剂与维生素D（贫血与缺乏者）；多饮水（哺乳期）\n避免过量咖啡因（加重焦虑与失眠）与酒精（影响情绪与哺乳）\n规律进餐、少量多餐，避免因情绪低落而漏餐或暴食\n\n【注意事项】\n产后抑郁与'产后情绪低落'不同：后者产后3～5天出现、2周内自限；产后抑郁持续≥2周且影响功能\nEPDS≥13或第10题（自伤意念）阳性需立即专业评估与干预\n哺乳期抗抑郁药优先选择舍曲林与帕罗西汀（乳汁浓度低），并观察婴儿反应\n产后精神病是精神科急症（起病急、幻觉妄想、伤婴风险高），需立即精神科干预与住院评估\n既往抑郁史、孕期焦虑、缺乏家庭支持、婴儿健康问题与经济压力是高危因素（需重点筛查）\n\n【急诊/急救】\n出现自杀意念或计划（EPDS第10题阳性）→ 立即精神科会诊、24小时家属陪伴、移除危险物品、必要时住院\n出现伤害婴儿的想法或行为 → 立即母婴分离（由家属/医护照护婴儿）并精神科急诊干预\n产后精神病表现（幻觉、妄想、意识混乱、行为紊乱）→ 立即精神科急诊、抗精神病药与住院治疗\n拒食拒饮伴脱水与电解质紊乱 → 静脉补液与营养支持，精神科评估\n严重失眠伴兴奋躁动 → 短期苯二氮卓类/抗精神病药（精神科指导）并加强监护","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「产后抑郁症」原文）"},"icd10_diagnosis":"F53.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2285,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"857a83eb3aed4e9aa09ac1f2ca685ed0ac33e5663eaac9753ef7059395b99d59","pinyin":"chanhouyiyuzheng","initials":"chyyz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","F53.0",30]]},{"id":"templates-2356e84505ff5128ff25","key":"v1-c9ccc21dfe2a3058|templates-2356e84505ff5128ff25","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"产后缺乳(中医辨证)","category":"中医","raw":{"name":"产后缺乳(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】气血虚弱：产后乳少或全无，乳汁清稀，乳房柔软无胀感，面色少华，神疲食少，舌淡少苔，脉虚细、肝郁气滞：产后乳汁分泌少，浓稠，或乳汁不下，乳房胀硬疼痛，胸胁胀满，情志抑郁，食欲不振，苔薄黄，脉弦。\n【待人工确认·本机素材无此段原文】","现病史":"产后哺乳期内，产妇乳汁甚少或全无者，称缺乳。分气血虚弱、肝郁气滞等证型。\n常见表现：气血虚弱：产后乳少或全无，乳汁清稀，乳房柔软无胀感，面色少华，神疲食少，舌淡少苔，脉虚细、肝郁气滞：产后乳汁分泌少，浓稠，或乳汁不下，乳房胀硬疼痛，胸胁胀满，情志抑郁，食欲不振，苔薄黄，脉弦。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：面色、神、舌诊（舌质/舌苔）、月经（量色质）、带下（量色质气味）\n闻诊：声音、经带气味\n问诊：月经史（初潮/周期/经期/经量/色质）、带下史、婚育史、既往史、十问歌\n切诊：脉诊、腹诊（小腹压痛/包块）\n辨证：脏腑辨证（肝肾脾）、气血辨证、冲任督带辨证","辅助检查":"检查计划：患者产后哺乳期内乳汁甚少或全无，不能满足婴儿需要，乳汁清稀、乳房柔软无胀感、面色少华、神疲食少者属气血虚弱，乳汁浓稠或不下、乳房胀硬疼痛、胸胁胀满、情志抑郁者属肝郁气滞，需先查明缺乳原因并排除器质性病变。入院即查乳房，检查有无乳头凹陷、乳头皲裂、乳管堵塞及乳房肿块，明确是否存在影响排乳的局部因素；完善血常规检查了解有无贫血及感染，气血虚弱者据此评估营养与造血状态；乳房红肿热痛、体温升高者完善CRP、降钙素原检查并完善乳腺彩超检查，以排除乳腺炎、乳腺脓肿及乳腺占位性病变，必要时行脓液培养及药物敏感试验指导抗感染治疗；完善肝肾功能、电解质及血糖检查，排除肝肾功能异常、电解质紊乱及糖尿病等全身因素所致乳汁分泌不足；完善甲状腺功能检查排除甲状腺功能减退等内分泌因素影响泌乳；对产后出血较多、体质虚弱者复查血常规了解贫血纠正情况。同时评估婴儿吸吮方式与哺乳频次，完善泌乳量评估与体重监测，了解母乳是否满足婴儿生长需要，并动态观察舌苔脉象变化，为气血双补或疏肝解郁通乳的辨证用药提供依据。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 产后乳汁甚少或全无，不能满足婴儿需要\n2. 检查乳房（有无乳头凹陷、乳管堵塞）\n3. 排除乳腺炎（乳房红肿热痛）\n1. 产后缺乳(中医辨证)（ICD-10：O92.5）","鉴别诊断":"1. 排除乳腺炎（乳房红肿热痛）","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药调理为主\n\n方案2（出血量多/贫血明显）：\n 用法：5%GS250ml+酚磺乙胺1.0g ivgtt qd；NS500ml+维生素C2.0g ivgtt qd\n\n方案3（合并感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。妊娠期、哺乳期用药务必谨慎！\n\n药物1（气血虚弱）：通乳颗粒10g tid，或八珍颗粒6g tid\n药物2（肝郁气滞）：下乳涌泉散10g tid，或逍遥丸6g bid\n药物3（外治）：局部热敷、按摩乳房\n\n【治疗】\n气血虚弱：补气养血，佐以通乳，通乳丹加减\n肝郁气滞：疏肝解郁，通络下乳，下乳涌泉散加减\n\n【处理要点】\n增加哺乳次数，按需哺乳，吸空乳房\n保证充足睡眠和水分摄入\n保持情志舒畅，家人支持理解\n\n【护理】\n情志护理：肝郁气滞型多因产后情志不舒、忧思恼怒致乳络不畅，应多倾听安抚、疏导郁结，嘱家属体谅关爱，避免言语刺激；情志舒畅则气血调达，乳行通畅。\n起居调护：保证充足睡眠，气血虚弱者忌劳累耗气，注意保暖防风寒，避免寒邪客于乳房致乳络凝滞；按需哺乳、两侧交替排空，勿使乳汁淤积。\n病情观察：观察乳汁分泌量、质地清稀或浓稠及乳房充盈度；若乳房胀痛加重、触及硬结、皮肤红肿灼热伴发热，警惕乳痈（急性乳腺炎），及时报告处理；兼察恶露、食欲、情志以辨气血亏虚与肝郁之侧重。\n外治护理：乳络不通者可用温热毛巾敷乳后，自乳房四周向乳头方向轻推按摩助乳排出；气血虚弱者配合艾灸膻中、乳根、少泽等穴温通乳络，灸时防烫伤。\n煎药服药护理：气血虚弱方（如通乳丹）宜文火久煎、温服；肝郁气滞方（如下乳涌泉散）不宜久煎，饭后温服；服药后观察下乳效果，效不佳及时调整辨证用药。\n\n【饮食】\n气血虚弱型宜补益气血、通络下乳，多食鲫鱼汤、猪蹄汤、鸡汤、鸡蛋、黄豆、红枣、桂圆等健脾养血之品，忌生冷寒凉伤脾碍运。\n肝郁气滞型宜疏肝理气通乳，饮食清淡疏利，可食丝瓜、莲藕、金针菜、萝卜及陈皮泡水，忌辛辣煎炸、肥甘厚味助火碍胃。\n痰湿壅阻者忌肥甘厚腻、甜腻生痰之品，宜清淡易消化，佐薏苡仁、赤小豆、山药健脾祛湿以充乳源。\n通忌回乳之品：麦芽、麦乳精、韭菜、山楂、花椒等易致乳汁减少，产后缺乳期间应避免食用。\n药膳食疗：气血虚弱者用鲫鱼通草汤（鲫鱼250g、通草6g炖汤）、猪蹄花生汤、黄芪当归炖母鸡；肝郁气滞者用王不留行炖猪蹄、丝瓜络煮汤，均连服数日观效。\n\n【注意事项】\n乳房红肿热痛、发热者警惕急性乳腺炎\n乳头皲裂者及时处理，防感染\n营养不良者加强饮食调理\n\n【急诊/急救】\n一般不需急救\n大出血伴休克：立即急诊抢救\n宫外孕破裂/急性腹痛：立即转妇科急诊","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「产后缺乳（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】产后缺乳\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、气血虚弱\n    症状舌脉：产后乳汁甚少或全无，乳汁清稀，乳房柔软无胀感，面色萎黄，神疲乏力，食少便溏，舌淡苔薄白，脉细弱\n    治法：补气养血、通乳下乳\n    方剂：通乳丹\n\n二、肝郁气滞\n    症状舌脉：产后乳汁分泌不畅，量少，乳房胀硬疼痛或有结块，胸胁胀满，情志抑郁，善太息，苔薄白，脉弦\n    治法：疏肝解郁、通络下乳\n    方剂：下乳涌泉散\n\n三、痰湿阻滞\n    症状舌脉：产后乳汁稀少，乳房松软不胀，形体肥胖，胸闷泛恶，痰多，食少便溏，舌淡胖苔白腻，脉滑\n    治法：健脾化痰、通络下乳\n    方剂：苍附导痰丸合漏芦散。【证型核对说明】本条证型依《中医妇科学》（中国中医药出版社“十四五”规划教材）·产后病·缺乳之辨证分型原貌，教材主列“气血虚弱”“肝郁气滞”2 型，另见“痰湿阻滞”一型，故本条共 3 型，未另增列证型\n\n【方剂参考】\n  通乳丹：组成 人参6g（另煎兑服，或党参15g代）、生黄芪15g、当归12g、麦冬12g、木通（须用川木通，禁用关木通）3g、桔梗6g、猪蹄1只（煮汤代水煎药）；功效 补气养血，通络下乳\n      用法：猪蹄煮汤，去浮油，以汤代水煎药，人参另煎兑服，温服，日一剂，分二次服。\n      注意：肝郁气滞、乳络不通之缺乳不宜；木通须用川木通（或木通）；关木通含马兜铃酸、2005年起取消药用标准，禁止使用；服人参期间忌萝卜、浓茶。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂；原方出自《傅青主女科·卷下·产后》\n  下乳涌泉散：组成 当归9g、川芎6g、白芍12g、生地黄12g、柴胡6g、青皮9g、天花粉12g、漏芦9g、通草6g、桔梗6g、白芷9g、穿山甲（现禁用，代以王不留行9g、皂角刺；功效 疏肝解郁，养血通乳\n      用法：水煎温服，日一剂，分二次服。\n      注意：气血虚弱无乳可下者不宜；乳房红肿热痛成痈者须另作处理；穿山甲自2020年起《中国药典》不再收载、禁止药用，本方以王不留行、皂角刺替代。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂；原方出自《清太医院配方》；穿山甲替代依《中国药典》2020年版一部\n  苍附导痰丸：组成 苍术9g、香附9g、陈皮9g、半夏9g、茯苓9g、枳壳6g、胆南星6g、炙甘草6g、生姜3片；功效 燥湿化痰，行气解郁，开痰散结\n      用法：研末，以生姜自然汁浸饼为丸，每次6-9g，淡姜汤送服，日二次；亦可作汤剂，加生姜3片水煎温服。\n      注意：阴虚血少、虚火偏旺者不宜；服药期间忌生冷、肥甘厚味；经闭属气血亏虚而非痰湿者忌用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛痰剂（燥湿化痰）；原方出自《叶氏女科证治》（组成及是否含胆南星各家记载不一，待核）\n\n【西医诊断】\n  产后乳汁分泌不足\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"O92.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2286,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f3fbdd9254679967cdeb3cf453ff19aeca36021011a11b258679016319b24a2d","pinyin":"chanhouqueru(zhongyibianzheng)","initials":"chqr(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","O92.5",30]]},{"id":"templates-fae3573a573329b58f77","key":"v1-c9ccc21dfe2a3058|templates-fae3573a573329b58f77","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"产后身痛(中医辨证)","category":"中医","raw":{"name":"产后身痛(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】血虚：产后遍身关节酸楚疼痛，肢体麻木，头晕心悸，面色萎黄，舌淡红少苔，脉细弱、风寒：产后肢体关节疼痛，屈伸不利，或痛无定处，或冷痛剧烈，得热则舒，恶寒怕风，舌淡苔薄白，脉细紧、血瘀：产后身痛，痛处固定，拒按，按之痛甚，得热则减，恶露量少色暗有块，舌暗有瘀点，脉弦涩、肾虚：产后腰膝酸软疼痛，腿脚乏力，或足跟痛，头晕耳鸣，舌淡苔薄，脉沉细。\n【待人工确认·本机素材无此段原文】","现病史":"产妇在产褥期内出现肢体或关节酸楚、疼痛、麻木、重着者，称产后身痛。分血虚、风寒、血瘀、肾虚等证型。\n常见表现：血虚：产后遍身关节酸楚疼痛，肢体麻木，头晕心悸，面色萎黄，舌淡红少苔，脉细弱、风寒：产后肢体关节疼痛，屈伸不利，或痛无定处，或冷痛剧烈，得热则舒，恶寒怕风，舌淡苔薄白，脉细紧、血瘀：产后身痛，痛处固定，拒按，按之痛甚，得热则减，恶露量少色暗有块，舌暗有瘀点，脉弦涩、肾虚：产后腰膝酸软疼痛，腿脚乏力，或足跟痛，头晕耳鸣，舌淡苔薄，脉沉细。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：面色、神、舌诊（舌质/舌苔）、月经（量色质）、带下（量色质气味）\n闻诊：声音、经带气味\n问诊：月经史（初潮/周期/经期/经量/色质）、带下史、婚育史、既往史、十问歌\n切诊：脉诊、腹诊（小腹压痛/包块）\n辨证：脏腑辨证（肝肾脾）、气血辨证、冲任督带辨证","辅助检查":"检查计划：患者产褥期内出现肢体关节酸楚、疼痛、麻木、重着，遍身关节酸痛伴头晕心悸、面色萎黄者属血虚，冷痛剧烈、得热则舒、恶寒怕风者属风寒，痛处固定拒按、恶露量少色暗有块者属血瘀，腰膝酸软、足跟痛伴头晕耳鸣者属肾虚。完善血常规检查了解有无贫血及感染，血虚证者据此评估贫血程度与营养状况；完善血沉、CRP检查了解有无炎症活动，排除风湿活动及产褥感染所致关节疼痛；完善风湿相关检查，包括抗链球菌溶血素O、类风湿因子、抗环瓜氨酸肽抗体及自身抗体谱，以排除类风湿关节炎、风湿热及系统性红斑狼疮等结缔组织病；肢体关节疼痛明显、肿胀或活动受限者完善关节X线检查，排除骨骼病变、关节退变及骨折，必要时完善关节彩超或MRI检查了解关节腔积液、滑膜及软组织情况；腰膝酸软、足跟痛及下肢乏力者完善骨密度检查及血钙、磷、碱性磷酸酶、25-羟维生素D检查，了解骨代谢状况以明确有无骨质疏松及骨软化；考虑腰椎病变所致下肢放射痛者完善腰椎MRI检查明确神经根受压节段。同时完善肝肾功能、电解质检查为中药及非甾体抗炎药用药安全提供依据，并动态观察舌脉变化以指导辨证分型。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 产后（产褥期）肢体关节酸楚疼痛麻木\n2. 血常规、血沉、CRP、风湿相关检查（排除风湿活动）\n3. X线（必要时）排除骨骼病变\n1. 产后身痛(中医辨证)（ICD-10：M79.6）","鉴别诊断":"1. 血常规、血沉、CRP、风湿相关检查（排除风湿活动）\n2. X线（必要时）排除骨骼病变\n3. 关节红肿热痛、发热者排除感染性关节炎","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药调理为主\n\n方案2（出血量多/贫血明显）：\n 用法：5%GS250ml+酚磺乙胺1.0g ivgtt qd；NS500ml+维生素C2.0g ivgtt qd\n\n方案3（合并感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。妊娠期、哺乳期用药务必谨慎！\n\n药物1（血虚）：八珍颗粒6g tid，或归脾丸6g tid\n药物2（风寒）：独活寄生丸6g bid，或风湿骨痛胶囊4粒 tid（哺乳期慎用，遵医嘱）\n药物3（血瘀）：血府逐瘀胶囊4粒 tid\n药物4（肾虚）：六味地黄丸6g bid，或金匮肾气丸6g bid\n药物5（外治）：局部热敷、艾灸\n\n【治疗】\n血虚：养血益气，温经通络，黄芪桂枝五物汤加减\n风寒：养血祛风，散寒除湿，独活寄生汤加减\n血瘀：养血活血，祛瘀通络，身痛逐瘀汤加减\n肾虚：补肾强腰，壮筋骨，养荣壮肾汤加减\n\n【处理要点】\n注意保暖，避免受凉、接触冷水\n适度活动，循序渐进\n加强营养，补钙\n\n【护理】\n病情观察：观察疼痛部位、性质、程度及持续时间，注意恶露的量、色、质、气味及有无发热、关节红肿等；肾虚水肿者记录24小时出入量，每日晨起测体重，观察尿量变化。\n起居调护：产后居室宜温暖干燥、避风保暖，忌久居阴冷潮湿之处；痛处局部保暖，腰膝、肩肘关节可加护腰护膝，避直接吹风；汗出较多者及时擦干更衣，忌汗出当风受凉。\n情志护理：产后多虚多瘀、情志易郁，忧思恼怒致肝郁气滞、气血不畅可加重身痛，应多予安慰开导、耐心倾听，嘱家属多加关心陪伴，使情绪平和舒畅。\n煎药服药护理：养血益气、通络止痛之剂宜温服、饭前服；祛风散寒止痛药宜热服，药后覆被取微汗以助药力，但以遍身微微汗出为度，切忌大汗淋漓（血汗同源，汗多更伤气血，血虚者尤忌）；服药后注意避风保暖。\n外治护理：可予艾灸（足三里、关元、腰阳关等）、热盐包、中药熏洗或药熨温经散寒止痛，操作时注意温度适中防烫伤，皮肤破损或溃疡处不宜熏洗，熏洗后及时擦干穿衣避风。\n\n【饮食】\n总宜温软易消化、营养丰富，少食多餐；忌生冷瓜果、冷饮及肥甘厚腻之品，以免寒凝经脉、损伤脾胃、助湿碍胃。\n血虚证：宜食补益气血之品，如桂圆、红枣、猪肝、瘦肉、乌鸡汤、阿胶等；忌过食辛散之品以免耗伤阴血。\n风寒证：忌生冷寒凉饮食，宜温热饮食，可饮生姜红糖水、葱白豆豉汤；药膳可选用当归生姜羊肉汤，温经散寒、养血止痛。\n血瘀证：宜食活血化瘀之品，如山楂、黑木耳、桃仁（少量）、玫瑰花茶、红糖水等；忌食酸涩收敛之品，以免瘀血留滞、经脉不通。\n肾虚证：宜食补肾壮腰之品，如核桃、黑芝麻、山药、枸杞，药膳可用杜仲炖猪腰、桑寄生煲鸡汤；哺乳者慎用回乳之品（如麦芽）。\n\n【注意事项】\n哺乳期用药需谨慎，遵医嘱\n关节红肿热痛、发热者排除感染性关节炎\n持续不缓解者风湿免疫科就诊\n\n【急诊/急救】\n一般不需急救\n大出血伴休克：立即急诊抢救\n宫外孕破裂/急性腹痛：立即转妇科急诊","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「产后身痛（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】产后身痛\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、血虚\n    症状舌脉：产后遍身关节酸楚、疼痛，肢体麻木，面色萎黄，头晕心悸，舌淡、苔薄，脉细弱\n    治法：养血益气、温经通络\n    方剂：黄芪桂枝五物汤\n\n二、风寒\n    症状舌脉：产后肢体关节疼痛，屈伸不利，或痛无定处，或冷痛剧烈、宛如针刺，或关节肿胀、麻木重着，恶寒怕风，舌淡、苔薄白，脉濡细\n    治法：养血祛风、散寒除湿\n    方剂：独活寄生汤\n\n三、血瘀\n    症状舌脉：产后身痛，尤以下肢疼痛、麻木、重着、肿胀明显，屈伸不利，小腿压痛，恶露量少、色紫暗有块，舌暗、苔白，脉弦涩\n    治法：养血活血、化瘀通络\n    方剂：身痛逐瘀汤\n\n四、肾虚\n    症状舌脉：产后腰膝、足跟疼痛，艰于俯仰，头晕耳鸣，夜尿多，舌淡暗、苔薄，脉沉细弦\n    治法：补肾养血、强腰壮骨\n    方剂：养荣壮肾汤。来源：《中医妇科学》（中国中医药出版社“十四五”规划教材）·产后病·产后身痛\n\n【方剂参考】\n  独活寄生汤：组成 独活9g、桑寄生6g、杜仲6g、牛膝6g、细辛3g、秦艽6g、茯苓6g、肉桂心6g、防风6g、川芎6g、人参6g、甘草6g、当归6g、芍药6g、干地黄6g；功效 祛风湿，止痹痛，益肝肾，补气血\n      用法：水煎温服，日二次，食前服；亦可为丸剂，每次6-9g，日二次，温酒或温开水送下。\n      注意：湿热痹证（关节红肿热痛、苔黄腻）及阴虚火旺者忌用；孕妇慎用细辛、肉桂；感冒发热期间停服。细辛药典用量1-3g，本方已减为3g，宜久煎。\n  身痛逐瘀汤：组成 秦艽3g、川芎6g、桃仁9g、红花9g、甘草6g、羌活3g、没药6g、当归9g、五灵脂6g（炒）、香附3g、牛膝9g、地龙6g；功效 活血祛瘀，通经止痛，祛风除湿\n      用法：水煎温服，日一剂，分二次服；原书亦可以黄酒少许兑服。\n      注意：孕妇忌用；有出血倾向、月经量多者及体虚无瘀者慎用；本方法瘀力较强，中病即止，不宜久服。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《医林改错·卷下》\n\n【西医诊断】\n  产后关节痛\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"M79.6","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2287,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e4f27bfad25ca024a2f26832853c1033377153600b8f898deed738a993f6f953","pinyin":"chanhoushentong(zhongyibianzheng)","initials":"chst(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","M79.6",30]]},{"id":"templates-cee3c3dcdc2f475f99c3","key":"v1-c9ccc21dfe2a3058|templates-cee3c3dcdc2f475f99c3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"低血糖昏迷","category":"院前急救","raw":{"name":"低血糖昏迷","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】糖尿病史/降糖药使用、心慌、出汗、手抖、饥饿感、意识模糊、嗜睡、严重者昏迷、抽搐、血糖<2.8mmol/L（糖尿病<3.9）。\n【待人工确认·本机素材无此段原文】","现病史":"血糖过低导致的意识障碍，常见于糖尿病患者用药过量。\n常见表现：糖尿病史/降糖药使用、心慌、出汗、手抖、饥饿感、意识模糊、嗜睡、严重者昏迷、抽搐、血糖<2.8mmol/L（糖尿病<3.9）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 床旁快速血糖测定（POCT）——入院即刻完成，昏迷患者首选筛查，同时每小时复查血糖动态评估补糖效果\n2. 静脉血糖+血气分析（含电解质、乳酸）——同步急查，评估酸中毒程度，排除低血糖诱发的代谢紊乱\n3. 血清电解质及肝肾功能——急查，重点关注血钾（补糖后钾向细胞内转移易致低钾血症），排除肝源性低血糖\n4. 心电图——急诊常规立即完成，筛查低血糖诱发的心律失常与心肌缺血\n5. 毒物/药物筛查（乙醇、磺脲类、胰岛素、β受体阻滞剂）——疑药物过量或酒精相关低血糖时送检，明确病因\n6. 头颅CT——静脉推注葡萄糖后意识未恢复或疑合并脑血管意外时尽快进行，排除卒中","初步诊断":"1. 糖尿病史/降糖药使用\n2. 典型低血糖表现\n3. 血糖<2.8mmol/L\n4. 供糖后症状迅速缓解\n1. 低血糖昏迷（ICD-10：E16.0）","鉴别诊断":"1. 诊断要点：糖尿病史/降糖药使用\n2. 诊断要点：典型低血糖表现\n3. 诊断要点：血糖<2.8mmol/L\n4. 诊断要点：供糖后症状迅速缓解\n5. 糖尿病患者血糖<3.9即需处理\n6. 昏迷者不要喂食（防误吸）\n7. 长效磺脲类引起者需长时间观察\n8. 反复低血糖需调整降糖方案\n9. 随身携带糖果及糖尿病识别卡","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：50%葡萄糖注射液40-60ml iv（立即）\n\n方案2：\n 用法：10%葡萄糖注射液500ml ivgtt 维持\n\n方案3：\n 用法：必要时重复\n\n方案4（顽固低血糖）：\n 用法：氢化可的松100mg ivgtt\n\n方案5：\n 用法：胰高血糖素1mg im（无法建立静脉时）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（清醒者）：\n 用法：口服糖水、糖果、饼干\n\n药物2：\n 用法：葡萄糖片15-20g\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即测血糖\n清醒者：口服糖水/糖果\n昏迷者：50%GS40-60ml iv\n维持：10%GS ivgtt\n顽固低血糖：氢化可的松\n监测血糖，每15-30分钟一次\n查找原因（用药过量、进食少、运动多）\n长效磺脲类药物引起者需持续监测24-48小时\n120转院（顽固/反复发作）\n\n【处理要点】\n平卧，防跌倒\n保持气道通畅\n监测血糖\n清醒后进食碳水化合物\n记录用药及进食情况\n\n【护理】\n立即取平卧位、头偏向一侧，保持气道通畅，昏迷者备好吸引器防误吸，必要时配合气管插管\n密切监测意识、瞳孔、心率、血压及出汗情况，每15～30分钟复测血糖直至稳定\n急救配合：遵医嘱立即静脉推注50%葡萄糖40～60ml，同时建立双路静脉通道，观察推注后意识恢复反应，配合准备10%葡萄糖持续静脉滴注维持\n液体与电解质管理：补糖后复查血钾，遵医嘱补钾；老年及心功能不全者控制输液速度，防止心衰\n并发症预防：加床栏防坠床、防舌咬伤，监测体温防低体温，意识未恢复者留置导尿并记录出入量\n\n【饮食】\n昏迷期间禁食禁水，防止误吸，一律经静脉途径补糖\n意识恢复、吞咽功能正常后立即给予含糖食物（糖水、果汁、饼干）过渡，再逐步改为温热流质饮食\n恢复期少量多餐，主食按时按量，避免空腹状态下饮酒或剧烈运动诱发再发低血糖\n忌单次大量摄入高浓度精制糖，防止血糖骤升骤降；糖尿病者按医嘱规律服用降糖药并配合进食\n指导患者随身携带糖果或含糖饮料，记录发作前饮食与用药情况，便于复诊调整方案\n\n【注意事项】\n糖尿病患者血糖<3.9即需处理\n昏迷者不要喂食（防误吸）\n长效磺脲类引起者需长时间观察\n反复低血糖需调整降糖方案\n随身携带糖果及糖尿病识别卡\n\n【急诊/急救】\n立即测血糖\n清醒者：口服糖水15-20g\n昏迷者：50%GS40-60ml iv（立即）\n维持：10%GS500ml ivgtt\n无法建立静脉：胰高血糖素1mg im\n监测血糖q15-30min\n顽固/反复发作：120转院","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「低血糖昏迷」原文）"},"icd10_diagnosis":"E16.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2288,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e5b2a7a98422cd7ff9257f20e33c01f70fc532edb9943c829d3f89b582a43706","pinyin":"dixuetanghunmi","initials":"dxthm","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E16.0",30]]}]);